function LobbyScreen({
  playerName, setPlayerName, playerAvatarId, setPlayerAvatarId, onStart, soundOn,
  socket, connStatus, roomInfo, myRole, joinError, onConnect, onCreateRoom, onJoinRoom,
  speedLevel, setSpeedLevel, onRejoin, onLeaveToHome, prefillJoinCode,
  lobbyChatMessages, lobbyChatDraft, setLobbyChatDraft, showLobbyChat, setShowLobbyChat,
  lobbyChatUnread, sendLobbyChatMessage, lobbyReplyingTo, setLobbyReplyingTo, lobbyChatScrollRef,
}) {
  // "Leave" shows a simple goodbye screen instead of calling
  // window.location.reload() — a real page reload can hang or trigger a
  // "taking longer than expected" prompt inside sandboxed/embedded contexts
  // (Telegram WebView, this artifact's own iframe, etc.), and there's
  // nothing in the Lobby itself that needs resetting anyway (no game
  // progress exists yet at this point).
  const [hasLeft, setHasLeft] = useState(false);

  // The Imposter (Saboteur) count is set once per lobby by whoever creates
  // it. Only the host (room creator) gets to set this — everyone else just
  // sees it reflected once the game starts and roles come back from the
  // server.
  const [imposterCount, setImposterCount] = useState(1);
  // [BUG FIX] If players leave the Lobby after the host already picked a
  // higher imposter count (e.g. 3 Saboteurs with 6 players, then 2
  // people leave), silently re-clamp it down rather than letting a now-
  // invalid value sit there until the server clamps it anyway at
  // startGame - keeps the displayed selection honest the whole time.
  useEffect(() => {
    const playerCount = roomInfo?.players?.length || 0;
    const maxImposters = Math.max(1, Math.min(3, playerCount - 2));
    setImposterCount((prev) => Math.min(prev, maxImposters));
  }, [roomInfo?.players?.length]);
  // [NEW FEATURE] speedLevel/setSpeedLevel now come from props
  // (MovementDemo) instead of being a local state here - this is what
  // lets server events (lobbySpeedChanged, roomCreated/roomJoined's
  // speedLevel) actually update what every player sees/feels live in
  // the Lobby, not just whatever the host's own browser tab happens to
  // have set locally.

  // [MULTIPLAYER] joinCodeInput is local UI only — the typed room-code
  // before "Join" is pressed. roomInfo (passed down from MovementDemo)
  // is the real, server-confirmed room state once connected.
  const [joinCodeInput, setJoinCodeInput] = useState('');
  // [DEV-BRANCH ONLY - PHASE 2] Auto-connects the moment the Lobby opens
  // - replaces the old manual "Connect to Server" button now that the
  // player already went through Home → Play to get here. Only fires
  // once per mount; onConnect itself is a no-op if already connected.
  useEffect(() => {
    onConnect?.();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  // [DEV-BRANCH ONLY - PHASE 2] Pre-fills the join code when arriving
  // here from a tap on Home's live public rooms list.
  useEffect(() => {
    if (prefillJoinCode) setJoinCodeInput(prefillJoinCode);
  }, [prefillJoinCode]);
  // [NEW FEATURE] Confirmation before creating a brand new room, so a
  // player who actually meant to JOIN a friend's room doesn't
  // accidentally spin up an empty new one instead.
  const [showCreateConfirm, setShowCreateConfirm] = useState(false);
  const isHost = !!(roomInfo && roomInfo.players && roomInfo.players.find(p => p.id === socket?.id)?.isHost);
  // [DEV-BRANCH ONLY TEST FEATURE] Dev Mode drops the minimum from 4 to 2
  // so a host testing solo (2 devices) doesn't need to round up real
  // players. Falls back to the normal MIN_PLAYERS whenever Dev Mode is
  // off - identical to live behavior in that case.
  const effectiveMinPlayers = roomInfo?.devMode ? 2 : MIN_PLAYERS;
  const canStartGame = !!roomInfo && roomInfo.players.length >= effectiveMinPlayers;

  const [pos, setPos] = useState({ x: 50, y: 75 }); // percentage coords
  const [facing, setFacing] = useState('right');
  const [isMoving, setIsMoving] = useState(false);
  const [showEditor, setShowEditor] = useState(false);
  const [nameInput, setNameInput] = useState(playerName);
  const keysRef = useRef({});
  const joyRef = useRef({ active: false, dx: 0, dy: 0 });
  const joyBaseRef = useRef(null);
  const [knob, setKnob] = useState({ x: 0, y: 0 });
  const posRef = useRef(pos);
  const rafRef = useRef(null);
  const roomRef = useRef(null);
  const [roomSize, setRoomSize] = useState({ w: 320, h: 213 });

  // [MULTIPLAYER] Other real players' positions while still in the Lobby
  // — kept entirely separate from the in-game otherPlayers state (see the
  // lobbyMove/lobbyMoved comment in the backend for why). Keyed by socket
  // id: { [id]: { x, y } } in the same 0-100 percentage space as our own
  // pos. Cleared whenever the Lobby unmounts naturally (component
  // remounts fresh on next visit, so no explicit cleanup is needed).
  const [otherLobbyPlayers, setOtherLobbyPlayers] = useState({});
  // [BUG FIX] Ref mirror of otherLobbyPlayers, read inside the
  // interpolation step below (which runs every animation frame inside a
  // [] / fixed-dependency useEffect) - needed for the same reason every
  // other "read latest state inside a long-lived loop" ref in this file
  // exists: the loop's own closure would otherwise only ever see
  // whatever otherLobbyPlayers was at the moment the loop was created.
  const otherLobbyPlayersRef = useRef(otherLobbyPlayers);
  useEffect(() => { otherLobbyPlayersRef.current = otherLobbyPlayers; }, [otherLobbyPlayers]);
  // [BUG FIX] Same interpolation pattern the in-game movement loop
  // already uses for otherPlayers - otherLobbyPlayers now holds the
  // DISPLAYED position, eased toward this target each frame, instead of
  // snapping straight to whatever the latest throttled lobbyMove update
  // says. This is the actual fix for other players looking like they're
  // "dragging"/jerky in the Lobby, especially at higher speed levels:
  // without interpolation, a faster speed meant each throttled update
  // covered MORE distance, making the snap-to-new-position jump more
  // visible than it was at the original (slower) default speed.
  const otherLobbyTargetRef = useRef({});
  const lastLobbyPosEmitRef = useRef(0);
  useEffect(() => {
    if (!socket) return;
    const onLobbyMoved = (data) => {
      const prevTarget = otherLobbyTargetRef.current[data.id] || {};
      otherLobbyTargetRef.current = {
        ...otherLobbyTargetRef.current,
        [data.id]: { ...prevTarget, x: data.x, y: data.y },
      };
      // Seed the displayed position immediately the FIRST time we hear
      // from this id - no point easing in from undefined.
      setOtherLobbyPlayers((prev) => {
        if (prev[data.id] && typeof prev[data.id].x === 'number') return prev;
        return { ...prev, [data.id]: { ...(prev[data.id] || {}), x: data.x, y: data.y } };
      });
    };
    socket.on('lobbyMoved', onLobbyMoved);
    return () => socket.off('lobbyMoved', onLobbyMoved);
  }, [socket]);

  // [LOBBY VISIBILITY FIX] Seed otherLobbyPlayers from roomInfo's
  // player-list (which now carries each player's last-known lobbyX/lobbyY
  // — see the backend's getPlayerList) every time it updates. This is
  // what lets a player see everyone already wandering the Lobby room
  // immediately, instead of only seeing players appear once each of them
  // personally moves at least once after we've joined.
  useEffect(() => {
    if (!roomInfo?.players) return;
    setOtherLobbyPlayers((prev) => {
      const next = { ...prev };
      const validIds = new Set();
      roomInfo.players.forEach((p) => {
        if (p.id === socket?.id) return;
        validIds.add(p.id);
        // [BUG FIX] Preserve any existing x/y from a movement update
        // already received (don't blow it away just because roomInfo
        // refreshed), and always cache avatarId here too — this is what
        // the render above falls back to when roomInfo and
        // otherLobbyPlayers are a frame or two out of sync with each
        // other, instead of the avatar disappearing on those frames.
        const existing = next[p.id] || prev[p.id] || {};
        next[p.id] = {
          ...existing,
          avatarId: p.avatarId,
          ...(typeof p.lobbyX === 'number' ? { x: p.lobbyX } : {}),
          ...(typeof p.lobbyY === 'number' ? { y: p.lobbyY } : {}),
        };
        // Keep the interpolation target in sync too.
        if (typeof p.lobbyX === 'number' && typeof p.lobbyY === 'number') {
          otherLobbyTargetRef.current = {
            ...otherLobbyTargetRef.current,
            [p.id]: { x: p.lobbyX, y: p.lobbyY },
          };
        }
      });
      // [BUG FIX] Remove any id that's no longer in the server's
      // player-list at all (e.g. a player refreshed and got a brand-new
      // socket.id - their OLD id disappears from roomInfo.players, but
      // this effect previously only ever ADDED to `prev`, never
      // pruned it). Without this, the old id's frozen avatar stuck
      // around forever side-by-side with their new moving one - the
      // "duplicate avatar after refresh" bug. Mirrors the same
      // validIds-based cleanup syncOtherPlayersFromList already does
      // for the in-game otherPlayers state.
      for (const id in next) {
        if (!validIds.has(id)) delete next[id];
      }
      for (const staleId in otherLobbyTargetRef.current) {
        if (!validIds.has(staleId)) delete otherLobbyTargetRef.current[staleId];
      }
      return next;
    });
  }, [roomInfo, socket]);

  // [LOBBY VISIBILITY FIX] The moment we're actually in a room (just
  // created/joined one), immediately broadcast our own current Lobby
  // position rather than waiting for the next time we move — this is
  // what lets OTHER players see us right away instead of only after we
  // first wander around.
  const announcedLobbyPosRef = useRef(false);
  useEffect(() => {
    if (!roomInfo || !socket || !socket.connected) return;
    if (announcedLobbyPosRef.current) return;
    announcedLobbyPosRef.current = true;
    socket.emit('lobbyMove', { x: posRef.current.x, y: posRef.current.y });
  }, [roomInfo, socket]);

  // Lightweight local audio context for the Lobby's own footstep sound —
  // same synthesis approach as the in-game one (short filtered-noise tap +
  // low thud, alternating pitch), kept independent since the Lobby is a
  // separate component from the main game and doesn't share its refs.
  const audioCtxRef = useRef(null);
  const footstepStepRef = useRef(0);
  const lastFootstepRef = useRef(0);
  const FOOTSTEP_INTERVAL_MS = 290;
  const getAudioCtx = useCallback(() => {
    if (!audioCtxRef.current) {
      const Ctx = window.AudioContext || window.webkitAudioContext;
      if (Ctx) audioCtxRef.current = new Ctx();
    }
    if (audioCtxRef.current && audioCtxRef.current.state === 'suspended') {
      audioCtxRef.current.resume();
    }
    return audioCtxRef.current;
  }, []);
  // Same reasoning as the in-game audio unlock: some browsers only allow
  // resuming a suspended AudioContext from directly inside a user-gesture
  // handler, not from a later async callback (like a requestAnimationFrame
  // tick triggered by holding down a key). Without this, the Lobby's
  // footstep context could stay silently suspended forever even though
  // soundOn is true and playFootstepSound is being called correctly.
  useEffect(() => {
    const unlock = () => {
      const ctx = getAudioCtx();
      if (ctx && ctx.state === 'suspended') ctx.resume();
      window.removeEventListener('pointerdown', unlock);
      window.removeEventListener('keydown', unlock);
      window.removeEventListener('touchstart', unlock);
    };
    window.addEventListener('pointerdown', unlock);
    window.addEventListener('keydown', unlock);
    window.addEventListener('touchstart', unlock);
    return () => {
      window.removeEventListener('pointerdown', unlock);
      window.removeEventListener('keydown', unlock);
      window.removeEventListener('touchstart', unlock);
    };
  }, [getAudioCtx]);
  const playFootstepSound = useCallback(() => {
    if (!soundOn) return;
    const ctx = getAudioCtx();
    if (!ctx) return;
    const now = ctx.currentTime;
    const stepAlt = footstepStepRef.current % 2 === 0;
    footstepStepRef.current += 1;
    const bufferSize = Math.floor(ctx.sampleRate * 0.045);
    const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) data[i] = Math.random() * 2 - 1;
    const noise = ctx.createBufferSource();
    noise.buffer = buffer;
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = stepAlt ? 950 : 880;
    filter.Q.value = 0.7;
    const noiseGain = ctx.createGain();
    noiseGain.gain.setValueAtTime(0.1, now);
    noiseGain.gain.linearRampToValueAtTime(0, now + 0.045);
    noise.connect(filter).connect(noiseGain).connect(ctx.destination);
    noise.start(now);
    noise.stop(now + 0.05);
    const thudOsc = ctx.createOscillator();
    const thudGain = ctx.createGain();
    thudOsc.type = 'sine';
    thudOsc.frequency.value = stepAlt ? 105 : 98;
    thudGain.gain.value = 0;
    thudOsc.connect(thudGain).connect(ctx.destination);
    thudGain.gain.linearRampToValueAtTime(0.11, now + 0.004);
    thudGain.gain.linearRampToValueAtTime(0, now + 0.05);
    thudOsc.start(now);
    thudOsc.stop(now + 0.055);
  }, [soundOn, getAudioCtx]);

  useEffect(() => {
    const upd = () => {
      if (roomRef.current) {
        const r = roomRef.current.getBoundingClientRect();
        setRoomSize({ w: r.width, h: r.height });
      }
    };
    upd();
    window.addEventListener('resize', upd);
    return () => window.removeEventListener('resize', upd);
  }, []);

  useEffect(() => {
    const kd = (e) => { keysRef.current[e.key.toLowerCase()] = true; };
    const ku = (e) => { keysRef.current[e.key.toLowerCase()] = false; };
    window.addEventListener('keydown', kd);
    window.addEventListener('keyup', ku);
    return () => { window.removeEventListener('keydown', kd); window.removeEventListener('keyup', ku); };
  }, []);

  // The main game's MOVE_SPEED is in world-pixels at TILE=22, and on screen
  // it's further multiplied by the camera `scale` (typically ~0.7-0.8 on a
  // phone), so the actual on-screen pace is MOVE_SPEED * scale px/frame.
  // The lobby room has no such camera scale (it's rendered close to 1:1
  // against its own box), so applying MOVE_SPEED directly here came out
  // visibly faster than in-game. LOBBY_SPEED_FACTOR brings the on-screen
  // pace back in line with that effective in-game scale.
  const LOBBY_SPEED_FACTOR = 0.62;
  // [BUG FIX] The movement loop's own useEffect below only runs ONCE on
  // mount ([] dependency array) - speedLevel as a plain prop value would
  // get captured in that one-time closure and NEVER update again even
  // as the host changes it. A ref always reflects the LATEST value
  // without needing to recreate the loop, which is what actually makes
  // a live speed change take effect in the Lobby instead of being
  // silently ignored after the very first render.
  const speedLevelRef = useRef(speedLevel);
  useEffect(() => { speedLevelRef.current = speedLevel; }, [speedLevel]);
  // [BUG FIX] Same stale-closure issue, but for the `socket` prop itself
  // - the movement loop's useEffect below has a [] dependency array
  // (runs once on mount), and at that very first mount, socket is still
  // null (the Lobby renders before connectSocket() has actually been
  // called/completed). The loop's closure then permanently captured
  // socket=null, which meant lobbyMove was NEVER emitted from inside the
  // movement loop itself - only the one-time "announce my position on
  // join" effect (which legitimately re-runs whenever socket changes)
  // ever successfully sent anything, so other players saw us appear
  // once but never actually move afterward. A ref always has the
  // CURRENT socket without needing the loop recreated.
  const socketRef = useRef(socket);
  useEffect(() => { socketRef.current = socket; }, [socket]);
  const playFootstepRef = useRef(() => {});
  useEffect(() => { playFootstepRef.current = playFootstepSound; }, [playFootstepSound]);
  // Mirrors showEditor into a ref so the movement loop (mounted once) can
  // pause while the avatar/name editor dialog is open — same idea as the
  // main game pausing movement while a mission popup is up. Without this,
  // any keys/joystick input still "held" from just before the dialog
  // opened would keep moving the player (and playing footstep sounds) in
  // the background behind the dialog.
  const showEditorRef = useRef(false);
  useEffect(() => { showEditorRef.current = showEditor; }, [showEditor]);
  useEffect(() => {
    const tick = () => {
      if (showEditorRef.current) {
        rafRef.current = requestAnimationFrame(tick);
        return;
      }
      let dx = 0, dy = 0;
      const k = keysRef.current;
      if (k['arrowup'] || k['w']) dy -= 1;
      if (k['arrowdown'] || k['s']) dy += 1;
      if (k['arrowleft'] || k['a']) dx -= 1;
      if (k['arrowright'] || k['d']) dx += 1;
      if (joyRef.current.active) { dx += joyRef.current.dx; dy += joyRef.current.dy; }

      if (dx !== 0 || dy !== 0) {
        const mag = Math.sqrt(dx * dx + dy * dy) || 1;
        const w = roomRef.current ? roomRef.current.getBoundingClientRect().width : roomSize.w;
        const h = roomRef.current ? roomRef.current.getBoundingClientRect().height : roomSize.h;
        // [NEW FEATURE] The host's chosen speed level now applies in the
        // Lobby too, live - same (speedLevel / 2) scaling the in-game
        // movement loop uses (level 2/50% = exactly the original,
        // unscaled speed), so every player can actually feel/preview the
        // chosen speed before the game even starts, not just see a
        // number on a button.
        const speedMultiplier = (speedLevelRef.current || 2) / 2;
        const speedPctX = (MOVE_SPEED * LOBBY_SPEED_FACTOR * speedMultiplier / w) * 100;
        const speedPctY = (MOVE_SPEED * LOBBY_SPEED_FACTOR * speedMultiplier / h) * 100;
        const sx = (dx / mag) * speedPctX;
        const sy = (dy / mag) * speedPctY;
        const cur = posRef.current;
        let nx = cur.x, ny = cur.y;
        if (lobbyCanStand(cur.x + sx, cur.y)) nx = cur.x + sx;
        if (lobbyCanStand(nx, cur.y + sy)) ny = cur.y + sy;
        const next = { x: nx, y: ny };
        posRef.current = next;
        setPos(next);
        // [MULTIPLAYER] Broadcast our Lobby position, throttled the same
        // way the in-game movement loop throttles playerMove (~10x/sec).
        const nowMs = performance.now();
        if (socketRef.current && socketRef.current.connected && nowMs - lastLobbyPosEmitRef.current > 70) {
          lastLobbyPosEmitRef.current = nowMs;
          socketRef.current.emit('lobbyMove', { x: next.x, y: next.y });
        }
        if (dx > 0) setFacing(f => f !== 'right' ? 'right' : f);
        else if (dx < 0) setFacing(f => f !== 'left' ? 'left' : f);
        setIsMoving(m => m ? m : true);
        const t = performance.now();
        if (t - lastFootstepRef.current >= FOOTSTEP_INTERVAL_MS) {
          lastFootstepRef.current = t;
          playFootstepRef.current();
        }
      } else {
        setIsMoving(m => m ? false : m);
        lastFootstepRef.current = 0;
      }

      // [BUG FIX] Ease every other Lobby player's displayed position
      // toward its latest target each frame - same interpolation the
      // in-game movement loop uses for otherPlayers, applied here too.
      // This is what actually smooths out other players' movement in
      // the Lobby instead of it visibly snapping/dragging between each
      // throttled update, especially noticeable at faster speed levels.
      // [BUG FIX] This lerp factor was a flat 0.25 regardless of speed -
      // fine at the OLD default (50-75%), but at the higher end of the
      // new 50-150% range, a faster-moving player covers noticeably more
      // ground BETWEEN each network position update, and this same fixed
      // catch-up rate simply couldn't keep pace - making every OTHER
      // player visibly lag/appear slower than their real speed, while
      // your own locally-simulated (zero-latency) movement always looked
      // correctly fast. This is what was actually behind "everyone's
      // speed doesn't look the same - mine looks faster, others look
      // slower" - it was never a value-sync bug (speedLevel itself was
      // always correctly synced), it was this smoothing rate not scaling
      // with it. Now it scales proportionally around speed level 4
      // (100%) as the baseline, capped so it doesn't overshoot into
      // jitter at the very top of the range.
      const lobbyLerpFactor = Math.min(0.6, 0.25 * ((speedLevelRef.current || 4) / 4));
      const lobbyTargets = otherLobbyTargetRef.current;
      let lobbyNeedsUpdate = false;
      const lobbyInterpolated = {};
      for (const id in lobbyTargets) {
        const target = lobbyTargets[id];
        const current = otherLobbyPlayersRef.current[id];
        if (!current || typeof current.x !== 'number') continue;
        const dxp = target.x - current.x;
        const dyp = target.y - current.y;
        if (Math.abs(dxp) < 0.05 && Math.abs(dyp) < 0.05) continue;
        lobbyNeedsUpdate = true;
        lobbyInterpolated[id] = { ...current, x: current.x + dxp * lobbyLerpFactor, y: current.y + dyp * lobbyLerpFactor };
      }
      if (lobbyNeedsUpdate) {
        setOtherLobbyPlayers((prev) => ({ ...prev, ...lobbyInterpolated }));
      }

      rafRef.current = requestAnimationFrame(tick);
    };
    rafRef.current = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(rafRef.current);
  }, [roomSize.w, roomSize.h]);

  const nearKiosk = Math.hypot(pos.x - KIOSK_PCT.x, (pos.y - KIOSK_PCT.y) * (roomSize.h / roomSize.w)) < KIOSK_RANGE_PCT;
  // [CRITICAL BUG FIX] This was missing entirely - `avatar.img` below (used
  // to render the player's own avatar walking around the Lobby) referenced
  // a completely undefined variable, throwing a ReferenceError on every
  // single Lobby render. Since the Lobby is the app's default/entry
  // screen and there's no error boundary, this crashed the whole React
  // tree on load - a guaranteed blank screen, every time, for every
  // player.
  const avatar = getAvatar(playerAvatarId);

  // Opening the editor also force-stops the walk animation/footstep state,
  // in case the dialog opened mid-step (e.g. a touch held over from the
  // joystick) — otherwise the avatar could keep "walking" visually behind
  // the dialog for a moment.
  const openEditor = () => {
    setIsMoving(false);
    lastFootstepRef.current = 0;
    setShowEditor(true);
  };

  const joyStart = (e) => {
    joyRef.current.active = true;
    const t = e.touches ? e.touches[0] : e;
    joyBaseRef.current._origin = { x: t.clientX, y: t.clientY };
  };
  const joyMove = (e) => {
    if (!joyRef.current.active) return;
    const t = e.touches ? e.touches[0] : e;
    const origin = joyBaseRef.current._origin;
    if (!origin) return;
    let dx = t.clientX - origin.x, dy = t.clientY - origin.y;
    const mag = Math.sqrt(dx * dx + dy * dy);
    const max = 36;
    if (mag > max) { dx = (dx / mag) * max; dy = (dy / mag) * max; }
    setKnob({ x: dx, y: dy });
    joyRef.current.dx = dx / max; joyRef.current.dy = dy / max;
  };
  const joyEnd = () => {
    joyRef.current.active = false; joyRef.current.dx = 0; joyRef.current.dy = 0;
    setKnob({ x: 0, y: 0 });
  };

  // [BUG FIX] Same Telegram-window-shake fix as the in-game joystick -
  // register touchstart/touchmove as NON-passive so preventDefault()
  // actually stops the drag bubbling up to Telegram as a page gesture.
  // [BUG FIX] This previously only ever handled touchstart/touchmove
  // natively, relying on React's own onTouchEnd prop (a separate, PASSIVE
  // synthetic listener) to reset joyRef.current.active back to false.
  // The actual "joystick gets stuck until I refresh the page" bug: if a
  // touch sequence ever gets interrupted (an incoming call/notification,
  // the OS taking over the gesture, switching apps mid-drag, etc.), the
  // browser fires 'touchcancel' instead of 'touchend' - which nothing
  // here was ever listening for at all. active stayed stuck at true
  // forever with no way to reset it short of a full reload. Now both
  // touchend AND touchcancel are handled natively, right alongside
  // touchstart/touchmove, so every way a touch sequence can end is
  // actually covered.
  useEffect(() => {
    const el = joyBaseRef.current;
    if (!el) return;
    const startNP = (e) => { e.preventDefault(); joyStart(e); };
    const moveNP = (e) => { e.preventDefault(); joyMove(e); };
    const endNP = (e) => { e.preventDefault(); joyEnd(); };
    el.addEventListener('touchstart', startNP, { passive: false });
    el.addEventListener('touchmove', moveNP, { passive: false });
    el.addEventListener('touchend', endNP, { passive: false });
    el.addEventListener('touchcancel', endNP, { passive: false });
    return () => {
      el.removeEventListener('touchstart', startNP);
      el.removeEventListener('touchmove', moveNP);
      el.removeEventListener('touchend', endNP);
      el.removeEventListener('touchcancel', endNP);
    };
  }, []);

  if (hasLeft) {
    return (
      <div style={{
        position: 'absolute', inset: 0, background: '#05070a',
        display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 24,
      }}>
        <div style={{ textAlign: 'center', maxWidth: 280 }}>
          <p style={{ fontSize: 15, fontWeight: 800, color: '#fff', margin: '0 0 8px' }}>You've left</p>
          <p style={{ fontSize: 12, color: '#6a7570', margin: '0 0 22px', lineHeight: 1.5 }}>
            You can close this tab, or rejoin the lobby below.
          </p>
          <button onClick={() => { setHasLeft(false); onRejoin?.(); }} style={{
            padding: '11px 26px', borderRadius: 999, border: 'none',
            background: 'linear-gradient(135deg,#6effc0,#2bb88a)', color: '#06140d',
            fontWeight: 800, fontSize: 13,
          }}>Rejoin Lobby</button>
        </div>
      </div>
    );
  }

  return (
    <div style={{ position: 'absolute', inset: 0, background: '#05070a', overflow: 'hidden' }}>
      <div style={{
        position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center',
        padding: '16px 16px 110px',
      }}>
        <div ref={roomRef} style={{
          position: 'relative', width: '100%', maxWidth: 480, aspectRatio: '1536 / 1024',
          borderRadius: 14, overflow: 'hidden', boxShadow: '0 8px 40px rgba(0,0,0,0.6)',
        }}>
          <img src={LOBBY_BG_IMG} alt="" style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover', display: 'block' }} />

          {/* Kiosk interaction hint + hotspot, anchored on the real green
              "NEAR" screen in the art (top-left), not a generic marker.
              The hint sits directly over the monitor screen itself rather
              than above/below the room — the player triggers this from
              the floor below (y >= ~21%), well clear of the monitor
              (y <= 20%), so the two never overlap. zIndex kept below the
              avatar (5) so walking near doesn't draw the box on top of
              the character either way. */}
          {nearKiosk && (
            <div onClick={openEditor} style={{
              position: 'absolute', left: '14.65%', top: '9.3%', width: '14%', height: '10.7%',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              background: 'rgba(5,9,7,0.82)', border: '1.5px solid rgba(110,255,192,0.7)',
              borderRadius: 4, zIndex: 4, cursor: 'pointer', padding: '2px 3px', boxSizing: 'border-box',
            }}>
              <span style={{ fontSize: 7.5, fontWeight: 700, color: '#6effc0', textAlign: 'center', lineHeight: 1.25 }}>
                Tap to edit avatar/name
              </span>
            </div>
          )}
          {!nearKiosk && (
            <div onClick={openEditor} style={{
              position: 'absolute', left: '14.65%', top: '9.3%', width: '14%', height: '10.7%',
              zIndex: 4, cursor: 'pointer', borderRadius: 6,
            }} />
          )}

          {/* [NEW FEATURE] Bouncing arrow pointing at the NEAR-screen edit
              hotspot, so a first-time player immediately sees where to set
              their avatar & name. Hidden once they walk up close (the tap
              prompt above takes over at that point). */}
          {!nearKiosk && (
            <div style={{
              position: 'absolute', left: '14.65%', top: '20.5%', width: '14%',
              display: 'flex', flexDirection: 'column', alignItems: 'center', zIndex: 5,
              pointerEvents: 'none', animation: 'editArrowBounce 1.1s ease-in-out infinite',
            }}>
              <span style={{ fontSize: 15, lineHeight: 1, color: '#6effc0', filter: 'drop-shadow(0 1px 2px rgba(0,0,0,0.8))' }}>▲</span>
              <span style={{
                marginTop: 2, fontSize: 8, fontWeight: 800, color: '#06140d',
                background: '#6effc0', borderRadius: 5, padding: '2px 6px', whiteSpace: 'nowrap',
                boxShadow: '0 1px 4px rgba(0,0,0,0.5)',
              }}>Edit avatar &amp; name</span>
            </div>
          )}

          {/* [MULTIPLAYER] Other real players, visible moving around the
              same Lobby room in real time — uses otherLobbyPlayers (kept
              separate from in-game otherPlayers, see its declaration
              above for why) and each player's own avatarId/facing isn't
              tracked here yet, so we look up their avatar from roomInfo's
              player list by id. */}
          {Object.entries(otherLobbyPlayers).map(([id, lp]) => {
            // [RELIABILITY FIX] Look up avatar/name from roomInfo if
            // available, but FALL BACK to whatever was last cached on
            // this entry (via the sync-effect above, which writes
            // avatarId onto otherLobbyPlayers itself) if roomInfo hasn't
            // caught up yet — this is what stops a player's avatar from
            // briefly vanishing/flickering on a frame where roomInfo and
            // otherLobbyPlayers are very slightly out of sync (a position
            // update arriving a tick before/after the corresponding
            // player-list update).
            const info = roomInfo?.players?.find((p) => p.id === id);
            const avatarId = info?.avatarId || lp.avatarId;
            if (!avatarId) return null;
            // [BUG FIX] Also require a real numeric x/y before rendering
            // at all - without this check, a player who just joined (and
            // whose roomInfo entry/avatarId arrived before their very
            // first lobbyMove broadcast) would render with
            // left:"undefined%"/top:"undefined%", which most browsers
            // either silently treat as 0 (snapping the avatar to the
            // Lobby's top-left corner) or simply fail to position at all
            // - this is the "sometimes doesn't show up when someone new
            // joins" bug: it wasn't random, it was specifically whenever
            // the player-list update won a race against that player's
            // own first position broadcast.
            if (typeof lp.x !== 'number' || typeof lp.y !== 'number') return null;
            return (
              <div key={id} style={{
                position: 'absolute', left: `${lp.x}%`, top: `${lp.y}%`, width: 24, height: 24, zIndex: 5,
                pointerEvents: 'none', transform: 'translate(-50%, -60%)',
                // [BUG FIX] No CSS transition here anymore - the
                // interpolation loop in the movement useEffect now
                // already eases this position toward its target every
                // frame, so a CSS transition on top of that was
                // double-smoothing (and at faster speed levels, actively
                // fighting the interpolation's own per-frame jumps,
                // which is part of what looked like "dragging").
              }}>
                <img src={getAvatar(avatarId).img} alt="" style={{
                  width: '100%', height: '100%', objectFit: 'contain', display: 'block',
                  filter: 'drop-shadow(0 2px 3px rgba(0,0,0,0.5))',
                }} />
              </div>
            );
          })}

          {/* Player avatar in lobby — identical sizing/flip/bounce logic to
              the in-game avatar, just positioned in % instead of screen px. */}
          <div style={{
            position: 'absolute', left: `${pos.x}%`, top: `${pos.y}%`, width: 24, height: 24, zIndex: 5,
            pointerEvents: 'none',
            transform: `translate(-50%, -60%) scaleX(${facing === 'left' ? -1 : 1})`,
          }}>
            <img src={avatar.img} alt="" style={{
              width: '100%', height: '100%', objectFit: 'contain', display: 'block',
              animation: isMoving ? 'avatarWalkBob 0.32s ease-in-out infinite' : 'none',
              filter: 'drop-shadow(0 2px 3px rgba(0,0,0,0.5))',
            }} />
          </div>
          <style>{`
            @keyframes avatarWalkBob {
              0%, 100% { transform: translateY(0); }
              50% { transform: translateY(-3px); }
            }
          `}</style>
        </div>
      </div>

      {/* [UPDATE] Removed the top "Walk up to the NEAR screen..." banner -
          redundant now that the floating bounce-arrow hint (see
          !nearKiosk block above) already points players to the same
          spot, and this text was eating up header space unnecessarily. */}

      {/* [LAYOUT FIX] Split into two separate columns instead of one
          stacked right-side column - host-setup controls (IMPOSTERS,
          SPEED, Connect/Create/Join) now live on the LEFT (previously
          empty space), and the ROOM player-list stays alone on the
          RIGHT. This is what stops the player-list from growing tall
          enough to collide with the host controls stacked above it -
          they're now in entirely separate areas of the screen instead
          of sharing one column. */}
      <div style={{
        position: 'absolute', top: 38, left: 12, display: 'flex', flexDirection: 'column',
        gap: 6, alignItems: 'flex-start', zIndex: 12,
      }}>
        {isHost && (() => {
          // [BUG FIX] Was a fixed [1,2,3] selector regardless of player
          // count - letting a host pick e.g. 3 Saboteurs with only 4
          // players in the room, leaving just 1 crewmate. Since the win
          // condition requires at least 2 crewmates alive at all times,
          // that left the game mathematically unwinnable for crewmates
          // from the very start (the server now also re-clamps this as a
          // safety net, but disabling the invalid options here up front
          // is what stops the host from picking them in the first place
          // and being confused when their choice silently changes).
          const playerCount = roomInfo?.players?.length || 0;
          const maxImposters = Math.max(1, Math.min(3, playerCount - 2));
          return (
          <div style={{
            background: 'rgba(8,8,13,0.85)', border: '1px solid rgba(255,255,255,0.12)',
            borderRadius: 10, padding: '7px 9px', display: 'flex', alignItems: 'center', gap: 7,
          }}>
            <span style={{ fontSize: 9, color: '#9aa0ad', fontWeight: 700, letterSpacing: 0.3 }}>SABOTEURS</span>
            {[1, 2, 3].map(n => {
              const disabled = n > maxImposters;
              return (
              <button
                key={n}
                onClick={() => !disabled && setImposterCount(n)}
                disabled={disabled}
                title={disabled ? `Needs ${n + 2}+ players` : undefined}
                style={{
                  width: 22, height: 22, borderRadius: 6, border: 'none', fontSize: 11.5, fontWeight: 800,
                  background: disabled ? 'rgba(255,255,255,0.03)' : imposterCount === n ? '#ff5c5c' : 'rgba(255,255,255,0.08)',
                  color: disabled ? '#4a4a52' : imposterCount === n ? '#fff' : '#9aa0ad',
                  opacity: disabled ? 0.5 : 1,
                }}>{n}</button>
              );
            })}
          </div>
          );
        })()}

        {/* [NEW FEATURE] Player movement speed - host-only CONTROL, but
            visible to/applied for EVERYONE (see the speedLevel prop
            passed down and the Lobby movement loop below) - every
            player in the Lobby feels and sees the exact same speed the
            host has chosen, live, immediately, not just once the game
            starts. [UPDATE] 5 levels are now 50/75/100/125/150% (was
            25/50/75/100/125 - 25% was rarely used and felt too slow;
            150% added as a new faster option). Level 4 (100%) is now
            the default. */}
        {isHost ? (
          <div style={{
            background: 'rgba(8,8,13,0.85)', border: '1px solid rgba(255,255,255,0.12)',
            borderRadius: 10, padding: '7px 9px', display: 'flex', alignItems: 'center', gap: 5,
          }}>
            <span style={{ fontSize: 9, color: '#9aa0ad', fontWeight: 700, letterSpacing: 0.3 }}>SPEED</span>
            {[2, 3, 4, 5, 6].map(n => (
              <button key={n} onClick={() => {
                // [BUG FIX] No longer calls setSpeedLevel(n) directly -
                // the host used to see their own speed change instantly
                // (zero-latency local state update) while every other
                // player had to wait for the network round-trip through
                // lobbySpeedChanged, which made the host's own movement
                // visibly speed up/slow down before anyone else's did.
                // Now the host waits for that same server echo too, so
                // everyone (host included) updates at exactly the same
                // moment - a tiny bit less "instant" for the host, but
                // perfectly synchronized for the whole room.
                if (socket && socket.connected) {
                  socket.emit('lobbySpeedChange', { speedLevel: n });
                }
              }} style={{
                width: 24, height: 22, borderRadius: 6, border: 'none', fontSize: 9.5, fontWeight: 800,
                display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 0,
                background: speedLevel === n ? '#6effc0' : 'rgba(255,255,255,0.08)',
                color: speedLevel === n ? '#06140d' : '#9aa0ad',
              }}>{n * 25}</button>
            ))}
          </div>
        ) : (
          // [NEW FEATURE] Non-host players see the current speed too
          // (read-only) - so everyone can judge for themselves whether
          // it feels right, even though only the host can change it.
          <div style={{
            background: 'rgba(8,8,13,0.85)', border: '1px solid rgba(255,255,255,0.12)',
            borderRadius: 10, padding: '7px 9px', display: 'flex', alignItems: 'center', gap: 6,
          }}>
            <span style={{ fontSize: 9, color: '#9aa0ad', fontWeight: 700, letterSpacing: 0.3 }}>SPEED</span>
            <span style={{ fontSize: 11, color: '#6effc0', fontWeight: 800 }}>{speedLevel * 25}%</span>
          </div>
        )}

        {/* [MULTIPLAYER] Real room create/join controls — replaces the old
            dev-only "Test as" toggle. Role no longer comes from a local
            toggle; it's assigned secretly by the server once Start is
            pressed (see roleAssigned handling in MovementDemo). */}
        {!roomInfo && (
          <div style={{
            background: 'rgba(8,8,13,0.9)', border: '1px solid rgba(255,255,255,0.12)',
            borderRadius: 10, padding: '8px 9px', display: 'flex', flexDirection: 'column',
            gap: 6, minWidth: 150,
          }}>
            {connStatus !== 'connected' ? (
              <>
                {/* [UPDATE] No longer a button to tap - the Lobby now
                    auto-connects on its own the moment it's opened (see
                    the useEffect below), since the player already went
                    through Home → Play to get here, "Connect to Server"
                    as a separate manual step no longer makes sense. Only
                    shown as status text; a tap-to-retry link appears if
                    it ever actually fails/disconnects. */}
                <div style={{
                  padding: '7px 10px', borderRadius: 8, fontSize: 11, fontWeight: 700,
                  background: 'rgba(110,255,192,0.15)', color: '#6effc0', textAlign: 'center',
                }}>
                  {connStatus === 'connecting' ? 'Connecting…' : 'Reconnecting…'}
                </div>
                {connStatus === 'connecting' && (
                  <SlowConnectNotice />
                )}
                {connStatus === 'disconnected' && (
                  <span onClick={onConnect} style={{ fontSize: 10, color: '#8fe3ff', textAlign: 'center', cursor: 'pointer' }}>
                    Tap to retry
                  </span>
                )}
              </>
            ) : (
              <>
                <button onClick={() => setShowCreateConfirm(true)} style={{
                  padding: '7px 10px', borderRadius: 8, border: 'none', fontSize: 11, fontWeight: 700,
                  background: '#6effc0', color: '#06140d',
                }}>Create Room</button>
                <div style={{ display: 'flex', gap: 5 }}>
                  <input
                    value={joinCodeInput}
                    onChange={e => setJoinCodeInput(e.target.value.toUpperCase())}
                    placeholder="ROOM CODE"
                    maxLength={4}
                    style={{
                      flex: 1, padding: '6px 8px', borderRadius: 6, border: '1px solid rgba(255,255,255,0.2)',
                      background: 'rgba(255,255,255,0.05)', color: '#fff', fontSize: 11, letterSpacing: 1,
                    }}
                  />
                  <button onClick={() => onJoinRoom(joinCodeInput)} style={{
                    padding: '6px 10px', borderRadius: 6, border: 'none', fontSize: 11, fontWeight: 700,
                    background: '#37a', color: '#fff',
                  }}>Join</button>
                </div>
                {joinError && <span style={{ fontSize: 9.5, color: '#ff8a8a' }}>{joinError}</span>}
              </>
            )}
          </div>
        )}
      </div>

      {/* [LAYOUT FIX] Player-list now lives alone on the right side,
          separate from the host-controls column on the left - this is
          what actually stops the two from ever colliding/overlapping,
          regardless of how many players join or how many host-controls
          are visible. */}
      <div style={{
        position: 'absolute', top: 38, right: 12, display: 'flex', flexDirection: 'column',
        gap: 6, alignItems: 'flex-end', zIndex: 12,
      }}>
        {roomInfo && (
          <div style={{
            background: 'rgba(8,8,13,0.9)', border: '1px solid rgba(110,255,192,0.35)',
            borderRadius: 10, padding: '8px 9px', display: 'flex', flexDirection: 'column',
            gap: 4, minWidth: 150, maxWidth: 220,
          }}>
            <span style={{ fontSize: 10, color: '#6effc0', fontWeight: 800 }}>
              ROOM: {roomInfo.code}
            </span>
            {/* [NEW FEATURE] Public/private status - lives inside the
                existing room-info panel (not a new floating overlay), so
                it can never collide with any other Lobby element. The
                HOST can tap it to toggle live; everyone else just sees
                the current state, read-only. */}
            {isHost ? (
              <div
                onClick={() => socket?.emit('setRoomVisibility', { isPublic: !roomInfo.isPublic })}
                style={{
                  display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 6,
                  background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.12)',
                  borderRadius: 7, padding: '4px 7px', cursor: 'pointer',
                }}
              >
                <span style={{ fontSize: 9.5, fontWeight: 700, color: roomInfo.isPublic ? '#8fe3ff' : '#c0c7c2' }}>
                  {roomInfo.isPublic ? '🌍 Public' : '🔒 Private'}
                </span>
                <div style={{
                  width: 26, height: 15, borderRadius: 999, flexShrink: 0, position: 'relative',
                  background: roomInfo.isPublic ? 'linear-gradient(135deg,#6effc0,#2bb88a)' : 'rgba(255,255,255,0.18)',
                  transition: 'background 0.2s',
                }}>
                  <div style={{
                    position: 'absolute', top: 1.5, left: roomInfo.isPublic ? 12.5 : 1.5,
                    width: 12, height: 12, borderRadius: '50%', background: '#fff',
                    transition: 'left 0.2s',
                  }} />
                </div>
              </div>
            ) : (
              <span style={{
                fontSize: 9.5, fontWeight: 700, color: roomInfo.isPublic ? '#8fe3ff' : '#8a9088',
                background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)',
                borderRadius: 7, padding: '4px 7px', textAlign: 'center',
              }}>
                {roomInfo.isPublic ? '🌍 Public room' : '🔒 Private room'}
              </span>
            )}
            {/* [DEV-BRANCH ONLY TEST FEATURE] Dev Mode toggle - same
                pattern as the Public/Private toggle above. Off by default.
                When ON: min players to start drops to 2, and the round
                won't auto-end on kill/vote (see checkWinCondition), so a
                host testing solo with 2 devices can exercise the full
                kill → meeting → chat → voting flow without the game
                cutting short. When 4+ real players show up, the host can
                just leave this OFF and everything behaves exactly like
                the live game. THIS ENTIRE BLOCK MUST NEVER BE MERGED TO
                THE LIVE/MAIN BRANCH. */}
            {isHost ? (
              <div
                onClick={() => socket?.emit('setDevMode', { devMode: !roomInfo.devMode })}
                style={{
                  display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 6,
                  background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.12)',
                  borderRadius: 7, padding: '4px 7px', cursor: 'pointer',
                }}
              >
                <span style={{ fontSize: 9.5, fontWeight: 700, color: roomInfo.devMode ? '#ff9f5a' : '#c0c7c2' }}>
                  {roomInfo.devMode ? '🛠 Dev Mode ON' : '🛠 Dev Mode'}
                </span>
                <div style={{
                  width: 26, height: 15, borderRadius: 999, flexShrink: 0, position: 'relative',
                  background: roomInfo.devMode ? 'linear-gradient(135deg,#ffb95a,#e0762b)' : 'rgba(255,255,255,0.18)',
                  transition: 'background 0.2s',
                }}>
                  <div style={{
                    position: 'absolute', top: 1.5, left: roomInfo.devMode ? 12.5 : 1.5,
                    width: 12, height: 12, borderRadius: '50%', background: '#fff',
                    transition: 'left 0.2s',
                  }} />
                </div>
              </div>
            ) : roomInfo.devMode ? (
              <span style={{
                fontSize: 9.5, fontWeight: 700, color: '#ff9f5a',
                background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)',
                borderRadius: 7, padding: '4px 7px', textAlign: 'center',
              }}>
                🛠 Dev Mode ON
              </span>
            ) : null}
            {/* [BUG FIX] Switched from a single vertical column to a
                2-column grid - with 10+ players, a single column grew
                tall enough to run off the bottom of the screen and
                overlap the joystick/Start button. A 2-column layout cuts
                the vertical space roughly in half for the same number
                of players. maxHeight+overflow is a safety net for any
                still-larger player counts, so it scrolls instead of
                ever overflowing past the screen again. */}
            <div style={{
              display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '2px 8px',
              maxHeight: '22vh', overflowY: 'auto',
            }}>
              {(() => {
                // [BUG FIX] Only treat inLobbyView as meaningful if AT
                // LEAST one player in the room actually has it set to
                // true - that's the signal "a game has ended and people
                // are trickling back," as opposed to a brand new room
                // where nobody has ever played yet (where every player's
                // inLobbyView is simply absent/false, and dimming
                // everyone would be wrong/confusing).
                const anyoneReturned = roomInfo.players.some((p) => p.inLobbyView === true);
                return roomInfo.players.map(p => (
                  <span key={p.id} style={{
                    fontSize: 9.5, color: '#cfd3da', display: 'flex', alignItems: 'center', gap: 4,
                    overflow: 'hidden', whiteSpace: 'nowrap',
                    opacity: anyoneReturned && p.inLobbyView !== true ? 0.45 : 1,
                  }}>
                    {p.isHost ? '👑' : '•'}
                    <img src={getAvatar(p.avatarId).img} alt="" style={{ width: 12, height: 12, objectFit: 'contain', flexShrink: 0 }} />
                    <span style={{ overflow: 'hidden', textOverflow: 'ellipsis' }}>{displayPlayerName(p.name, p.avatarId)}</span>
                  </span>
                ));
              })()}
            </div>
          </div>
        )}
      </div>

      {/* Start / Leave — Among-Us-style pill buttons, bottom corners, well
          clear of the center joystick.
          [MULTIPLAYER] Only the HOST sees/uses the Start button now — it
          sends startGame to the server, which secretly assigns roles to
          everyone in the room. Non-host players don't need a Start button
          at all: their screen transitions automatically the moment their
          own roleAssigned event arrives (handled in MovementDemo). */}
      <button onClick={() => {
        // [UPDATE] "Leave" now sends the player back to the Home screen
        // (via the onLeaveToHome prop, up to MovementDemo's screen
        // state) instead of showing this component's own local
        // goodbye/"Rejoin Lobby" screen - Home is the natural place to
        // land now that it exists, with its own "▶ Play" button to get
        // back into a room.
        socket?.emit('leaveRoom');
        try {
          localStorage.removeItem('nearSaboteurRoomCode');
          localStorage.removeItem('nearSaboteurPlayerToken');
        } catch (e) { /* localStorage unavailable */ }
        onLeaveToHome?.();
      }} style={{
        position: 'absolute', left: 18, bottom: 22, padding: '13px 26px', borderRadius: 999,
        border: '2px solid #ff5c5c', background: 'rgba(255,92,92,0.12)', color: '#ff8a8a',
        fontWeight: 800, fontSize: 13.5, letterSpacing: 0.3, zIndex: 15,
      }}>LEAVE</button>
      {isHost && (
        <button onClick={canStartGame ? () => onStart({ imposterCount, speedLevel }) : undefined} disabled={!canStartGame} style={{
          position: 'absolute', right: 18, bottom: 22, padding: '13px 30px', borderRadius: 999,
          border: canStartGame ? 'none' : '2px solid rgba(255,255,255,0.15)',
          background: canStartGame ? 'linear-gradient(135deg,#6effc0,#2bb88a)' : 'rgba(255,255,255,0.06)',
          color: canStartGame ? '#06140d' : '#5a655f',
          fontWeight: 800, fontSize: 13.5, letterSpacing: 0.3, zIndex: 15,
          boxShadow: canStartGame ? '0 0 18px rgba(110,255,192,0.55)' : 'none',
          animation: canStartGame ? 'lobbyStartGlow 1.6s ease-in-out infinite' : 'none',
        }}>START</button>
      )}
      {!isHost && roomInfo && (
        <div style={{
          position: 'absolute', right: 18, bottom: 22, padding: '13px 20px', borderRadius: 999,
          border: '2px solid rgba(255,255,255,0.15)', color: '#9aa0ad',
          fontWeight: 700, fontSize: 12, zIndex: 15,
        }}>Waiting for host…</div>
      )}
      <style>{`
        @keyframes lobbyStartGlow {
          0%, 100% { box-shadow: 0 0 14px rgba(110,255,192,0.45); }
          50% { box-shadow: 0 0 26px rgba(110,255,192,0.85); }
        }
        @keyframes editArrowBounce {
          0%, 100% { transform: translateY(0); }
          50% { transform: translateY(-6px); }
        }
      `}</style>
      {/* [BUG FIX] The minimum-players notice used to be a tiny faint
          grey line that was easy to miss entirely - hosts didn't realise
          WHY the Start button wasn't working. Now it's a clear amber pill
          with the live count and exactly how many more players are
          needed. Only the not-enough-players case gets the prominent
          badge; the pre-room hint stays a subtle line. */}
      {(!roomInfo || roomInfo.players.length < effectiveMinPlayers) && (
        !roomInfo ? (
          <p style={{ position: 'absolute', bottom: 185, left: 0, right: 0, textAlign: 'center', fontSize: 10, color: '#5a655f', padding: '0 16px' }}>
            Connect and create/join a room to play with friends
          </p>
        ) : (
          <div style={{
            position: 'absolute', bottom: 185, left: '50%', transform: 'translateX(-50%)',
            display: 'flex', alignItems: 'center', gap: 8, whiteSpace: 'nowrap',
            background: 'rgba(255,180,60,0.14)', border: '1.5px solid rgba(255,180,60,0.55)',
            borderRadius: 999, padding: '8px 16px',
          }}>
            <span style={{ fontSize: 15 }}>👥</span>
            <span style={{ fontSize: 13, fontWeight: 800, color: '#ffce7a' }}>
              {roomInfo.players.length} / {effectiveMinPlayers} players
            </span>
            <span style={{ fontSize: 12, fontWeight: 600, color: '#d8b878' }}>
              — need {effectiveMinPlayers - roomInfo.players.length} more to start
            </span>
          </div>
        )
      )}

      {/* Joystick — same bottom-center placement and size as in-game. */}
      <div ref={joyBaseRef}
        onMouseDown={joyStart} onMouseMove={joyMove} onMouseUp={joyEnd} onMouseLeave={joyEnd}
        onTouchEnd={joyEnd}
        style={{
          position: 'absolute', bottom: 65, left: '50%', transform: 'translateX(-50%)',
          width: 110, height: 110, borderRadius: '50%',
          background: 'rgba(255,255,255,0.06)', border: '2px solid rgba(255,255,255,0.25)',
          touchAction: 'none', zIndex: 10, display: 'flex', alignItems: 'center', justifyContent: 'center',
        }}>
        <div style={{
          width: 46, height: 46, borderRadius: '50%',
          background: joyRef.current.active ? 'rgba(110,255,192,0.85)' : 'rgba(255,255,255,0.35)',
          border: '2px solid rgba(255,255,255,0.5)',
          transform: `translate(${knob.x}px,${knob.y}px)`, pointerEvents: 'none',
        }} />
      </div>

      {/* [NEW FEATURE] Lobby chat - floating round button, left-middle
          edge (clear of the host-controls panel above it, the LEAVE
          button below it, and the joystick which stays centered) with
          an unread-count badge (1-9 exact, "9+" beyond that). Tapping
          opens the full chat panel below. Only ever rendered/usable here
          in the Lobby - there is no equivalent button anywhere in actual
          gameplay, this whole feature is Lobby-only by design. */}
      {roomInfo && (
        <button
          onClick={() => setShowLobbyChat(true)}
          style={{
            position: 'absolute', left: 12, top: '55%', transform: 'translateY(-50%)', zIndex: 20,
            width: 42, height: 42, borderRadius: '50%', border: '2px solid rgba(110,255,192,0.55)',
            background: 'rgba(8,8,13,0.88)', display: 'flex', alignItems: 'center', justifyContent: 'center',
            fontSize: 18, padding: 0,
          }}
        >
          💬
          {lobbyChatUnread > 0 && (
            <span style={{
              position: 'absolute', top: -4, right: -4, minWidth: 17, height: 17, borderRadius: 999,
              background: '#ff5c5c', color: '#fff', fontSize: 9.5, fontWeight: 800,
              display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '0 3px',
              border: '1.5px solid #05070a',
            }}>{lobbyChatUnread > 9 ? '9+' : lobbyChatUnread}</span>
          )}
        </button>
      )}

      {/* [NEW FEATURE] Lobby chat panel - full message list with reply
          support and auto-scroll (both on new messages and while
          typing - see the effects that own lobbyChatScrollRef). Talks
          to whoever is currently in this same Lobby room, nobody else. */}
      {showLobbyChat && (
        <div style={{
          position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.82)', zIndex: 40,
          display: 'flex', alignItems: 'flex-end', padding: 0,
        }} onClick={() => setShowLobbyChat(false)}>
          <div onClick={(e) => e.stopPropagation()} style={{
            width: '100%', maxHeight: '72%', background: 'linear-gradient(180deg, #0d1a14, #081210)',
            borderTopLeftRadius: 16, borderTopRightRadius: 16, border: '1px solid rgba(110,255,192,0.25)',
            borderBottom: 'none', display: 'flex', flexDirection: 'column', overflow: 'hidden',
          }}>
            <div style={{
              display: 'flex', alignItems: 'center', justifyContent: 'space-between',
              padding: '12px 14px', borderBottom: '1px solid rgba(255,255,255,0.08)', flexShrink: 0,
            }}>
              <span style={{ fontSize: 13, fontWeight: 800, color: '#6effc0' }}>💬 Lobby Chat</span>
              <button onClick={() => setShowLobbyChat(false)} style={{
                width: 26, height: 26, borderRadius: '50%', background: 'rgba(255,255,255,0.08)',
                border: 'none', color: '#e8e8f0', fontSize: 12,
              }}>✕</button>
            </div>

            <div ref={lobbyChatScrollRef} style={{ flex: 1, overflowY: 'auto', padding: '10px 14px', display: 'flex', flexDirection: 'column', gap: 8 }}>
              {lobbyChatMessages.length === 0 ? (
                <p style={{ fontSize: 11.5, color: '#5a655f', textAlign: 'center', marginTop: 20 }}>No messages yet - say hi!</p>
              ) : lobbyChatMessages.map((m) => {
                const shouting = isAllCapsMessage(m.text);
                return (
                <div key={m.id} onClick={() => setLobbyReplyingTo({ senderName: m.authorName, text: m.text })} style={{
                  alignSelf: m.isSelf ? 'flex-end' : 'flex-start', maxWidth: '82%', cursor: 'pointer',
                }}>
                  {!m.isSelf && (
                    <p style={{ fontSize: 9.5, color: '#5fc8ff', fontWeight: 700, margin: '0 0 2px 2px' }}>{m.authorName}</p>
                  )}
                  <div style={{
                    background: shouting ? 'linear-gradient(135deg,#ffd75e,#e8a831)' : (m.isSelf ? 'rgba(110,255,192,0.16)' : 'rgba(255,255,255,0.07)'),
                    border: shouting ? '1px solid rgba(255,255,255,0.4)' : `1px solid ${m.isSelf ? 'rgba(110,255,192,0.3)' : 'rgba(255,255,255,0.1)'}`,
                    boxShadow: shouting ? '0 0 10px rgba(255,215,94,0.5)' : 'none',
                    borderRadius: 12, padding: '7px 10px',
                  }}>
                    {m.replyTo && (
                      <div style={{
                        borderLeft: '2px solid rgba(110,255,192,0.5)', paddingLeft: 6, marginBottom: 4,
                        opacity: 0.75,
                      }}>
                        <p style={{ fontSize: 9, fontWeight: 700, color: '#6effc0', margin: 0 }}>{m.replyTo.senderName}</p>
                        <p style={{ fontSize: 9.5, color: '#c8c8c8', margin: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{m.replyTo.text}</p>
                      </div>
                    )}
                    <p style={{ fontSize: 12, color: shouting ? '#241a00' : '#e8e8f0', fontWeight: shouting ? 800 : 400, margin: 0, wordBreak: 'break-word' }}>{m.text}</p>
                  </div>
                </div>
                );
              })}
            </div>

            {/* Reply preview - tapping any message above sets this; a
                small "replying to X" strip above the input, same idea
                as the meeting/ghost chat reply feature elsewhere. */}
            {lobbyReplyingTo && (
              <div style={{
                display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                padding: '6px 14px', background: 'rgba(110,255,192,0.08)', borderTop: '1px solid rgba(255,255,255,0.08)',
              }}>
                <div style={{ overflow: 'hidden' }}>
                  <p style={{ fontSize: 9.5, fontWeight: 700, color: '#6effc0', margin: 0 }}>Replying to {lobbyReplyingTo.senderName}</p>
                  <p style={{ fontSize: 10, color: '#9aa0ad', margin: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{lobbyReplyingTo.text}</p>
                </div>
                <button onClick={() => setLobbyReplyingTo(null)} style={{ background: 'none', border: 'none', color: '#9aa0ad', fontSize: 14, flexShrink: 0, marginLeft: 8 }}>✕</button>
              </div>
            )}

            <div style={{ display: 'flex', gap: 8, padding: '10px 14px', borderTop: '1px solid rgba(255,255,255,0.08)', flexShrink: 0 }}>
              <input
                value={lobbyChatDraft}
                onChange={(e) => setLobbyChatDraft(e.target.value)}
                onKeyDown={(e) => { if (e.key === 'Enter') sendLobbyChatMessage(); }}
                placeholder="Message the Lobby…"
                maxLength={200}
                style={{
                  flex: 1, background: 'rgba(255,255,255,0.06)', border: '1px solid rgba(255,255,255,0.15)',
                  borderRadius: 20, padding: '9px 14px', color: '#e8e8f0', fontSize: 13,
                }}
              />
              <button onClick={sendLobbyChatMessage} disabled={!lobbyChatDraft.trim()} style={{
                width: 38, height: 38, borderRadius: '50%', border: 'none', flexShrink: 0,
                background: lobbyChatDraft.trim() ? '#6effc0' : 'rgba(255,255,255,0.08)',
                color: lobbyChatDraft.trim() ? '#06140d' : '#5a655f', fontSize: 15,
              }}>➤</button>
            </div>
          </div>
        </div>
      )}


      {/* [NEW FEATURE] Create-room confirmation - avoids accidentally
          creating a new room when the user actually wanted to join a
          friend's existing one. */}
      {showCreateConfirm && (
        <div style={{
          position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.8)',
          display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 35, padding: 20,
        }}>
          <div style={{
            background: 'linear-gradient(160deg, #0d1a14, #05100b)', borderRadius: 16,
            padding: '22px 20px 18px', width: '100%', maxWidth: 320,
            border: '1px solid rgba(110,255,192,0.25)', textAlign: 'center',
          }}>
            <div style={{ fontSize: 30, marginBottom: 8 }}>🚪</div>
            <h3 style={{ fontSize: 16, fontWeight: 800, color: '#fff', margin: '0 0 8px' }}>
              Create a new room?
            </h3>
            <p style={{ fontSize: 12.5, color: '#9aa39c', margin: '0 0 20px', lineHeight: 1.5 }}>
              This starts a brand new room with you as the host. If you meant to join a
              friend's room instead, go back and enter their room code.
            </p>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 9 }}>
              <button onClick={() => { setShowCreateConfirm(false); onCreateRoom(); }} style={{
                padding: '12px', borderRadius: 999, border: 'none', fontSize: 13.5, fontWeight: 800,
                background: 'linear-gradient(135deg,#6effc0,#2bb88a)', color: '#06140d',
              }}>Create New Room</button>
              <button onClick={() => setShowCreateConfirm(false)} style={{
                padding: '12px', borderRadius: 999, border: '1px solid rgba(255,255,255,0.2)',
                background: 'transparent', color: '#c0c7c2', fontSize: 13, fontWeight: 700,
              }}>Cancel — I'll join a room instead</button>
            </div>
          </div>
        </div>
      )}

      {showEditor && (
        <div style={{
          position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.78)',
          display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 30, padding: 16,
        }}>
          <div style={{
            background: 'linear-gradient(160deg, #0d1a14, #05100b)', borderRadius: 16,
            padding: '18px 18px 16px', width: '100%', maxWidth: 320,
            border: '1px solid rgba(110,255,192,0.25)', maxHeight: '80vh', overflowY: 'auto',
          }}>
            <h3 style={{ fontSize: 14, fontWeight: 800, color: '#fff', margin: '0 0 12px' }}>Customize</h3>

            <p style={{ fontSize: 9.5, color: '#6a7570', letterSpacing: 0.3, margin: '0 0 6px' }}>NAME</p>
            <input
              value={nameInput} onChange={e => setNameInput(e.target.value)} maxLength={16}
              placeholder="Your name"
              style={{
                width: '100%', boxSizing: 'border-box', padding: '9px 11px', borderRadius: 9,
                background: 'rgba(255,255,255,0.06)', border: '1px solid rgba(110,255,192,0.25)',
                color: '#fff', fontSize: 13.5, outline: 'none', marginBottom: 14,
              }}
            />

            <p style={{ fontSize: 9.5, color: '#6a7570', letterSpacing: 0.3, margin: '0 0 8px' }}>AVATAR</p>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', gap: 8, marginBottom: 16 }}>
              {AVATARS.map(a => {
                // [MULTIPLAYER] An avatar already used by another player in
                // this room can't be picked — prevents two players showing
                // up looking identical, which would make them impossible
                // to tell apart in-game. Our own currently-selected avatar
                // is excluded from this check (so re-selecting what we
                // already have never blocks itself).
                const takenByOther = roomInfo?.players?.some(
                  (p) => p.avatarId === a.id && p.id !== socket?.id
                );
                return (
                  <button
                    key={a.id}
                    onClick={() => {
                      if (takenByOther) return;
                      setPlayerAvatarId(a.id);
                      if (socket && socket.connected && roomInfo) {
                        socket.emit('updateProfile', { avatarId: a.id });
                      }
                    }}
                    disabled={takenByOther}
                    style={{
                      display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 3,
                      padding: '6px 2px', borderRadius: 9,
                      background: playerAvatarId === a.id ? 'rgba(110,255,192,0.16)' : 'rgba(255,255,255,0.04)',
                      border: playerAvatarId === a.id ? '1.5px solid #6effc0' : '1px solid rgba(255,255,255,0.08)',
                      opacity: takenByOther ? 0.3 : 1,
                    }}
                  >
                    <img src={a.img} alt="" style={{ width: 28, height: 'auto', display: 'block' }} />
                    <span style={{ fontSize: 8, color: '#9aa0ad' }}>{a.name}</span>
                  </button>
                );
              })}
            </div>

            <button onClick={() => {
              setPlayerName(nameInput);
              setShowEditor(false);
              // [MULTIPLAYER] If we already joined/created a room before
              // opening this editor, the server still has our OLD name —
              // push the update so everyone else's player-list refreshes too.
              if (socket && socket.connected && roomInfo) {
                socket.emit('updateProfile', { name: nameInput });
              }
            }} style={{
              width: '100%', padding: '11px 0', borderRadius: 10, border: 'none',
              background: 'linear-gradient(135deg,#6effc0,#2bb88a)', color: '#06140d', fontWeight: 800, fontSize: 13,
            }}>Done</button>
          </div>
        </div>
      )}
    </div>
  );
}

function MovementDemo() {
  const cafe = ROOMS.find(r => r.id === 'cafeteria');
  // Spawn beside the central table (not on it — the table is now solid and would trap the player).
  const startPx = spawnPointPx(0);
  const [screen, setScreen] = useState('auth'); // [LOCAL-UI]
  const [playerName, setPlayerName] = useState(''); // [PER-PLAYER]
  const [playerAvatarId, setPlayerAvatarId] = useState(() => AVATARS[Math.floor(Math.random() * AVATARS.length)].id); // [PER-PLAYER]

  // [DEV-BRANCH ONLY - PHASE 2 STEP 1] Account auth state - email+password
  // signup with OTP verification, login, forgot/reset password. Talks
  // directly to the backend's /auth/* routes (plain fetch, not
  // Socket.io - these are one-shot HTTP calls, not real-time events).
  // THIS BLOCK MUST NEVER BE MERGED TO THE LIVE/MAIN BRANCH UNTIL FULLY
  // TESTED ON DEV.
  const [authMode, setAuthMode] = useState('login'); // 'login' | 'signup' | 'verifyOtp' | 'forgot' | 'resetOtp'
  const [authEmail, setAuthEmail] = useState('');
  const [authPassword, setAuthPassword] = useState('');
  const [authOtp, setAuthOtp] = useState('');
  const [authNewPassword, setAuthNewPassword] = useState('');
  const [authError, setAuthError] = useState('');
  // [DEV-BRANCH ONLY - PHASE 2] Show/hide toggles for every password
  // field in the app - one boolean per field, since each is its own
  // independent input.
  const [showAuthPassword, setShowAuthPassword] = useState(false);
  const [showAuthNewPassword, setShowAuthNewPassword] = useState(false);
  const [showWalletCreatePassword, setShowWalletCreatePassword] = useState(false);
  const [showViewSeedPassword, setShowViewSeedPassword] = useState(false);
  const [showDeletePassword, setShowDeletePassword] = useState(false);

  const [authInfo, setAuthInfo] = useState('');
  const [authLoading, setAuthLoading] = useState(false);
  const [loggedInPlayer, setLoggedInPlayer] = useState(null);
  // [DEV-BRANCH ONLY - PHASE 2] Guest mode - "Play as Guest" on the
  // login screen skips account creation, wallet setup, and profile
  // setup entirely and drops the player straight onto Home. Guests can
  // only use Free Play (everything else on Home shows a "create a
  // profile" notice instead, per the agreed design) and never earn
  // points, since there's no account for points to attach to.
  const [isGuestPlayer, setIsGuestPlayer] = useState(false);
  const [showGuestLockedNotice, setShowGuestLockedNotice] = useState(false);
  function handlePlayAsGuest() {
    setIsGuestPlayer(true);
    setLoggedInPlayer(null);
    setPlayerName('Guest');
    setScreen('home');
  }
  // Wrap any Home button that requires a real account with this - shows
  // the locked notice for guests instead of running the action, runs
  // the action normally for everyone else.
  function guestGuard(action) {
    return (...args) => {
      if (isGuestPlayer) { setShowGuestLockedNotice(true); return; }
      action(...args);
    };
  }
  // [DEV-BRANCH ONLY - PHASE 2] Toggles the Home screen's Settings menu
  // (currently just Log out - a placeholder for future buttons like
  // account settings, wallet management, etc).
  const [showHomeSettings, setShowHomeSettings] = useState(false);

  // [DEV-BRANCH ONLY - PHASE 2] Home screen data - announcements (posted
  // directly in MongoDB Atlas, no admin UI needed - see the Announcement
  // schema comment on the backend) and live public rooms (polled every
  // 6s while on the Home screen so it feels roughly live without a
  // dedicated websocket subscription just for this one list).
  const [announcements, setAnnouncements] = useState([]);
  const [publicRooms, setPublicRooms] = useState([]);
  // [DEV-BRANCH ONLY - PHASE 2] Set when tapping a room in Home's live
  // public rooms list - LobbyScreen picks this up to pre-fill its own
  // join-code field, so the player just taps the existing "Join Room"
  // button themselves (reuses all the existing connect/join logic
  // untouched, this is purely a convenience pre-fill).
  const [prefillJoinCode, setPrefillJoinCode] = useState('');
  // [DEV-BRANCH ONLY - PHASE 2] Which Home hub tile's modal is open, if
  // any - 'wallet' | 'leaderboard' | 'pools' | 'rooms' | 'announcements' | null.
  // The Home screen itself is a fixed single-viewport grid of tiles (no
  // scrolling); each tile's actual content lives in its own full-screen
  // modal instead, which is what keeps everything reachable without the
  // hub screen itself ever needing to scroll or cut content off.
  const [homeModal, setHomeModal] = useState(null);
  // [DEV-BRANCH ONLY - PHASE 2] Home screen avatar carousel - lets the
  // player browse their 10 available avatars directly from Home instead
  // of going into Profile Edit. Switches instantly (also updates the
  // header's own profile picture, since both read the same
  // playerAvatarId), and persists the choice to the account in the
  // background via the same /profile/setup endpoint Profile Edit
  // already uses - debounced so rapidly tapping through avatars doesn't
  // fire one request per tap.
  const [avatarAnimDir, setAvatarAnimDir] = useState(1);
  const [avatarAnimKey, setAvatarAnimKey] = useState(0);
  const avatarPersistTimerRef = useRef(null);
  function changeHomeAvatar(dir) {
    const idx = AVATARS.findIndex((a) => a.id === playerAvatarId);
    const next = AVATARS[(idx + dir + AVATARS.length) % AVATARS.length];
    setAvatarAnimDir(dir);
    setAvatarAnimKey((k) => k + 1);
    setPlayerAvatarId(next.id);
    if (avatarPersistTimerRef.current) clearTimeout(avatarPersistTimerRef.current);
    if (loggedInPlayer?.username) {
      avatarPersistTimerRef.current = setTimeout(() => {
        authFetch('/profile/setup', {
          email: authEmail,
          name: (playerName || loggedInPlayer.name || '').trim(),
          username: loggedInPlayer.username,
          avatarId: next.id,
        }).then((data) => setLoggedInPlayer(data.player)).catch(() => {});
      }, 600);
    }
  }
  useEffect(() => {
    if (screen !== 'home') return;
    let cancelled = false;
    async function loadHomeData() {
      try {
        const [annRes, roomsRes] = await Promise.all([
          fetch(`${BACKEND_URL}/announcements`).then((r) => r.json()),
          fetch(`${BACKEND_URL}/rooms/public`).then((r) => r.json()),
        ]);
        if (cancelled) return;
        if (Array.isArray(annRes.announcements)) setAnnouncements(annRes.announcements);
        if (Array.isArray(roomsRes.rooms)) setPublicRooms(roomsRes.rooms);
      } catch (e) { /* Home screen still works without this data */ }
    }
    loadHomeData();
    const interval = setInterval(loadHomeData, 6000);
    return () => { cancelled = true; clearInterval(interval); };
  }, [screen]);

  async function authFetch(path, body) {
    const res = await fetch(`${BACKEND_URL}${path}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    let data = {};
    try { data = await res.json(); } catch (e) { /* non-JSON error page */ }
    if (!res.ok) throw new Error(data.message || 'Something went wrong.');
    return data;
  }

  // [DEV-BRANCH ONLY - PHASE 2] "Encrypted keystore" helpers for
  // in-game wallets - all done with the browser's own Web Crypto API,
  // nothing here ever leaves the device except the final ciphertext
  // (which is useless without the password). PBKDF2 turns the account
  // password into an AES-GCM key (a random salt makes this different
  // every time, even for the same password); AES-GCM then encrypts the
  // private key with a random IV. Decryption is the same process in
  // reverse, given the right password.
  function bufToB64(buf) {
    return btoa(String.fromCharCode(...new Uint8Array(buf)));
  }
  function b64ToBuf(b64) {
    return Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
  }
  async function deriveKeyFromPassword(password, saltBytes) {
    const enc = new TextEncoder();
    const keyMaterial = await crypto.subtle.importKey('raw', enc.encode(password), 'PBKDF2', false, ['deriveKey']);
    return crypto.subtle.deriveKey(
      { name: 'PBKDF2', salt: saltBytes, iterations: 150000, hash: 'SHA-256' },
      keyMaterial,
      { name: 'AES-GCM', length: 256 },
      false,
      ['encrypt', 'decrypt']
    );
  }
  async function encryptPrivateKey(secretKeyStr, password) {
    const salt = crypto.getRandomValues(new Uint8Array(16));
    const iv = crypto.getRandomValues(new Uint8Array(12));
    const key = await deriveKeyFromPassword(password, salt);
    const enc = new TextEncoder();
    const ciphertext = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, enc.encode(secretKeyStr));
    return { ciphertext: bufToB64(ciphertext), salt: bufToB64(salt), iv: bufToB64(iv) };
  }
  async function decryptPrivateKey(ciphertextB64, saltB64, ivB64, password) {
    const salt = b64ToBuf(saltB64);
    const iv = b64ToBuf(ivB64);
    const key = await deriveKeyFromPassword(password, salt);
    const plainBuf = await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, key, b64ToBuf(ciphertextB64));
    return new TextDecoder().decode(plainBuf);
  }

  async function handleSignup() {
    setAuthError(''); setAuthInfo(''); setAuthLoading(true);
    try {
      const data = await authFetch('/auth/signup', { email: authEmail, password: authPassword });
      setAuthInfo(data.message);
      setAuthMode('verifyOtp');
    } catch (err) { setAuthError(err.message); }
    setAuthLoading(false);
  }

  // [DEV-BRANCH ONLY - PHASE 2] Persists the session token (never the
  // password) to localStorage, so reopening the app can restore login
  // via /auth/session instead of asking to log in again. Same pattern
  // the existing room-reconnect feature already uses for roomCode/
  // playerToken - see the reconnect-attempt effect elsewhere in this
  // file.
  function saveSession(email, sessionToken) {
    try {
      localStorage.setItem('nearSaboteurAuthEmail', email);
      localStorage.setItem('nearSaboteurSessionToken', sessionToken);
    } catch (e) { /* localStorage unavailable - session just won't persist */ }
  }
  function clearSession() {
    try {
      localStorage.removeItem('nearSaboteurAuthEmail');
      localStorage.removeItem('nearSaboteurSessionToken');
    } catch (e) { /* localStorage unavailable */ }
  }

  async function handleVerifyOtp() {
    setAuthError(''); setAuthInfo(''); setAuthLoading(true);
    try {
      const data = await authFetch('/auth/verify-otp', { email: authEmail, otp: authOtp });
      setLoggedInPlayer(data.player);
      if (data.sessionToken) saveSession(authEmail, data.sessionToken);
      setScreen('walletChoice');
    } catch (err) { setAuthError(err.message); }
    setAuthLoading(false);
  }

  // [DEV-BRANCH ONLY - PHASE 2] Decides where a player lands after
  // login/verify, based on how much of onboarding they've already
  // completed - so a returning player never has to redo a step.
  function nextScreenForPlayer(player) {
    if (!player.walletType || player.walletType === 'none') return 'walletChoice';
    if (!player.name || !player.username) return 'profileSetup';
    return 'home';
  }

  async function handleLogin() {
    setAuthError(''); setAuthInfo(''); setAuthLoading(true);
    try {
      const data = await authFetch('/auth/login', { email: authEmail, password: authPassword });
      setLoggedInPlayer(data.player);
      if (data.sessionToken) saveSession(authEmail, data.sessionToken);
      if (data.player.name) setPlayerName(data.player.name);
      if (data.player.avatarId) setPlayerAvatarId(data.player.avatarId);
      setScreen(nextScreenForPlayer(data.player));
    } catch (err) { setAuthError(err.message); }
    setAuthLoading(false);
  }

  // [DEV-BRANCH ONLY - PHASE 2] On mount, check for a saved session
  // token and try to restore it silently - if it works, the player
  // lands straight back where they left off instead of seeing the
  // login screen at all. Failure (expired/invalid token, or no token
  // saved yet) just leaves them on the normal login screen, same as
  // today. Runs once.
  const [sessionRestoring, setSessionRestoring] = useState(true);
  useEffect(() => {
    let cancelled = false;
    (async () => {
      let savedEmail = null, savedToken = null;
      try {
        savedEmail = localStorage.getItem('nearSaboteurAuthEmail');
        savedToken = localStorage.getItem('nearSaboteurSessionToken');
      } catch (e) { /* localStorage unavailable */ }
      if (!savedToken) { setSessionRestoring(false); return; }
      try {
        const data = await authFetch('/auth/session', { sessionToken: savedToken });
        if (cancelled) return;
        setAuthEmail(savedEmail || data.player.email);
        setLoggedInPlayer(data.player);
        if (data.player.name) setPlayerName(data.player.name);
        if (data.player.avatarId) setPlayerAvatarId(data.player.avatarId);
        setScreen(nextScreenForPlayer(data.player));
      } catch (err) {
        clearSession(); // stale/expired token - fall back to normal login
      }
      if (!cancelled) setSessionRestoring(false);
    })();
    return () => { cancelled = true; };
  }, []);

  async function handleForgotPassword() {
    setAuthError(''); setAuthInfo(''); setAuthLoading(true);
    try {
      const data = await authFetch('/auth/forgot-password', { email: authEmail });
      setAuthInfo(data.message);
      setAuthMode('resetOtp');
    } catch (err) { setAuthError(err.message); }
    setAuthLoading(false);
  }

  async function handleResetPassword() {
    setAuthError(''); setAuthInfo(''); setAuthLoading(true);
    try {
      await authFetch('/auth/reset-password', { email: authEmail, otp: authOtp, newPassword: authNewPassword });
      setAuthPassword(''); setAuthOtp(''); setAuthNewPassword('');
      // [UPDATE] If this was triggered mid-session (from Profile/
      // Settings, while already logged in) go straight back to Home -
      // no need to log in again, they just proved account ownership via
      // OTP. Only the true "forgot password, logged out" path still
      // lands on the login screen.
      if (loggedInPlayer) {
        setAuthInfo(''); setAuthMode('login');
        setScreen('home');
      } else {
        setAuthInfo('Password updated. You can now log in.');
        setAuthMode('login');
      }
    } catch (err) { setAuthError(err.message); }
    setAuthLoading(false);
  }

  // [DEV-BRANCH ONLY - PHASE 2] Wallet connect/create state (testnet
  // only). walletSelector/walletModal are the NEAR Wallet Selector
  // instances (async to set up, so they're lazily created once the
  // player actually reaches the wallet-choice screen, not on every
  // page load). newWalletSeed holds a freshly-generated in-game
  // wallet's private key ONLY long enough to show it to the player once
  // - it is never sent anywhere, and is cleared from state as soon as
  // they confirm they've saved it. THIS BLOCK MUST NEVER BE MERGED TO
  // THE LIVE/MAIN BRANCH.
  const [walletSelector, setWalletSelector] = useState(null);
  const [walletModal, setWalletModal] = useState(null);
  const [walletLoading, setWalletLoading] = useState(false);
  const [walletError, setWalletError] = useState('');
  const [newWalletSeed, setNewWalletSeed] = useState(null); // { accountId, secretKey }
  const [seedSavedConfirmed, setSeedSavedConfirmed] = useState(false);

  // Lazily initializes the wallet selector once the player reaches the
  // wallet-choice screen. Never runs during normal gameplay/Lobby use,
  // so it can't add any load time for players who never touch the
  // wallet screen.
  useEffect(() => {
    if (screen !== 'walletChoice' || walletSelector) return;
    let cancelled = false;
    (async () => {
      try {
        const selector = await setupWalletSelector({
          network: 'testnet',
          modules: [setupHotWallet(), setupMeteorWallet(), setupIntearWallet()],
        });
        if (cancelled) return;
        const modal = setupModal(selector, {});
        setWalletSelector(selector);
        setWalletModal(modal);
      } catch (err) {
        if (!cancelled) setWalletError('Could not load wallet options: ' + err.message);
      }
    })();
    return () => { cancelled = true; };
  }, [screen, walletSelector]);

  // Fires once the player finishes signing in through the wallet
  // selector's modal (any of HOT/Meteor/Intear). Saves the resulting
  // PUBLIC account id to the backend - the wallet itself always keeps
  // the private key, this app never sees or touches it.
  useEffect(() => {
    if (!walletSelector) return;
    const sub = walletSelector.on('signedIn', async ({ accounts }) => {
      const accountId = accounts && accounts[0] && accounts[0].accountId;
      if (!accountId) return;
      setWalletLoading(true); setWalletError('');
      try {
        const data = await authFetch('/wallet/connect', { email: authEmail, walletAddress: accountId });
        setLoggedInPlayer(data.player);
        setScreen('profileSetup');
      } catch (err) { setWalletError(err.message); }
      setWalletLoading(false);
    });
    return () => sub.remove();
  }, [walletSelector, authEmail]);

  function handleConnectWallet() {
    setWalletError('');
    if (!walletModal) {
      setWalletError('Wallet options are still loading — try again in a moment.');
      return;
    }
    walletModal.show();
  }

  // Generates a real ed25519 keypair client-side (near-api-js) and
  // derives its testnet implicit account id (the hex encoding of the
  // raw public key bytes - this is how NEAR resolves an as-yet-unfunded
  // "implicit account" without needing a separate registration step).
  // The private key touches ONLY this browser tab's memory/state -
  // never sent to the backend, never logged. It's shown to the player
  // exactly once (see the confirmation screen below) so they can save
  // it; if they navigate away before confirming, it's gone for good,
  // same as any real wallet's seed phrase.
  function handleGenerateWallet() {
    setWalletError('');
    try {
      const keyPair = KeyPair.fromRandom('ed25519');
      const publicKey = keyPair.getPublicKey();
      const accountId = Array.from(publicKey.data).map((b) => b.toString(16).padStart(2, '0')).join('');
      setNewWalletSeed({ accountId, secretKey: keyPair.toString() });
      setSeedSavedConfirmed(false);
    } catch (err) {
      setWalletError('Could not generate a wallet: ' + err.message);
    }
  }

  // [DEV-BRANCH ONLY - PHASE 2] Password used to encrypt the new
  // in-game wallet's keystore. Pre-filled from authPassword when
  // available (the common case - right after signup/login), but always
  // editable/required, since a session restored from a saved token
  // never has the password in memory at all.
  const [walletCreatePassword, setWalletCreatePassword] = useState('');
  useEffect(() => {
    if (screen === 'walletChoice' && authPassword) setWalletCreatePassword(authPassword);
  }, [screen, authPassword]);

  async function handleConfirmWalletCreated() {
    if (!newWalletSeed) return;
    if (!walletCreatePassword) {
      setWalletError('Enter your account password to secure this wallet.');
      return;
    }
    setWalletLoading(true); setWalletError('');
    try {
      const { ciphertext, salt, iv } = await encryptPrivateKey(newWalletSeed.secretKey, walletCreatePassword);
      const data = await authFetch('/wallet/create', {
        email: authEmail, walletAddress: newWalletSeed.accountId,
        keystoreCiphertext: ciphertext, keystoreSalt: salt, keystoreIv: iv,
      });
      setLoggedInPlayer(data.player);
      setNewWalletSeed(null);
      setWalletCreatePassword('');
      setScreen('profileSetup');
    } catch (err) { setWalletError(err.message); }
    setWalletLoading(false);
  }

  // [DEV-BRANCH ONLY - PHASE 2] Profile Setup/Edit - name + unique
  // username. [UPDATE] Avatar selection removed from here entirely -
  // avatar choice stays a per-match thing in the Lobby only (see
  // AVATARS/getAvatar there), never part of the account profile. This
  // same screen/state serves BOTH the initial post-wallet setup
  // (screen 'profileSetup') AND later edits from Settings (screen
  // 'profileEdit') - see isEditingProfile below. THIS BLOCK MUST NEVER
  // BE MERGED TO THE LIVE/MAIN BRANCH.
  const [profileUsername, setProfileUsername] = useState('');
  const [profileError, setProfileError] = useState('');
  const [profileLoading, setProfileLoading] = useState(false);
  const [walletCopied, setWalletCopied] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  // [DEV-BRANCH ONLY - PHASE 2] "View Seed Phrase" - password-gated
  // reveal of an in-game wallet's private key, decrypted entirely
  // client-side (see decryptPrivateKey). Only ever possible for
  // walletType 'ingame' - connected wallets never had a key to store in
  // the first place.
  const [showViewSeedModal, setShowViewSeedModal] = useState(false);
  const [viewSeedPassword, setViewSeedPassword] = useState('');
  const [viewSeedError, setViewSeedError] = useState('');
  const [viewSeedLoading, setViewSeedLoading] = useState(false);
  const [revealedSeed, setRevealedSeed] = useState('');

  async function handleViewSeedPhrase() {
    setViewSeedError('');
    if (!viewSeedPassword) {
      setViewSeedError('Enter your account password.');
      return;
    }
    setViewSeedLoading(true);
    try {
      const data = await authFetch('/wallet/keystore', { email: authEmail, password: viewSeedPassword });
      const secretKey = await decryptPrivateKey(data.keystoreCiphertext, data.keystoreSalt, data.keystoreIv, viewSeedPassword);
      setRevealedSeed(secretKey);
    } catch (err) {
      // A wrong password produces a decrypt failure here (AES-GCM
      // authentication fails), not a clean error message - normalize it
      // to the same friendly text as a backend-rejected password.
      setViewSeedError(err.message && err.message !== 'Something went wrong.' ? err.message : 'Incorrect password.');
    }
    setViewSeedLoading(false);
  }

  const [deletePassword, setDeletePassword] = useState('');
  const [deleteError, setDeleteError] = useState('');
  const [deleteLoading, setDeleteLoading] = useState(false);

  // Keeps the username field pre-filled with whatever's already saved -
  // covers both re-entering this screen via Settings, and a session
  // restored from a saved token on app load.
  useEffect(() => {
    if (loggedInPlayer?.username) setProfileUsername(loggedInPlayer.username);
  }, [loggedInPlayer]);

  async function handleSaveProfile() {
    setProfileError('');
    if (!playerName.trim()) {
      setProfileError('Please enter a name.');
      return;
    }
    if (!profileUsername.trim()) {
      setProfileError('Please enter a username.');
      return;
    }
    setProfileLoading(true);
    try {
      const data = await authFetch('/profile/setup', { email: authEmail, name: playerName.trim(), username: profileUsername.trim(), avatarId: playerAvatarId });
      setLoggedInPlayer(data.player);
      setScreen('home');
    } catch (err) { setProfileError(err.message); }
    setProfileLoading(false);
  }

  function handleCopyWallet() {
    const addr = loggedInPlayer?.walletAddress || '';
    if (!addr) return;
    try {
      navigator.clipboard?.writeText(addr);
      setWalletCopied(true);
      setTimeout(() => setWalletCopied(false), 1500);
    } catch (e) { /* clipboard unavailable */ }
  }

  // [DEV-BRANCH ONLY - PHASE 2] Reset Password - reachable both from
  // inside the Profile screen and from the Settings menu directly.
  // Reuses the existing OTP-based forgot/reset flow on the auth screen
  // (pre-filled with the known email) rather than duplicating it.
  function handleGoToResetPassword() {
    setAuthMode('forgot');
    setAuthEmail(loggedInPlayer?.email || authEmail);
    setAuthError(''); setAuthInfo('');
    setScreen('auth');
  }

  // [DEV-BRANCH ONLY - PHASE 2] Delete Profile - permanent, requires
  // the account password as confirmation (matches the backend's own
  // requirement - see /profile/delete). No undo once this succeeds.
  async function handleDeleteProfile() {
    setDeleteError('');
    if (!deletePassword) {
      setDeleteError('Enter your password to confirm.');
      return;
    }
    setDeleteLoading(true);
    try {
      await authFetch('/profile/delete', { email: authEmail, password: deletePassword });
      clearSession();
      setLoggedInPlayer(null);
      setAuthEmail(''); setAuthPassword(''); setAuthOtp(''); setAuthNewPassword('');
      setDeletePassword(''); setShowDeleteConfirm(false);
      setAuthMode('login'); setAuthError(''); setAuthInfo('Your account has been deleted.');
      setScreen('auth');
    } catch (err) { setDeleteError(err.message); }
    setDeleteLoading(false);
  }

  // [DEV-BRANCH ONLY - PHASE 2] Logout - invalidates the session token
  // server-side (fire-and-forget, never blocks the local logout), clears
  // it from localStorage, and clears all account state, sending the
  // player back to the login screen. Room/game state isn't touched
  // (this screen only exists before a room is ever joined).
  function handleLogout() {
    if (authEmail) {
      fetch(`${BACKEND_URL}/auth/logout`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: authEmail }),
      }).catch(() => {});
    }
    clearSession();
    setLoggedInPlayer(null);
    setIsGuestPlayer(false);
    setAuthEmail(''); setAuthPassword(''); setAuthOtp(''); setAuthNewPassword('');
    setAuthMode('login'); setAuthError(''); setAuthInfo('');
    setScreen('auth');
    setShowHomeSettings(false);
  }

  // [NEW FEATURE] Telegram Mini App integration. Safe to run even outside
  // Telegram (window.Telegram is simply undefined in a normal browser, so
  // this whole block is a no-op there) - same code works for both the
  // regular web version and the Telegram WebView.
  useEffect(() => {
    const tg = window.Telegram?.WebApp;
    if (!tg) return;
    // Tells Telegram the app has finished loading and is ready to be
    // shown - without this, Telegram may keep its own loading
    // spinner up indefinitely.
    tg.ready();
    // Expands the WebView to full height immediately (otherwise it opens
    // in a half-height "peek" state the user would have to manually
    // drag open).
    tg.expand();
    // [SAFE AREA] Telegram reserves some space at the top (its own close/
    // settings icons) and sometimes the bottom (home-indicator area on
    // iOS) that this app's own HUD shouldn't be drawn underneath. Exposed
    // as CSS variables so any element can opt in via e.g.
    // `paddingTop: 'var(--tg-safe-top, 0px)'` without hardcoding a guess.
    const applySafeArea = () => {
      const root = document.documentElement;
      root.style.setProperty('--tg-safe-top', `${tg.safeAreaInset?.top || 0}px`);
      root.style.setProperty('--tg-safe-bottom', `${tg.safeAreaInset?.bottom || 0}px`);
    };
    applySafeArea();
    tg.onEvent?.('safeAreaChanged', applySafeArea);
    // Matches the page background to Telegram's own theme so there's no
    // jarring white/black flash around the edges while the app loads.
    if (tg.themeParams?.bg_color) {
      document.body.style.background = tg.themeParams.bg_color;
    }
    // Disables Telegram's own "pull down to close" gesture, which would
    // otherwise easily trigger by accident during normal up/down
    // movement-joystick use.
    tg.disableVerticalSwipes?.();

    return () => {
      // [BUG FIX] This used to call tg.onEvent again (adding a second
      // listener) instead of tg.offEvent — so the safeAreaChanged
      // listener was never actually removed on unmount/re-run.
      tg.offEvent?.('safeAreaChanged', applySafeArea);
    };
  }, []);

  // ── [MULTIPLAYER] Socket connection + room state ────────────────────────
  // socketRef holds the ONE shared socket (from getSocket()). connStatus
  // drives the Lobby's "Connect to Server" button. roomInfo mirrors the
  // server's confirmed room state (code + player list) once created/joined.
  // joinError surfaces a failed join attempt in the Lobby UI.
  const socketRef = useRef(null);
  const [connStatus, setConnStatus] = useState('disconnected'); // 'disconnected' | 'connecting' | 'connected' — [LOCAL-UI]
  const [roomInfo, setRoomInfo] = useState(null); // { code, players: [{id,name,avatarId,isHost}] } — [SHARED]
  // [BUG FIX] Ref mirror of roomInfo - the votingResult socket handler is
  // registered once on mount (empty-deps effect) and needs the LATEST
  // player ordering (for Assembly-Hall return spawn assignment below),
  // not whatever roomInfo happened to be at mount time.
  const roomInfoRef = useRef(roomInfo);
  useEffect(() => { roomInfoRef.current = roomInfo; }, [roomInfo]);
  const [joinError, setJoinError] = useState(''); // [LOCAL-UI]

  // [MULTIPLAYER: SHARED] Real roster of other players, synced from the
  // server. Replaces the old solo-test dummy crewmate concept. Keyed by
  // socket id. Each entry: { name, avatarId, x, y, alive, isGhost }.
  const [otherPlayers, setOtherPlayers] = useState({});
  const otherPlayersRef = useRef(otherPlayers);
  useEffect(() => { otherPlayersRef.current = otherPlayers; }, [otherPlayers]);
  // [SMOOTHNESS FIX] otherPlayers itself now holds the DISPLAYED position
  // (what's actually rendered), separate from otherPlayersTargetRef which
  // holds the latest position the server told us about. A dedicated
  // interpolation loop (see the otherPlayersTargetRef effect below) moves
  // the displayed position toward the target a little each tick instead
  // of snapping straight to it — this is what makes other players glide
  // between their throttled (~70ms) position updates instead of visibly
  // jumping, without needing a CSS transition (which caused the
  // shake/flicker bug when combined with the camera following our own
  // movement at 60fps).
  const otherPlayersTargetRef = useRef({});
  const lastPosEmitRef = useRef(0); // [LOCAL-UI] throttle timestamp for playerMove emits
  // [MULTIPLAYER: PER-PLAYER] Whether I (this client) am currently alive.
  // Flipped to false by the playerKilled handler when targetId === my own
  // socket id, or by the votingResult handler if I'm voted out. Once
  // false, ghost rules (movement still visible to other ghosts only, chat
  // read-only, no voting) apply — see the ghost-rule wiring further down.
  const [myAlive, setMyAlive] = useState(true);
  // [BUG FIX] resetGame itself is defined further down (after
  // connectSocket, due to its own dependencies), but the
  // roomResetForNewGame handler inside connectSocket needs to call it.
  // This ref bridges that gap: resetGame assigns itself here once
  // defined, and the handler always reads the LATEST version through the
  // ref rather than closing over a possibly-stale direct reference.
  const resetGameRef = useRef(null);
  const myAliveRef = useRef(true);
  useEffect(() => { myAliveRef.current = myAlive; }, [myAlive]);

  // [WIN CONDITION] Set once the server announces a winner. null while
  // the game is still in progress; { winner: 'saboteur'|'crewmate',
  // reason } once decided. Movement/actions pause for the rest of the
  // game once this is set (checked the same way meeting/killCutscene
  // already pause things, via a ref read inside the rAF loop).
  const [gameResult, setGameResult] = useState(null);
  const gameResultRef = useRef(null);
  useEffect(() => { gameResultRef.current = gameResult; }, [gameResult]);

  const connectSocket = useCallback(() => {
    if (socketRef.current && socketRef.current.connected) return;
    setConnStatus('connecting');
    // [BUG FIX] Nudge the backend awake with a plain HTTP request before
    // attempting the actual Socket.io connection - see wakeBackend's own
    // comment for why this matters more than just raising the
    // WebSocket timeout alone.
    wakeBackend();
    const socket = getSocket();
    socketRef.current = socket;

    socket.off('connect');
    socket.off('disconnect');
    socket.off('roomCreated');
    socket.off('roomJoined');
    socket.off('joinError');
    socket.off('playerListUpdated');
    socket.off('lobbySpeedChanged');
    socket.off('roleAssigned');
    socket.off('startGameError');
    socket.off('reconnected');
    socket.off('reconnectError');
    socket.off('playerDisconnectedMidGame');
    socket.off('playerFrozenMidGame');
    socket.off('gameOver');
    socket.off('roomResetForNewGame');
    socket.off('playAgainError');
    socket.off('playerMoved');
    socket.off('playerKilled');
    socket.off('bodyDropped');
    socket.off('killError');
    socket.off('sabotageTriggered');
    socket.off('sabotageError');
    socket.off('sabotageRepaired');
    socket.off('playerVentTravel');
    socket.off('playerDisguised');
    socket.off('playerDisguiseEnded');
    socket.off('meetingStarted');
    socket.off('meetingError');
    socket.off('taskReminder');
    socket.off('kickedForInactivity');
    socket.off('saboteurKillAlarm');
    socket.off('saboteurKillCountdownStart');
    socket.off('saboteurEliminatedForInactivity');
    socket.off('saboteurTimerCleared');
    socket.off('chatMessageReceived');
    socket.off('ghostChatMessageReceived');
    socket.off('ghostChatBacklog');
    socket.off('lobbyChatMessageReceived');
    socket.off('skipDiscussionUpdate');
    socket.off('voteUpdate');
    socket.off('meetingStageChanged');
    socket.off('discussionSkipped');
    socket.off('votingResult');
    socket.off('voteError');
    socket.off('sabotageStateSync');
    socket.off('chatError');
    socket.off('meetingVotesSync');

    socket.on('connect', () => {
      setConnStatus('connected');
      // [RECONNECTION] If we have a saved room+token from before (e.g.
      // this is a fresh page load after a refresh/reopen, not just our
      // first-ever connect this session), try to silently reattach to
      // our old player slot before the Lobby even renders its
      // create/join buttons.
      try {
        const savedCode = localStorage.getItem('nearSaboteurRoomCode');
        const savedToken = localStorage.getItem('nearSaboteurPlayerToken');
        if (savedCode && savedToken) {
          socket.emit('reconnectToRoom', { code: savedCode, playerToken: savedToken });
        }
      } catch (e) { /* localStorage unavailable */ }
    });
    socket.on('disconnect', () => setConnStatus('disconnected'));

    // Seeds/refreshes otherPlayers from a server player-list, preserving
    // any x/y/alive/isGhost we already know about each id (the player
    // list itself doesn't carry position — that only ever comes via
    // playerMoved — so a naive overwrite would reset everyone to {x:
    // undefined, y: undefined} every time someone joins/leaves).
    const syncOtherPlayersFromList = (players) => {
      setOtherPlayers((prev) => {
        const next = {};
        const validIds = new Set();
        players.forEach((p) => {
          if (p.id === socket.id) return; // exclude self
          validIds.add(p.id);
          next[p.id] = {
            ...(prev[p.id] || {}),
            name: p.name,
            avatarId: p.avatarId,
            // [BUG FIX] This was missing entirely - every playerListUpdated
            // (and the reconnected event itself, which is built from the
            // same getPlayerList shape) silently dropped any active
            // disguise for every OTHER player, even though the server
            // correctly included disguiseAvatarId in the list the whole
            // time. Concretely: if Player A activates a disguise, then
            // Player B refreshes their page, B's reconnect would show A's
            // REAL avatar again instead of the still-active disguise,
            // until some other playerDisguised broadcast happened to
            // re-sync it (or the disguise simply ran out). Now it's kept
            // in sync from the player-list directly, same as every other
            // field here.
            disguiseAvatarId: p.disguiseAvatarId || null,
            // [RENDER FIX] Seed x/y/alive from the server's player-list
            // too (not just from playerMoved broadcasts) — this is what
            // lets a newly-joined player immediately see everyone who's
            // already in the room, instead of waiting for each of them to
            // move at least once before they appear on screen.
            ...(typeof p.x === 'number' ? { x: p.x } : {}),
            ...(typeof p.y === 'number' ? { y: p.y } : {}),
            ...(typeof p.alive === 'boolean' ? { alive: p.alive } : {}),
          };
          // Keep the interpolation target in sync too, so the loop
          // doesn't try to ease from a stale/undefined target later.
          if (typeof p.x === 'number' && typeof p.y === 'number') {
            otherPlayersTargetRef.current = {
              ...otherPlayersTargetRef.current,
              [p.id]: { ...(otherPlayersTargetRef.current[p.id] || {}), x: p.x, y: p.y },
            };
          }
        });
        // [BUG FIX] Pick up any already-dropped bodies from the
        // player-list too (bodyX/bodyY, only present for dead players) -
        // this is what lets a LATE-JOINING or reconnecting player learn
        // about a body that hit the ground before they ever connected,
        // instead of it being permanently invisible to them (no
        // cross/dim avatar, no Report option, since the original
        // bodyDropped/playerKilled broadcast happened before they were
        // listening). Done as its own setDeadBodies call right here
        // rather than threading it through the otherPlayers update
        // above, since deadBodies is a separate piece of state.
        setDeadBodies((prevBodies) => {
          const nextBodies = { ...prevBodies };
          players.forEach((p) => {
            if (p.id === socket.id) return;
            if (typeof p.bodyX === 'number' && typeof p.bodyY === 'number' && !nextBodies[p.id]) {
              // [BUG FIX] If this same dead player already has a body
              // entry under a DIFFERENT (now-stale) key - e.g. they
              // reconnected and got a new socket.id - remove the old one
              // first, deduped by avatarId (stable across reconnects,
              // and guaranteed unique per room). Otherwise the old entry
              // never gets cleaned up, leaving a duplicate corpse marker
              // sitting at the exact same position (visible both on the
              // normal map and in the CCTV body-list).
              for (const oldKey in nextBodies) {
                if (oldKey !== p.id && nextBodies[oldKey].avatarId === p.avatarId) {
                  delete nextBodies[oldKey];
                }
              }
              nextBodies[p.id] = { x: p.bodyX, y: p.bodyY, avatarId: p.avatarId };
            }
          });
          return nextBodies;
        });
        // [BUG FIX] Remove any id from otherPlayersTargetRef that's no
        // longer in the server's player-list at all - previously this
        // ref only ever grew, never shrank, which on its own was mostly
        // harmless (the interpolation loop already skips ids missing
        // from `next`/otherPlayers), but combined with the race-condition
        // fixed server-side in reconnectToRoom, leaving stale target refs
        // around was one more place a disconnected player's old id could
        // theoretically resurface from. Cleaning it here too closes that
        // off completely, not just at the source.
        for (const staleId in otherPlayersTargetRef.current) {
          if (!validIds.has(staleId)) {
            delete otherPlayersTargetRef.current[staleId];
          }
        }
        return next;
      });
    };

    socket.on('roomCreated', (data) => {
      setRoomInfo({ code: data.code, players: data.players, isPublic: !!data.isPublic, devMode: !!data.devMode });
      syncOtherPlayersFromList(data.players);
      setJoinError('');
      // [NEW FEATURE] Sync the room's current speed setting too - the
      // host's own choice is what created this value server-side, but
      // reading it back here keeps a single source of truth (the
      // server) rather than just trusting whatever was already in local
      // state before the room existed.
      if (typeof data.speedLevel === 'number') setSpeedLevel(data.speedLevel);
      // [NEW FEATURE] Lobby chat backlog - empty for a brand new room,
      // but keeps this the single place both roomCreated/roomJoined
      // populate lobby chat history from.
      if (Array.isArray(data.lobbyChat)) setLobbyChatMessages(data.lobbyChat);
      // [RECONNECTION] Save these so a later page-reload/reopen can call
      // reconnectToRoom automatically instead of starting over in the
      // Lobby — see the reconnect-attempt effect further down.
      try {
        localStorage.setItem('nearSaboteurRoomCode', data.code);
        localStorage.setItem('nearSaboteurPlayerToken', data.playerToken);
      } catch (e) { /* localStorage unavailable - reconnection just won't be offered */ }
    });
    socket.on('roomJoined', (data) => {
      setRoomInfo({ code: data.code, players: data.players, isPublic: !!data.isPublic, devMode: !!data.devMode });
      syncOtherPlayersFromList(data.players);
      setJoinError('');
      // [NEW FEATURE] A newly-joined player immediately sees/feels
      // whatever speed the host already set, instead of defaulting to
      // 50% until the game actually starts.
      if (typeof data.speedLevel === 'number') setSpeedLevel(data.speedLevel);
      // [NEW FEATURE] Lobby chat backlog - so joining mid-conversation
      // shows what was already said, not just messages from this point on.
      if (Array.isArray(data.lobbyChat)) setLobbyChatMessages(data.lobbyChat);
      // [AVATAR UNIQUENESS] If the server had to reassign our avatar
      // (because our requested one was already taken by someone else who
      // joined a split-second earlier), reflect that in our own local
      // state too, so what we see ourselves matches what the server
      // actually recorded — otherwise we'd show one avatar to ourselves
      // and a different one to everyone else.
      if (data.avatarId && data.avatarId !== playerAvatarId) {
        setPlayerAvatarId(data.avatarId);
      }
      try {
        localStorage.setItem('nearSaboteurRoomCode', data.code);
        localStorage.setItem('nearSaboteurPlayerToken', data.playerToken);
      } catch (e) { /* localStorage unavailable */ }
    });
    socket.on('joinError', (data) => {
      setJoinError(data.message || 'Could not join room.');
    });
    socket.on('playerListUpdated', (data) => {
      setRoomInfo((prev) => prev ? { ...prev, players: data.players } : prev);
      syncOtherPlayersFromList(data.players);
    });

    // [NEW FEATURE] The host changed the Lobby speed - every player
    // (including the host's own other listeners, harmlessly) gets this
    // live, so everyone feels/sees the new speed immediately while
    // still in the Lobby, not just once the game actually starts.
    socket.on('lobbySpeedChanged', (data) => {
      if (typeof data.speedLevel === 'number') setSpeedLevel(data.speedLevel);
    });

    // [NEW FEATURE] The host toggled the room's public/private status
    // live from the Lobby - every player (host included) gets this
    // immediately so the badge/toggle in the room-info panel always
    // reflects the true current state.
    socket.on('roomVisibilityUpdated', (data) => {
      setRoomInfo((prev) => prev ? { ...prev, isPublic: !!data.isPublic } : prev);
    });

    // [DEV-BRANCH ONLY TEST FEATURE] The host toggled Dev Mode live from
    // the Lobby - every player (host included) gets this immediately so
    // the badge/toggle always reflects the true current state.
    socket.on('devModeUpdated', (data) => {
      setRoomInfo((prev) => prev ? { ...prev, devMode: !!data.devMode } : prev);
    });

    // [RECONNECTION] Server confirms we successfully reattached to our old
    // player slot — restore everything: room info, role, alive-state, and
    // jump straight past the Lobby into the loading screen (or directly to
    // game if it's already past loading — loading itself is brief enough
    // that just always going through it again is simpler and harmless).
    socket.on('reconnected', (data) => {
      setRoomInfo({ code: data.code, players: data.players, isPublic: !!data.isPublic, devMode: !!data.devMode });
      syncOtherPlayersFromList(data.players);
      // [BUG FIX] Find our own server-side data and sync avatarId
      // UNCONDITIONALLY - not just when the game has already started.
      // This was the actual bug: avatarId-sync previously only ran
      // inside the `if (data.gameStarted)` branch below, so reconnecting
      // while STILL IN THE LOBBY (the most common case - refreshing the
      // page before pressing Start) never corrected a stale local
      // avatarId at all, even though the server's copy (which the
      // player-list itself already showed correctly) was right there in
      // myServerData the whole time.
      const myServerData = data.players.find((p) => p.id === socket.id);
      // [BUG FIX] This is what a reconnect (a brief network blip, the tab
      // getting backgrounded, refreshing mid-game, etc.) previously never
      // restored - avatarId/role/alive/etc. below all get synced back
      // from the server, but playerName (local-only React state, with no
      // other restoration path) stayed at whatever it was BEFORE the
      // reconnect completed. On a true fresh page load that's simply ''
      // (its initial default), which is exactly why the OWN player's
      // name tag above their own avatar (the only place that reads the
      // local `playerName` state directly instead of the synced
      // roomInfo.players entry - see displayPlayerName's fallback)
      // could suddenly start showing the avatar's color name instead of
      // the real name the player had actually set, while every OTHER
      // player's tag stayed correct the whole time.
      if (myServerData && myServerData.name && myServerData.name !== playerName) {
        setPlayerName(myServerData.name);
      }
      if (myServerData && myServerData.avatarId && myServerData.avatarId !== playerAvatarId) {
        setPlayerAvatarId(myServerData.avatarId);
      }
      if (data.gameStarted) {
        if (data.role) setPlayerRole(data.role);
        // [BUG FIX] Restore fellow-Saboteur list on reconnect
        if (Array.isArray(data.fellowSaboteurs)) setFellowSaboteurs(data.fellowSaboteurs);
        setMyAlive(data.alive !== false);
        // [BUG FIX] This is THE fix for "someone can end up back in a
        // game that's already over, with nobody else in it" - room.
        // gameStarted deliberately stays true even after a winner is
        // decided (only returnToLobby resets it), so without this
        // explicit check, a player reconnecting after everyone else has
        // already moved on to the win screen would get routed straight
        // into live gameplay instead, alone, with no way back out except
        // waiting for the host to eventually start a new game. Skip
        // straight to the win screen instead - same as if the live
        // gameOver event had just arrived.
        if (data.winner) {
          skipRoleRevealRef.current = true;
          setScreen('game');
          setGameResult({ winner: data.winner, reason: data.reason || null });
          return;
        }
        // [BUG FIX] A reconnecting mid-game player shouldn't see the
        // role-reveal screen again - that's only for a brand new game
        // starting. This flag tells the loading->roleReveal chain effect
        // (below) to skip straight to 'game' instead.
        skipRoleRevealRef.current = true;
        setScreen('loading');
        // [NEW FEATURE] Restore the shared crew-progress meter too, so a
        // reconnecting player sees the correct live % immediately instead
        // of it sitting at 0% until someone else's next mission update.
        if (data.crewProgress && typeof data.crewProgress.percent === 'number') {
          setCrewProgress(data.crewProgress);
        }
        // [BUG FIX] Restore our saved mission list (if the server has
        // one) instead of leaving whatever pickRandomMissions() already
        // generated on this fresh mount - this is THE fix for a page
        // refresh wiping out mission progress and handing the player an
        // entirely new random set. Only ever applies to crewmates
        // (Saboteurs never have a missionsList to begin with, so this
        // safely no-ops for them).
        if (Array.isArray(data.missionsList) && data.missionsList.length > 0) {
          setMyMissions(data.missionsList);
        }
        // [BUG FIX] Restore server-authoritative sabotage/disguise uses
        // and cooldowns too - without this, a refreshed Saboteur's
        // client fell back to fresh defaults (3/3/5/5 uses, no active
        // cooldown) regardless of what they'd actually already used,
        // letting a refresh effectively reset their per-game limits.
        if (data.sabotageUses) {
          setSabotageUsesLeft({
            power: data.sabotageUses.electricity ?? 3,
            hacker: data.sabotageUses.hacker ?? 3,
            gateLeft: data.sabotageUses.gateLeft ?? 5,
            gateRight: data.sabotageUses.gateRight ?? 5,
          });
        }
        if (typeof data.sabotageCooldownUntil === 'number') setSabotageCooldownUntil(data.sabotageCooldownUntil);
        if (typeof data.disguiseUsesLeft === 'number') setDisguiseUsesLeft(data.disguiseUsesLeft);
        if (typeof data.disguiseCooldownUntil === 'number') setDisguiseCooldownUntil(data.disguiseCooldownUntil);
        if (typeof data.killCooldownUntil === 'number') setKillCooldownUntil(data.killCooldownUntil);
        if (typeof data.postKillSabotageLockUntil === 'number') setPostKillLockUntil(data.postKillSabotageLockUntil);
        // [BUG FIX] Restore our own in-progress disguise too, if we
        // refreshed mid-disguise - without this, our own screen showed
        // our real avatar/no countdown badge again after a refresh, even
        // though the server (and every other player) still correctly had
        // the disguise active.
        if (data.activeDisguise && data.activeDisguise.avatarId && data.activeDisguise.endsAt) {
          setDisguiseActive({ avatarId: data.activeDisguise.avatarId, endsAt: data.activeDisguise.endsAt });
        }
        // [BUG FIX] Restore our OWN last-known position from the
        // server's player-list too - syncOtherPlayersFromList
        // deliberately excludes our own id (it's for OTHER players), so
        // without this our own avatar would silently snap back to the
        // default spawn point on every reconnect, while the server still
        // had our actual last position - this mismatch is what made our
        // own avatar appear in the wrong place after a refresh.
        if (myServerData && typeof myServerData.x === 'number' && typeof myServerData.y === 'number') {
          const restoredPos = { x: myServerData.x, y: myServerData.y };
          setPos(restoredPos);
          posRef.current = restoredPos;
        }
        // [BUG FIX] Sync any sabotage that was already active before we
        // reconnected - without this, a player who reconnects mid-game
        // never finds out gates are locked or the power's out, since
        // they missed the original sabotageTriggered broadcast entirely.
        if (data.activeGateLock) {
          setGateLock({ group: data.activeGateLock.group, expiresAt: data.activeGateLock.expiresAt });
        }
        if (data.activeSabotageType === 'electricity') setPowerSabotaged(true);
        else if (data.activeSabotageType === 'hacker') setHackerAttack(true);
      } else {
        // [BUG FIX] Still in the Lobby - restore our Lobby (percentage)
        // position too, the same way the gameStarted branch restores the
        // in-game (pixel) position, so our own avatar reappears exactly
        // where it was instead of snapping back to whatever default spot
        // the Lobby initializes new players at.
        if (myServerData && typeof myServerData.lobbyX === 'number' && typeof myServerData.lobbyY === 'number') {
          const restoredLobbyPos = { x: myServerData.lobbyX, y: myServerData.lobbyY };
          setPos(restoredLobbyPos);
          posRef.current = restoredLobbyPos;
        }
      }
      // [BUG FIX] If a meeting was already active when we connected (we
      // joined late, or reconnected mid-meeting), build our local
      // meeting state from it now - this is THE fix for a late-joining
      // player getting stuck on the regular game screen while everyone
      // else is in a chat/voting screen, with no idea it's even
      // happening. Raw chat messages come back in the server's own
      // internal shape (senderId/senderName/senderAvatar/timestamp) -
      // converted here into the same {authorName, authorAvatarId, isSelf}
      // shape chatMessageReceived already builds, so the rest of the
      // chat-rendering code doesn't need to care how a message arrived.
      if (data.activeMeeting) {
        preMeetingPosRef.current = preMeetingPosRef.current || { ...posRef.current };
        setMeeting({
          stage: data.activeMeeting.stage,
          calledByReason: data.activeMeeting.reason,
          calledByPlayerId: data.activeMeeting.calledBy,
          startedAt: data.activeMeeting.startedAt,
          messages: (data.activeMeeting.messages || []).map((m) => ({
            id: m.timestamp + Math.random(),
            authorName: displayPlayerName(m.senderName, m.senderAvatar),
            authorAvatarId: m.senderAvatar,
            text: m.text,
            isSelf: m.senderId === socket.id,
            replyTo: m.replyTo || null,
          })),
          myVote: data.activeMeeting.liveVotes?.[socket.id] || null,
          result: null,
          deadPlayerNames: data.activeMeeting.deadPlayerNames || [],
          liveVotes: data.activeMeeting.liveVotes || {},
        });
      }
      // [NEW FEATURE] Restore ghost chat history on reconnect - only
      // ever present in the payload at all if this player is currently
      // a ghost (see the server's reconnectToRoom handler).
      if (Array.isArray(data.ghostChat)) {
        setGhostChatMessages(data.ghostChat.map((m) => ({
          id: m.timestamp + Math.random(),
          _ts: m.timestamp,
          _sender: m.senderId,
          authorName: displayPlayerName(m.senderName, m.senderAvatar),
          authorAvatarId: m.senderAvatar,
          text: m.text,
          isSelf: m.senderId === socket.id,
          replyTo: m.replyTo || null,
        })));
      }
      console.log('Reconnected to room', data.code);
    });
    socket.on('reconnectError', (data) => {
      console.log('Reconnect error:', data.message);
      // Saved session is no longer valid (room gone, grace period
      // expired, etc.) - clear it so we don't keep trying forever.
      try {
        localStorage.removeItem('nearSaboteurRoomCode');
        localStorage.removeItem('nearSaboteurPlayerToken');
      } catch (e) { /* localStorage unavailable */ }
    });

    // [DISCONNECT/RECONNECT] Another player dropped mid-game — same
    // alive=false update a kill or vote-out would cause, but explicitly
    // WITHOUT touching deadBodies, since nothing actually happened to them
    // in-fiction (no body should appear where they were standing).
    socket.on('playerFrozenMidGame', (data) => {
      // [WIN-CONDITION PAUSE] This player has disconnected but is still
      // within their grace period — deliberately NOT touching alive
      // here, since they're still counted as alive for win-condition
      // purposes. Their avatar will simply stop receiving position
      // updates and stay frozen wherever they last were, which is all
      // the "visual" treatment this needs for now.
      console.log('Player frozen (disconnected, awaiting reconnect):', data.playerId);
    });

    socket.on('playerDisconnectedMidGame', (data) => {
      setOtherPlayers((prev) => ({
        ...prev,
        [data.playerId]: { ...(prev[data.playerId] || {}), alive: false },
      }));
    });

    // [WIN CONDITION] The server has decided the game is over — store the
    // result so the win-announcement screen renders. Movement/actions
    // pause the same way they do for any other full-screen overlay
    // (meeting, kill cutscene, vent travel) via the existing pause-check
    // pattern, by checking gameResultRef in the rAF loop.
    socket.on('gameOver', (data) => {
      // [BUG FIX] If voting just eliminated the last Saboteur, or a kill
      // just dropped the crew below the win threshold, this event
      // arrives almost simultaneously with votingResult/playerKilled -
      // showing the win-screen immediately would step right over the
      // elimination role-reveal or kill cutscene that should play out
      // first. Wait for whichever is in progress to finish.
      if (awaitingEliminationRevealRef.current) {
        setTimeout(() => setGameResult({ winner: data.winner, reason: data.reason }), 3500);
      } else if (awaitingKillCutsceneRef.current) {
        setTimeout(() => setGameResult({ winner: data.winner, reason: data.reason }), KILL_CUTSCENE_MS);
      } else {
        setGameResult({ winner: data.winner, reason: data.reason });
      }
    });

    // [BUG FIX] The host pressed "Play Again" - every player (host
    // included) gets this and runs the exact same local reset the old
    // "Exit to Lobby" confirm button used (resetGame, defined further
    // down), which clears missions/wallet/sabotage-progress/etc. and
    // sends the screen back to 'lobby'. Crucially, this does NOT touch
    // localStorage or the socket connection at all - everyone stays
    // connected to the SAME room (server already kept the room and
    // everyone's avatar/name intact; only the game-specific state was
    // cleared), which is what keeps the group together instead of each
    // player's old reload-based button scattering them into separate
    // fresh sessions.
    socket.on('roomResetForNewGame', (data) => {
      setRoomInfo((prev) => prev ? { ...prev, players: data.players } : prev);
      resetGameRef.current?.();
    });
    socket.on('playAgainError', (data) => {
      console.log('Play again error:', data.message);
    });

    // [MULTIPLAYER: PER-PLAYER] Server secretly assigns this player's own
    // role once the host presses Start. Saboteurs get no missions at all
    // (same rule the old dev-toggle path used) — they can still open any
    // mission popup to look busy, but completeMission() silently no-ops
    // since nothing matches in myMissions.
    socket.on('roleAssigned', (data) => {
      setPlayerRole(data.role);
      setMyMissions(data.role === 'saboteur' ? [] : pickRandomMissions(MISSIONS_ASSIGNED_COUNT));
      // [BUG FIX] Explicitly clear any leftover state from a PREVIOUS
      // game in this same tab before starting the new one - this is the
      // actual fix for "Saboteur wins announced immediately, before
      // anyone's even played": gameResult (and deadBodies, just in
      // case) could still be holding the previous game's outcome if the
      // player started a fresh game/room without going through the
      // "Play Again"/"Exit to Lobby" buttons that normally clear it
      // (resetGame). Without this, the moment screen flips to 'game'
      // below, the stale gameResult would immediately render the old
      // win screen on top of the brand new game.
      setGameResult(null);
      setDeadBodies({});
      // [BUG FIX] Same "leftover from a previous game" issue as
      // gameResult/deadBodies above - a Saboteur mid-countdown when the
      // PREVIOUS game ended (e.g. voted out, or crew won via missions,
      // before their 7-minute timer would have naturally resolved) could
      // otherwise still see that old countdown/alert ticking away,
      // confusingly overlaid on the brand new game.
      setSaboteurCountdownMs(null);
      setShowSaboteurAlarm(false);
      setShowTaskReminder(false);
      // [NEW FEATURE] Multi-Saboteur awareness: if there's 2+ Saboteurs,
      // the server includes our fellow Saboteurs' name/avatarId here -
      // ONLY ever present for Saboteur sockets, crewmates never get this
      // field at all. Stored for the new role-reveal screen (after
      // loading, before gameplay) and for the persistent in-game
      // name-tag-coloring (so a Saboteur sees their fellow Saboteurs'
      // names in red, everyone else stays white).
      setFellowSaboteurs(Array.isArray(data.fellowSaboteurs) ? data.fellowSaboteurs : []);
      // [NEW FEATURE] Total Saboteur count - safe to reveal to EVERY
      // player (crewmate or Saboteur), since it's just a number, not an
      // identity. Used by the role-reveal screen so a crewmate at least
      // knows how many Saboteurs to watch out for, without ever learning
      // who they are.
      if (typeof data.saboteurCount === 'number') setSaboteurCount(data.saboteurCount);
      // [BUG FIX] A fresh game always starts everyone alive - explicitly
      // restore this here too (on top of the "Return to Lobby" button
      // now calling resetGame()), as defense-in-depth against a ghost's
      // myAlive=false ever surviving into a brand new game.
      if (typeof data.alive === 'boolean') setMyAlive(data.alive);
      // [NEW FEATURE] The host's chosen speed level (1-5, default 2) -
      // applies to every alive player equally for the rest of this game.
      if (typeof data.speedLevel === 'number') setSpeedLevel(data.speedLevel);
      // [SPAWN FIX] Each player gets a unique spawnIndex from the server,
      // so everyone lands on a different cafeteria spawn point instead of
      // all stacking on the same tile and getting stuck inside each other.
      const spawnPos = spawnPointPx(typeof data.spawnIndex === 'number' ? data.spawnIndex : 0);
      setPos(spawnPos);
      posRef.current = spawnPos;
      // [VISIBILITY FIX] Immediately tell the server our spawn position
      // instead of waiting for the movement loop's next throttled tick —
      // this is what lets OTHER players see us right away on their
      // screen, rather than only after we first move.
      socket.emit('playerMove', { x: spawnPos.x, y: spawnPos.y });
      setScreen('loading');
    });
    socket.on('startGameError', (data) => {
      setJoinError(data.message || 'Could not start game.');
    });
    // [NEW FEATURE] Defensive - the visibility toggle is only ever shown
    // to the host, so this should basically never fire, but reusing the
    // same joinError banner if it somehow does (e.g. a stale host-status
    // race) is better than silently doing nothing.
    socket.on('setRoomVisibilityError', (data) => {
      setJoinError(data.message || 'Could not change room visibility.');
    });

    // [MULTIPLAYER: SHARED] Another player's position update. isGhost
    // (sent by the server) marks whether the sender is dead — when true,
    // this update only ever arrives if WE are also a ghost (server-side
    // rule), so no extra client-side filtering is needed here.
    socket.on('playerMoved', (data) => {
      // [SMOOTHNESS FIX] Update the TARGET, not the displayed position
      // directly — the interpolation loop (in the main tick function)
      // reads this ref every frame and eases otherPlayers' displayed x/y
      // toward it gradually, instead of the display snapping straight to
      // wherever the latest network update says.
      const prevTarget = otherPlayersTargetRef.current[data.id] || {};
      otherPlayersTargetRef.current = {
        ...otherPlayersTargetRef.current,
        [data.id]: { ...prevTarget, x: data.x, y: data.y, isGhost: data.isGhost },
      };
      // Also seed the displayed position immediately if this is the
      // FIRST time we've ever heard from this id (no point easing in
      // from {x: undefined, y: undefined} — just appear where they are).
      setOtherPlayers((prev) => {
        if (prev[data.id] && typeof prev[data.id].x === 'number') {
          return prev; // already exists - let the interpolation loop ease it
        }
        return { ...prev, [data.id]: { ...(prev[data.id] || {}), x: data.x, y: data.y, isGhost: data.isGhost } };
      });
    });

    // [FAIRNESS] A kill happened — but this event now ONLY ever arrives
    // for the killer and the victim themselves (the server no longer
    // broadcasts it to the whole room), exactly matching Among Us: nobody
    // else learns anything about this until they personally find the
    // body. The cutscene plays identically for both the killer and victim.
    socket.on('playerKilled', (data) => {
      const isMe = data.targetId === socket.id;
      const amKiller = data.killerId === socket.id;
      const victimPos = isMe ? posRef.current : (otherPlayersRef.current[data.targetId] || {});
      setKillCutscene({
        id: Date.now(),
        stage: 'lunge',
        type: Math.random() < 0.5 ? 'knife' : 'twist',
        dummyWorldX: victimPos.x,
        dummyWorldY: victimPos.y,
        targetId: data.targetId,
        killerId: data.killerId,
      });
      // [BUG FIX] If this kill also ends the game (e.g. it drops the
      // crew below the minimum needed to continue), a near-simultaneous
      // gameOver event would otherwise show the win screen immediately,
      // cutting off the kill cutscene animation before it even plays -
      // the second-to-last Crewmate would appear to vanish with no kill
      // animation at all, replaced instantly by the win announcement.
      // This is only relevant for the killer and victim - they're the
      // only two who ever receive this event (third-party players never
      // see the cutscene, so they have nothing to wait for).
      awaitingKillCutsceneRef.current = true;
      setTimeout(() => { awaitingKillCutsceneRef.current = false; }, KILL_CUTSCENE_MS);
      if (isMe) {
        setKillCooldownUntil(0); // a dead player has no kill cooldown to track
      } else {
        setOtherPlayers((prev) => ({
          ...prev,
          [data.targetId]: { ...(prev[data.targetId] || {}), alive: false },
        }));
      }
      // [BUG FIX] This was never being set at all before - the server
      // correctly starts the killer's cooldown the instant a kill
      // succeeds (killCooldownUntil/postKillSabotageLockUntil), but the
      // killer's own LOCAL client never learned about it from this event
      // (only the victim's branch above ever touched any cooldown
      // state). Without this, the kill button looked immediately ready
      // again right after a real kill, even though the server's own
      // independent cooldown check was correctly rejecting any actual
      // second attempt the whole time.
      if (amKiller) {
        const now = Date.now();
        setKillCooldownUntil(now + KILL_COOLDOWN_MS);
        setPostKillLockUntil(now + POST_KILL_LOCK_MS);
        // [NEW FEATURE] This Saboteur just landed their first (or any)
        // kill - the backend's hasKilled flag permanently exempts them
        // from the kill-timer deadline from now on, so clear any
        // countdown/alert already showing on their screen immediately
        // rather than waiting for it to naturally time out.
        setSaboteurCountdownMs(null);
        setShowSaboteurAlarm(false);
      }
    });

    // [FAIRNESS] Raw body data — sent to everyone EXCEPT the killer/victim
    // (who already have it from the cutscene above). This is just data,
    // never a notification: it lets the body render on a third-party
    // player's map once they happen to walk close enough to see it for
    // themselves, the same way any other player's position is just data
    // rather than an announcement. No popup or banner appears from this
    // alone — canReportBody's existing proximity check is what decides
    // whether THIS player currently sees a Report button.
    socket.on('bodyDropped', (data) => {
      setDeadBodies((prev) => ({
        ...prev,
        [data.bodyOwnerId]: { x: data.x, y: data.y, avatarId: data.avatarId },
      }));
      setOtherPlayers((prev) => ({
        ...prev,
        [data.bodyOwnerId]: { ...(prev[data.bodyOwnerId] || {}), alive: false },
      }));
    });
    socket.on('killError', (data) => {
      // Surfaced nowhere visually for now (kill attempts that fail
      // server-side are rare and self-explanatory — e.g. pressing the
      // button twice in one frame); logged for debugging only.
      console.log('Kill error:', data.message);
    });

    // [MULTIPLAYER: SHARED] Another player (the Saboteur) triggered a
    // sabotage. The server sends this to the whole room (io.to, not
    // socket.to), including back to the Saboteur themself — re-applying
    // the same state we already set locally is harmless, so no special
    // "skip if it was me" branch is needed here.
    socket.on('sabotageTriggered', (data) => {
      if (data.type === 'electricity') setPowerSabotaged(true);
      else if (data.type === 'hacker') setHackerAttack(true);
      // [BUG FIX] Backend always sends type "gateLeft"/"gateRight" (see
      // the validTypes fix in triggerSabotageAction) - this listener was
      // still checking the OLD "lockLeft"/"lockRight" naming, so it
      // never matched. Result: only the Saboteur (who sets their own
      // gateLock state locally and instantly on button-press) ever saw
      // the gate as locked - every other player's screen never received
      // this broadcast correctly, so the gate stayed walkable for them.
      else if (data.type === 'gateLeft') {
        setGateLock((prev) => prev.group ? prev : { group: 'A', expiresAt: Date.now() + GATE_LOCK_DURATION_MS });
      } else if (data.type === 'gateRight') {
        setGateLock((prev) => prev.group ? prev : { group: 'B', expiresAt: Date.now() + GATE_LOCK_DURATION_MS });
      }
    });
    socket.on('sabotageError', (data) => {
      console.log('Sabotage error:', data.message);
    });
    // [NEW FEATURE] Shared crew mission-progress meter - the server sends
    // this every time ANY crewmate's mission progress changes, to the
    // WHOLE room (so the Saboteur and ghosts see it update live too, not
    // just crewmates).
    socket.on('crewProgressUpdated', (data) => {
      if (data && typeof data.percent === 'number') setCrewProgress(data);
    });

    // [BUG FIX] Server confirms a sabotage was repaired - clear the
    // active effect for EVERYONE in the room, not just whoever fixed it.
    // This is the fix for the "everyone has to repair it individually"
    // bug: one crewmate fixing it now turns the lights back on for the
    // whole room, Saboteur included, exactly like a real shared power
    // grid.
    socket.on('sabotageRepaired', (data) => {
      if (data.type === 'electricity') setPowerSabotaged(false);
      else if (data.type === 'hacker') setHackerAttack(false);
    });

    // [BUG FIX] Another player (the Saboteur) is entering/traveling/
    // exiting a vent. We mark them as currently "in a vent" so the
    // render below hides their avatar entirely (same as our own avatar
    // disappears from our own screen) and plays the matching squish
    // animation at the same moment, instead of their avatar just
    // freezing fully visible in place for the whole duration — which
    // was the actual bug, since nothing previously told other players a
    // vent trip was even happening.
    socket.on('playerVentTravel', (data) => {
      setOtherPlayers((prev) => ({
        ...prev,
        [data.id]: {
          ...(prev[data.id] || {}),
          inVent: data.phase !== 'exit',
          ventAnimPhase: data.phase === 'enter' ? 'entering' : data.phase === 'exit' ? 'exiting' : null,
        },
      }));
      // The transient squish animation clears itself after the same
      // 350ms duration the Saboteur's own client uses, leaving the
      // underlying inVent (hidden) state alone until the matching exit
      // event arrives.
      if (data.phase === 'enter' || data.phase === 'exit') {
        setTimeout(() => {
          setOtherPlayers((prev) => prev[data.id] ? { ...prev, [data.id]: { ...prev[data.id], ventAnimPhase: null } } : prev);
        }, 350);
      }
    });

    // [BUG FIX] A Saboteur somewhere in the room just disguised - update
    // our view of them (otherPlayers[id].disguiseAvatarId) so any place
    // that renders their avatar uses the disguise, not their real
    // avatarId. This is the actual fix for "disguise only worked for the
    // Saboteur's own screen" - previously nothing ever told other
    // players a disguise had even happened.
    socket.on('playerDisguised', (data) => {
      setOtherPlayers((prev) => ({
        ...prev,
        [data.id]: { ...(prev[data.id] || {}), disguiseAvatarId: data.avatarId },
      }));
    });
    socket.on('playerDisguiseEnded', (data) => {
      setOtherPlayers((prev) => {
        if (!prev[data.id]) return prev;
        const next = { ...prev[data.id] };
        delete next.disguiseAvatarId;
        return { ...prev, [data.id]: next };
      });
    });

    // [MULTIPLAYER: SHARED] Server confirms a meeting actually started
    // (either the Assembly Hall button or a body-report — reason mirrors
    // calledBy). This is the ONLY place local meeting state gets created
    // now; callMeeting itself just asks the server, it doesn't set
    // anything locally, so every player's meeting object is built from
    // the same server-confirmed event instead of racing each other.
    socket.on('meetingStarted', (data) => {
      // [BUG FIX] If we were inside a vent when someone ELSE called this
      // meeting, our local inVent state would otherwise stay stuck true
      // forever - the vent's own Exit button is unreachable once the
      // meeting overlay covers the screen, and the movement loop is
      // permanently paused while inVent is truthy (see inVentRef's check
      // in the main tick function), so without this we'd be soft-locked,
      // unable to move at all once the meeting ends. Tell the server too
      // (so its own inVent tracking - used to block kill/sabotage while
      // vented - doesn't stay stuck either), but skip the exit animation
      // entirely since the meeting overlay already covers everything.
      if (inVentRef.current) {
        setInVent(null);
        setVentAnim(null);
        socket.emit('ventTravel', { phase: 'exit', roomId: inVentRef.current });
      }
      // [BUG FIX] If a mission popup (CCTV, wallet verification, etc.)
      // was open when this meeting started - whether we called it
      // ourselves or just got pulled into someone else's - close it now.
      // Without this, showMission stayed true the whole time, hidden
      // behind the meeting overlay, and reappeared completely
      // unexpectedly the instant the meeting ended.
      setShowMission(false);
      setEliminationRoleReveal(null);
      // [BUG FIX] Close the standalone Ghost Chat panel if it was open -
      // the meeting screen (higher z-index) now has its own embedded
      // ghost chat section, so the standalone panel would otherwise sit
      // hidden underneath it, then unexpectedly reappear once the
      // meeting ends.
      setShowGhostChat(false);
      // [TELEPORT-BACK FEATURE] Snapshot exactly where we were standing
      // the instant the meeting was called — this is what we'll teleport
      // back to once voting resolves (see votingResult below). Captured
      // here (not when WE personally press the meeting button) so it
      // works the same way whether we called the meeting ourselves or
      // just got pulled into someone else's.
      preMeetingPosRef.current = { ...posRef.current };
      // [BUG FIX] Clear any unsent reply-in-progress from a previous
      // meeting - without this, an unsent "Replying to X" banner could
      // carry over into this brand new meeting and get attached to a
      // message about a conversation that isn't even visible anymore.
      setReplyingTo(null);
      setChatDraft('');
      setMeeting({
        stage: 'alarm',
        // [BUG FIX] Renamed from calledBy to calledByReason for clarity -
        // this was always the "self"/"report" REASON string
        // (room.meeting.reason server-side), never an actual player id,
        // despite the confusing old name. calledByPlayerId below is the
        // ACTUAL Saboteur/caller's socket id, used to show the
        // meeting-call badge next to the right player's card on the
        // voting screen.
        calledByReason: data.reason,
        calledByPlayerId: data.calledBy,
        // [NEW FEATURE] Full caller/reported-body details (name+avatar)
        // for the Emergency Meeting alarm screen - see the render below.
        callerName: data.callerName,
        callerAvatarId: data.callerAvatarId,
        reportedBody: data.reportedBody || null,
        startedAt: Date.now(),
        messages: [],
        myVote: null,
        result: null,
        // [DEATH ANNOUNCEMENT] Every player who's currently dead, shown
        // at the top of the discussion chat — same as Among Us listing
        // every death known so far whenever a meeting is called.
        deadPlayerNames: data.deadPlayerNames || [],
        // [NEW FEATURE] Live vote tracking - { voterId: choice } - built
        // up in real time as voteUpdate events arrive during the voting
        // stage (see the voteUpdate listener below). Reset fresh for
        // every new meeting.
        liveVotes: {},
      });
    });
    socket.on('meetingError', (data) => {
      console.log('Meeting error:', data.message);
      if (typeof data.cooldownRemainingMs === 'number') {
        // [DISCUSSION COOLDOWN] Briefly show how long until the next
        // meeting can be called, so pressing the button while on
        // cooldown doesn't look like it silently did nothing.
        setMeetingCooldownNotice(Math.ceil(data.cooldownRemainingMs / 1000));
        setTimeout(() => setMeetingCooldownNotice(null), 2500);
      }
    });

    // [NEW FEATURE] Task-reminder popup - fires only on THIS player's
    // own screen (server targets the event at their socket id
    // specifically, see the inactivity-check interval on the backend),
    // every 3 minutes they've gone without finishing a mission. A brief
    // top-of-screen banner, not a full-screen interruption - visible
    // for 5s then auto-dismisses. taskReminderKey just forces each new
    // occurrence to reset/replay the same banner even if the previous
    // one hasn't finished fading yet. [UPDATE] Now also carries exactly
    // how many warnings this is (out of the max before removal) and how
    // often they recur, so the banner itself can spell out the stakes -
    // plus a short popup sound so it's genuinely hard to miss.
    socket.on('taskReminder', (data) => {
      setTaskReminderKey((k) => k + 1);
      setTaskReminderInfo({ strikeNumber: data?.strikeNumber || 1, maxStrikes: data?.maxStrikes || 3, intervalMs: data?.intervalMs || 180000 });
      setShowTaskReminder(true);
      playAlertPopupSound();
      setTimeout(() => setShowTaskReminder(false), 5000);
    });

    // [NEW FEATURE] This player specifically was just removed from the
    // game for repeated mission inactivity (the 4th reminder with still
    // no progress - see the backend). Their incomplete missions are
    // deliberately NOT held against the team's shared progress/win-
    // condition (unlike a normal leave) - nothing else to do here
    // except let them know why they're suddenly back at the Lobby.
    socket.on('kickedForInactivity', () => {
      setInactivityKickedNotice(true);
      setScreen('lobby');
    });

    // [NEW FEATURE] Saboteur kill-timer alerts - only ever received by a
    // Saboteur who hasn't killed yet (see the backend's saboteurAlarmStage
    // gating), never by crewmates or a Saboteur who's already killed.
    // Stages 1-3 are brief "kill someone" alert popups. [UPDATE] Now
    // carries how much time is left until the 7-minute deadline, so the
    // alert can spell out the stakes - plus the same popup sound as the
    // task-reminder above.
    socket.on('saboteurKillAlarm', (data) => {
      setSaboteurAlarmKey((k) => k + 1);
      setSaboteurAlarmInfo({ remainingMs: data?.remainingMs ?? null });
      setShowSaboteurAlarm(true);
      playAlertPopupSound();
      setTimeout(() => setShowSaboteurAlarm(false), 5000);
    });

    // [NEW FEATURE] The 6-minute mark with still no kill - the server
    // hands off a single starting value and this runs its own local 60s
    // countdown from there (ticking every second) rather than the server
    // pushing per-second updates.
    socket.on('saboteurKillCountdownStart', (data) => {
      setSaboteurCountdownMs(Math.max(0, data.remainingMs || 60000));
      playAlertPopupSound();
    });

    // [NEW FEATURE] The 7-minute deadline passed with zero kills - this
    // Saboteur is auto-eliminated (same as a normal death, just no body
    // to find). alive=false already arrived/will arrive via the regular
    // playerListUpdated broadcast; this just tells THEM specifically why.
    socket.on('saboteurEliminatedForInactivity', () => {
      setMyAlive(false);
      setSaboteurCountdownMs(null);
    });

    // [NEW FEATURE] A DIFFERENT Saboteur on the team (not this one) just
    // landed the kill that satisfies the whole team's deadline - clear
    // any alarm/countdown already showing here, since it's no longer
    // heading toward anything.
    socket.on('saboteurTimerCleared', () => {
      setSaboteurCountdownMs(null);
      setShowSaboteurAlarm(false);
    });

    // [BUG FIX] This had NO listener registered at all before (only a
    // cleanup socket.off('voteError') existed) - any rejected vote
    // attempt was completely silent, with the local optimistic myVote
    // potentially left stuck pointing at a vote the server never
    // actually recorded. Reset it back to null so the player can see
    // their vote didn't go through and try again.
    socket.on('voteError', (data) => {
      console.log('Vote error:', data.message);
      // [BUG FIX] Previously had NO listener at all (only a cleanup
      // socket.off('voteError') existed) - any rejected vote attempt was
      // completely silent. Deliberately NOT resetting myVote here (that
      // could incorrectly wipe out an already-accepted vote if this ever
      // fires for the duplicate-vote case) - the votingResult handler's
      // own reconciliation against the server's authoritative vote
      // record is what actually corrects any local/server divergence,
      // once results come in.
    });

    // [BUG FIX] Defensive resync, sent by the server at meeting-start and
    // meeting-end specifically to the Saboteur - applies the server's
    // real, persisted sabotage-use counts/cooldowns over whatever the
    // local display currently shows, self-correcting it regardless of
    // what caused it to drift.
    socket.on('sabotageStateSync', (data) => {
      if (data.sabotageUses) {
        setSabotageUsesLeft({
          power: data.sabotageUses.electricity ?? 3,
          hacker: data.sabotageUses.hacker ?? 3,
          gateLeft: data.sabotageUses.gateLeft ?? 5,
          gateRight: data.sabotageUses.gateRight ?? 5,
        });
      }
      if (typeof data.sabotageCooldownUntil === 'number') setSabotageCooldownUntil(data.sabotageCooldownUntil);
      if (typeof data.disguiseCooldownUntil === 'number') setDisguiseCooldownUntil(data.disguiseCooldownUntil);
      if (typeof data.postKillSabotageLockUntil === 'number') setPostKillLockUntil(data.postKillSabotageLockUntil);
    });

    // [BUG FIX] Whenever someone reconnects mid-meeting, the server
    // re-broadcasts its authoritative (already id-migrated) vote map to
    // the WHOLE room. Without this, every OTHER client's local liveVotes
    // kept using that player's OLD (now-stale) socket.id as a key, and
    // the very next playerListUpdated prunes that old id from
    // otherPlayers - so the reconnecting player's already-cast vote
    // silently vanished from view under whichever target they'd voted
    // for (their vote was never actually lost server-side, only
    // displayed wrong on everyone else's screen). Just replace our local
    // liveVotes/skip-vote state wholesale with the server's truth here.
    socket.on('meetingVotesSync', (data) => {
      setMeeting((m) => m && {
        ...m,
        liveVotes: data.votes || {},
        myVote: (data.votes && Object.prototype.hasOwnProperty.call(data.votes, socket.id))
          ? data.votes[socket.id]
          : m.myVote,
      });
    });

    // [MULTIPLAYER: SHARED] A chat message — ours or someone else's. The
    // server is the single source of truth for message order (everyone
    // gets messages in the same sequence), so isSelf is derived by
    // comparing senderId to our own socket id rather than trusting
    // anything the client claims.
    socket.on('chatMessageReceived', (data) => {
      setMeeting((m) => m && {
        ...m,
        messages: [...m.messages, {
          id: data.timestamp + Math.random(),
          authorName: displayPlayerName(data.senderName, data.senderAvatar),
          authorAvatarId: data.senderAvatar,
          text: data.text,
          isSelf: data.senderId === socket.id,
          replyTo: data.replyTo || null, // [NEW FEATURE] reply-to-message
        }],
      });
    });

    // [NEW FEATURE] Ghost chat — same pattern as chatMessageReceived
    // above, but appends to the completely separate ghostChatMessages
    // list instead. Only a ghost's client ever receives this at all
    // (server only ever targets currently-dead sockets individually).
    socket.on('ghostChatMessageReceived', (data) => {
      setGhostChatMessages((prev) => [...prev, {
        id: data.timestamp + Math.random(),
        _ts: data.timestamp,
        _sender: data.senderId,
        authorName: displayPlayerName(data.senderName, data.senderAvatar),
        authorAvatarId: data.senderAvatar,
        text: data.text,
        isSelf: data.senderId === socket.id,
        replyTo: data.replyTo || null,
      }]);
    });

    // [NEW FEATURE] Lobby chat - same message-shape transform as ghost
    // chat above. Unread count only increments while the chat panel is
    // closed (showLobbyChatRef, not the state directly - see why in that
    // ref's own comment) - opening the panel already resets it to 0 via
    // the effect that owns showLobbyChatRef.
    socket.on('lobbyChatMessageReceived', (data) => {
      setLobbyChatMessages((prev) => [...prev, {
        id: data.id || (data.timestamp + Math.random()),
        _ts: data.timestamp,
        _sender: data.senderId,
        authorName: displayPlayerName(data.senderName, data.senderAvatar),
        authorAvatarId: data.senderAvatar,
        text: data.text,
        isSelf: data.senderId === socket.id,
        replyTo: data.replyTo || null,
      }]);
      if (!showLobbyChatRef.current && data.senderId !== socket.id) {
        setLobbyChatUnread((n) => n + 1);
      }
    });

    socket.on('chatError', (data) => {
      console.log('Chat error:', data.message);
    });

    // [BUG FIX] Backlog sent the moment we become a ghost (via kill or
    // vote-elimination) - without this we'd only ever see ghost chat
    // messages going forward, with the entire history before our death
    // invisible until/unless we happened to refresh the page later.
    socket.on('ghostChatBacklog', (data) => {
      const msgs = (data.messages || []).map((m) => ({
        id: m.timestamp + Math.random(),
        _ts: m.timestamp,
        _sender: m.senderId,
        authorName: displayPlayerName(m.senderName, m.senderAvatar),
        authorAvatarId: m.senderAvatar,
        text: m.text,
        isSelf: m.senderId === socket.id,
        replyTo: m.replyTo || null,
      }));
      setGhostChatMessages((prev) => {
        // Merge rather than overwrite, in case a couple of live messages
        // already arrived before this backlog did. Dedup on the server
        // timestamp+sender (unique per message) rather than text+author,
        // so two ghosts sending the same short text (e.g. "gg") don't
        // cause one to be wrongly dropped as a duplicate.
        const existingKeys = new Set(prev.map((p) => `${p._ts}|${p._sender}`));
        const merged = [...msgs.filter((m) => !existingKeys.has(`${m._ts}|${m._sender}`)), ...prev];
        return merged;
      });
    });

    // [SKIP DISCUSSION] Running tally of skip-votes, broadcast to
    // everyone every time someone casts one — used just to show the
    // count on the button (e.g. "3/5"), the actual 50% threshold check
    // happens server-side.
    socket.on('skipDiscussionUpdate', (data) => {
      setMeeting((m) => m && {
        ...m,
        skipVoteCount: data.totalSkipVotes,
        skipVoteTotal: data.totalAlive,
      });
    });

    // [NEW FEATURE] A vote landed somewhere, live - update our running
    // liveVotes map (voterId -> choice) so the voting screen can show a
    // small avatar of the voter next to whichever target/skip they
    // picked, in real time, matching Among Us's own live voting screen.
    // totalVotes/totalAlive are also stored for the "X/Y voted" counter.
    socket.on('voteUpdate', (data) => {
      setMeeting((m) => m && {
        ...m,
        liveVotes: { ...m.liveVotes, [data.voterId]: data.choice },
        totalVotesIn: data.totalVotes,
        totalAliveForVote: data.totalAlive,
      });
    });

    // [SKIP DISCUSSION] Server moved the meeting straight to voting
    // because enough players voted to skip — same stage value the
    // alarm->chat and chat->voting client timers already use, so the
    // existing stage-based rendering picks this up automatically.
    socket.on('meetingStageChanged', (data) => {
      setMeeting((m) => m && { ...m, stage: data.stage, startedAt: Date.now() });
    });

    // [NEW FEATURE] The 50% skip-threshold was just reached - show a
    // brief "Discussion skipped" loading transition for the 1.5s window
    // before the server actually flips the meeting to the voting stage
    // (see meetingStageChanged above), instead of the chat screen
    // instantly vanishing and voting appearing with no transition at all.
    socket.on('discussionSkipped', () => {
      setShowSkipTransition(true);
      setTimeout(() => setShowSkipTransition(false), 1500);
    });

    // [MULTIPLAYER: SHARED] The server's final tally — every player
    // receives the exact same result object, so there's no risk of two
    // clients disagreeing about who got eliminated. If I myself was
    // eliminated, mark myAlive false (same path a kill uses); if someone
    // else was, mark them dead in otherPlayers and drop a body for them
    // at their last known position (votingResult doesn't carry a
    // position, so we read it from whatever we already have synced).
    socket.on('votingResult', (data) => {
      setMeeting((m) => m && {
        ...m,
        stage: 'results',
        startedAt: Date.now(),
        // [BUG FIX] Reconcile our own vote with the server's authoritative
        // record now that it's available - if a rare edge case (e.g. a
        // double-tap right at the render boundary) ever caused our local
        // myVote to diverge from what the server actually recorded, this
        // self-heals it here rather than leaving a permanently wrong
        // local display.
        myVote: (data.votes && Object.prototype.hasOwnProperty.call(data.votes, socket.id))
          ? data.votes[socket.id]
          : m.myVote,
        result: {
          eliminatedName: data.eliminatedName,
          eliminatedId: data.eliminatedId,
          eliminatedRole: data.eliminatedRole,
          eliminatedAvatarId: data.eliminatedAvatarId,
          tie: data.tie,
          tally: data.voteCounts,
          // [NEW FEATURE] Raw voter->target mapping, revealed only now
          // that voting's over — used to render "who voted for whom" on
          // the results screen.
          votes: data.votes || {},
        },
      });
      if (data.eliminatedId) {
        // [NEW FEATURE] 3.5-second elimination role-reveal, Among-Us
        // style - separate from (and shown before) the regular results/
        // vote-breakdown screen.
        setEliminationRoleReveal({
          name: data.eliminatedName, role: data.eliminatedRole, avatarId: data.eliminatedAvatarId,
        });
        // [BUG FIX] If this elimination also ends the game (e.g. the
        // last Saboteur just got voted out), gameOver needs to know to
        // wait for this window to finish first - see
        // awaitingEliminationRevealRef.
        awaitingEliminationRevealRef.current = true;
        setTimeout(() => {
          setEliminationRoleReveal(null);
          awaitingEliminationRevealRef.current = false;
        }, 3500);
        // [BUG FIX] Ejection (voted out) is NOT the same thing as being
        // killed by the Saboteur - a voted-out player is formally
        // ejected from the group, not murdered, so unlike an actual
        // kill they never leave a body behind on the map at all. This
        // previously added one anyway (at their last known position),
        // which didn't match that distinction and looked/felt wrong -
        // now this only updates alive-status (self via setMyAlive,
        // others via otherPlayers), no deadBodies entry either way.
        if (data.eliminatedId === socket.id) {
          setMyAlive(false);
        } else {
          setOtherPlayers((prev) => ({
            ...prev,
            [data.eliminatedId]: { ...(prev[data.eliminatedId] || {}), alive: false },
          }));
        }
      }
      // [BODY CLEANUP] Every body the server says is now "known" (was
      // already dead before this meeting, or just got eliminated by this
      // vote) disappears from the map — same as Among Us clearing bodies
      // once they've been discussed. A brief delay lets the results
      // screen itself still show correctly before bodies vanish under it.
      if (Array.isArray(data.clearedBodyIds) && data.clearedBodyIds.length > 0) {
        setTimeout(() => {
          setDeadBodies((prev) => {
            const next = { ...prev };
            data.clearedBodyIds.forEach((id) => { delete next[id]; });
            return next;
          });
        }, 4000); // matches the ~4s the results screen stays up before auto-closing
      }
      // [FEATURE CHANGE] Once voting resolves, EVERYONE - every alive
      // player, every ghost, the Saboteur included, and even the player
      // who was JUST eliminated by this very vote - returns to the
      // Assembly Hall (cafeteria), exactly as originally specified.
      // Nothing else about player state (missions, avatar, wallet,
      // sabotage progress, alive/dead status) is touched here - this
      // only ever moves position. [BUG FIX] This replaces the previous
      // "snap back to wherever you were standing before the meeting"
      // behavior, which didn't match the requirement and also excluded
      // ghosts entirely.
      // Each player gets their own distinct Assembly Hall spawn point
      // (not all stacked on one tile) by using their stable index within
      // roomInfo.players - that array's ordering is identical across
      // every client (it comes from the same server-broadcast list), so
      // everyone independently computes the same assignment without
      // needing the server to send one explicitly.
      {
        const players = roomInfoRef.current?.players || [];
        const myIndex = players.findIndex((p) => p.id === socket.id);
        const returnPos = spawnPointPx(myIndex >= 0 ? myIndex : 0);
        setTimeout(() => {
          setPos(returnPos);
          posRef.current = returnPos;
          if (socketRef.current && socketRef.current.connected) {
            socketRef.current.emit('playerMove', { x: returnPos.x, y: returnPos.y });
          }
        }, 4000);
      }
    });

    socket.connect();
  }, []);

  // [RECONNECTION] If a saved room+token exists from before (a refresh,
  // reopening the tab, etc.), connect automatically on mount rather than
  // waiting for the player to notice and press "Connect to Server"
  // themselves — the actual reconnectToRoom attempt happens inside the
  // 'connect' handler above once the socket is actually live.
  useEffect(() => {
    try {
      const savedCode = localStorage.getItem('nearSaboteurRoomCode');
      const savedToken = localStorage.getItem('nearSaboteurPlayerToken');
      if (savedCode && savedToken) {
        connectSocket();
      }
    } catch (e) { /* localStorage unavailable */ }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleCreateRoom = useCallback((isPublic) => {
    if (!socketRef.current) return;
    socketRef.current.emit('createRoom', { name: playerName, avatarId: playerAvatarId, isPublic: !!isPublic });
  }, [playerName, playerAvatarId]);

  const handleJoinRoom = useCallback((code) => {
    if (!socketRef.current || !code) return;
    socketRef.current.emit('joinRoom', { code, name: playerName, avatarId: playerAvatarId });
  }, [playerName, playerAvatarId]);

  // [MULTIPLAYER] Only the host calls this (Lobby only renders the Start
  // button for the host — see LobbyScreen). Server validates host-ness
  // again on its side regardless, so this can never be spoofed by editing
  // client state.
  const handleStartGame = useCallback((ic, sl) => {
    if (!socketRef.current) return;
    socketRef.current.emit('startGame', { imposterCount: ic, speedLevel: sl });
  }, []);

  // Role assignment: now comes from the server's startGame -> roleAssigned
  // flow (see connectSocket below for the listener). Every player gets a
  // role nobody else can see. imposterCount is set once by the host and
  // flows to the server when Start is pressed; everyone else just receives
  // their own role and proceeds straight to loading.
  const [playerRole, setPlayerRole] = useState('crewmate'); // 'crewmate' | 'saboteur' — [PER-PLAYER]
  // [NEW FEATURE] Multi-Saboteur awareness - only ever populated for a
  // Saboteur's own client (the server never sends this field to
  // crewmates at all). Used both for the brief 2s reveal popup right
  // after roles are assigned, and persistently afterward to color
  // fellow Saboteurs' name-tags red in-game.
  const [fellowSaboteurs, setFellowSaboteurs] = useState([]); // [{ name, avatarId }]
  const [saboteurCount, setSaboteurCount] = useState(1); // [NEW FEATURE] safe-to-reveal count, used by the role-reveal screen
  // [NEW FEATURE] 2-second Among-Us-style "X was The Saboteur/Crewmate"
  // reveal, shown right after a successful vote-out, before the regular
  // results/vote-breakdown screen. { name, role, avatarId } | null.
  const [eliminationRoleReveal, setEliminationRoleReveal] = useState(null);
  // [BUG FIX] If voting just eliminated the last Saboteur (single-
  // Saboteur game), the server's gameOver event arrives almost
  // simultaneously with votingResult - without this, "Crewmate Wins"
  // would pop up WHILE (or even before) the elimination role-reveal
  // ("X was The Saboteur") finished showing, stepping all over it. This
  // ref tells the gameOver handler to hold off and apply the result only
  // once the reveal window has actually finished.
  const awaitingEliminationRevealRef = useRef(false);
  // [BUG FIX] Same purpose as awaitingEliminationRevealRef above, but for
  // a kill (rather than a vote) that ends the game - see the playerKilled
  // handler and the gameOver handler for how this is used.
  const awaitingKillCutsceneRef = useRef(false);
  const [imposterCount, setImposterCount] = useState(1); // [SHARED]
  // [NEW FEATURE] Speed level (1-5, default 2 = 50%/original speed),
  // chosen by the host in the Lobby and applied to every alive player
  // once the game starts. Ghosts always move at a fixed speed regardless
  // of this — see the movement loop's effectiveSpeed calculation.
  const [speedLevel, setSpeedLevel] = useState(4); // [UPDATE] Default 100% (was 75%) - levels are now 50/75/100/125/150
  // [BUG FIX] Same stale-closure issue as the Lobby's own movement loop -
  // the main game's movement useEffect below also has a [] dependency
  // array (runs once on mount), so reading speedLevel directly there
  // would freeze whatever value existed at that first render forever. A
  // ref always has the latest value without needing the loop itself to
  // be recreated.
  const speedLevelRef = useRef(speedLevel);
  useEffect(() => { speedLevelRef.current = speedLevel; }, [speedLevel]);

  // [MULTIPLAYER: SHARED] The old solo-test dummy crewmate (a single
  // wandering NPC) has been fully replaced by the real `otherPlayers`
  // roster declared above, synced from the server. There is no
  // client-side AI anymore — every "other player" on screen is a real
  // person's synced position.
  const [facing, setFacing] = useState('right'); // [PER-PLAYER]
  const [pos, setPos] = useState(startPx); // [PER-PLAYER]
  // Distance between the player and the dummy, in world pixels — used to
  // decide when the Kill button should appear for a Saboteur. Declared
  // here (right after both pos and dummyPos exist) since it only depends
  // on those two world-coordinate values, not on camera/scale — needs to
  // exist before handleKillDummy below, which references it.
  // [MULTIPLAYER: SHARED] Finds the nearest ALIVE other player within kill
  // range — replaces the old single dummyPos distance-check now that a
  // real roster (multiple other players) exists. Returns null if nobody
  // alive is in range. Recomputed every render off pos/otherPlayers, same
  // pattern the old distToDummy used (a plain derived value, not state).
  const nearestKillTarget = useMemo(() => {
    let best = null;
    let bestDist = Infinity;
    for (const id in otherPlayers) {
      const p = otherPlayers[id];
      if (p.alive === false) continue;
      if (typeof p.x !== 'number' || typeof p.y !== 'number') continue;
      const d = Math.hypot(pos.x - p.x, pos.y - p.y);
      if (d < bestDist) { bestDist = d; best = { id, ...p, dist: d }; }
    }
    return best;
  }, [pos, otherPlayers]);
  const KILL_RANGE_PX = TILE * 2.4; // bumped up from 1.6 — moving targets were hard to line up with the tighter range
  const canKillDummy = playerRole === 'saboteur' && myAlive && !!nearestKillTarget && nearestKillTarget.dist <= KILL_RANGE_PX;
  // [MULTIPLAYER: SHARED] Bodies map — when a player is killed, we snapshot
  // their last known position here (keyed by id) so the body keeps
  // rendering at the spot they died, even as otherPlayers' own x/y might
  // theoretically still update (it won't, since dead players stop
  // broadcasting movement, but this keeps body-position decoupled from
  // live-position lookups either way). Populated by the playerKilled
  // handler (see connectSocket).
  const [deadBodies, setDeadBodies] = useState({}); // { [playerId]: {x,y,avatarId} }
  const nearestReportableBody = useMemo(() => {
    let best = null;
    let bestDist = Infinity;
    for (const id in deadBodies) {
      const b = deadBodies[id];
      const d = Math.hypot(pos.x - b.x, pos.y - b.y);
      if (d < bestDist) { bestDist = d; best = { id, ...b, dist: d }; }
    }
    return best;
  }, [pos, deadBodies]);
  const REPORT_RANGE_PX = TILE * 2.4;
  const canReportBody = playerRole === 'crewmate' && myAlive && !!nearestReportableBody && nearestReportableBody.dist <= REPORT_RANGE_PX;
  // ── Vent system (Saboteur-only) ───────────────────────────────────────
  // null while not in a vent; otherwise the room id of the vent currently
  // occupied. While inside a vent, the player's own avatar/position
  // rendering is hidden from the normal map (they're "inside the walls"),
  // and the only available interactions are picking a connected room's
  // vent to travel to, or exiting back into the current room.
  // [MULTIPLAYER: SHARED — other players should see the Saboteur vanish
  // into / emerge from a vent, just not be able to use it themselves]
  const [inVent, setInVent] = useState(null); // room id | null
  // Brief animation flag — 'entering' while the avatar shrinks into the
  // grate, 'exiting' while it grows back out, null otherwise. Purely
  // visual, auto-clears itself after the animation's CSS duration.
  // [LOCAL-UI]
  const [ventAnim, setVentAnim] = useState(null);
  const [currentRoom, setCurrentRoom] = useState(null); // [LOCAL-UI]
  // Whether the player is currently standing close enough to their current
  // room's vent grate to interact with it — only matters for a Saboteur
  // (everyone else simply never sees the "Enter Vent" option at all).
  // Declared right here (depends only on currentRoom/pos/inVent/
  // playerRole, all already in scope) so it's available to any handler
  // declared below, like enterVent.
  const currentRoomVentPos = currentRoom && VENT_POSITIONS[currentRoom.id] ? VENT_POSITIONS[currentRoom.id] : null;
  const nearVent = playerRole === 'saboteur' && myAlive && !inVent && currentRoomVentPos &&
    Math.hypot(pos.x / TILE - currentRoomVentPos.x, pos.y / TILE - currentRoomVentPos.y) <= VENT_INTERACT_RANGE_TILES;
  const [nearTask, setNearTask] = useState(null); // [LOCAL-UI]
  const [showMission, setShowMission] = useState(false); // [LOCAL-UI]
  const [viewport, setViewport] = useState({ w: 360, h: 640 }); // [LOCAL-UI]
  const [knob, setKnob] = useState({ x: 0, y: 0 }); // [LOCAL-UI]
  const [soundOn, setSoundOn] = useState(true); // [LOCAL-UI]
  const [showSettings, setShowSettings] = useState(false); // [LOCAL-UI]
  const [showMap, setShowMap] = useState(false); // [LOCAL-UI]
  const [showExitConfirm, setShowExitConfirm] = useState(false); // [LOCAL-UI]
  const [wallet, setWallet] = useState(() => { // [PER-PLAYER]
    const w = {};
    SWAP_ASSETS.forEach(a => { w[a.id] = a.id === 'NEAR' ? 100 : 0; });
    return w;
  });
  const [myMissions, setMyMissions] = useState(() => pickRandomMissions(MISSIONS_ASSIGNED_COUNT)); // [PER-PLAYER]
  // Meme coin holdings live in their own state, deliberately separate from
  // `wallet` (which only ever holds the SWAP_ASSETS coins) — keeps the main
  // wallet panel's "every asset has a real logo" look intact, since meme
  // coins render with CoinLogo's letter-fallback instead of a real icon.
  const [memeWallet, setMemeWallet] = useState(() => { // [PER-PLAYER]
    const m = {};
    MEME_COINS.forEach(c => { m[c.id] = 0; });
    return m;
  });
  // Timestamp (ms) of when total meme holdings most recently went from
  // "below mission target" to "at/above it" — null while below target. The
  // Meme Market mission completes once Date.now() - memeHoldSince exceeds
  // the player's randomly-assigned hold duration. Selling back below target
  // resets this to null, so the hold timer only counts continuous holding.
  const [memeHoldSince, setMemeHoldSince] = useState(null); // [PER-PLAYER]
  // The "Hold 200 NEAR" mission's checkmark toggles live with the balance
  // (crossing back below 200 un-checks it again), but the +10 NEAR reward
  // only ever pays out once per game — this tracks whether that's already
  // happened, independent of the mission's own `done` flag.
  const [walletMissionRewarded, setWalletMissionRewarded] = useState(false); // [PER-PLAYER]
  const [showWallet, setShowWallet] = useState(false); // [LOCAL-UI]
  const [showMissionTracker, setShowMissionTracker] = useState(false); // [LOCAL-UI]
  const [showSaboteurPanel, setShowSaboteurPanel] = useState(false); // [LOCAL-UI]
  const [showDisguisePicker, setShowDisguisePicker] = useState(false); // [LOCAL-UI] — avatar-choice screen for Disguise
  const [congratsNote, setCongratsNote] = useState(null); // { label } | null, shown briefly on mission completion — [LOCAL-UI]
  // Fires once, the moment every assigned mission (including the
  // compulsory "Hold 200 NEAR" one) is done — a bigger, one-time
  // celebration distinct from the small per-mission toast above.
  const [allMissionsDone, setAllMissionsDone] = useState(false); // [PER-PLAYER]
  const [showAllDoneModal, setShowAllDoneModal] = useState(false); // [LOCAL-UI]

  // ── Emergency Meeting (Assembly Hall) ───────────────────────────────
  // [MULTIPLAYER: SHARED] — this entire system is fundamentally a
  // multiplayer feature: it only means something with other real players
  // in it. Solo-test only has this one real player to show (no other
  // players or chat messages can appear without a backend actually
  // relaying them), but the data shape here is deliberately built as if
  // a roster existed, so wiring in real players later is a data-source
  // swap, not a UI rewrite. Stages: null (no meeting) -> 'alarm' (3s
  // siren before everyone gets pulled in) -> 'chat' (2.5 min discussion)
  // -> 'voting' (cast a vote) -> 'results' (outcome shown briefly) -> null.
  const MEETING_CHAT_DURATION_MS = 150000; // 2.5 minutes
  const MEETING_ALARM_DURATION_MS = 3000;
  const MEETING_RESULTS_DURATION_MS = 4000;
  const [meeting, setMeeting] = useState(null);
  // [NEW FEATURE] Brief "Discussion skipped" loading overlay, shown for
  // the 1.5s window between the skip-threshold being reached and the
  // server actually moving the meeting to the voting stage.
  const [showSkipTransition, setShowSkipTransition] = useState(false);
  // Shape while active: {
  //   stage: 'alarm' | 'chat' | 'voting' | 'results',
  //   calledBy: 'self' | 'report',  // emergency button vs body report
  //   startedAt: number,             // timestamp the current stage began
  //   messages: [{ id, authorName, authorAvatarId, text, isSelf }],
  //   myVote: string | 'skip' | null,  // who THIS player voted for
  //   result: { eliminatedName: string | null, tally: {...} } | null,
  // }
  const [chatDraft, setChatDraft] = useState(''); // [LOCAL-UI] current text-input value
  // [BUG FIX] Auto-scroll-to-bottom ref for the chat message list - new
  // messages were previously appended off-screen with no auto-scroll,
  // so the user had to manually scroll down every time to see if a new
  // message had arrived.
  const chatScrollRef = useRef(null);
  const ghostChatScrollRef = useRef(null);
  // [NEW FEATURE] Ghost-only chat - completely separate message list,
  // input draft, and panel-open state from the normal meeting chat.
  // Only ever populated for a player who is currently a ghost (myAlive
  // === false) - see the ghostChatMessageReceived listener.
  const [ghostChatMessages, setGhostChatMessages] = useState([]);
  const [ghostChatDraft, setGhostChatDraft] = useState('');
  const [showGhostChat, setShowGhostChat] = useState(false);
  // [NEW FEATURE] Lobby chat - separate message list/draft/panel-open
  // state again, same pattern as ghost chat above but scoped to the
  // Lobby screen instead of ghosts. showLobbyChat also needs a ref
  // mirror (see the effect right below) since the lobbyChatMessageReceived
  // socket listener is registered once and closes over whatever value
  // showLobbyChat had AT REGISTRATION TIME otherwise - a ref always
  // reads the current value instead.
  const [lobbyChatMessages, setLobbyChatMessages] = useState([]);
  const [lobbyChatDraft, setLobbyChatDraft] = useState('');
  const [showLobbyChat, setShowLobbyChat] = useState(false);
  const [lobbyChatUnread, setLobbyChatUnread] = useState(0);
  const showLobbyChatRef = useRef(false);
  useEffect(() => { showLobbyChatRef.current = showLobbyChat; if (showLobbyChat) setLobbyChatUnread(0); }, [showLobbyChat]);
  const lobbyChatScrollRef = useRef(null);
  // [NEW FEATURE] Reply-to-message — holds the message currently being
  // replied to (or null), shown as a small preview above the input box,
  // same idea as WhatsApp/Telegram's reply feature. Shared shape used by
  // both the regular meeting chat and the ghost chat.
  const [replyingTo, setReplyingTo] = useState(null);
  const [ghostReplyingTo, setGhostReplyingTo] = useState(null);
  const [lobbyReplyingTo, setLobbyReplyingTo] = useState(null);
  const [meetingCooldownNotice, setMeetingCooldownNotice] = useState(null); // [LOCAL-UI] seconds remaining, briefly shown
  // [NEW FEATURE] Task-reminder banner + inactivity-kick notice state -
  // see the taskReminder/kickedForInactivity socket handlers above.
  const [showTaskReminder, setShowTaskReminder] = useState(false);
  const [taskReminderKey, setTaskReminderKey] = useState(0);
  const [taskReminderInfo, setTaskReminderInfo] = useState({ strikeNumber: 1, maxStrikes: 3, intervalMs: 180000 });
  const [inactivityKickedNotice, setInactivityKickedNotice] = useState(false);
  // [NEW FEATURE] Saboteur kill-timer state - see the saboteurKillAlarm/
  // saboteurKillCountdownStart/saboteurEliminatedForInactivity socket
  // handlers above.
  const [showSaboteurAlarm, setShowSaboteurAlarm] = useState(false);
  const [saboteurAlarmKey, setSaboteurAlarmKey] = useState(0);
  const [saboteurAlarmInfo, setSaboteurAlarmInfo] = useState({ remainingMs: null });
  const [saboteurCountdownMs, setSaboteurCountdownMs] = useState(null); // null = no active countdown
  useEffect(() => {
    // [BUG FIX] This local per-second countdown didn't know anything
    // about meetings - it would keep ticking down purely client-side
    // even while a meeting/chat/voting screen was open, which no longer
    // matches the backend's own timer (now genuinely paused during a
    // meeting - see the saboteurKillTimer interval's comments). Pausing
    // it here too keeps the displayed number in sync with what the
    // server is actually still counting.
    if (saboteurCountdownMs === null || meeting) return;
    if (saboteurCountdownMs <= 0) return;
    const t = setInterval(() => {
      // [NEW FEATURE] A tick sound once per second for the whole 60s
      // countdown, building tension like a ticking clock - stops
      // automatically the moment the countdown itself stops (meeting
      // starts, Saboteur kills, or time runs out), since it's driven by
      // this same interval.
      playTickSound();
      setSaboteurCountdownMs((ms) => (ms === null ? null : Math.max(0, ms - 1000)));
    }, 1000);
    return () => clearInterval(t);
  }, [saboteurCountdownMs !== null, !!meeting]);
  // [NEW FEATURE] Which target (a player id, 'skip', or 'me') the player
  // just tapped but hasn't confirmed yet - shows a tick/cross
  // confirmation overlay on that specific target's card before the vote
  // actually gets cast. null when nothing's pending.
  const [pendingVoteTarget, setPendingVoteTarget] = useState(null);
  // Clear any pending (unconfirmed) vote-tap whenever the meeting's
  // stage itself changes - e.g. if voting somehow ends while a
  // confirmation popup is still open, it shouldn't linger into whatever
  // screen comes next.
  useEffect(() => { setPendingVoteTarget(null); }, [meeting?.stage]);

  // One active stake position per player, ever — null when nothing is
  // staked. { assetId, amount, startedAt, lastClaimAt } — lastClaimAt moves
  // forward each time a reward is claimed, so only the *new* elapsed window
  // is ever paid out, never the same window twice.
  const [stakePosition, setStakePosition] = useState(null); // [PER-PLAYER]
  // Confidential Mode — toggled on from the Confidential Vault. `active`
  // becomes true only after the 3s activation delay completes; `expiresAt`
  // is when it auto-shuts-off (2 minutes after activation), enforced by the
  // effect below regardless of whether any popup is currently open.
  const [confidentialMode, setConfidentialMode] = useState({ active: false, activating: false, expiresAt: null }); // [PER-PLAYER]
  useEffect(() => {
    if (!confidentialMode.active || !confidentialMode.expiresAt) return;
    const msLeft = confidentialMode.expiresAt - Date.now();
    if (msLeft <= 0) {
      setConfidentialMode({ active: false, activating: false, expiresAt: null });
      return;
    }
    const t = setTimeout(() => setConfidentialMode({ active: false, activating: false, expiresAt: null }), msLeft);
    return () => clearTimeout(t);
  }, [confidentialMode.active, confidentialMode.expiresAt]);

  // Power sabotage — when true, vision shrinks drastically (handled in the
  // fog-of-war render below) until someone repairs the breaker panel at the
  // Electrical room. In the real game this gets flipped on by a Saboteur
  // role; for now it's flipped on via the test panel (see TEST PANEL below).
  // [MULTIPLAYER: SHARED]
  const [powerSabotaged, setPowerSabotaged] = useState(false);
  // Hacker attack — a second, independent Saboteur sabotage. While true, the
  // whole screen pulses red (Among-Us-style alarm) until someone resolves
  // it at the Cyber Defense Center. [MULTIPLAYER: SHARED]
  const [hackerAttack, setHackerAttack] = useState(false);

  // ── Saboteur action panel — usage limits + shared cooldown ─────────────
  // Each of the 4 sabotage actions has its own lifetime usage cap (power
  // cut and hacker attack: 3 each; each gate-lock side: 5 each), but all 4
  // share ONE 20-second cooldown — using any one of them locks out all 4
  // for that duration, not just the one used.
  // [MULTIPLAYER: SHARED — visible to everyone, even though only the
  // Saboteur who owns these limits can trigger the actions]
  const SABOTAGE_COOLDOWN_MS = 20000;
  const SABOTAGE_USES = { power: 3, hacker: 3, gateLeft: 5, gateRight: 5 };
  const [sabotageUsesLeft, setSabotageUsesLeft] = useState({ ...SABOTAGE_USES });
  const [sabotageCooldownUntil, setSabotageCooldownUntil] = useState(0);
  const [sabotageCooldownSecLeft, setSabotageCooldownSecLeft] = useState(0); // [LOCAL-UI] (derived countdown display)
  useEffect(() => {
    if (!sabotageCooldownUntil) { setSabotageCooldownSecLeft(0); return; }
    const update = () => {
      const left = Math.ceil((sabotageCooldownUntil - Date.now()) / 1000);
      setSabotageCooldownSecLeft(left > 0 ? left : 0);
    };
    update();
    const t = setInterval(update, 250);
    return () => clearInterval(t);
  }, [sabotageCooldownUntil]);

  // ── Disguise (Saboteur action #5) ───────────────────────────────────
  // Deliberately separate from the 4 sabotage actions above — it does NOT
  // share their 20s cooldown, and it's the ONE action that stays usable
  // during the 20s kill-lockdown (see handleKillDummy below). Disguise has
  // its own independent 30s cooldown and a lifetime cap of 3 uses. While
  // active, the player's own rendered avatar swaps to a random different
  // one for exactly 15s, then automatically reverts — this runs to
  // completion even if a kill happens mid-disguise (per design: a kill
  // doesn't cut the disguise short, it just starts the 20s lockdown
  // alongside/after it).
  // [MULTIPLAYER: SHARED — other players should see the disguised avatar
  // too, not just the Saboteur's own screen]
  const DISGUISE_DURATION_MS = 15000;
  const DISGUISE_COOLDOWN_MS = 30000;
  const DISGUISE_MAX_USES = 3;
  const [disguiseUsesLeft, setDisguiseUsesLeft] = useState(DISGUISE_MAX_USES);
  const [disguiseCooldownUntil, setDisguiseCooldownUntil] = useState(0);
  const [disguiseCooldownSecLeft, setDisguiseCooldownSecLeft] = useState(0); // [LOCAL-UI]
  // null while not disguised; otherwise the avatar id being worn instead
  // of the player's real one, plus when it ends.
  const [disguiseActive, setDisguiseActive] = useState(null); // { avatarId, endsAt } | null
  useEffect(() => {
    if (!disguiseCooldownUntil) { setDisguiseCooldownSecLeft(0); return; }
    const update = () => {
      const left = Math.ceil((disguiseCooldownUntil - Date.now()) / 1000);
      setDisguiseCooldownSecLeft(left > 0 ? left : 0);
    };
    update();
    const t = setInterval(update, 250);
    return () => clearInterval(t);
  }, [disguiseCooldownUntil]);
  // Auto-reverts the disguise after its full 15s, regardless of anything
  // else happening in the meantime (kills, etc. don't cut it short).
  useEffect(() => {
    if (!disguiseActive) return;
    const msLeft = disguiseActive.endsAt - Date.now();
    if (msLeft <= 0) { setDisguiseActive(null); return; }
    const t = setTimeout(() => {
      setDisguiseActive(null);
      // [BUG FIX] Explicitly tell the server the disguise ended, so
      // everyone else's screen reverts us back to our real avatar at
      // the exact same moment our own does, rather than waiting on the
      // server's own 15s safety-net timer (which exists only as a
      // fallback in case this event itself never arrives).
      socketRef.current?.emit('endDisguise');
    }, msLeft);
    return () => clearTimeout(t);
  }, [disguiseActive]);
  // Live countdown (seconds remaining) while disguised — shown directly on
  // the Saboteur panel's Disguise button itself, per request, rather than
  // a separate indicator.
  const [disguiseSecLeft, setDisguiseSecLeft] = useState(0); // [LOCAL-UI]
  useEffect(() => {
    if (!disguiseActive) { setDisguiseSecLeft(0); return; }
    const update = () => {
      const left = Math.ceil((disguiseActive.endsAt - Date.now()) / 1000);
      setDisguiseSecLeft(left > 0 ? left : 0);
    };
    update();
    const t = setInterval(update, 250);
    return () => clearInterval(t);
  }, [disguiseActive]);
  const triggerDisguise = useCallback((chosenAvatarId) => {
    const now = Date.now();
    if (playerRole !== 'saboteur') return;
    if (disguiseActive) return; // already disguised
    if (now < disguiseCooldownUntil) return;
    if (disguiseUsesLeft <= 0) return;
    if (!chosenAvatarId || chosenAvatarId === playerAvatarId) return; // must pick a different avatar

    setDisguiseUsesLeft(u => u - 1);
    setDisguiseCooldownUntil(now + DISGUISE_COOLDOWN_MS);
    setDisguiseActive({ avatarId: chosenAvatarId, endsAt: now + DISGUISE_DURATION_MS });
    // [BUG FIX] Tell the server we're disguising - relayed to everyone
    // else as playerDisguised, so their otherPlayers entry for us shows
    // the disguised avatar too, instead of only our own screen ever
    // reflecting the disguise while everyone else kept seeing our real
    // avatar the whole time.
    socketRef.current?.emit('activateDisguise', { avatarId: chosenAvatarId });
  }, [playerRole, disguiseActive, disguiseCooldownUntil, disguiseUsesLeft, playerAvatarId]);
  // What the player's avatar should actually render as right now — the
  // disguise if active, otherwise their real chosen avatar. Every render
  // site that draws "the player's avatar" should use this instead of
  // playerAvatarId directly, so the disguise is reflected everywhere
  // (in-world sprite, kill cutscene, etc.) with one single source of truth.
  const displayedAvatarId = disguiseActive ? disguiseActive.avatarId : playerAvatarId;

  // ── Kill mechanic ────────────────────────────────────────────────────
  // Separate from the sabotage-action cooldown — killing has its own 15s
  // cooldown, independent of (and not affected by) using sabotage actions.
  // [MULTIPLAYER: SHARED]
  const KILL_COOLDOWN_MS = 25000;
  const [killCooldownUntil, setKillCooldownUntil] = useState(0);
  const [killCooldownSecLeft, setKillCooldownSecLeft] = useState(0); // [LOCAL-UI] (derived countdown display)
  useEffect(() => {
    if (!killCooldownUntil) { setKillCooldownSecLeft(0); return; }
    const update = () => {
      const left = Math.ceil((killCooldownUntil - Date.now()) / 1000);
      setKillCooldownSecLeft(left > 0 ? left : 0);
    };
    update();
    const t = setInterval(update, 250);
    return () => clearInterval(t);
  }, [killCooldownUntil]);

  // Post-kill lockdown — for 20s after any kill, the 4 sabotage actions
  // (power/hacker/gate-left/gate-right) are entirely off-limits, regardless
  // of their own individual cooldown/uses-left state. Disguise is the only
  // action exempt from this. [MULTIPLAYER: SHARED]
  const POST_KILL_LOCK_MS = 20000;
  const [postKillLockUntil, setPostKillLockUntil] = useState(0);
  const [postKillLockSecLeft, setPostKillLockSecLeft] = useState(0); // [LOCAL-UI]
  useEffect(() => {
    if (!postKillLockUntil) { setPostKillLockSecLeft(0); return; }
    const update = () => {
      const left = Math.ceil((postKillLockUntil - Date.now()) / 1000);
      setPostKillLockSecLeft(left > 0 ? left : 0);
    };
    update();
    const t = setInterval(update, 250);
    return () => clearInterval(t);
  }, [postKillLockUntil]);

  // ── Kill cutscene ────────────────────────────────────────────────────
  // Among-Us-style: when a kill happens, gameplay pauses and BOTH the
  // killer and victim are shown in a close-up, centered cutscene together
  // — not just a small in-world effect. Runs through a few short stages
  // (approach/lunge, strike, fall) over a fixed 2.5s window, then
  // dismisses automatically and the body/blood are left behind in-world.
  // [MULTIPLAYER: SHARED — every nearby player should see this play out,
  // not just the killer]
  const KILL_CUTSCENE_MS = 2500;
  // null while no cutscene is active; otherwise { id, stage, ... } where
  // stage walks through 'lunge' -> 'strike' -> 'fall' as time progresses.
  const [killCutscene, setKillCutscene] = useState(null);
  // Keyed on killCutscene?.id (a stable value set once when the cutscene
  // starts), not the whole object — the object changes on every stage
  // transition, and since those transitions happen INSIDE this same
  // effect's own setTimeout calls, depending on the whole object would
  // re-run the effect (and clear+restart its own timers) on every stage
  // change, looping back to 'lunge' forever instead of ever reaching
  // 'fall'. Keying on the stable id makes this run exactly once per kill.
  useEffect(() => {
    if (!killCutscene) return;
    const t1 = setTimeout(() => setKillCutscene(c => c && { ...c, stage: 'strike' }), 700);
    const t2 = setTimeout(() => setKillCutscene(c => c && { ...c, stage: 'fall' }), 1300);
    const t3 = setTimeout(() => {
      // Cutscene's over — this is the moment the kill actually "lands":
      // mark the victim dead and drop their body at the spot they died,
      // so the body/blood appear right as gameplay resumes, not before.
      // [MULTIPLAYER] Branches on whether the victim was me or someone
      // else, since "my own alive-state" and "another player's
      // alive-state" live in two different pieces of state (myAlive vs
      // otherPlayers[id].alive) — see their declarations above.
      const targetId = killCutscene.targetId;
      const bodyPos = { x: killCutscene.dummyWorldX, y: killCutscene.dummyWorldY };
      if (targetId === socketRef.current?.id) {
        setMyAlive(false);
      }
      setDeadBodies((prev) => ({
        ...prev,
        [targetId]: { ...bodyPos, avatarId: otherPlayersRef.current[targetId]?.avatarId || playerAvatarId },
      }));
      setKillCutscene(null);
    }, KILL_CUTSCENE_MS);
    return () => { clearTimeout(t1); clearTimeout(t2); clearTimeout(t3); };
  }, [killCutscene?.id]);

  // ── Saboteur gate lock ─────────────────────────────────────────────────
  // { group: 'A'|'B'|null, expiresAt: number|null }. Only one group can be
  // locked at a time — locking the other side first requires this one to
  // expire (or be cleared). Kept in sync with the module-level
  // gateLockState object so the movement/collision code (a plain function,
  // not a component) can read it synchronously every frame.
  // [MULTIPLAYER: SHARED]
  const [gateLock, setGateLock] = useState({ group: null, expiresAt: null });
  // [NEW FEATURE] Shared crew mission-progress meter - visible to EVERY
  // player (crewmate, Saboteur, and ghost alike), driven entirely by the
  // server's crewProgressUpdated broadcast (see computeCrewProgress on
  // the backend). { percent, done, total } across ALL crewmates
  // (alive + dead), summed.
  const [crewProgress, setCrewProgress] = useState({ percent: 0, done: 0, total: 0, minDone: 0 });

  // ── Sabotage alert sounds ──────────────────────────────────────────────
  // Synthesized with the Web Audio API (no audio files to load — zero extra
  // network weight). Two classic, instantly-recognizable alarm archetypes:
  //  - Power outage: a slow, deep, pulsing single-tone beep — the familiar
  //    "system failure" / life-support-alarm sound.
  //  - Hacker attack: a fast alternating two-tone siren — the familiar
  //    police/security-alarm "EE-OO-EE-OO" pattern.
  // Both respect the soundOn toggle and stop immediately once their
  // sabotage is resolved.
  const audioCtxRef = useRef(null);
  const getAudioCtx = useCallback(() => {
    if (!audioCtxRef.current) {
      const Ctx = window.AudioContext || window.webkitAudioContext;
      if (Ctx) audioCtxRef.current = new Ctx();
    }
    // Browsers create AudioContexts in a "suspended" state until resumed —
    // usually tied to a user gesture. Without this, oscillators schedule
    // and "play" with zero audible output. Resuming here (called from
    // every sound trigger, most of which originate from a tap/click) keeps
    // actual playback working without needing a separate unlock screen.
    if (audioCtxRef.current && audioCtxRef.current.state === 'suspended') {
      audioCtxRef.current.resume();
    }
    return audioCtxRef.current;
  }, []);

  // Some browsers only allow resuming a suspended AudioContext from inside
  // an actual user-gesture event handler (not just "called sometime after a
  // tap happened elsewhere"). This one-time listener creates/resumes the
  // context on the very first interaction with the page, so by the time any
  // gameplay sound tries to play, the context is already running.
  useEffect(() => {
    const unlock = () => {
      const ctx = getAudioCtx();
      if (ctx && ctx.state === 'suspended') ctx.resume();
      window.removeEventListener('pointerdown', unlock);
      window.removeEventListener('keydown', unlock);
      window.removeEventListener('touchstart', unlock);
    };
    window.addEventListener('pointerdown', unlock);
    window.addEventListener('keydown', unlock);
    window.addEventListener('touchstart', unlock);
    return () => {
      window.removeEventListener('pointerdown', unlock);
      window.removeEventListener('keydown', unlock);
      window.removeEventListener('touchstart', unlock);
    };
  }, [getAudioCtx]);

  // One-shot "lock clank" sound — plays once right when a lock is
  // triggered, not continuously. A short low-to-lower two-note thud, like a
  // heavy bolt slamming shut.
  const playGateLockSound = useCallback(() => {
    if (!soundOn) return;
    const ctx = getAudioCtx();
    if (!ctx) return;
    [220, 140].forEach((freq, i) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'square';
      osc.frequency.value = freq;
      gain.gain.value = 0;
      osc.connect(gain).connect(ctx.destination);
      const now = ctx.currentTime + i * 0.07;
      gain.gain.linearRampToValueAtTime(0.08, now + 0.01);
      gain.gain.linearRampToValueAtTime(0, now + 0.16);
      osc.start(now);
      osc.stop(now + 0.17);
    });
  }, [soundOn, getAudioCtx]);

  // One-shot "unlock clank" — the mirror of the lock sound, low-to-high
  // instead of high-to-low, so it reads as a bolt sliding open rather than
  // slamming shut.
  const playGateUnlockSound = useCallback(() => {
    if (!soundOn) return;
    const ctx = getAudioCtx();
    if (!ctx) return;
    // A single smooth rising glide — sine wave sweeping up in pitch, like a
    // spring-loaded bolt releasing — clearly distinct in shape and timbre
    // from the two sharp square-wave thuds of the lock sound.
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    gain.gain.value = 0;
    osc.connect(gain).connect(ctx.destination);
    const now = ctx.currentTime;
    osc.frequency.setValueAtTime(160, now);
    osc.frequency.exponentialRampToValueAtTime(520, now + 0.22);
    gain.gain.linearRampToValueAtTime(0.07, now + 0.03);
    gain.gain.linearRampToValueAtTime(0, now + 0.26);
    osc.start(now);
    osc.stop(now + 0.27);
  }, [soundOn, getAudioCtx]);

  // [NEW FEATURE] Short attention-grabbing "ding" for the task-reminder /
  // saboteur-alarm popups - a quick two-note rising chime (~0.9s total),
  // distinct in timbre from every other sound in the game so it reads
  // unambiguously as "look at this notification" the moment it plays.
  const playAlertPopupSound = useCallback(() => {
    if (!soundOn) return;
    const ctx = getAudioCtx();
    if (!ctx) return;
    const now = ctx.currentTime;
    [[660, 0], [880, 0.16]].forEach(([freq, delay]) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'triangle';
      gain.gain.value = 0;
      osc.connect(gain).connect(ctx.destination);
      const t = now + delay;
      osc.frequency.setValueAtTime(freq, t);
      gain.gain.linearRampToValueAtTime(0.09, t + 0.03);
      gain.gain.linearRampToValueAtTime(0, t + 0.32);
      osc.start(t);
      osc.stop(t + 0.33);
    });
  }, [soundOn, getAudioCtx]);

  // [NEW FEATURE] A single short "tick" - meant to be called once per
  // second for the Saboteur's final 60-second countdown, building tension
  // like a ticking clock. Deliberately tiny/dry (a very short square-wave
  // click) so 60 repeats in a row stays unobtrusive rather than grating.
  const playTickSound = useCallback(() => {
    if (!soundOn) return;
    const ctx = getAudioCtx();
    if (!ctx) return;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'square';
    gain.gain.value = 0;
    osc.connect(gain).connect(ctx.destination);
    const now2 = ctx.currentTime;
    osc.frequency.setValueAtTime(1000, now2);
    gain.gain.linearRampToValueAtTime(0.05, now2 + 0.01);
    gain.gain.linearRampToValueAtTime(0, now2 + 0.06);
    osc.start(now2);
    osc.stop(now2 + 0.07);
  }, [soundOn, getAudioCtx]);

  // Synthesized "kill" impact sound — a sharp, short filtered-noise hit
  // (the strike) immediately followed by a low descending thud (the
  // impact/fall). Entirely original Web Audio synthesis, not sampled or
  // copied from any existing game.
  const playKillSound = useCallback(() => {
    if (!soundOn) return;
    const ctx = getAudioCtx();
    if (!ctx) return;
    const now = ctx.currentTime;

    // Sharp noise burst — the "strike"
    const bufferSize = Math.floor(ctx.sampleRate * 0.08);
    const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) data[i] = Math.random() * 2 - 1;
    const noise = ctx.createBufferSource();
    noise.buffer = buffer;
    const filter = ctx.createBiquadFilter();
    filter.type = 'highpass';
    filter.frequency.value = 1800;
    const noiseGain = ctx.createGain();
    noiseGain.gain.setValueAtTime(0.18, now);
    noiseGain.gain.exponentialRampToValueAtTime(0.001, now + 0.08);
    noise.connect(filter).connect(noiseGain).connect(ctx.destination);
    noise.start(now);
    noise.stop(now + 0.09);

    // Low descending thud — the impact, landing right after the strike
    const thudOsc = ctx.createOscillator();
    const thudGain = ctx.createGain();
    thudOsc.type = 'sine';
    thudOsc.frequency.setValueAtTime(180, now + 0.04);
    thudOsc.frequency.exponentialRampToValueAtTime(55, now + 0.35);
    thudGain.gain.setValueAtTime(0, now + 0.04);
    thudGain.gain.linearRampToValueAtTime(0.22, now + 0.07);
    thudGain.gain.exponentialRampToValueAtTime(0.001, now + 0.4);
    thudOsc.connect(thudGain).connect(ctx.destination);
    thudOsc.start(now + 0.04);
    thudOsc.stop(now + 0.42);
  }, [soundOn, getAudioCtx]);

  // Synthesized vent enter/exit sound — a brief metallic "whoosh + clang"
  // (filtered noise sweep for the air/movement, plus a short ringing tone
  // for the metal grate), distinct in direction: entering sweeps the
  // noise-filter frequency DOWN (sucked in/away), exiting sweeps it UP
  // (popped back out). Entirely original Web Audio synthesis.
  const playVentSound = useCallback((entering) => {
    if (!soundOn) return;
    const ctx = getAudioCtx();
    if (!ctx) return;
    const now = ctx.currentTime;

    // Whoosh — filtered noise with a moving cutoff frequency
    const bufferSize = Math.floor(ctx.sampleRate * 0.3);
    const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) data[i] = Math.random() * 2 - 1;
    const noise = ctx.createBufferSource();
    noise.buffer = buffer;
    const filter = ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.Q.value = 1.2;
    if (entering) {
      filter.frequency.setValueAtTime(2200, now);
      filter.frequency.exponentialRampToValueAtTime(400, now + 0.28);
    } else {
      filter.frequency.setValueAtTime(400, now);
      filter.frequency.exponentialRampToValueAtTime(2200, now + 0.28);
    }
    const noiseGain = ctx.createGain();
    noiseGain.gain.setValueAtTime(0.001, now);
    noiseGain.gain.linearRampToValueAtTime(0.16, now + 0.05);
    noiseGain.gain.exponentialRampToValueAtTime(0.001, now + 0.3);
    noise.connect(filter).connect(noiseGain).connect(ctx.destination);
    noise.start(now);
    noise.stop(now + 0.32);

    // Short metallic clang — a couple of overtone-rich, fast-decaying tones
    const clangFreqs = entering ? [520, 780] : [420, 630];
    clangFreqs.forEach((freq, i) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'triangle';
      osc.frequency.value = freq;
      const t0 = now + (entering ? 0.16 : 0.02) + i * 0.02;
      gain.gain.setValueAtTime(0.001, t0);
      gain.gain.linearRampToValueAtTime(0.09, t0 + 0.01);
      gain.gain.exponentialRampToValueAtTime(0.001, t0 + 0.18);
      osc.connect(gain).connect(ctx.destination);
      osc.start(t0);
      osc.stop(t0 + 0.2);
    });
  }, [soundOn, getAudioCtx]);


  // Sliding-door sound for the regular (non-Saboteur-locked) gates that
  // animate open/closed as the player walks near them — an original
  // "whoosh + mechanical clunk" design (not a copy of any existing game's
  // door audio): a short burst of filtered noise for the slide, immediately
  // followed by a low percussive thud as the panels reach the end of their
  // travel. Opening glides slightly upward in tone, closing glides slightly
  // downward, so the two directions are subtly distinguishable by ear.
  const playGateSlideSound = useCallback((opening) => {
    if (!soundOn) return;
    const ctx = getAudioCtx();
    if (!ctx) return;
    const now = ctx.currentTime;
    const bufferSize = Math.floor(ctx.sampleRate * 0.12);
    const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) data[i] = Math.random() * 2 - 1;
    const noise = ctx.createBufferSource();
    noise.buffer = buffer;
    const filter = ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.setValueAtTime(opening ? 900 : 1400, now);
    filter.frequency.exponentialRampToValueAtTime(opening ? 1400 : 900, now + 0.11);
    filter.Q.value = 1.2;
    const noiseGain = ctx.createGain();
    noiseGain.gain.setValueAtTime(0.05, now);
    noiseGain.gain.linearRampToValueAtTime(0, now + 0.12);
    noise.connect(filter).connect(noiseGain).connect(ctx.destination);
    noise.start(now);
    noise.stop(now + 0.13);
    const thudOsc = ctx.createOscillator();
    const thudGain = ctx.createGain();
    thudOsc.type = 'sine';
    thudOsc.frequency.value = opening ? 110 : 95;
    thudGain.gain.value = 0;
    thudOsc.connect(thudGain).connect(ctx.destination);
    const thudStart = now + 0.1;
    thudGain.gain.linearRampToValueAtTime(0.07, thudStart + 0.005);
    thudGain.gain.linearRampToValueAtTime(0, thudStart + 0.08);
    thudOsc.start(thudStart);
    thudOsc.stop(thudStart + 0.09);
  }, [soundOn, getAudioCtx]);

  // ── Footstep sound ───────────────────────────────────────────────────
  // A soft, synthesized "pad" footstep — short filtered-noise tap with a
  // touch of low thud underneath, alternating between two slightly
  // different pitches (left/right step) so a running cadence doesn't sound
  // robotically identical every time, similar in spirit to Among Us's
  // walk sound without reusing any of its actual audio. Triggered on a
  // timer from the movement loop while isMoving is true (see
  // footstepIntervalRef below), not on every animation frame.
  const footstepStepRef = useRef(0);
  const playFootstepSound = useCallback(() => {
    if (!soundOn) return;
    const ctx = getAudioCtx();
    if (!ctx) return;
    const now = ctx.currentTime;
    const stepAlt = footstepStepRef.current % 2 === 0;
    footstepStepRef.current += 1;

    // Short filtered noise burst — the "pad" contact of a footstep.
    const bufferSize = Math.floor(ctx.sampleRate * 0.045);
    const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) data[i] = Math.random() * 2 - 1;
    const noise = ctx.createBufferSource();
    noise.buffer = buffer;
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = stepAlt ? 950 : 880;
    filter.Q.value = 0.7;
    const noiseGain = ctx.createGain();
    noiseGain.gain.setValueAtTime(0.1, now);
    noiseGain.gain.linearRampToValueAtTime(0, now + 0.045);
    noise.connect(filter).connect(noiseGain).connect(ctx.destination);
    noise.start(now);
    noise.stop(now + 0.05);

    // Very low, very brief thud underneath, for a bit of weight.
    const thudOsc = ctx.createOscillator();
    const thudGain = ctx.createGain();
    thudOsc.type = 'sine';
    thudOsc.frequency.value = stepAlt ? 105 : 98;
    thudGain.gain.value = 0;
    thudOsc.connect(thudGain).connect(ctx.destination);
    thudGain.gain.linearRampToValueAtTime(0.11, now + 0.004);
    thudGain.gain.linearRampToValueAtTime(0, now + 0.05);
    thudOsc.start(now);
    thudOsc.stop(now + 0.055);
  }, [soundOn, getAudioCtx]);


  // plays exactly once per transition — not continuously while a gate sits
  // open, and not on renders where nothing changed. Re-evaluated whenever
  // the player moves (the only thing that can change a gate's distance to
  // them) and whenever a Saboteur lock toggles (which can force gates shut
  // outside of normal proximity rules).
  const gateOpenStateRef = useRef(new Map());
  const lastGateCheckRef = useRef(0);
  useEffect(() => {
    // [PERFORMANCE] Throttled to ~10x/second - otherPlayers can update
    // very frequently (the interpolation loop touches it every frame),
    // and re-scanning all 36 gates against every player's position on
    // every single one of those updates would be wasteful. A 100ms
    // throttle is still far faster than a human can perceive a gate's
    // open/close transition lagging behind.
    const now = performance.now();
    if (now - lastGateCheckRef.current < 100) return;
    lastGateCheckRef.current = now;

    const pcx = pos.x + PLAYER_SIZE / 2, pcy = pos.y + PLAYER_SIZE / 2;
    // [BUG FIX] Build the full list of every alive player's position
    // (ourselves + every otherPlayers entry with known x/y) - this is
    // what makes a gate actually open/close (and play its sound) in
    // response to ANY player walking through it, not just ourselves.
    const allPositions = myAlive ? [{ x: pcx, y: pcy }] : [];
    for (const id in otherPlayers) {
      const p = otherPlayers[id];
      if (p.alive === false) continue;
      if (typeof p.x !== 'number' || typeof p.y !== 'number') continue;
      allPositions.push({ x: p.x + PLAYER_SIZE / 2, y: p.y + PLAYER_SIZE / 2 });
    }
    // [BUG FIX] Half the camera's own view-width in pixels - the camera
    // is always centered on US, so "is this gate currently visible on
    // OUR screen" is equivalent to "is this gate within half the view
    // width of our own position." VIEW_TILES/TILE are module-level
    // constants the render below also uses for the camera itself, so
    // this stays in sync with whatever the actual camera shows.
    const halfViewPx = (VIEW_TILES * TILE) / 2;
    for (const g of GATES) {
      const gcx = (g.x + g.w / 2) * TILE, gcy = (g.y + g.h / 2) * TILE;
      const inOwnView = Math.abs(gcx - pcx) < halfViewPx && Math.abs(gcy - pcy) < halfViewPx;
      const nowOpen = isGateOpen(g, allPositions);
      const wasOpen = gateOpenStateRef.current.get(g.id);
      if (wasOpen === undefined) {
        // First time we've seen this gate — just record its state, don't
        // play a sound for the initial spawn-in.
        gateOpenStateRef.current.set(g.id, nowOpen);
        continue;
      }
      if (nowOpen !== wasOpen) {
        gateOpenStateRef.current.set(g.id, nowOpen);
        // [BUG FIX] Only actually play the sound if this gate is
        // currently within OUR OWN camera view - otherwise every gate
        // anywhere on the whole map (any player walking through ANY of
        // the 36 gates) would play its slide sound regardless of
        // whether we could even see it happening, which is noisy and
        // makes it impossible to tell which gate it was. The open/closed
        // STATE itself is still tracked for every gate (so it renders
        // correctly the moment it scrolls into view), only the sound is
        // gated on visibility.
        if (inOwnView) playGateSlideSound(nowOpen);
      }
    }
  }, [pos, otherPlayers, myAlive, gateLock.group, playGateSlideSound]);

  useEffect(() => {
    gateLockState.lockedIds = gateLock.group === 'A' ? new Set(GATE_GROUP_A)
      : gateLock.group === 'B' ? new Set(GATE_GROUP_B)
      : null;
  }, [gateLock.group]);
  useEffect(() => {
    if (!gateLock.group || !gateLock.expiresAt) return;
    const msLeft = gateLock.expiresAt - Date.now();
    if (msLeft <= 0) { playGateUnlockSound(); setGateLock({ group: null, expiresAt: null }); return; }
    const t = setTimeout(() => { playGateUnlockSound(); setGateLock({ group: null, expiresAt: null }); }, msLeft);
    return () => clearTimeout(t);
  }, [gateLock.group, gateLock.expiresAt, playGateUnlockSound]);
  // Live seconds-remaining for the countdown badge next to the map icon —
  // recalculated every second from expiresAt rather than decremented by
  // hand, so it can't drift out of sync with the actual unlock effect above.
  const [lockSecondsLeft, setLockSecondsLeft] = useState(0);
  useEffect(() => {
    if (!gateLock.group || !gateLock.expiresAt) { setLockSecondsLeft(0); return; }
    const update = () => setLockSecondsLeft(Math.max(0, Math.ceil((gateLock.expiresAt - Date.now()) / 1000)));
    update();
    const t = setInterval(update, 1000);
    return () => clearInterval(t);
  }, [gateLock.group, gateLock.expiresAt]);


  const handleLockGateGroup = useCallback((group) => {
    setGateLock(prev => {
      if (prev.group) return prev; // a lock is already active — can't lock the other side
      playGateLockSound();
      return { group, expiresAt: Date.now() + GATE_LOCK_DURATION_MS };
    });
  }, [playGateLockSound]);

  // Single entry point for all 4 Saboteur sabotage actions — enforces the
  // per-action lifetime usage cap, the shared 20s cooldown across all 4,
  // AND the post-kill lockdown (these 4 are completely off-limits for 20s
  // after any kill, regardless of their own cooldown/uses-left state).
  // Returns nothing; UI buttons just check sabotageUsesLeft/
  // sabotageCooldownSecLeft/postKillLockSecLeft themselves to decide
  // whether to render as disabled in the first place.
  const triggerSabotageAction = useCallback((key) => {
    const now = Date.now();
    if (!myAlive) return; // [MULTIPLAYER] ghosts can't sabotage
    if (now < postKillLockUntil) return; // locked out following a recent kill
    if (now < sabotageCooldownUntil) return; // still on shared cooldown
    if ((sabotageUsesLeft[key] || 0) <= 0) return; // no uses left for this action

    setSabotageUsesLeft(prev => ({ ...prev, [key]: prev[key] - 1 }));
    setSabotageCooldownUntil(now + SABOTAGE_COOLDOWN_MS);

    if (key === 'power') setPowerSabotaged(true);
    else if (key === 'hacker') setHackerAttack(true);
    else if (key === 'gateLeft') handleLockGateGroup('A');
    else if (key === 'gateRight') handleLockGateGroup('B');

    // [MULTIPLAYER: SHARED] Tell the server this sabotage happened so it
    // can broadcast it to everyone else in the room. Our own local state
    // above already updated immediately (no need to wait for a round-trip
    // to see our own effect), but other players only learn about it
    // through this event — see the sabotageTriggered handler for how they
    // receive it. The server maps our local key names to its own type
    // strings: power->electricity, hacker stays hacker, gateLeft/Right
    // stay as-is.
    if (socketRef.current) {
      const serverType = key === 'power' ? 'electricity' : key;
      socketRef.current.emit('sabotageAction', { type: serverType });
    }
  }, [myAlive, postKillLockUntil, sabotageCooldownUntil, sabotageUsesLeft, handleLockGateGroup]);

  // Starts a kill: only proceeds if actually in range, alive, and off
  // cooldown (the button itself is hidden/disabled in those cases too, but
  // the checks are repeated here so this function is safe to call from
  // anywhere). Doesn't kill the dummy immediately — instead kicks off the
  // 2.5s cutscene above, which applies the actual death/body-drop once it
  // finishes, so the in-world body appears right as the cutscene ends.
  // Also starts a 20s "post-kill lockdown" — separate from the kill
  // cooldown itself — during which the 4 sabotage actions (power/hacker/
  // gate-left/gate-right) are completely disabled. Disguise is
  // deliberately exempt from this lockdown (see triggerDisguise) so a
  // [MULTIPLAYER: SHARED] Sends the kill request to the server — the
  // server is the sole authority on whether this succeeds (re-validates
  // role/alive/range/target-is-saboteur independently). This function no
  // longer flips any local alive/cutscene state directly; that all now
  // happens in the playerKilled handler (see connectSocket) once the
  // server confirms the kill actually went through, so a malicious client
  // editing its own canKillDummy can't fake a kill that never happened.
  const handleKillDummy = useCallback(() => {
    const now = Date.now();
    if (playerRole !== 'saboteur') return;
    if (now < killCooldownUntil) return;
    if (!nearestKillTarget || nearestKillTarget.dist > KILL_RANGE_PX) return;
    if (!socketRef.current) return;
    socketRef.current.emit('killPlayer', { targetId: nearestKillTarget.id });
  }, [playerRole, killCooldownUntil, nearestKillTarget]);

  // ── Vent handlers ────────────────────────────────────────────────────
  // Enters the vent in the current room — only works for a Saboteur
  // actually standing near a vent grate. Plays a brief "squishing into
  // the grate" animation first, then hides the avatar and switches into
  // vent mode — matching the Among Us feel of vanishing into the vent
  // rather than just popping into a separate screen.
  const enterVent = useCallback(() => {
    if (playerRole !== 'saboteur' || !nearVent || !currentRoom) return;
    setVentAnim('entering');
    playVentSound(true);
    // [BUG FIX] Tell the server we're entering a vent — relayed to every
    // other player in the room as playerVentTravel, so their screens
    // play the exact same squish-in animation and then hide our avatar,
    // instead of it just freezing fully visible in place (which was the
    // actual bug: nothing previously told other players a vent was even
    // happening at all).
    socketRef.current?.emit('ventTravel', { phase: 'enter', roomId: currentRoom.id });
    setTimeout(() => {
      setInVent(currentRoom.id);
      setVentAnim(null);
    }, 350);
  }, [playerRole, nearVent, currentRoom, playVentSound]);

  // Travels from the vent currently occupied to a connected room's vent —
  // only allowed if the destination is an actual neighbor in
  // VENT_ADJACENCY (no jumping to an unconnected room). Moves the
  // player's real world position (and camera) to that room's vent grate,
  // so the map view shifts to the new room immediately, same as Among Us
  // popping the camera to wherever the vent comes out.
  const travelToVentRoom = useCallback((destRoomId) => {
    if (!inVent) return;
    const neighbors = VENT_ADJACENCY[inVent] || [];
    if (!neighbors.includes(destRoomId)) return; // not a direct neighbor — not allowed
    const destPos = VENT_POSITIONS[destRoomId];
    if (!destPos) return;
    setInVent(destRoomId);
    const next = { x: destPos.x * TILE, y: destPos.y * TILE };
    posRef.current = next;
    setPos(next);
    // [BUG FIX] Tell the server we moved to a new room's vent — other
    // players near the DESTINATION vent grate need to know we're now
    // hidden there too (we're invisible the whole time we're "in" any
    // vent, regardless of which room's grate we're currently at).
    socketRef.current?.emit('ventTravel', { phase: 'travel', roomId: destRoomId });
  }, [inVent]);

  // Exits the vent back into whichever room is currently occupied,
  // landing right at that room's vent grate, then plays the reverse
  // "emerging from the grate" animation.
  const exitVent = useCallback(() => {
    if (!inVent) return;
    const exitedRoomId = inVent;
    setInVent(null);
    setVentAnim('exiting');
    playVentSound(false);
    // [BUG FIX] Tell the server we're exiting — relayed to everyone else
    // as the reverse animation, so the Saboteur's avatar reappears for
    // other nearby players at the exact same moment it does for the
    // Saboteur themself, instead of having silently been visible (and
    // frozen) the entire time they were actually inside the vent.
    socketRef.current?.emit('ventTravel', { phase: 'exit', roomId: exitedRoomId });
    setTimeout(() => setVentAnim(null), 350);
  }, [inVent, playVentSound]);

  // ── Meeting handlers ────────────────────────────────────────────────
  // [MULTIPLAYER: SHARED] Sends the meeting request to the server —
  // doesn't set local meeting state directly anymore. The server is the
  // single source of truth for "is a meeting active right now" (so two
  // players can't both start one at the same time); our own meeting
  // state only gets set once the meetingStarted confirmation comes back
  // (see connectSocket), same event every player in the room receives.
  const callMeeting = useCallback((calledBy, reportedBodyId) => {
    if (meeting) return; // a meeting is already in progress
    if (!myAlive) return; // [MULTIPLAYER] ghosts can't call meetings
    if (!socketRef.current) return;
    // [BUG FIX] This is the actual root cause of "the report popup never
    // shows up" - reportedBodyId was never actually being sent to the
    // server at all, only the plain 'report' reason string. Without it,
    // the backend's reportedBody lookup (see meetingStarted) always
    // resolved to null, so the "who was found dead / who reported them"
    // popup had nothing to show, every single time.
    socketRef.current.emit('callMeeting', { reason: calledBy, reportedBodyId: reportedBodyId || null });
  }, [meeting, myAlive]);

  const sendChatMessage = useCallback(() => {
    const text = chatDraft.trim();
    if (!text || !meeting || meeting.stage !== 'chat') return;
    if (!myAlive) return; // [MULTIPLAYER] ghosts are read-only in the normal chat - use ghost chat instead
    if (!socketRef.current) return;
    // [MULTIPLAYER: SHARED] No longer appends to local messages directly
    // — the server echoes our own message back via chatMessageReceived
    // (to everyone, including us), which is what actually adds it to the
    // list. This keeps message order identical for every player instead
    // of each client racing to append its own copy first.
    socketRef.current.emit('sendChatMessage', {
      text,
      // [NEW FEATURE] Reply-to-message — sends just the small bits of
      // the message being replied to, shown as a quoted preview on the
      // recipient's side too.
      replyTo: replyingTo ? { senderName: replyingTo.senderName, text: replyingTo.text } : null,
    });
    setChatDraft('');
    setReplyingTo(null);
  }, [chatDraft, meeting, myAlive, replyingTo]);

  // [NEW FEATURE] Ghost-only chat — same pattern as sendChatMessage
  // above, but on the separate ghost channel. Works anytime (not gated
  // to meeting.stage === 'chat'), since ghosts have no other way to talk
  // to each other and aren't tied to the living crew's meeting schedule.
  const sendGhostChatMessage = useCallback(() => {
    const text = ghostChatDraft.trim();
    if (!text) return;
    if (myAlive) return; // only ghosts can use this channel
    if (!socketRef.current) return;
    socketRef.current.emit('sendGhostChatMessage', {
      text,
      replyTo: ghostReplyingTo ? { senderName: ghostReplyingTo.senderName, text: ghostReplyingTo.text } : null,
    });
    setGhostChatDraft('');
    setGhostReplyingTo(null);
  }, [ghostChatDraft, myAlive, ghostReplyingTo]);

  // [NEW FEATURE] Lobby chat send - same pattern as sendGhostChatMessage,
  // just no myAlive gate (anyone in the Lobby can use it).
  const sendLobbyChatMessage = useCallback(() => {
    const text = lobbyChatDraft.trim();
    if (!text) return;
    if (!socketRef.current) return;
    socketRef.current.emit('sendLobbyChatMessage', {
      text,
      replyTo: lobbyReplyingTo ? { senderName: lobbyReplyingTo.senderName, text: lobbyReplyingTo.text } : null,
    });
    setLobbyChatDraft('');
    setLobbyReplyingTo(null);
  }, [lobbyChatDraft, lobbyReplyingTo]);

  // [BUG FIX] Auto-scroll both chat lists to the bottom whenever a new
  // message arrives, but ONLY if the user was already near the bottom -
  // otherwise, someone who scrolled up to read older messages would get
  // yanked straight back down every time a new message came in, making
  // it impossible to actually read history during an active discussion.
  useEffect(() => {
    const el = chatScrollRef.current;
    if (!el) return;
    const nearBottom = el.scrollHeight - el.scrollTop - el.clientHeight < 80;
    if (nearBottom) el.scrollTop = el.scrollHeight;
  }, [meeting?.messages?.length]);
  useEffect(() => {
    const el = ghostChatScrollRef.current;
    if (!el) return;
    const nearBottom = el.scrollHeight - el.scrollTop - el.clientHeight < 80;
    if (nearBottom) el.scrollTop = el.scrollHeight;
  }, [ghostChatMessages.length]);
  // [NEW FEATURE] Lobby chat auto-scroll - new messages follow the same
  // "only if already near bottom" courtesy as the other two chats above,
  // but per Om7eth's explicit request, ALSO scrolls to bottom on every
  // keystroke while typing a reply (lobbyChatDraft changing) - unlike
  // the new-message case, this one is unconditional, so composing a
  // message always keeps the input/latest messages in view even if the
  // player had scrolled up to read history first.
  useEffect(() => {
    const el = lobbyChatScrollRef.current;
    if (!el) return;
    const nearBottom = el.scrollHeight - el.scrollTop - el.clientHeight < 80;
    if (nearBottom) el.scrollTop = el.scrollHeight;
  }, [lobbyChatMessages.length]);
  useEffect(() => {
    const el = lobbyChatScrollRef.current;
    if (!el || !lobbyChatDraft) return;
    el.scrollTop = el.scrollHeight;
  }, [lobbyChatDraft]);

  // [MULTIPLAYER: SHARED] Sends our vote to the server by player id (not
  // name — the server's vote-tally and elimination logic both key off
  // socket id, same id otherPlayers uses). 'skip' is sent as a literal
  // string the server already recognizes as "no target". Local myVote is
  // still set immediately for instant UI feedback (locking in our own
  // vote button) — the actual elimination outcome comes later from
  // votingResult once everyone's voted or the timeout hits.
  const castVote = useCallback((targetIdOrSkip) => {
    // [BUG FIX] Using meetingRef.current here instead of the closure-
    // captured `meeting` state - a rapid double-tap (tapping a card,
    // then accidentally tapping a second one before React re-renders to
    // disable the buttons) could otherwise read a STALE `meeting.myVote
    // === null` on the second tap too, letting it slip past this guard.
    // The server has its own independent guard and would only ever
    // record the FIRST vote either way, but the second tap's local
    // setMeeting call below would still overwrite the LOCAL myVote
    // display with the second (wrong) target - making it look like a
    // different vote was cast than what the server actually counted,
    // and making the original vote appear to "vanish" from its target.
    if (!meetingRef.current || meetingRef.current.stage !== 'voting') return;
    if (meetingRef.current.myVote !== null) return; // already voted, can't change it
    if (!myAlive) return; // [MULTIPLAYER] ghosts can't vote
    if (!socketRef.current) return;
    // [BUG FIX] Synchronously update the ref BEFORE emitting/setState -
    // closes even the extreme case of a near-simultaneous second tap
    // landing before React's next render+effect cycle would otherwise
    // have updated meetingRef.current.myVote.
    meetingRef.current = { ...meetingRef.current, myVote: targetIdOrSkip };
    socketRef.current.emit('castVote', { targetId: targetIdOrSkip === 'skip' ? null : targetIdOrSkip });
    setMeeting(m => m && { ...m, myVote: targetIdOrSkip });
  }, [myAlive]);

  // Alarm -> chat, automatically, after MEETING_ALARM_DURATION_MS.
  useEffect(() => {
    if (!meeting || meeting.stage !== 'alarm') return;
    const t = setTimeout(() => {
      setMeeting(m => m && m.stage === 'alarm' ? { ...m, stage: 'chat', startedAt: Date.now() } : m);
    }, MEETING_ALARM_DURATION_MS);
    return () => clearTimeout(t);
  }, [meeting?.stage]);

  // Chat -> voting, automatically, after the full 2.5-minute window —
  // matches the original brief: everyone gets a maximum of 2.5 minutes
  // to chat, after which chat closes and voting opens.
  useEffect(() => {
    if (!meeting || meeting.stage !== 'chat') return;
    const t = setTimeout(() => {
      setMeeting(m => m && m.stage === 'chat' ? { ...m, stage: 'voting', startedAt: Date.now() } : m);
    }, MEETING_CHAT_DURATION_MS);
    return () => clearTimeout(t);
  }, [meeting?.stage]);

  // [BUG FIX] Voting now ALWAYS waits for this 30s timer (the server no
  // longer auto-resolves the instant every alive player has voted) -
  // this is what makes "results only appear once voting time has
  // actually ended" true even if everyone votes within the first few
  // seconds. Every client independently fires this same 30s timeout;
  // the server's finalizeVoting only ever actually runs once per
  // meeting (it deletes room.meeting as part of resolving), so the
  // extra calls from other clients' timers are harmless no-ops.
  useEffect(() => {
    if (!meeting || meeting.stage !== 'voting') return;
    const t = setTimeout(() => {
      socketRef.current?.emit('forceFinalizeVoting');
    }, 30000);
    return () => clearTimeout(t);
  }, [meeting?.stage]);

  // Results -> meeting closes entirely, after a few seconds to read it.
  useEffect(() => {
    if (!meeting || meeting.stage !== 'results') return;
    const t = setTimeout(() => setMeeting(null), MEETING_RESULTS_DURATION_MS);
    return () => clearTimeout(t);
  }, [meeting?.stage]);

  useEffect(() => {
    if (!powerSabotaged || !soundOn) return;
    const ctx = getAudioCtx();
    if (!ctx) return;
    let stopped = false;
    let timer = null;
    const beep = () => {
      if (stopped) return;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.value = 200; // deep, simple tone
      gain.gain.value = 0;
      osc.connect(gain).connect(ctx.destination);
      const now = ctx.currentTime;
      const dur = 0.4;
      gain.gain.linearRampToValueAtTime(0.04, now + 0.03);
      gain.gain.linearRampToValueAtTime(0.04, now + dur - 0.05);
      gain.gain.linearRampToValueAtTime(0, now + dur);
      osc.start(now);
      osc.stop(now + dur + 0.01);
      timer = setTimeout(beep, 900); // slow, steady "system failure" cadence
    };
    beep();
    return () => { stopped = true; if (timer) clearTimeout(timer); };
  }, [powerSabotaged, soundOn, getAudioCtx]);

  useEffect(() => {
    if (!hackerAttack || !soundOn) return;
    const ctx = getAudioCtx();
    if (!ctx) return;
    let stopped = false;
    let timer = null;
    let toggle = false;
    const siren = () => {
      if (stopped) return;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'square';
      osc.frequency.value = toggle ? 740 : 555; // classic police-siren two-tone interval
      gain.gain.value = 0;
      osc.connect(gain).connect(ctx.destination);
      const now = ctx.currentTime;
      const dur = 0.22;
      gain.gain.linearRampToValueAtTime(0.022, now + 0.015);
      gain.gain.linearRampToValueAtTime(0.022, now + dur - 0.03);
      gain.gain.linearRampToValueAtTime(0, now + dur);
      osc.start(now);
      osc.stop(now + dur + 0.01);
      toggle = !toggle;
      timer = setTimeout(siren, dur * 1000);
    };
    siren();
    return () => { stopped = true; if (timer) clearTimeout(timer); };
  }, [hackerAttack, soundOn, getAudioCtx]);

  // 0 = normal vision, 1 = fully sabotaged. Animated smoothly over 2s in
  // either direction (radial-gradient strings can't be CSS-transitioned
  // reliably, so this is interpolated by hand via rAF). Drives both the
  // vision radius and the fog tint together, so the whole blackout effect
  // — shrinking AND fading to a washed-out haze — eases in as one motion,
  // the same way the lights visibly dim in Among Us rather than cutting out.
  const [sabotageProgress, setSabotageProgress] = useState(0);
  const sabotageAnimRef = useRef(null);
  useEffect(() => {
    const target = powerSabotaged ? 1 : 0;
    const start = sabotageProgress;
    if (start === target) return;
    const durationMs = 2000;
    const startTime = performance.now();
    if (sabotageAnimRef.current) cancelAnimationFrame(sabotageAnimRef.current);
    const step = (now) => {
      const t = Math.min(1, (now - startTime) / durationMs);
      const eased = t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
      setSabotageProgress(start + (target - start) * eased);
      if (t < 1) sabotageAnimRef.current = requestAnimationFrame(step);
    };
    sabotageAnimRef.current = requestAnimationFrame(step);
    return () => { if (sabotageAnimRef.current) cancelAnimationFrame(sabotageAnimRef.current); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [powerSabotaged]);
  // ─────────────────────────────────────────────────────────────────────
  // TEST PANEL — dev-only, NOT part of the real game. Lets Om7eth trigger
  // Saboteur-side effects (currently: cutting the power) without needing
  // ── NEAR Legion (admin room) ──────────────────────────────────────────
  // sbtMinted is permanent once true — the wallet-connect/mint flow only
  // ever runs once. legionDone tracks each of the 4 Legion activities
  // independently of whatever room missions were randomly assigned to this
  // player — doing the action anywhere in the game (not just via an
  // assigned mission) counts. legionClaimed tracks which of those 4
  // rewards have already been paid out, so a claim can't double-pay.
  // [PER-PLAYER] (all three)
  const [sbtMinted, setSbtMinted] = useState(false);
  const [legionDone, setLegionDone] = useState({ stake: false, swap: false, confidential: false, nearAi: false });
  const [legionClaimed, setLegionClaimed] = useState({ stake: false, swap: false, confidential: false, nearAi: false });

  // Marks a room's mission as done in this player's task list and grants the
  // NEAR reward — but only if that mission was actually assigned to them and
  // hasn't already been completed (so re-opening a finished mission, or
  // finishing a room that was never assigned, doesn't pay out twice/wrongly).
  const completeMission = useCallback((roomId) => {
    setMyMissions(prev => {
      const idx = prev.findIndex(m => m.room === roomId && !m.done);
      if (idx === -1) return prev;
      const next = [...prev];
      next[idx] = { ...next[idx], done: true };
      setWallet(w => ({ ...w, NEAR: w.NEAR + NEAR_REWARD_PER_MISSION }));
      setCongratsNote({ label: next[idx].label });
      return next;
    });
  }, []);

  // Sends the player back to the Lobby and wipes every piece of in-game
  // progress, so the next "Start" begins a genuinely new session rather
  // than resuming this one — used by Settings > Exit. Deliberately avoids
  // window.location.reload(): a full page reload can hang or show a
  // "taking longer than expected" browser prompt inside sandboxed/embedded
  // contexts (e.g. a Telegram WebView or this artifact's own iframe), so a
  // plain in-memory state reset is both faster and more reliable here.
  // playerName, playerAvatarId, and soundOn are intentionally left alone —
  // those are the player's own identity/preferences, not game progress.
  // (Defined further below, once posRef/facingRef/isMovingRef exist —
  // see resetGame near the movement-loop setup.)

  // The "NEAR Legion" mission (admin room) only finishes once every Legion
  // activity is done — minting the SBT alone isn't enough. This checks
  // globally (not tied to being in the admin room) so it fires the moment
  // the last activity is completed, wherever the player happens to be.
  useEffect(() => {
    if (LEGION_ACTIVITIES.every(a => legionDone[a.key])) {
      completeMission('admin');
    }
  }, [legionDone, completeMission]);

  // ── "Hold 200 NEAR" mission tracking ─────────────────────────────────
  // Unlike every other mission, this one's checkmark tracks the wallet
  // balance live in both directions: crossing up to 200 checks it,
  // dropping back below 200 (e.g. spending on a swap/stake fee) unchecks
  // it again. The +10 NEAR completion reward, however, only ever pays out
  // once per game — walletMissionRewarded guards that separately from the
  // done flag itself.
  useEffect(() => {
    const mission = myMissions.find(m => m.room === 'wallet_balance');
    if (!mission) return;
    const atTarget = (wallet.NEAR || 0) >= 200;
    if (atTarget !== mission.done) {
      setMyMissions(prev => prev.map(m => m.room === 'wallet_balance' ? { ...m, done: atTarget } : m));
    }
    if (atTarget && !walletMissionRewarded) {
      setWalletMissionRewarded(true);
      setWallet(w => ({ ...w, NEAR: w.NEAR + NEAR_REWARD_PER_MISSION }));
      setCongratsNote({ label: mission.label });
    }
  }, [wallet.NEAR, myMissions, walletMissionRewarded]);

  // ── Confidential Vault lock ──────────────────────────────────────────
  // Locked for absolutely everyone (Saboteur included) until EVERY
  // crewmate has completed at least MISSIONS_REQUIRED_FOR_VAULT missions.
  // [BUG FIX] Previously only ever checked the LOCAL player's own
  // mission count (an explicitly-flagged solo-test approximation, per
  // the old comment here) - now uses crewProgress.minDone, the real
  // minimum missions-done across every crewmate in the room, computed
  // server-side and kept live via the same crewProgressUpdated broadcast
  // the shared progress meter uses.
  const vaultUnlocked = crewProgress.minDone >= MISSIONS_REQUIRED_FOR_VAULT;


  // ── Meme Market hold-tracking (weapons mission) ───────────────────────
  // Tracks whether total meme holdings (NEAR-equivalent) are at/above this
  // player's randomly-assigned target. The moment holdings cross up to
  // target, memeHoldSince is stamped; if holdings ever drop back below
  // target (selling/swapping back), the stamp clears, so only continuous
  // holding counts. A separate effect below polls elapsed time against the
  // target hold duration and auto-completes the mission once it's met,
  // wherever the player happens to be standing.
  const memeMission = myMissions.find(m => m.room === 'weapons');
  const memeHoldingsNear = memeHoldingsValueNear(memeWallet);
  useEffect(() => {
    if (!memeMission || memeMission.done) return;
    const atTarget = memeHoldingsNear >= memeMission.memeTargetNear;
    setMemeHoldSince(prev => {
      if (atTarget && prev == null) return Date.now();
      if (!atTarget && prev != null) return null;
      return prev;
    });
  }, [memeHoldingsNear, memeMission]);
  useEffect(() => {
    if (!memeMission || memeMission.done || memeHoldSince == null) return;
    const requiredMs = memeMission.memeHoldMinutes * 60000;
    const msLeft = requiredMs - (Date.now() - memeHoldSince);
    if (msLeft <= 0) { completeMission('weapons'); return; }
    const t = setTimeout(() => completeMission('weapons'), msLeft);
    return () => clearTimeout(t);
  }, [memeHoldSince, memeMission, completeMission]);

  // Buying a meme coin: deducts spend + flat fee from NEAR, credits the
  // bought coin's tokens into memeWallet. Spend amount is in NEAR; fee is
  // always charged in NEAR on top, same convention as swap/stake elsewhere.
  const handleMemeBuy = useCallback((coinId, spendNear) => {
    setWallet(w => ({ ...w, NEAR: w.NEAR - spendNear - MEME_BUY_FEE_NEAR }));
    setMemeWallet(m => ({ ...m, [coinId]: (m[coinId] || 0) + nearToMemeTokens(coinId, spendNear) }));
  }, []);

  // Swapping a meme coin back to NEAR ("meme exchange"): debits tokens from
  // memeWallet, credits the NEAR-equivalent (minus a flat fee) into wallet.
  const handleMemeSwapBack = useCallback((coinId, tokenAmt) => {
    const outNear = memeTokensToNear(coinId, tokenAmt);
    setMemeWallet(m => ({ ...m, [coinId]: Math.max(0, (m[coinId] || 0) - tokenAmt) }));
    setWallet(w => ({ ...w, NEAR: w.NEAR + Math.max(0, outNear - MEME_BUY_FEE_NEAR) }));
  }, []);

  // Purely cosmetic re-render tick so the "holding Xm" readout in the
  // Mission Tracker visibly counts up while it's open — the actual
  // auto-completion logic above runs on its own setTimeout regardless of
  // whether this tracker is even open.
  const [, setMemeTick] = useState(0);
  useEffect(() => {
    if (!showMissionTracker || memeHoldSince == null) return;
    const id = setInterval(() => setMemeTick(t => t + 1), 1000);
    return () => clearInterval(id);
  }, [showMissionTracker, memeHoldSince]);

  // Opens a new stake position — only possible when the player has none
  // active yet. Deducts the staked amount from that asset's balance and the
  // flat fee from NEAR.
  const handleStake = useCallback((assetId, amount) => {
    if (stakePosition) return; // already staking — can't open a second position
    const now = Date.now();
    setStakePosition({ assetId, amount, startedAt: now, lastClaimAt: now });
    setWallet(w => {
      const next = { ...w };
      next[assetId] = (next[assetId] || 0) - amount; // deduct the staked principal
      next.NEAR = next.NEAR - STAKE_FEE_NEAR;          // then deduct the flat fee — safe even when assetId is itself 'NEAR'
      return next;
    });
    setLegionDone(d => d.stake ? d : { ...d, stake: true });
  }, [stakePosition]);

  // Closes the active stake position — returns the original staked
  // asset/amount to the wallet and charges the unstake fee. Does NOT pay out
  // any reward; that's only ever done via handleClaim. Completing a full
  // stake -> unstake cycle is what finishes the "Stake NEAR" mission.
  const handleUnstake = useCallback(() => {
    if (!stakePosition) return;
    const { assetId, amount } = stakePosition;
    setStakePosition(null);
    setWallet(w => {
      const next = { ...w };
      next[assetId] = (next[assetId] || 0) + amount; // return the staked principal
      next.NEAR = next.NEAR - UNSTAKE_FEE_NEAR;        // then deduct the flat fee — safe even when assetId is itself 'NEAR'
      return next;
    });
    completeMission('upper_eng');
  }, [stakePosition, completeMission]);

  // Pays out the NEAR reward accrued since the last claim (or since staking
  // began) and advances lastClaimAt so the same window can never be paid
  // twice. The staked principal is untouched. The first claim ever finishes
  // the "Claim Rewards" mission.
  const handleClaim = useCallback((rewardAmount) => {
    setWallet(w => ({ ...w, NEAR: w.NEAR + rewardAmount }));
    setStakePosition(prevPos => prevPos ? { ...prevPos, lastClaimAt: Date.now() } : prevPos);
    completeMission('lower_eng');
  }, [completeMission]);

  // Pays out the fixed Legion reward for one completed activity (stake,
  // swap, confidential, nearAi) — only if it's actually done and hasn't
  // already been claimed, so this can't be triggered twice for the same
  // activity.
  const handleLegionClaim = useCallback((key) => {
    setLegionClaimed(c => {
      if (c[key]) return c; // already claimed
      if (!legionDone[key]) return c; // not actually done yet — shouldn't happen, but guard anyway
      setWallet(w => ({ ...w, NEAR: w.NEAR + NEAR_LEGION_REWARD }));
      return { ...c, [key]: true };
    });
  }, [legionDone]);

  // Starts Confidential Mode's 3s activation delay; once it completes, mode
  // goes active with a 2-minute expiry (auto-disable effect lives with the
  // confidentialMode state declaration above).
  const handleActivateConfidential = useCallback(() => {
    setConfidentialMode(prev => {
      if (prev.active || prev.activating) return prev; // already on/activating — no-op
      return { active: false, activating: true, expiresAt: null };
    });
    setLegionDone(d => d.confidential ? d : { ...d, confidential: true });
    setTimeout(() => {
      setConfidentialMode(prev => {
        if (!prev.activating) return prev; // user could have left the screen but state persists — only commit if still activating
        return { active: true, activating: false, expiresAt: Date.now() + CONFIDENTIAL_DURATION_MS };
      });
    }, CONFIDENTIAL_ACTIVATE_MS);
  }, []);

  // Called when a swap completes — only counts toward the "Confidential
  // Swap" mission (reactor) if Confidential Mode was active at the moment
  // the swap was confirmed.
  const handleSwapComplete = useCallback(({ fromId, toId, fromAmt, toAmt, feeNear, wasConfidential }) => {
    setWallet(w => {
      const next = { ...w };
      next[fromId] = next[fromId] - fromAmt;
      next.NEAR = next.NEAR - feeNear; // fee always comes out of NEAR
      next[toId] = (next[toId] || 0) + toAmt;
      return next;
    });
    completeMission('shields'); // the plain Cross-Chain Swap mission, no condition
    if (wasConfidential) completeMission('reactor'); // the Confidential Swap mission
    setLegionDone(d => d.swap ? d : { ...d, swap: true });
  }, [completeMission]);

  useEffect(() => {
    if (!congratsNote) return;
    const t = setTimeout(() => setCongratsNote(null), 3200);
    return () => clearTimeout(t);
  }, [congratsNote]);

  // Detects the moment every assigned mission flips to done, and shows the
  // big one-time celebration modal. Guarded by allMissionsDone so it only
  // fires once per game — without that guard, re-renders after the modal
  // is dismissed would keep re-triggering it since the underlying
  // condition (all missions done) stays true.
  useEffect(() => {
    if (allMissionsDone) return;
    if (myMissions.length > 0 && myMissions.every(m => m.done)) {
      setAllMissionsDone(true);
      setShowAllDoneModal(true);
    }
  }, [myMissions, allMissionsDone]);
  // [WIN CONDITION] Report our own mission progress to the server every
  // time it changes, so checkWinCondition can see whether every alive
  // crewmate has finished everything. Saboteurs have an empty myMissions
  // array (0/0) — checkWinCondition only ever looks at crewmates anyway,
  // so this is harmless to send regardless of role.
  useEffect(() => {
    if (!socketRef.current || !socketRef.current.connected) return;
    // [BUG FIX] Only report mission progress once the game has actually
    // started (screen === 'game' or past it) - this effect was
    // previously firing the moment myMissions got its initial value
    // (which happens on mount, while still in the Lobby, well before
    // any role/game state exists server-side), sending a premature
    // missionsDone/missionsTotal report and triggering an unnecessary
    // checkWinCondition call before the game had even begun.
    if (screen === 'lobby' || screen === 'loading' || screen === 'roleReveal') return;
    // [BUG FIX] Send the FULL mission objects (not just done/total
    // counts) - this is what lets the server hand back the exact same
    // list (including per-mission random values like a meme mission's
    // memeTargetNear/memeHoldMinutes) on reconnect, instead of a refresh
    // silently generating a brand new random set and losing all
    // progress.
    socketRef.current.emit('reportMissionProgress', { missions: myMissions });
  }, [myMissions, screen]);
  const keysRef = useRef({});
  const joyRef = useRef({ active: false, dx: 0, dy: 0 });
  const joyBaseRef = useRef(null);
  const posRef = useRef(startPx);
  // [TELEPORT-BACK FEATURE] Snapshot of exactly where we were standing
  // the instant a meeting started — used to send us back to that exact
  // spot once voting resolves. null when no meeting is/was active yet.
  const preMeetingPosRef = useRef(null);
  const rafRef = useRef(null);
  // [BUG FIX] Tracks the real-world timestamp of the previous movement
  // tick. Used to scale movement by actual elapsed time instead of by
  // raw frame count - see the dtScale calculation in the movement loop
  // below for why this was necessary (different devices/phones render
  // requestAnimationFrame at different real frame rates, e.g. 60fps vs
  // 30fps under load, and without this fix that difference directly
  // translated into different ACTUAL movement speed for different
  // players even though everyone had the exact same speedLevel).
  const lastTickTimeRef = useRef(0);

  // If a gate lock starts while the player happens to be standing inside
  // that gate's own footprint, they'd otherwise be sealed in place by their
  // own position (every corner of their hitbox already inside a now-solid
  // tile). Push them out to the nearest walkable tile the instant the lock
  // takes effect, so nobody ever gets stuck.
  useEffect(() => {
    if (!gateLock.group) return;
    const lockedGates = (gateLock.group === 'A' ? GATE_GROUP_A : GATE_GROUP_B)
      .map(id => GATES.find(g => g.id === id))
      .filter(Boolean);
    const cur = posRef.current;
    const playerTx = Math.floor((cur.x + PLAYER_SIZE / 2) / TILE);
    const playerTy = Math.floor((cur.y + PLAYER_SIZE / 2) / TILE);
    const insideLockedGate = lockedGates.some(g =>
      playerTx >= g.x && playerTx < g.x + g.w && playerTy >= g.y && playerTy < g.y + g.h
    );
    if (!insideLockedGate) return;
    // Expanding ring search outward from the player's current tile for the
    // nearest tile that's walkable and not itself inside any locked gate.
    for (let radius = 1; radius <= 8; radius++) {
      for (let dy = -radius; dy <= radius; dy++) {
        for (let dx = -radius; dx <= radius; dx++) {
          if (Math.max(Math.abs(dx), Math.abs(dy)) !== radius) continue;
          const tx = playerTx + dx, ty = playerTy + dy;
          if (isWalkableTile(tx, ty)) {
            const next = { x: tx * TILE + (TILE - PLAYER_SIZE) / 2, y: ty * TILE + (TILE - PLAYER_SIZE) / 2 };
            posRef.current = next;
            setPos(next);
            return;
          }
        }
      }
    }
  }, [gateLock.group]);

  useEffect(() => {
    const upd = () => setViewport({ w: window.innerWidth, h: window.innerHeight });
    upd();
    window.addEventListener('resize', upd);
    window.addEventListener('orientationchange', upd);
    return () => { window.removeEventListener('resize', upd); window.removeEventListener('orientationchange', upd); };
  }, []);

  useEffect(() => {
    const kd = (e) => { keysRef.current[e.key.toLowerCase()] = true; };
    const ku = (e) => { keysRef.current[e.key.toLowerCase()] = false; };
    window.addEventListener('keydown', kd);
    window.addEventListener('keyup', ku);
    return () => { window.removeEventListener('keydown', kd); window.removeEventListener('keyup', ku); };
  }, []);

  // Mirror showMission into a ref so the rAF movement loop (set up once on
  // mount) can read the latest value without needing to be in its deps —
  // this lets us fully pause movement updates while a mission is open
  // without restarting the animation-frame loop.
  const showMissionRef = useRef(false);
  useEffect(() => { showMissionRef.current = showMission; }, [showMission]);
  // Mirrors killCutscene into a ref so the movement loop can pause for it
  // too — both the player and the dummy freeze in place while the kill
  // cutscene is on screen, same idea as pausing for a mission popup.
  const killCutsceneRef = useRef(null);
  useEffect(() => { killCutsceneRef.current = killCutscene; }, [killCutscene]);
  // Mirrors inVent — movement pauses entirely while inside a vent (the
  // player isn't walking the map, they're navigating the vent-travel UI).
  const inVentRef = useRef(null);
  useEffect(() => { inVentRef.current = inVent; }, [inVent]);
  // Mirrors meeting — movement pauses entirely once a meeting starts
  // (alarm/chat/voting/results), same idea as pausing for a mission popup.
  const meetingRef = useRef(null);
  useEffect(() => { meetingRef.current = meeting; }, [meeting]);
  const facingRef = useRef('right');
  const [isMoving, setIsMoving] = useState(false);
  const isMovingRef = useRef(false);

  // Sends the player back to the Lobby and wipes every piece of in-game
  // progress, so the next "Start" begins a genuinely new session rather
  // than resuming this one — used by Settings > Exit. Deliberately avoids
  // window.location.reload(): a full page reload can hang or show a
  // "taking longer than expected" browser prompt inside sandboxed/embedded
  // contexts (e.g. a Telegram WebView or this artifact's own iframe), so a
  // plain in-memory state reset is both faster and more reliable here.
  // playerName, playerAvatarId, and soundOn are intentionally left alone —
  // those are the player's own identity/preferences, not game progress.
  // Resets posRef/facingRef/isMovingRef too (not just their React-state
  // mirrors) — the movement loop reads those refs every frame as the
  // authoritative position/facing, so without this the player would
  // visually snap back to the spawn point for one frame and then the
  // movement loop would immediately carry them right back to wherever
  // they were standing when they exited.
  const resetGame = useCallback(() => {
    gateLockState.lockedIds = null;
    posRef.current = startPx;
    facingRef.current = 'right';
    isMovingRef.current = false;
    setFacing('right');
    setPos(startPx);
    setCurrentRoom(null);
    setNearTask(null);
    setShowMission(false);
    setKnob({ x: 0, y: 0 });
    setShowSettings(false);
    setShowMap(false);
    setShowExitConfirm(false);
    setWallet(() => {
      const w = {};
      SWAP_ASSETS.forEach(a => { w[a.id] = a.id === 'NEAR' ? 100 : 0; });
      return w;
    });
    setMyMissions(pickRandomMissions(MISSIONS_ASSIGNED_COUNT));
    setMemeWallet(() => {
      const m = {};
      MEME_COINS.forEach(c => { m[c.id] = 0; });
      return m;
    });
    setMemeHoldSince(null);
    setWalletMissionRewarded(false);
    setPlayerRole('crewmate');
    setShowWallet(false);
    setShowMissionTracker(false);
    setShowSaboteurPanel(false);
    setShowDisguisePicker(false);
    setCongratsNote(null);
    setAllMissionsDone(false);
    setShowAllDoneModal(false);
    setStakePosition(null);
    setConfidentialMode({ active: false, activating: false, expiresAt: null });
    setPowerSabotaged(false);
    setHackerAttack(false);
    setGateLock({ group: null, expiresAt: null });
    setEliminationRoleReveal(null);
    setCrewProgress({ percent: 0, done: 0, total: 0, minDone: 0 });
    setLockSecondsLeft(0);
    setSabotageProgress(0);
    setSabotageUsesLeft({ power: 3, hacker: 3, gateLeft: 5, gateRight: 5 });
    setGhostChatMessages([]);
    setShowGhostChat(false);
    setReplyingTo(null);
    setGhostReplyingTo(null);
    setSabotageCooldownUntil(0);
    setKillCooldownUntil(0);
    setPostKillLockUntil(0);
    setDisguiseUsesLeft(DISGUISE_MAX_USES);
    setDisguiseCooldownUntil(0);
    setDisguiseActive(null);
    setKillCutscene(null);
    setInVent(null);
    setVentAnim(null);
    setMeeting(null);
    setChatDraft('');
    setMyAlive(true);
    setDeadBodies({});
    setOtherPlayers({});
    // [BUG FIX] Clear the win-announcement too - without this, after a
    // "Play Again" reset, the gameResult from the PREVIOUS game would
    // still be set, and the (now highest-z-index) win screen would
    // immediately render again on top of the fresh Lobby.
    setGameResult(null);
    setSbtMinted(false);
    setLegionDone({ stake: false, swap: false, confidential: false, nearAi: false });
    setLegionClaimed({ stake: false, swap: false, confidential: false, nearAi: false });
    setScreen('lobby');
  }, [startPx]);
  // [BUG FIX] Keep resetGameRef pointed at the latest resetGame closure,
  // so the roomResetForNewGame handler (registered much earlier, inside
  // connectSocket) always calls the current version rather than a stale
  // one from an earlier render.
  useEffect(() => { resetGameRef.current = resetGame; }, [resetGame]);
  // Last time a footstep sound fired, in ms (performance.now()) — gated on
  // a fixed cadence rather than every animation frame, and reset whenever
  // the player stops so the very next step after standing still always
  // plays immediately instead of waiting out a stale interval.
  const lastFootstepRef = useRef(0);
  const FOOTSTEP_INTERVAL_MS = 290;
  // The movement loop below is mounted once (empty deps) and reads this
  // ref instead of calling playFootstepSound directly, so it always uses
  // the latest soundOn/getAudioCtx closure without needing to restart the
  // rAF loop every time those change.
  const playFootstepRef = useRef(() => {});
  useEffect(() => { playFootstepRef.current = playFootstepSound; }, [playFootstepSound]);

  // Mirrors `screen` into a ref so the movement loop (mounted once) can
  // skip updates entirely while the player is in the Lobby — the Lobby has
  // its own separate movement loop, and without this guard a stray
  // keypress while in the Lobby could still nudge the (currently hidden)
  // in-game player position in the background.
  const screenRef = useRef(screen);
  useEffect(() => { screenRef.current = screen; }, [screen]);

  // Brief "loading" screen between Lobby and the actual game — gives every
  // device a fixed window to finish loading room art, avatars, and other
  // assets before gameplay starts, so nobody drops into a half-rendered
  // map or sees a stutter right at spawn. In real multiplayer this is also
  // where clients would wait for the server to confirm everyone's ready.
  // [BUG FIX] See the reconnected handler's gameStarted branch - set true
  // right before a mid-game reconnect's setScreen('loading'), so the
  // chain effect below knows to skip the role-reveal screen entirely for
  // that case (it's only meant for a brand new game starting).
  const skipRoleRevealRef = useRef(false);
  useEffect(() => {
    if (screen !== 'loading') return;
    const t = setTimeout(() => {
      if (skipRoleRevealRef.current) {
        skipRoleRevealRef.current = false;
        setScreen('game');
      } else {
        setScreen('roleReveal');
      }
    }, 3000);
    return () => clearTimeout(t);
  }, [screen]);

  // [NEW FEATURE] Role-reveal stage — exactly 2 seconds, sequentially
  // AFTER loading finishes (not overlapping it), then gameplay starts.
  useEffect(() => {
    if (screen !== 'roleReveal') return;
    const t = setTimeout(() => setScreen('game'), 2000);
    return () => clearTimeout(t);
  }, [screen]);

  // [MULTIPLAYER] The dummy crewmate's wander-AI loop has been removed —
  // real other players move themselves and broadcast their own position
  // (see the playerMoved handler in connectSocket), so there's nothing
  // left here to simulate.

  useEffect(() => {
    const tick = () => {
      // [BUG FIX] Frame-rate-independent movement: compute how much real
      // time has passed since the last tick, expressed as a multiplier
      // where 1.0 means exactly one 60fps-frame's worth of time elapsed.
      // Without this, the OLD code moved the player a fixed number of
      // pixels every single rAF callback regardless of how much real
      // time that callback represented - so a phone rendering at a
      // smooth 60fps moved a player visibly faster (more ticks per real
      // second) than a phone struggling at 30fps, even with the exact
      // same speedLevel. Clamped to a max of 3x to avoid a single huge
      // jump after the tab/app was backgrounded or otherwise paused for
      // a while (e.g. switching to another Telegram chat and back).
      const now = performance.now();
      const dtScale = lastTickTimeRef.current
        ? Math.min(3, (now - lastTickTimeRef.current) / (1000 / 60))
        : 1;
      lastTickTimeRef.current = now;
      // [BUG FIX] Only truly "not in active gameplay" states stop the
      // loop entirely now (screen isn't 'game', or the game has already
      // ended) - a mission popup, kill cutscene, vent travel, or meeting
      // being open no longer pauses OTHER players' position
      // interpolation (see the skipOwnMovement check below and the
      // interpolation block further down, which now runs unconditionally
      // whenever we get this far). This is what makes the security
      // camera (and anything else relying on otherPlayers while a popup
      // is open) actually show live movement instead of a frozen
      // snapshot from the moment the popup opened.
      if (screenRef.current !== 'game' || gameResultRef.current) {
        rafRef.current = requestAnimationFrame(tick);
        return;
      }
      // [BUG FIX] This used to be the condition for the early-return
      // above (which froze EVERYTHING, including other players). Now it
      // only skips processing the LOCAL player's own movement input and
      // collision - correctly, since they're interacting with a popup/
      // cutscene/vent/meeting UI and shouldn't be walking around during
      // it - while leaving other players' interpolation (below) running.
      const skipOwnMovement = showMissionRef.current || killCutsceneRef.current || inVentRef.current || meetingRef.current;
      if (!skipOwnMovement) {
      let dx = 0, dy = 0;
      const k = keysRef.current;
      if (k['arrowup'] || k['w']) dy -= 1;
      if (k['arrowdown'] || k['s']) dy += 1;
      if (k['arrowleft'] || k['a']) dx -= 1;
      if (k['arrowright'] || k['d']) dx += 1;
      if (joyRef.current.active) { dx += joyRef.current.dx; dy += joyRef.current.dy; }

      if (dx !== 0 || dy !== 0) {
        const mag = Math.sqrt(dx * dx + dy * dy) || 1;
        // [NEW FEATURE] Alive players move at MOVE_SPEED scaled by the
        // host's chosen speed level: level 2 (50%) is exactly MOVE_SPEED
        // itself (the original, unmodified speed), so existing feel is
        // preserved by default. Each level is a 25%-of-MOVE_SPEED step:
        // level 1=25%, 2=50%, 3=75%, 4=100%, 5=125% of MOVE_SPEED's own
        // value (NOT of "the player's base speed" in the abstract -
        // MOVE_SPEED itself already IS the level-2/50% reference point).
        // [GHOST RULE] Ghosts always move at a FIXED 3x of the base
        // MOVE_SPEED constant, completely unaffected by the speed level -
        // this was an explicit requirement: ghost speed shouldn't change
        // no matter what the host picks for living players.
        const effectiveSpeed = (myAliveRef.current
          ? MOVE_SPEED * (speedLevelRef.current / 2)
          : MOVE_SPEED * 3) * dtScale;
        const sx = (dx / mag) * effectiveSpeed;
        const sy = (dy / mag) * effectiveSpeed;
        const cur = posRef.current;
        // Move each axis separately so you slide along walls smoothly.
        // canStand handles tiles/walls/gates; blockedByOtherPlayer adds
        // player-vs-player solidity on top — checked against every real
        // OTHER PLAYER currently in the room (replaces the old solo-test
        // dummy crewmate check now that a real roster exists).
        const blockedByOtherPlayer = (px, py) => {
          const others = otherPlayersRef.current;
          for (const id in others) {
            const p = others[id];
            if (p.alive === false) continue; // ghosts don't block movement
            if (Math.hypot(px - p.x, py - p.y) < PLAYER_SOLID_RADIUS_PX) return true;
          }
          return false;
        };
        let nx = cur.x;
        let ny = cur.y;
        // [GHOST RULE] A dead player floats freely through walls, gates,
        // and other players entirely — no collision checks apply at all,
        // just the outer map boundary so they can't wander into negative
        // coordinates or off the far edge of the grid. This is what lets
        // a ghost cut straight from one room to another without using
        // corridors, exactly as specified.
        const MAP_W_PX = GRID_W * TILE, MAP_H_PX = GRID_H * TILE;
        if (!myAliveRef.current) {
          nx = Math.max(0, Math.min(cur.x + sx, MAP_W_PX - PLAYER_SIZE));
          ny = Math.max(0, Math.min(cur.y + sy, MAP_H_PX - PLAYER_SIZE));
        } else {
          if (canStand(cur.x + sx, cur.y) && !blockedByOtherPlayer(cur.x + sx, cur.y)) nx = cur.x + sx;
          if (canStand(nx, cur.y + sy) && !blockedByOtherPlayer(nx, cur.y + sy)) ny = cur.y + sy;

          // [COLLISION-STUCK FIX] If we're ALREADY overlapping another
          // player this frame (can happen from two players approaching
          // each other simultaneously, or from a stale/throttled position
          // briefly putting us inside someone before the next sync
          // arrives), nudge ourselves directly away from them by a small
          // fixed amount — this is what actually un-sticks two players
          // who'd otherwise freeze pressed against each other forever,
          // since the plain "block movement toward" check above does
          // nothing once you're already inside the blocked radius (it
          // only prevents getting MORE overlapped, not resolves existing
          // overlap). Checked independently of the player's own input, so
          // it applies even if they're standing still.
          const others = otherPlayersRef.current;
          let pushX = 0, pushY = 0;
          for (const id in others) {
            const p = others[id];
            if (p.alive === false) continue;
            const dist = Math.hypot(nx - p.x, ny - p.y);
            if (dist > 0 && dist < PLAYER_SOLID_RADIUS_PX) {
              const overlap = PLAYER_SOLID_RADIUS_PX - dist;
              pushX += ((nx - p.x) / dist) * overlap * 0.5;
              pushY += ((ny - p.y) / dist) * overlap * 0.5;
            }
          }
          if (pushX !== 0 || pushY !== 0) {
            const pushedX = nx + pushX, pushedY = ny + pushY;
            if (canStand(pushedX, ny)) nx = pushedX;
            if (canStand(nx, pushedY)) ny = pushedY;
          }
        }
        const next = { x: nx, y: ny };
        // [PERF] posRef must stay pixel-accurate every frame (collision +
        // the throttled network emit below both read it), but the React
        // setPos — which re-renders the ENTIRE world (camera, fog, every
        // other player, the whole HUD) — is skipped when we effectively
        // didn't move this frame (sub-0.4px on both axes). This cuts out
        // a large chunk of redundant full-scene re-renders that were the
        // main cause of the occasional lag on busier phones, with no
        // visible difference (a <0.4px shift isn't perceptible).
        const prevSelfPos = posRef.current;
        posRef.current = next;
        // [BUG FIX] Threshold lowered from 0.4px to 0.12px - 0.4 was
        // actually ABOVE the slowest possible per-frame movement (speed
        // level 1/25% moves only ~0.375px/frame), so the lowest speed
        // setting could visually stutter for the local player (setPos
        // skipped most frames even during genuine movement). 0.12px
        // stays safely below every speed level's per-frame movement, so
        // real movement always renders every frame regardless of speed,
        // while still skipping truly-idle (stationary) frames.
        if (Math.abs(next.x - prevSelfPos.x) >= 0.12 || Math.abs(next.y - prevSelfPos.y) >= 0.12) {
          setPos(next);
        }
        // [MULTIPLAYER: PER-PLAYER] Broadcast our new position to the
        // server, throttled to ~10x/second so we don't flood the socket
        // on every single animation frame.
        const nowMs = performance.now();
        // [SMOOTHNESS] Tightened from 100ms to 70ms (~14x/sec instead of
        // 10x/sec) — combined with the CSS transition on other players'
        // rendering above, this is what actually closes most of the gap
        // between "smooth" and "jumpy" for how other players see us move.
        // Still well within reasonable bandwidth for a handful of players.
        if (socketRef.current && socketRef.current.connected && nowMs - lastPosEmitRef.current > 70) {
          lastPosEmitRef.current = nowMs;
          socketRef.current.emit('playerMove', { x: next.x, y: next.y });
        }
        if (dx > 0 && facingRef.current !== 'right') { facingRef.current = 'right'; setFacing('right'); }
        else if (dx < 0 && facingRef.current !== 'left') { facingRef.current = 'left'; setFacing('left'); }
        if (!isMovingRef.current) { isMovingRef.current = true; setIsMoving(true); }
        const t = performance.now();
        if (t - lastFootstepRef.current >= FOOTSTEP_INTERVAL_MS) {
          lastFootstepRef.current = t;
          playFootstepRef.current();
        }
      } else if (isMovingRef.current) {
        isMovingRef.current = false; setIsMoving(false);
        lastFootstepRef.current = 0;
      }
      } // end skipOwnMovement guard - everything below always runs

      // [SMOOTHNESS FIX] Ease every other player's DISPLAYED position
      // toward its latest known TARGET a little each frame, instead of
      // snapping straight to it whenever a throttled network update
      // arrives. A factor of 0.25 reaches ~99% of the way to the target
      // within about 16 frames (~0.27s) — fast enough to feel responsive,
      // slow enough to visibly glide between the ~70ms-apart updates
      // rather than jumping. Batched into a single setOtherPlayers call
      // per frame (not one per player) to keep this cheap even with
      // several other players in the room.
      const targets = otherPlayersTargetRef.current;
      let needsUpdate = false;
      const interpolated = {};
      // [BUG FIX] Scale the catch-up factor by dtScale so this is frame-
      // rate-independent too, same as the local player's own movement.
      // Compounds correctly for a constant per-REAL-SECOND catch-up rate
      // regardless of how many rAF frames actually fire per second on
      // this specific device - without this, a viewer on a slower/busier
      // phone caught everyone else up more slowly (fewer frames = fewer
      // 0.25 steps per second), making other players look artificially
      // sluggish ONLY on that viewer's screen, even though their real
      // network-reported positions were arriving at the correct rate.
      // [BUG FIX] This was ALSO missing any scaling by speedLevel (only
      // dtScale, which normalizes for frame-rate, not for how fast
      // players are actually moving) - same root cause as the Lobby's
      // own interpolation, just in actual gameplay this time. At the
      // higher end of the 50-150% speed range, a faster-moving player
      // covers noticeably more ground between each network position
      // update, and this fixed 0.25 catch-up rate couldn't keep pace -
      // making every OTHER player visibly lag/appear slower than their
      // real speed, while your own locally-simulated movement always
      // looked correctly fast. Scaled proportionally around speed level
      // 4 (100%) as the baseline, capped at 1 same as before.
      const speedScaledBase = 0.25 * ((speedLevelRef.current || 4) / 4);
      const catchUpFactor = Math.min(1, speedScaledBase * dtScale);
      for (const id in targets) {
        const target = targets[id];
        const current = otherPlayersRef.current[id];
        if (!current || typeof current.x !== 'number') continue;
        const dxp = target.x - current.x;
        const dyp = target.y - current.y;
        if (Math.abs(dxp) < 0.05 && Math.abs(dyp) < 0.05) continue; // close enough, skip
        needsUpdate = true;
        interpolated[id] = {
          ...current,
          x: current.x + dxp * catchUpFactor,
          y: current.y + dyp * catchUpFactor,
          isGhost: target.isGhost,
        };
      }
      if (needsUpdate) {
        setOtherPlayers((prev) => ({ ...prev, ...interpolated }));
      }

      rafRef.current = requestAnimationFrame(tick);
    };
    rafRef.current = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(rafRef.current);
  }, []);

  useEffect(() => {
    const r = roomAtPixel(pos.x, pos.y);
    setCurrentRoom(r);
    const tp = nearbyTaskPoint(pos.x, pos.y);
    setNearTask(tp);
    if (!tp) setShowMission(false);
  }, [pos]);

  const JOY_R = 50;
  const joyStart = useCallback((e) => { joyRef.current.active = true; joyMove(e); }, []);
  const joyMove = useCallback((e) => {
    if (!joyRef.current.active || !joyBaseRef.current) return;
    const t = e.touches ? e.touches[0] : e;
    const rect = joyBaseRef.current.getBoundingClientRect();
    const cx = rect.left + rect.width / 2, cy = rect.top + rect.height / 2;
    let dx = (t.clientX - cx) / (rect.width / 2);
    let dy = (t.clientY - cy) / (rect.height / 2);
    const mag = Math.sqrt(dx * dx + dy * dy);
    if (mag > 1) { dx /= mag; dy /= mag; }
    joyRef.current.dx = dx; joyRef.current.dy = dy;
    setKnob({ x: dx * JOY_R, y: dy * JOY_R });
  }, []);
  const joyEnd = useCallback(() => {
    joyRef.current.active = false; joyRef.current.dx = 0; joyRef.current.dy = 0;
    setKnob({ x: 0, y: 0 });
  }, []);

  // [BUG FIX] Telegram Mini App window shaking / sliding down while
  // dragging the joystick. Root cause: React's own onTouchStart/
  // onTouchMove props always attach as PASSIVE listeners, so calling
  // e.preventDefault() inside them is silently ignored - the touch then
  // bubbles up to the page, and Telegram interprets that vertical drag
  // as a swipe-to-close/scroll gesture, shaking the whole Mini App.
  // Registering the SAME handlers manually with { passive: false } here
  // is what finally lets preventDefault() actually stop that bubbling.
  // (disableVerticalSwipes(), touch-action:none, and overflow-lock all
  // help too - see the Telegram SDK init effect and the joystick's CSS -
  // but this non-passive preventDefault is the core fix.)
  useEffect(() => {
    const el = joyBaseRef.current;
    if (!el) return;
    const startNP = (e) => { e.preventDefault(); joyStart(e); };
    const moveNP = (e) => { e.preventDefault(); joyMove(e); };
    // [BUG FIX] This is the actual "joystick gets stuck until I refresh
    // the page" bug - only touchstart/touchmove were ever handled
    // natively here, leaving 'touchend' to React's own separate PASSIVE
    // synthetic onTouchEnd prop, and 'touchcancel' (fired instead of
    // touchend whenever a touch sequence gets interrupted - an incoming
    // call/notification, the OS taking over the gesture, switching apps
    // mid-drag) completely unhandled anywhere. joyRef.current.active
    // could get stuck at true with no way to reset it short of a full
    // reload. Both are now handled natively, right alongside
    // touchstart/touchmove, so every way a touch sequence can end is
    // actually covered.
    const endNP = (e) => { e.preventDefault(); joyEnd(); };
    el.addEventListener('touchstart', startNP, { passive: false });
    el.addEventListener('touchmove', moveNP, { passive: false });
    el.addEventListener('touchend', endNP, { passive: false });
    el.addEventListener('touchcancel', endNP, { passive: false });
    return () => {
      el.removeEventListener('touchstart', startNP);
      el.removeEventListener('touchmove', moveNP);
      el.removeEventListener('touchend', endNP);
      el.removeEventListener('touchcancel', endNP);
    };
  }, [joyStart, joyMove, joyEnd]);

  // [BUG FIX] VIEW_TILES moved to a module-level constant (see its
  // declaration near the other map constants) - it's now also used by
  // the gate-sound visibility check above, which runs in an earlier
  // effect than this render, so it needed to exist outside this
  // component's own render body rather than only being declared here.
  const worldViewPx = VIEW_TILES * TILE;
  const scale = Math.min(viewport.w, viewport.h) / worldViewPx;
  const mapPxW = GRID_W * TILE, mapPxH = GRID_H * TILE;
  const camX = Math.max(0, Math.min(mapPxW - worldViewPx, pos.x + PLAYER_SIZE / 2 - worldViewPx / 2));
  const camY = Math.max(0, Math.min(mapPxH - worldViewPx, pos.y + PLAYER_SIZE / 2 - worldViewPx / 2));

  // Player's position on SCREEN (not world) — the fog-of-war circle is centered here.
  // Distinct from world position because the camera clamps near map edges, so the
  // player isn't always screen-centered; the vision circle must follow the player's
  // actual on-screen dot, not assume it's always in the middle.
  const playerScreenX = (pos.x + PLAYER_SIZE / 2 - camX) * scale;
  const playerScreenY = (pos.y + PLAYER_SIZE / 2 - camY) * scale;
  // [MULTIPLAYER] World->screen conversion is now a reusable function
  // instead of a single dummy's precomputed X/Y, since there can be any
  // number of other players/bodies on screen at once.
  const worldToScreenX = (wx) => (wx + PLAYER_SIZE / 2 - camX) * scale;
  const worldToScreenY = (wy) => (wy + PLAYER_SIZE / 2 - camY) * scale;

  // Grid layer (corridor/wall/door floors+textures) depends only on `scale`, never on
  // player position — memoize so it's built once per zoom level, not on every
  // movement frame (this was the main cause of movement lag: ~484+ DOM nodes with
  // background-image math were being rebuilt 30-60 times/sec).
  const gridLayerEls = React.useMemo(() => {
    const els = [];
    const TEX_TILES = 4; // texture repeats every 4 tiles
    const texPx = TEX_TILES * TILE * scale;
    const WALL_TEX_TILES = 3;
    const wallTexPx = WALL_TEX_TILES * TILE * scale;
    for (let ty = 0; ty < GRID_H; ty++) {
      let runStart = -1, runCh = null;
      for (let tx = 0; tx <= GRID_W; tx++) {
        const ch = tx < GRID_W ? GRID_ROWS[ty][tx] : null;
        const draw = ch === 'c' || ch === '#' || ch === 'D';
        if (draw && ch === runCh) continue;
        // flush current run
        if (runStart !== -1) {
          const left = runStart * TILE * scale;
          const top = ty * TILE * scale;
          const isFloor = runCh === 'c' || runCh === 'D';
          const isWall = runCh === '#';
          els.push(
            <div key={runCh + ty + '_' + runStart} style={{
              position: 'absolute', left, top,
              width: (tx - runStart) * TILE * scale, height: TILE * scale,
              background: isFloor ? '#15151f' : '#0d0d14',
              backgroundImage: isFloor ? `url(${CORRIDOR_TEX})` : isWall ? `url(${WALL_TEX})` : 'none',
              backgroundRepeat: (isFloor || isWall) ? 'repeat' : 'no-repeat',
              backgroundSize: isFloor ? `${texPx}px ${texPx}px` : isWall ? `${wallTexPx}px ${wallTexPx}px` : 'auto',
              // anchor texture to global map origin so runs/rows align seamlessly
              backgroundPosition: (isFloor || isWall) ? `${-left}px ${-top}px` : '0 0',
              boxShadow: runCh === 'D' ? '0 0 4px rgba(212,168,67,0.5)' : 'none',
              zIndex: runCh === '#' ? 2 : (runCh === 'D' ? 4 : 1),
            }} />
          );
          runStart = -1; runCh = null;
        }
        if (draw) { runStart = tx; runCh = ch; }
      }
    }
    return els;
  }, [scale]);

  // Corridor border strips (visual-only edge list precomputed at module load) — same
  // reasoning: only rebuild when zoom/scale changes, never on player movement.
  const corridorBorderEls = React.useMemo(() => {
    const BORDER = Math.max(3, TILE * scale * 0.12);
    const WALL_TEX_TILES = 3;
    const wallTexPx = WALL_TEX_TILES * TILE * scale;
    const tileW = TILE * scale, tileH = TILE * scale;
    return CORRIDOR_BORDER_EDGES.map(({ tx, ty, side }) => {
      const left = tx * TILE * scale, top = ty * TILE * scale;
      let style;
      if (side === 'top') style = { left, top, width: tileW, height: BORDER };
      else if (side === 'bottom') style = { left, top: top + tileH - BORDER, width: tileW, height: BORDER };
      else if (side === 'left') style = { left, top, width: BORDER, height: tileH };
      else style = { left: left + tileW - BORDER, top, width: BORDER, height: tileH };
      return (
        <div key={`${side[0]}${tx}_${ty}`} style={{
          position: 'absolute',
          backgroundImage: `url(${WALL_TEX})`,
          backgroundRepeat: 'repeat',
          backgroundSize: `${wallTexPx}px ${wallTexPx}px`,
          backgroundPosition: `${-left}px ${-top}px`,
          zIndex: 3,
          ...style,
        }} />
      );
    });
  }, [scale]);

  // [BUG FIX] The root container's touchAction was hardcoded to 'none'
  // (needed for the actual game screens - joystick, taps, etc. must not
  // trigger the browser's own scroll/zoom gestures). But CSS touch-action
  // is NOT purely a per-element setting - a browser computes the "used"
  // touch-action for a region as the intersection of the target element's
  // AND every ancestor's touch-action. That meant 'none' here was silently
  // blocking scrolling everywhere UNDERNEATH it too, even on plain
  // form/menu screens (auth, wallet setup, profile, home) that have their
  // own `overflow: auto` - those never actually collapsed into "cut off"
  // content, they were just unable to scroll to reveal it, and it's also
  // very likely why a focused input near the bottom couldn't be scrolled
  // into view above the on-screen keyboard. Switching to 'auto' only for
      {/* [NEW FEATURE] Shown once, right after landing back in the Lobby
          from being auto-removed for mission inactivity (see the
          kickedForInactivity socket handler) - explains why, since
          otherwise suddenly being back at the Lobby mid-game would be
          confusing with no context. */}
      {inactivityKickedNotice && screen === 'lobby' && (
        <div
          onClick={() => setInactivityKickedNotice(false)}
          style={{
            position: 'absolute', inset: 0, zIndex: 95, background: 'rgba(0,0,0,0.75)',
            display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 24,
          }}
        >
          <div style={{
            maxWidth: 300, background: '#1a1410', border: '1px solid rgba(255,193,76,0.4)',
            borderRadius: 14, padding: 20, textAlign: 'center',
          }}>
            <div style={{ fontSize: 30, marginBottom: 8 }}>⚠️</div>
            <p style={{ fontSize: 13, fontWeight: 800, color: '#ffc14c', margin: '0 0 6px' }}>Removed for inactivity</p>
            <p style={{ fontSize: 11.5, color: '#c8c8c8', margin: '0 0 14px', lineHeight: 1.5 }}>
              You were sent back to the Lobby after missing your missions for too long.
            </p>
            <button onClick={() => setInactivityKickedNotice(false)} style={{
              width: '100%', padding: '9px 0', borderRadius: 8, border: 'none',
              background: '#ffc14c', color: '#1a1410', fontWeight: 800, fontSize: 12.5,
            }}>Got it</button>
          </div>
        </div>
      )}

  // these non-gameplay screens fixes both.
  const isFormScreen = ['auth', 'walletChoice', 'profileSetup', 'profileEdit', 'home'].includes(screen);

  return (
    <div style={{
      background: '#0a0a0f', height: '100vh', width: '100vw', overflow: 'hidden',
      // [MOBILE FIX] 100dvh (dynamic viewport height) is more reliable than
      // 100vh on mobile browsers where the address bar can show/hide and
      // change the actual visible height — falls back to 100vh above on
      // browsers that don't support dvh yet (the second height wins where
      // supported, since CSS just uses the last valid declaration).
      ...(CSS?.supports?.('height: 100dvh') ? { height: '100dvh' } : {}),
      position: 'fixed', top: 0, left: 0, fontFamily: 'system-ui, sans-serif',
      color: '#e8e8f0', userSelect: 'none', touchAction: isFormScreen ? 'auto' : 'none',
    }}>
      {/* [DEV-BRANCH ONLY - PHASE 2 STEP 1] Account auth screen - email +
          password signup with OTP verification, login, forgot/reset
          password. Plain functional styling for now (matches the game's
          existing dark background + green accent), not final design -
          the goal right now is just confirming the backend auth flow
          actually works end to end. THIS BLOCK MUST NEVER BE MERGED TO
          THE LIVE/MAIN BRANCH UNTIL FULLY TESTED ON DEV. */}
      {/* [DEV-BRANCH ONLY - PHASE 2] Brief loading state while checking
          for a saved session on app load - avoids a flash of the login
          screen for a returning player who's about to be auto-restored. */}
      {sessionRestoring && (
        <div style={{
          position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center',
        }}>
          <span style={{ fontSize: 13, color: '#6a7570' }}>Loading…</span>
        </div>
      )}

      {!sessionRestoring && screen === 'auth' && (
        <div style={{ position: 'absolute', inset: 0, overflow: 'hidden', background: '#000' }}>
        {/* [REDESIGN] Om7eth's own reference image is the login screen
            background, full opacity, no dimming overlay - the "NEAR
            SABOTEUR / TRUST NO AGENT" title art is already drawn into
            it. The login form is a code-drawn card placed inside the
            empty screen panel the art leaves for it, using the same
            locked-aspect-ratio frame technique as Home so it lines up
            on any device. */}
        <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <div style={{ position: 'relative', width: `min(100vw, calc(100vh * ${LOGIN_IMG_W} / ${LOGIN_IMG_H}))`, height: `min(100vh, calc(100vw * ${LOGIN_IMG_H} / ${LOGIN_IMG_W}))` }}>
            <img src={LOGIN_BG_IMG} alt="" style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'fill', display: 'block' }} />

            <div style={{
              ...loginRect(245, 603, 781, 1140), display: 'flex', flexDirection: 'column',
              justifyContent: 'flex-start', padding: '2.4% 7%', gap: '1.3%', overflowY: 'auto', touchAction: 'auto',
            }}>
              <p style={{ fontSize: 11.5, color: '#8fe3ff', margin: '0 0 1%', textAlign: 'center', fontWeight: 700, letterSpacing: 0.3 }}>
                {authMode === 'login' && 'Log in to your account'}
                {authMode === 'signup' && 'Create an account'}
                {authMode === 'verifyOtp' && `Enter the code sent to ${authEmail}`}
                {authMode === 'forgot' && 'Enter your email to reset your password'}
                {authMode === 'resetOtp' && `Enter the code sent to ${authEmail}, and a new password`}
              </p>

              {(authMode === 'login' || authMode === 'signup' || authMode === 'forgot') && (
                <input
                  type="email" placeholder="Email" value={authEmail}
                  onChange={(e) => setAuthEmail(e.target.value)}
                  style={{
                    background: 'rgba(5,15,12,0.55)', border: '1px solid rgba(110,255,192,0.35)',
                    borderRadius: 7, padding: '9px 11px', color: '#e8e8f0', fontSize: 13, width: '100%', boxSizing: 'border-box',
                  }}
                />
              )}

              {(authMode === 'login' || authMode === 'signup') && (
                <div style={{ position: 'relative' }}>
                  <input
                    type={showAuthPassword ? 'text' : 'password'} placeholder="Password" value={authPassword}
                    onChange={(e) => setAuthPassword(e.target.value)}
                    style={{
                      width: '100%', boxSizing: 'border-box', background: 'rgba(5,15,12,0.55)', border: '1px solid rgba(110,255,192,0.35)',
                      borderRadius: 7, padding: '9px 38px 9px 11px', color: '#e8e8f0', fontSize: 13,
                    }}
                  />
                  <span
                    onClick={() => setShowAuthPassword((v) => !v)}
                    style={{ position: 'absolute', right: 9, top: '50%', transform: 'translateY(-50%)', cursor: 'pointer', display: 'flex' }}
                  ><EyeIcon open={showAuthPassword} size={14} /></span>
                </div>
              )}

              {(authMode === 'verifyOtp' || authMode === 'resetOtp') && (
                <input
                  type="text" inputMode="numeric" placeholder="6-digit code" value={authOtp}
                  onChange={(e) => setAuthOtp(e.target.value)}
                  style={{
                    background: 'rgba(5,15,12,0.55)', border: '1px solid rgba(110,255,192,0.35)',
                    borderRadius: 7, padding: '9px 11px', color: '#e8e8f0', fontSize: 13, letterSpacing: 3, width: '100%', boxSizing: 'border-box',
                  }}
                />
              )}

              {authMode === 'resetOtp' && (
                <div style={{ position: 'relative' }}>
                  <input
                    type={showAuthNewPassword ? 'text' : 'password'} placeholder="New password" value={authNewPassword}
                    onChange={(e) => setAuthNewPassword(e.target.value)}
                    style={{
                      width: '100%', boxSizing: 'border-box', background: 'rgba(5,15,12,0.55)', border: '1px solid rgba(110,255,192,0.35)',
                      borderRadius: 7, padding: '9px 38px 9px 11px', color: '#e8e8f0', fontSize: 13,
                    }}
                  />
                  <span
                    onClick={() => setShowAuthNewPassword((v) => !v)}
                    style={{ position: 'absolute', right: 9, top: '50%', transform: 'translateY(-50%)', cursor: 'pointer', display: 'flex' }}
                  ><EyeIcon open={showAuthNewPassword} size={14} /></span>
                </div>
              )}

              {authError && <p style={{ color: '#ff6b6b', fontSize: 11, margin: 0 }}>{authError}</p>}
              {authInfo && !authError && <p style={{ color: '#6effc0', fontSize: 11, margin: 0 }}>{authInfo}</p>}

              <button
                disabled={authLoading}
                onClick={() => {
                  if (authMode === 'login') handleLogin();
                  else if (authMode === 'signup') handleSignup();
                  else if (authMode === 'verifyOtp') handleVerifyOtp();
                  else if (authMode === 'forgot') handleForgotPassword();
                  else if (authMode === 'resetOtp') handleResetPassword();
                }}
                style={{
                  background: authLoading ? 'rgba(110,255,192,0.3)' : '#6effc0', color: '#05130d',
                  border: 'none', borderRadius: 7, padding: '10px 0', fontSize: 13, fontWeight: 800, width: '100%',
                }}
              >
                {authLoading ? '...' : (
                  authMode === 'login' ? 'Log In' :
                  authMode === 'signup' ? 'Sign Up' :
                  authMode === 'verifyOtp' ? 'Verify' :
                  authMode === 'forgot' ? 'Send Reset Code' : 'Reset Password'
                )}
              </button>

              <div style={{ display: 'flex', flexDirection: 'column', gap: 4, alignItems: 'center', marginTop: '0.5%' }}>
                {authMode === 'login' && (
                  <>
                    <span
                      onClick={() => { setAuthMode('signup'); setAuthError(''); setAuthInfo(''); }}
                      style={{ fontSize: 11, color: '#8fe3ff', cursor: 'pointer' }}
                    >Don't have an account? Sign up</span>
                    <span
                      onClick={() => { setAuthMode('forgot'); setAuthError(''); setAuthInfo(''); }}
                      style={{ fontSize: 11, color: '#9aa0ad', cursor: 'pointer' }}
                    >Forgot password?</span>
                  </>
                )}
                {authMode === 'signup' && (
                  <span
                    onClick={() => { setAuthMode('login'); setAuthError(''); setAuthInfo(''); }}
                    style={{ fontSize: 11, color: '#8fe3ff', cursor: 'pointer' }}
                  >Already have an account? Log in</span>
                )}
                {(authMode === 'forgot' || authMode === 'verifyOtp' || authMode === 'resetOtp') && (
                  <span
                    onClick={() => { setAuthMode('login'); setAuthError(''); setAuthInfo(''); }}
                    style={{ fontSize: 11, color: '#9aa0ad', cursor: 'pointer' }}
                  >Back to login</span>
                )}
              </div>

              {/* [DEV-BRANCH ONLY - PHASE 2] Play as Guest - a small,
                  secondary pill (not full-width, not a primary-looking
                  button) so it reads as the lightweight opt-out it is.
                  Skips account/wallet/profile entirely and drops
                  straight onto Home. Guests can only use Free Play;
                  every other Home button shows a "create a profile"
                  notice instead (see guestGuard()), and guests never
                  earn points. */}
              {(authMode === 'login' || authMode === 'signup') && (
                <button
                  onClick={handlePlayAsGuest}
                  style={{
                    background: 'transparent', color: '#8a9199', border: '1px solid rgba(154,160,173,0.35)',
                    borderRadius: 20, padding: '5px 16px', fontSize: 10, fontWeight: 700,
                    alignSelf: 'center', marginTop: '1%', cursor: 'pointer', WebkitTapHighlightColor: 'transparent',
                  }}
                >Play as Guest</button>
              )}
            </div>
          </div>
        </div>
        </div>
      )}

      {/* [DEV-BRANCH ONLY - PHASE 2] Wallet Choice screen - real NEAR
          wallet (testnet), web-version only. THIS BLOCK MUST NEVER BE
          MERGED TO THE LIVE/MAIN BRANCH. */}
      {screen === 'walletChoice' && (
        <div style={{
          position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column',
          alignItems: 'center', justifyContent: 'center', padding: 24, gap: 14, overflow: 'auto',
        }}>
          {!newWalletSeed ? (
            <>
              <h1 style={{ fontSize: 20, fontWeight: 900, color: '#6effc0', margin: '0 0 4px', textAlign: 'center' }}>
                Set up your NEAR wallet
              </h1>
              <p style={{ fontSize: 12, color: '#9aa0ad', margin: '0 0 8px', textAlign: 'center', maxWidth: 320 }}>
                Testnet only for now. Connect a wallet you already have, or let us generate a new one for you.
              </p>

              {walletError && <p style={{ color: '#ff6b6b', fontSize: 12, margin: 0, maxWidth: 300, textAlign: 'center' }}>{walletError}</p>}

              <button
                disabled={walletLoading}
                onClick={handleConnectWallet}
                style={{
                  width: '100%', maxWidth: 320, background: '#6effc0', color: '#05130d',
                  border: 'none', borderRadius: 8, padding: '13px 0', fontSize: 14, fontWeight: 800,
                }}
              >Connect Existing Wallet</button>

              <button
                disabled={walletLoading}
                onClick={handleGenerateWallet}
                style={{
                  width: '100%', maxWidth: 320, background: 'rgba(255,255,255,0.08)', color: '#e8e8f0',
                  border: '1px solid rgba(255,255,255,0.2)', borderRadius: 8, padding: '13px 0', fontSize: 14, fontWeight: 800,
                }}
              >Create New Wallet</button>
            </>
          ) : (
            <>
              <h1 style={{ fontSize: 18, fontWeight: 900, color: '#ff9f5a', margin: '0 0 4px', textAlign: 'center' }}>
                ⚠️ Save this now
              </h1>
              <p style={{ fontSize: 12, color: '#9aa0ad', margin: '0 0 4px', textAlign: 'center', maxWidth: 320 }}>
                This is the only time you'll see your private key. If you lose it, this wallet and anything in it is gone for good — we can't recover it for you.
              </p>

              <div style={{
                width: '100%', maxWidth: 320, background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,159,90,0.4)',
                borderRadius: 10, padding: 14, display: 'flex', flexDirection: 'column', gap: 10,
              }}>
                <div>
                  <span style={{ fontSize: 10, color: '#9aa0ad', fontWeight: 700 }}>ACCOUNT ID (testnet)</span>
                  <p style={{ fontSize: 11, color: '#e8e8f0', wordBreak: 'break-all', margin: '2px 0 0', fontFamily: 'monospace' }}>{newWalletSeed.accountId}</p>
                </div>
                <div>
                  <span style={{ fontSize: 10, color: '#9aa0ad', fontWeight: 700 }}>PRIVATE KEY</span>
                  <p style={{ fontSize: 11, color: '#ff9f5a', wordBreak: 'break-all', margin: '2px 0 0', fontFamily: 'monospace' }}>{newWalletSeed.secretKey}</p>
                </div>
              </div>

              <label style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 12, color: '#e8e8f0', maxWidth: 320 }}>
                <input type="checkbox" checked={seedSavedConfirmed} onChange={(e) => setSeedSavedConfirmed(e.target.checked)} />
                I've saved my private key somewhere safe
              </label>

              {/* [DEV-BRANCH ONLY - PHASE 2] Encrypts the private key
                  with this password (client-side, see encryptPrivateKey)
                  so the SAME wallet can be unlocked again later from any
                  device via Profile → View Seed Phrase. Pre-filled when
                  we already have the password in memory (right after
                  signup/login). */}
              <div style={{ width: '100%', maxWidth: 320 }}>
                <p style={{ fontSize: 9.5, color: '#6a7570', letterSpacing: 0.3, margin: '0 0 4px' }}>CONFIRM ACCOUNT PASSWORD (to secure this wallet)</p>
                <div style={{ position: 'relative' }}>
                  <input
                    type={showWalletCreatePassword ? 'text' : 'password'} value={walletCreatePassword}
                    onChange={(e) => setWalletCreatePassword(e.target.value)}
                    placeholder="Your account password"
                    style={{
                      width: '100%', boxSizing: 'border-box', background: 'rgba(255,255,255,0.06)',
                      border: '1px solid rgba(255,255,255,0.15)', borderRadius: 8, padding: '10px 40px 10px 12px',
                      color: '#e8e8f0', fontSize: 13,
                    }}
                  />
                  <span
                    onClick={() => setShowWalletCreatePassword((v) => !v)}
                    style={{ position: 'absolute', right: 10, top: '50%', transform: 'translateY(-50%)', fontSize: 15, cursor: 'pointer', opacity: 0.7 }}
                  >{showWalletCreatePassword ? '🙈' : '👁️'}</span>
                </div>
                {/* [UPDATE] This MUST be the real account password - it's
                    what encrypts the wallet, and the same password is
                    the only way to ever unlock it again later. Warn
                    clearly (rather than silently letting it drift) if
                    what's typed here no longer matches what we already
                    know the account password to be. */}
                {authPassword && walletCreatePassword && walletCreatePassword !== authPassword && (
                  <p style={{ fontSize: 10.5, color: '#ff9f5a', margin: '4px 0 0', lineHeight: 1.4 }}>
                    ⚠️ This doesn't match your account password. It must be exactly your account password, or you won't be able to unlock this wallet later.
                  </p>
                )}
              </div>

              {walletError && <p style={{ color: '#ff6b6b', fontSize: 12, margin: 0, maxWidth: 300, textAlign: 'center' }}>{walletError}</p>}

              <button
                disabled={!seedSavedConfirmed || walletLoading}
                onClick={handleConfirmWalletCreated}
                style={{
                  width: '100%', maxWidth: 320,
                  background: (!seedSavedConfirmed || walletLoading) ? 'rgba(110,255,192,0.3)' : '#6effc0',
                  color: '#05130d', border: 'none', borderRadius: 8, padding: '13px 0', fontSize: 14, fontWeight: 800,
                }}
              >{walletLoading ? '...' : 'Continue'}</button>
            </>
          )}
        </div>
      )}

      {/* [DEV-BRANCH ONLY - PHASE 2] Profile Setup/Edit - name, unique
          username, wallet address, email (read-only), password reset
          link. Same screen serves both the initial post-wallet setup
          ('profileSetup') and later edits from Settings ('profileEdit')
          - isEditingProfile below is the only behavioral difference
          (Delete Profile + wallet copy button + Back only show in edit
          mode). THIS BLOCK MUST NEVER BE MERGED TO THE LIVE/MAIN
          BRANCH. */}
      {(screen === 'profileSetup' || screen === 'profileEdit') && (() => {
        const isEditingProfile = screen === 'profileEdit';
        return (
        <div style={{
          position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column',
          alignItems: 'center', justifyContent: 'center', padding: 24, gap: 14, overflow: 'auto',
        }}>
          {isEditingProfile && (
            <span
              onClick={() => setScreen('home')}
              style={{ position: 'absolute', top: 16, left: 16, fontSize: 12, color: '#9aa0ad', cursor: 'pointer' }}
            >← Back</span>
          )}

          <h1 style={{ fontSize: 20, fontWeight: 900, color: '#6effc0', margin: '0 0 4px', textAlign: 'center' }}>
            {isEditingProfile ? 'Edit profile' : 'Set up your profile'}
          </h1>

          <div style={{
            width: '100%', maxWidth: 320, display: 'flex', flexDirection: 'column', gap: 10,
            background: 'rgba(255,255,255,0.04)', border: '1px solid rgba(255,255,255,0.1)',
            borderRadius: 12, padding: 18,
          }}>
            <p style={{ fontSize: 9.5, color: '#6a7570', letterSpacing: 0.3, margin: '0 0 2px' }}>NAME</p>
            <input
              value={playerName} onChange={(e) => setPlayerName(e.target.value)} maxLength={16}
              placeholder="Your name"
              style={{
                background: 'rgba(255,255,255,0.06)', border: '1px solid rgba(255,255,255,0.15)',
                borderRadius: 8, padding: '10px 12px', color: '#e8e8f0', fontSize: 14,
              }}
            />

            <p style={{ fontSize: 9.5, color: '#6a7570', letterSpacing: 0.3, margin: '10px 0 2px' }}>USERNAME (unique)</p>
            <input
              value={profileUsername}
              onChange={(e) => setProfileUsername(e.target.value.toLowerCase().replace(/[^a-z0-9_]/g, ''))}
              maxLength={20}
              placeholder="e.g. saboteur_99"
              style={{
                background: 'rgba(255,255,255,0.06)', border: '1px solid rgba(255,255,255,0.15)',
                borderRadius: 8, padding: '10px 12px', color: '#e8e8f0', fontSize: 14,
              }}
            />

            {/* [UPDATE] Profile avatar picker - shown to CHANGE the
                account-level avatar (used on the Home "Profile" button)
                only when editing an existing profile via Settings, not
                during the very first post-wallet setup, matching how
                this was scoped before. Separate concept from the
                per-match avatar picked in the Lobby. */}
            {isEditingProfile && (
              <>
                <p style={{ fontSize: 9.5, color: '#6a7570', letterSpacing: 0.3, margin: '10px 0 2px' }}>PROFILE AVATAR</p>
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', gap: 8 }}>
                  {AVATARS.map((a) => (
                    <button
                      key={a.id}
                      onClick={() => setPlayerAvatarId(a.id)}
                      style={{
                        display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 3,
                        padding: '6px 2px', borderRadius: 9,
                        background: playerAvatarId === a.id ? 'rgba(110,255,192,0.16)' : 'rgba(255,255,255,0.04)',
                        border: playerAvatarId === a.id ? '1.5px solid #6effc0' : '1px solid rgba(255,255,255,0.08)',
                      }}
                    >
                      <img src={a.img} alt="" style={{ width: 26, height: 'auto', display: 'block' }} />
                    </button>
                  ))}
                </div>
              </>
            )}

            <p style={{ fontSize: 9.5, color: '#6a7570', letterSpacing: 0.3, margin: '10px 0 2px' }}>WALLET ADDRESS</p>
            <div style={{
              display: 'flex', alignItems: 'center', gap: 8,
              background: 'rgba(255,255,255,0.06)', border: '1px solid rgba(255,255,255,0.15)',
              borderRadius: 8, padding: '10px 12px',
            }}>
              <span style={{ flex: 1, fontSize: 11, color: '#e8e8f0', fontFamily: 'monospace', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                {loggedInPlayer?.walletAddress || '—'}
              </span>
              {isEditingProfile && (
                <span onClick={handleCopyWallet} style={{ fontSize: 11, color: '#6effc0', fontWeight: 700, cursor: 'pointer', flexShrink: 0 }}>
                  {walletCopied ? 'Copied!' : 'Copy'}
                </span>
              )}
            </div>

            <p style={{ fontSize: 9.5, color: '#6a7570', letterSpacing: 0.3, margin: '10px 0 2px' }}>EMAIL</p>
            <div style={{
              background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.08)',
              borderRadius: 8, padding: '10px 12px', fontSize: 13, color: '#9aa0ad',
            }}>
              {loggedInPlayer?.email}
            </div>

            <span onClick={handleGoToResetPassword} style={{ fontSize: 12, color: '#8fe3ff', cursor: 'pointer', marginTop: 2 }}>
              Reset password
            </span>

            {profileError && <p style={{ color: '#ff6b6b', fontSize: 12, margin: 0 }}>{profileError}</p>}

            <button
              disabled={profileLoading}
              onClick={handleSaveProfile}
              style={{
                background: profileLoading ? 'rgba(110,255,192,0.3)' : '#6effc0', color: '#05130d',
                border: 'none', borderRadius: 8, padding: '11px 0', fontSize: 14, fontWeight: 800, marginTop: 4,
              }}
            >{profileLoading ? '...' : 'Save Changes'}</button>

            {isEditingProfile && loggedInPlayer?.walletType === 'ingame' && (
              <button
                onClick={() => { setShowViewSeedModal(true); setRevealedSeed(''); setViewSeedPassword(''); setViewSeedError(''); }}
                style={{
                  background: 'rgba(255,255,255,0.06)', color: '#e8e8f0', border: '1px solid rgba(255,255,255,0.15)',
                  borderRadius: 8, padding: '10px 0', fontSize: 12, fontWeight: 700, marginTop: 6,
                }}
              >View Seed Phrase</button>
            )}

            {isEditingProfile && (
              <button
                onClick={() => setShowDeleteConfirm(true)}
                style={{
                  background: 'transparent', color: '#ff6b6b', border: '1px solid rgba(255,107,107,0.35)',
                  borderRadius: 8, padding: '10px 0', fontSize: 12, fontWeight: 700, marginTop: 6,
                }}
              >Delete Profile</button>
            )}
          </div>

          {/* [DEV-BRANCH ONLY - PHASE 2] View Seed Phrase modal -
              password-gated, client-side decrypt only (see
              handleViewSeedPhrase / decryptPrivateKey). */}
          {showViewSeedModal && (
            <div style={{
              position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.8)', zIndex: 50,
              display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 24,
            }}>
              <div style={{
                width: '100%', maxWidth: 300, background: 'linear-gradient(160deg, #0d1a14, #05100b)',
                border: '1px solid rgba(110,255,192,0.25)', borderRadius: 14, padding: 18,
                display: 'flex', flexDirection: 'column', gap: 10,
              }}>
                <h3 style={{ fontSize: 14, fontWeight: 900, color: '#6effc0', margin: 0 }}>🔑 View Seed Phrase</h3>
                {!revealedSeed ? (
                  <>
                    <p style={{ fontSize: 12, color: '#9aa0ad', margin: 0, lineHeight: 1.5 }}>
                      Enter your account password to decrypt and reveal your wallet's private key. This happens only on your device.
                    </p>
                    <div style={{ position: 'relative' }}>
                      <input
                        type={showViewSeedPassword ? 'text' : 'password'} placeholder="Account password" value={viewSeedPassword}
                        onChange={(e) => setViewSeedPassword(e.target.value)}
                        style={{
                          width: '100%', boxSizing: 'border-box', background: 'rgba(255,255,255,0.06)', border: '1px solid rgba(255,255,255,0.15)',
                          borderRadius: 8, padding: '10px 40px 10px 12px', color: '#e8e8f0', fontSize: 13,
                        }}
                      />
                      <span
                        onClick={() => setShowViewSeedPassword((v) => !v)}
                        style={{ position: 'absolute', right: 10, top: '50%', transform: 'translateY(-50%)', fontSize: 15, cursor: 'pointer', opacity: 0.7 }}
                      >{showViewSeedPassword ? '🙈' : '👁️'}</span>
                    </div>
                    {viewSeedError && <p style={{ color: '#ff6b6b', fontSize: 11, margin: 0 }}>{viewSeedError}</p>}
                    <button
                      disabled={viewSeedLoading}
                      onClick={handleViewSeedPhrase}
                      style={{
                        background: '#6effc0', color: '#05130d', border: 'none', borderRadius: 8,
                        padding: '11px 0', fontSize: 13, fontWeight: 800,
                      }}
                    >{viewSeedLoading ? '...' : 'Reveal'}</button>
                  </>
                ) : (
                  <>
                    <p style={{ fontSize: 11, color: '#ff9f5a', margin: 0 }}>⚠️ Never share this with anyone.</p>
                    <p style={{ fontSize: 11, color: '#e8e8f0', wordBreak: 'break-all', fontFamily: 'monospace', margin: 0 }}>{revealedSeed}</p>
                  </>
                )}
                <span
                  onClick={() => { setShowViewSeedModal(false); setRevealedSeed(''); setViewSeedPassword(''); }}
                  style={{ fontSize: 12, color: '#9aa0ad', textAlign: 'center', cursor: 'pointer' }}
                >Close</span>
              </div>
            </div>
          )}
          {showDeleteConfirm && (
            <div style={{
              position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.8)', zIndex: 50,
              display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 24,
            }}>
              <div style={{
                width: '100%', maxWidth: 300, background: 'linear-gradient(160deg, #1a0505, #100303)',
                border: '1px solid rgba(255,107,107,0.4)', borderRadius: 14, padding: 18,
                display: 'flex', flexDirection: 'column', gap: 10,
              }}>
                <h3 style={{ fontSize: 14, fontWeight: 900, color: '#ff6b6b', margin: 0 }}>⚠️ Delete your account?</h3>
                <p style={{ fontSize: 12, color: '#d8a0a0', margin: 0, lineHeight: 1.5 }}>
                  This permanently deletes your profile, wallet link, and all points/stats. This cannot be undone.
                </p>
                <div style={{ position: 'relative' }}>
                  <input
                    type={showDeletePassword ? 'text' : 'password'} placeholder="Enter your password to confirm" value={deletePassword}
                    onChange={(e) => setDeletePassword(e.target.value)}
                    style={{
                      width: '100%', boxSizing: 'border-box', background: 'rgba(255,255,255,0.06)', border: '1px solid rgba(255,255,255,0.15)',
                      borderRadius: 8, padding: '10px 40px 10px 12px', color: '#e8e8f0', fontSize: 13,
                    }}
                  />
                  <span
                    onClick={() => setShowDeletePassword((v) => !v)}
                    style={{ position: 'absolute', right: 10, top: '50%', transform: 'translateY(-50%)', fontSize: 15, cursor: 'pointer', opacity: 0.7 }}
                  >{showDeletePassword ? '🙈' : '👁️'}</span>
                </div>
                {deleteError && <p style={{ color: '#ff6b6b', fontSize: 11, margin: 0 }}>{deleteError}</p>}
                <button
                  disabled={deleteLoading}
                  onClick={handleDeleteProfile}
                  style={{
                    background: '#ff6b6b', color: '#1a0505', border: 'none', borderRadius: 8,
                    padding: '11px 0', fontSize: 13, fontWeight: 800,
                  }}
                >{deleteLoading ? '...' : 'Yes, delete my account'}</button>
                <span
                  onClick={() => { setShowDeleteConfirm(false); setDeletePassword(''); setDeleteError(''); }}
                  style={{ fontSize: 12, color: '#9aa0ad', textAlign: 'center', cursor: 'pointer' }}
                >Cancel</span>
              </div>
            </div>
          )}
        </div>
        );
      })()}
      {/* [DEV-BRANCH ONLY - PHASE 2] Home screen. THIS BLOCK MUST NEVER
          BE MERGED TO THE LIVE/MAIN BRANCH. */}
      {screen === 'home' && (
        <div style={{ position: 'absolute', inset: 0, overflow: 'hidden', background: '#000' }}>
        {/* [REDESIGN] Om7eth's own reference image is used as the actual
            Home screen background, full opacity, no dimming/gradient
            overlay - every button already drawn into that art (Activity,
            Wallet, Leaderboard, Announcements, the platform, chevrons,
            and the bottom nav) is left completely untouched. This outer
            wrapper is pure black (matches the image's own black
            background) and centers an inner frame locked to the image's
            exact aspect ratio, so it scales cleanly to any phone screen
            without cropping or stretching, and every tap zone below -
            positioned by exact pixel measurement from the image itself
            via homeRect() - lines up correctly no matter the device. */}
        <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <div style={{ position: 'relative', width: `min(100vw, calc(100vh * ${HOME_IMG_W} / ${HOME_IMG_H}))`, height: `min(100vh, calc(100vw * ${HOME_IMG_H} / ${HOME_IMG_W}))` }}>
            <img src={HOME_SCREEN_BG_IMG} alt="" style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'fill', display: 'block' }} />

            {/* Profile - tap opens the settings sheet; shows whichever
                avatar is currently selected on the platform below, kept
                in sync with it at all times. */}
            <HomeTapZone rect={homeRect(43, 46, 185, 192)} radius={16} onClick={guestGuard(() => setShowHomeSettings(true))}>
              <img src={getAvatar(playerAvatarId).img} alt="Profile" style={{ maxWidth: '58%', maxHeight: '78%', width: 'auto', height: 'auto', objectFit: 'contain' }} />
            </HomeTapZone>

            {/* Name / username - decorative, only changes via Profile
                Edit (reached through the settings sheet), not tappable
                itself. */}
            <div style={{ ...homeRect(202, 50, 585, 188), display: 'flex', flexDirection: 'column', justifyContent: 'center', paddingLeft: '3%', pointerEvents: 'none', overflow: 'hidden' }}>
              <span style={{ fontSize: 15, fontWeight: 900, color: '#eafff4', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                {isGuestPlayer ? 'Guest' : (playerName || loggedInPlayer?.name || 'Player')}
              </span>
              <span style={{ fontSize: 11, color: '#7fd9b8', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                {isGuestPlayer ? 'No profile' : `@${loggedInPlayer?.username || 'player'}`}
              </span>
            </div>

            {/* Weekly points value - the "WEEKLY POINTS" label is
                already drawn into the image; this just fills in the
                live number underneath it. Guests never earn points
                (there's no account for them to attach to). */}
            <div style={{ ...homeRect(583, 96, 917, 199), display: 'flex', alignItems: 'center', justifyContent: 'center', pointerEvents: 'none' }}>
              <span style={{ fontSize: 20, fontWeight: 900, color: '#fff' }}>{isGuestPlayer ? '—' : (loggedInPlayer?.totalPoints ?? 0)}</span>
            </div>

            {/* Avatar carousel - sits on the platform already drawn in
                the image; the two chevrons (also already drawn) get
                invisible tap zones on top of them. */}
            <HomeAvatarSprite avatarId={playerAvatarId} animDir={avatarAnimDir} animKey={avatarAnimKey} rect={homeRect(232, 610, 493, 1030)} />
            <HomeTapZone rect={homeRect(28, 872, 158, 1012)} radius={999} onClick={() => changeHomeAvatar(-1)} />
            <HomeTapZone rect={homeRect(575, 872, 705, 1012)} radius={999} onClick={() => changeHomeAvatar(1)} />

            {/* Live public rooms - the one new section (not in the
                image), placed in the gap right above Activity as
                requested. Tapping a room joins it immediately, no
                manual code entry. */}
            <HomeLiveRoomsCard rect={homeRect(660, 232, 907, 400)} rooms={publicRooms} onJoin={guestGuard((code) => { setScreen('lobby'); handleJoinRoom(code); })} />

            {/* Activity / Wallet / Leaderboard - already fully drawn in
                the image, just need the tap + glow feedback. Sized with
                a little extra margin on each edge so the glow always
                fully covers the drawn card even if the exact border
                position varies a few px by device/scaling. */}
            <HomeTapZone rect={homeRect(703, 428, 907, 660)} radius={16} onClick={guestGuard(() => setHomeModal('activity'))} />
            <HomeTapZone rect={homeRect(703, 668, 907, 900)} radius={16} onClick={guestGuard(() => setHomeModal('wallet'))} />
            <HomeTapZone rect={homeRect(703, 905, 907, 1137)} radius={16} onClick={guestGuard(() => setHomeModal('leaderboard'))} />

            {/* Announcements bar. */}
            <HomeTapZone rect={homeRect(419, 1255, 936, 1395)} radius={44} onClick={guestGuard(() => setHomeModal('announcements'))} />
            {announcements.length > 0 && (
              <div style={{ ...homeRect(900, 1268, 918, 1286), borderRadius: '50%', background: '#ff6b6b', border: '1.5px solid #05070a', pointerEvents: 'none' }} />
            )}

            {/* Bottom nav - Home + Free Play are live now; Pool/Paid/
                Sponsor Games are reachable and give real click feedback
                but are wired up one at a time in later steps. */}
            <HomeTapZone rect={homeRect(12, 1412, 186, 1644)} radius={16} onClick={() => setScreen('home')} />
            <HomeTapZone rect={homeRect(186, 1412, 368, 1644)} radius={16} onClick={() => setScreen('lobby')} />
            <HomeTapZone rect={homeRect(368, 1412, 553, 1644)} radius={16} onClick={guestGuard(() => setHomeModal('poolGames'))} />
            <HomeTapZone rect={homeRect(553, 1412, 739, 1644)} radius={16} onClick={guestGuard(() => setHomeModal('paidGames'))} />
            <HomeTapZone rect={homeRect(739, 1412, 928, 1644)} radius={16} onClick={guestGuard(() => setHomeModal('sponsorGames'))} />

          {/* [DEV-BRANCH ONLY - PHASE 2] Home hub modals - each tile's
              full content, full-screen so nothing needs to be cut off or
              scrolled awkwardly within a small tile. */}
          {homeModal === 'announcements' && (
            <HomeModal title="Announcements" onClose={() => setHomeModal(null)}>
              {announcements.length === 0 ? (
                <p style={{ fontSize: 12, color: '#6a7570', textAlign: 'center', marginTop: 20 }}>Nothing posted yet.</p>
              ) : announcements.map((a, i) => (
                <div key={i} style={{
                  background: 'rgba(255,180,60,0.1)', border: '1px solid rgba(255,180,60,0.3)',
                  borderRadius: 10, padding: '10px 12px', marginBottom: 8,
                }}>
                  <p style={{ fontSize: 13, fontWeight: 800, color: '#ffce7a', margin: '0 0 3px' }}>{a.title}</p>
                  {a.body && <p style={{ fontSize: 12, color: '#d8c8a8', margin: 0, lineHeight: 1.4 }}>{a.body}</p>}
                </div>
              ))}
            </HomeModal>
          )}

          {homeModal === 'activity' && (
            <HomeModal title="Activity" onClose={() => setHomeModal(null)}>
              <p style={{ fontSize: 12, color: '#d8c8a8', lineHeight: 1.6 }}>
                Your recent match history - missions completed, kills, votes, wins and losses - will show up here.
              </p>
              <p style={{ fontSize: 11, color: '#6a7570', marginTop: 10 }}>Coming in a future update.</p>
            </HomeModal>
          )}

          {homeModal === 'wallet' && (
            <HomeModal title="Wallet" onClose={() => setHomeModal(null)}>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                <div>
                  <span style={{ fontSize: 10, color: '#9aa0ad', fontWeight: 700 }}>ADDRESS</span>
                  <p style={{ fontSize: 12, color: '#e8e8f0', wordBreak: 'break-all', fontFamily: 'monospace', margin: '2px 0 0' }}>
                    {loggedInPlayer?.walletAddress || 'No wallet set up yet.'}
                  </p>
                </div>
                <div>
                  <span style={{ fontSize: 10, color: '#9aa0ad', fontWeight: 700 }}>TYPE</span>
                  <p style={{ fontSize: 12, color: '#e8e8f0', margin: '2px 0 0' }}>
                    {loggedInPlayer?.walletType === 'ingame' ? 'In-game wallet (testnet)' : loggedInPlayer?.walletType === 'connected' ? 'Connected wallet (testnet)' : '—'}
                  </p>
                </div>
                <p style={{ fontSize: 11, color: '#6a7570', lineHeight: 1.5, marginTop: 4 }}>
                  Balance, transfers, and other NEAR assets are coming in a future update. Manage your wallet (view seed phrase, disconnect) from Profile.
                </p>
              </div>
            </HomeModal>
          )}

          {homeModal === 'leaderboard' && (
            <HomeModal title="Leaderboard" onClose={() => setHomeModal(null)}>
              <div style={{
                background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.12)',
                borderRadius: 10, padding: 14, marginBottom: 12,
              }}>
                <span style={{ fontSize: 10, color: '#9aa0ad', fontWeight: 700 }}>YOUR STATS</span>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 8 }}>
                  <span style={{ fontSize: 12, color: '#9aa0ad' }}>Total Points</span>
                  <span style={{ fontSize: 12, color: '#6effc0', fontWeight: 800 }}>{loggedInPlayer?.totalPoints ?? 0}</span>
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 6 }}>
                  <span style={{ fontSize: 12, color: '#9aa0ad' }}>Games Played</span>
                  <span style={{ fontSize: 12, color: '#e8e8f0' }}>{loggedInPlayer?.gamesPlayed ?? 0}</span>
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 6 }}>
                  <span style={{ fontSize: 12, color: '#9aa0ad' }}>Games Won</span>
                  <span style={{ fontSize: 12, color: '#e8e8f0' }}>{loggedInPlayer?.gamesWon ?? 0}</span>
                </div>
              </div>
              <p style={{ fontSize: 11, color: '#6a7570', lineHeight: 1.5 }}>
                The full global leaderboard (all players, weekly reset every Saturday) is coming in a future update.
              </p>
            </HomeModal>
          )}

          {homeModal === 'poolGames' && (
            <HomeModal title="Pool Games" onClose={() => setHomeModal(null)}>
              <p style={{ fontSize: 12, color: '#d8c8a8', lineHeight: 1.6 }}>
                Create a public or private pool - fund it yourself, or set a fixed entry fee for others to join. Everyone who joins gets a private room code, and rewards are split by performance once the pool's games are done.
              </p>
              <p style={{ fontSize: 11, color: '#6a7570', marginTop: 10 }}>Coming in a future update.</p>
            </HomeModal>
          )}

          {homeModal === 'paidGames' && (
            <HomeModal title="Paid Games" onClose={() => setHomeModal(null)}>
              <p style={{ fontSize: 12, color: '#d8c8a8', lineHeight: 1.6 }}>
                Join a room with a fixed NEAR entry fee - the pot grows with every player, and payouts are split by performance once the game ends.
              </p>
              <p style={{ fontSize: 11, color: '#6a7570', marginTop: 10 }}>Coming in a future update.</p>
            </HomeModal>
          )}

          {homeModal === 'sponsorGames' && (
            <HomeModal title="Sponsor Games" onClose={() => setHomeModal(null)}>
              <p style={{ fontSize: 12, color: '#d8c8a8', lineHeight: 1.6 }}>
                Community owners will be able to fund and run reward pools for their own members as an engagement tool.
              </p>
              <p style={{ fontSize: 11, color: '#6a7570', marginTop: 10 }}>Coming in a future update.</p>
            </HomeModal>
          )}

          {/* [DEV-BRANCH ONLY - PHASE 2] Guest-locked notice - shown by
              guestGuard() whenever a guest taps something that needs a
              real account. "Create Profile" sends them back to the
              login screen's Sign Up tab; "Not now" just dismisses and
              they stay on Home as a guest. */}
          {showGuestLockedNotice && (
            <div
              onClick={() => setShowGuestLockedNotice(false)}
              style={{
                position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.7)', zIndex: 50,
                display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '8%',
              }}
            >
              <div
                onClick={(e) => e.stopPropagation()}
                style={{
                  width: '100%', maxWidth: 320, background: 'linear-gradient(160deg, #0d1a14, #05100b)',
                  borderRadius: 14, padding: '20px 18px', border: '1px solid rgba(110,255,192,0.3)',
                  display: 'flex', flexDirection: 'column', gap: 10, textAlign: 'center',
                }}
              >
                <h3 style={{ fontSize: 15, fontWeight: 900, color: '#fff', margin: 0 }}>Create a profile</h3>
                <p style={{ fontSize: 12.5, color: '#9aa0ad', margin: 0, lineHeight: 1.5 }}>
                  Guests can only play Free Play. Create a free account to unlock this and everything else.
                </p>
                <button
                  onClick={() => {
                    setShowGuestLockedNotice(false);
                    setIsGuestPlayer(false);
                    setAuthMode('signup');
                    setAuthError(''); setAuthInfo('');
                    setScreen('auth');
                  }}
                  style={{
                    background: '#6effc0', color: '#05130d', border: 'none', borderRadius: 8,
                    padding: '11px 0', fontSize: 13.5, fontWeight: 800, marginTop: 4,
                  }}
                >Create Profile</button>
                <span
                  onClick={() => setShowGuestLockedNotice(false)}
                  style={{ fontSize: 12, color: '#9aa0ad', cursor: 'pointer', padding: '4px 0' }}
                >Not now</span>
              </div>
            </div>
          )}

          {showHomeSettings && (
            <div
              onClick={() => setShowHomeSettings(false)}
              style={{
                position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.7)', zIndex: 40,
                display: 'flex', alignItems: 'flex-end',
              }}
            >
              <div
                onClick={(e) => e.stopPropagation()}
                style={{
                  width: '100%', background: 'linear-gradient(160deg, #0d1a14, #05100b)',
                  borderTopLeftRadius: 16, borderTopRightRadius: 16, padding: '18px 18px 28px',
                  border: '1px solid rgba(110,255,192,0.25)', borderBottom: 'none',
                  maxHeight: '80vh', overflowY: 'auto', touchAction: 'auto',
                }}
              >
                <h3 style={{ fontSize: 14, fontWeight: 800, color: '#fff', margin: '0 0 14px' }}>Profile</h3>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                  <button
                    onClick={() => { setShowHomeSettings(false); setScreen('profileEdit'); }}
                    style={{
                      width: '100%', background: 'rgba(255,255,255,0.06)', color: '#e8e8f0',
                      border: '1px solid rgba(255,255,255,0.15)', borderRadius: 9, padding: '12px 0',
                      fontSize: 13, fontWeight: 700,
                    }}
                  >Profile</button>
                  <button
                    onClick={() => { setShowHomeSettings(false); handleGoToResetPassword(); }}
                    style={{
                      width: '100%', background: 'rgba(255,255,255,0.06)', color: '#e8e8f0',
                      border: '1px solid rgba(255,255,255,0.15)', borderRadius: 9, padding: '12px 0',
                      fontSize: 13, fontWeight: 700,
                    }}
                  >Reset Password</button>
                  {/* [DEV-BRANCH ONLY - PHASE 2] More settings buttons go
                      here as later features land. */}
                  <button
                    onClick={handleLogout}
                    style={{
                      width: '100%', background: 'rgba(255,107,107,0.12)', color: '#ff8a8a',
                      border: '1px solid rgba(255,107,107,0.3)', borderRadius: 9, padding: '12px 0',
                      fontSize: 13, fontWeight: 800,
                    }}
                  >Log out</button>
                </div>
              </div>
            </div>
          )}
          </div>
        </div>
        </div>
      )}


      {screen === 'lobby' && (
        <LobbyScreen
          playerName={playerName}
          setPlayerName={setPlayerName}
          playerAvatarId={playerAvatarId}
          setPlayerAvatarId={setPlayerAvatarId}
          onStart={({ imposterCount: ic, speedLevel: sl }) => {
            setImposterCount(ic);
            handleStartGame(ic, sl);
            // Don't transition screen here — the host's own screen moves
            // to 'loading' only once their roleAssigned event arrives
            // (same listener every player uses), so host and everyone
            // else transition through the exact same code path.
          }}
          soundOn={soundOn}
          socket={socketRef.current}
          connStatus={connStatus}
          roomInfo={roomInfo}
          myRole={playerRole}
          joinError={joinError}
          onConnect={connectSocket}
          onCreateRoom={handleCreateRoom}
          onJoinRoom={handleJoinRoom}
          speedLevel={speedLevel}
          setSpeedLevel={setSpeedLevel}
          onRejoin={() => {
            // [BUG FIX] Clear all stale room/player state from before the
            // LEAVE - without this, pressing "Rejoin Lobby" would show
            // the create/join screen again, but otherPlayers/roomInfo
            // still held the OLD room's data until a fresh
            // roomCreated/roomJoined event overwrote it, which could
            // briefly show stale players or avatars left over from the
            // room we just left.
            setRoomInfo(null);
            setOtherPlayers({});
            otherPlayersTargetRef.current = {};
          }}
          onLeaveToHome={() => setScreen('home')}
          prefillJoinCode={prefillJoinCode}
          lobbyChatMessages={lobbyChatMessages}
          lobbyChatDraft={lobbyChatDraft}
          setLobbyChatDraft={setLobbyChatDraft}
          showLobbyChat={showLobbyChat}
          setShowLobbyChat={setShowLobbyChat}
          lobbyChatUnread={lobbyChatUnread}
          sendLobbyChatMessage={sendLobbyChatMessage}
          lobbyReplyingTo={lobbyReplyingTo}
          setLobbyReplyingTo={setLobbyReplyingTo}
          lobbyChatScrollRef={lobbyChatScrollRef}
        />
      )}

      {/* Loading transition — fixed 3s window between Lobby and actual
          gameplay, giving every device time to finish loading room art and
          other assets before anyone can move. */}
      {screen === 'loading' && (
        <div style={{
          position: 'absolute', inset: 0, background: '#05070a',
          display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
        }}>
          <img src={getAvatar(playerAvatarId).img} alt="" style={{
            width: 64, height: 'auto', marginBottom: 18,
            animation: 'loadingBob 0.9s ease-in-out infinite',
            filter: 'drop-shadow(0 4px 10px rgba(0,0,0,0.5))',
          }} />
          <p style={{ fontSize: 13, fontWeight: 700, color: '#6effc0', margin: '0 0 16px', letterSpacing: 0.3 }}>
            Boarding the station…
          </p>
          <div style={{ width: 180, height: 6, borderRadius: 999, background: 'rgba(255,255,255,0.1)', overflow: 'hidden' }}>
            <div style={{
              width: '100%', height: '100%', borderRadius: 999,
              background: 'linear-gradient(90deg,#6effc0,#2bb88a)',
              animation: 'loadingBar 3s linear forwards',
            }} />
          </div>
          <style>{`
            @keyframes loadingBob { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-6px); } }
            @keyframes loadingBar { from { transform: translateX(-100%); } to { transform: translateX(0%); } }
          `}</style>
        </div>
      )}

      {/* [NEW FEATURE] Role-reveal screen — sequential AFTER the loading
          window finishes (not overlapping it), shown to EVERY player for
          exactly 2 seconds, then gameplay starts. A crewmate only ever
          learns their OWN role and the total Saboteur count (never any
          other player's role) - white text, their own selected avatar.
          A Saboteur sees their own role in red, Among-Us-style bold
          condensed lettering, plus - only if there are 2+ Saboteurs in
          this game - their fellow Saboteur(s)' avatar+name below. */}
      {screen === 'roleReveal' && (
        <div style={{
          position: 'absolute', inset: 0,
          background: playerRole === 'saboteur' ? 'radial-gradient(circle at 50% 40%, #2a0a0a, #0a0303)' : 'radial-gradient(circle at 50% 40%, #0d1a14, #05070a)',
          display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 14, padding: 24,
        }}>
          <img src={getAvatar(playerAvatarId).img} alt="" style={{
            width: 84, height: 'auto',
            filter: playerRole === 'saboteur' ? 'drop-shadow(0 0 22px rgba(255,60,60,0.6))' : 'drop-shadow(0 0 18px rgba(110,255,192,0.45))',
            animation: 'roleRevealPop 0.4s ease-out',
          }} />
          <p style={{
            margin: 0, fontSize: 22, fontWeight: 900, letterSpacing: 1.2, textTransform: 'uppercase',
            fontFamily: '"Arial Black", "Helvetica Neue", sans-serif',
            color: playerRole === 'saboteur' ? '#ff3b3b' : '#ffffff',
            textShadow: playerRole === 'saboteur' ? '0 0 18px rgba(255,59,59,0.65)' : '0 1px 3px rgba(0,0,0,0.6)',
          }}>
            {playerRole === 'saboteur' ? 'You are The Saboteur' : 'You are a Crewmate'}
          </p>
          {playerRole === 'crewmate' && (
            <p style={{ margin: 0, fontSize: 12.5, fontWeight: 700, color: '#9aa0ad', letterSpacing: 0.3 }}>
              {saboteurCount} Saboteur{saboteurCount > 1 ? 's' : ''} {saboteurCount > 1 ? 'are' : 'is'} hiding among you.
            </p>
          )}
          {playerRole === 'saboteur' && fellowSaboteurs.length > 0 && (
            <div style={{ marginTop: 8, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 8 }}>
              <p style={{ fontSize: 11, fontWeight: 800, color: '#ff8a8a', letterSpacing: 0.5, margin: 0 }}>
                YOUR FELLOW SABOTEUR{fellowSaboteurs.length > 1 ? 'S' : ''}
              </p>
              <div style={{ display: 'flex', gap: 16, flexWrap: 'wrap', justifyContent: 'center' }}>
                {fellowSaboteurs.map((s, i) => (
                  <div key={i} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 5 }}>
                    <img src={getAvatar(s.avatarId).img} alt="" style={{ width: 42, height: 'auto' }} />
                    <span style={{ fontSize: 11, fontWeight: 700, color: '#ff8a8a' }}>{displayPlayerName(s.name, s.avatarId)}</span>
                  </div>
                ))}
              </div>
            </div>
          )}
          <style>{`@keyframes roleRevealPop { from { transform: scale(0.6); opacity: 0; } to { transform: scale(1); opacity: 1; } }`}</style>
        </div>
      )}

      <div style={{ display: screen === 'game' ? 'block' : 'none', position: 'absolute', inset: 0 }}>
      <div style={{ position: 'absolute', inset: 0, overflow: 'hidden', background: '#000' }}>
        <div style={{
          position: 'absolute', left: -camX * scale, top: -camY * scale,
          width: mapPxW * scale, height: mapPxH * scale, background: '#06060a',
        }}>
          {/* Rooms. Assembly Hall (cafeteria) uses its themed image (ratio matches room
              exactly, so it fits with no stretch). Others use placeholder colors. */}
          {ROOMS.map((rm) => {
            const displayName = ROOM_NAME_OVERRIDE[rm.id] || rm.name;
            const themeImg = rm.id === 'cafeteria' ? ASSEMBLY_HALL_IMG : rm.id === 'medbay' ? MEDBAY_IMG : rm.id === 'security' ? SECURITY_IMG : rm.id === 'reactor' ? VAULT_IMG : rm.id === 'upper_eng' ? STAKING_IMG : rm.id === 'lower_eng' ? LOWERENG_IMG : rm.id === 'electrical' ? ELECTRICAL_IMG : rm.id === 'storage' ? NEARAI_IMG : rm.id === 'comms' ? NEARMERCH_IMG : rm.id === 'o2' ? IRONCLAW_IMG : rm.id === 'admin' ? LEGION_IMG : rm.id === 'shields' ? EXCHANGE_IMG : rm.id === 'weapons' ? MEME_IMG : rm.id === 'navigation' ? CYBER_IMG : null;
            return (
              <div key={rm.id} style={{
                position: 'absolute',
                left: rm.x * TILE * scale, top: rm.y * TILE * scale,
                width: rm.w * TILE * scale, height: rm.h * TILE * scale,
                background: themeImg ? `#0a0e12 url(${themeImg}) center/100% 100% no-repeat` : rm.color,
                boxSizing: 'border-box', overflow: 'hidden',
              }}>
                {!themeImg && (
                  <span style={{
                    position: 'absolute', top: 5 * scale, left: 7 * scale,
                    fontSize: Math.max(9, 10 * scale), color: '#cfcfe0', fontWeight: 500, whiteSpace: 'nowrap',
                  }}>{displayName}</span>
                )}
              </div>
            );
          })}

          {/* Grid layer: corridors, walls, doors — drawn from the tile grid.
              Run-length batched per row to keep the DOM light.
              Corridor (c) and door (D) floors use the NEAR metal texture; walls (#)
              use a darker matching panel texture. Both anchored in GLOBAL map space
              so adjacent tiles line up into one continuous surface.
              Memoized on `scale` only — this never depends on player position, so it
              must not be recomputed on every movement frame (484+ tiles would be
              expensive to rebuild 30-60 times/sec). */}
          {gridLayerEls}

          {/* Corridor border layer (visual only — does not touch the walkability grid).
              Wherever a corridor tile's edge faces open void (no wall/room there),
              draw a thin wall-textured strip along that edge so every corridor reads
              as properly bounded by a wall, not floating in black space.
              Edge list is precomputed once at module load (CORRIDOR_BORDER_EDGES);
              the JSX itself is memoized on `scale` so it isn't rebuilt every frame. */}
          {corridorBorderEls}



          {/* Animated sliding doors — clearly read as DOORS (frame + paneled detail +
              status light), not walls. Open when the player is near, closed when far. */}
          {GATES.map((g) => {
            const pcx = pos.x + PLAYER_SIZE / 2;
            const pcy = pos.y + PLAYER_SIZE / 2;
            const isLocked = !!gateLockState.lockedIds && gateLockState.lockedIds.has(g.id);
            // [BUG FIX] Now checks every alive player's position, not
            // just our own - this is what makes a gate render open on
            // OUR screen when ANOTHER player is standing near it, even
            // if we ourselves are far away. Building this array inline
            // in the render (rather than a separate effect) keeps it
            // naturally tied to React's own render cadence instead of
            // needing its own throttle.
            const allGatePositions = myAlive ? [{ x: pcx, y: pcy }] : [];
            for (const oid in otherPlayers) {
              const op = otherPlayers[oid];
              if (op.alive === false) continue;
              if (typeof op.x !== 'number' || typeof op.y !== 'number') continue;
              allGatePositions.push({ x: op.x + PLAYER_SIZE / 2, y: op.y + PLAYER_SIZE / 2 });
            }
            const open = isGateOpen(g, allGatePositions);

            const gx = g.x * TILE * scale;
            const gy = g.y * TILE * scale;
            const gw = g.w * TILE * scale;
            const gh = g.h * TILE * scale;
            const vert = g.orient === 'v';
            const accentColor = isLocked ? '#ff5555' : '#3ddc97';
            const accentGlow = isLocked ? 'rgba(255,85,85,0.9)' : 'rgba(61,220,151,0.9)';

            // each sliding panel: dark metal with a bright leading edge —
            // green normally, red when sealed by a Saboteur gate lock
            const panel = (extra) => ({
              position: 'absolute',
              background: isLocked ? 'linear-gradient(135deg, #3b2424, #241616)' : 'linear-gradient(135deg, #243b33, #16241f)',
              transition: 'transform 0.2s ease, background 0.2s ease',
              ...extra,
            });
            // bright accent line on the panel's leading (meeting) edge
            const accent = (extra) => ({
              position: 'absolute', background: accentColor,
              boxShadow: `0 0 6px ${accentGlow}`,
              ...extra,
            });

            return (
              <div key={g.id} style={{
                position: 'absolute', left: gx, top: gy, width: gw, height: gh,
                overflow: 'hidden', zIndex: 4,
                // door recess frame so it reads as an opening in the wall
                boxShadow: 'inset 0 0 0 ' + Math.max(1, 1.2 * scale) + 'px ' + (isLocked ? 'rgba(255,85,85,0.4)' : 'rgba(61,220,151,0.35)'),
                background: open ? 'rgba(20,30,26,0.25)' : isLocked ? 'rgba(40,18,18,0.65)' : 'rgba(15,22,19,0.6)',
              }}>
                {vert ? (
                  <>
                    <div style={panel({ left: 0, top: 0, width: '100%', height: '50%',
                      transform: open ? 'translateY(-100%)' : 'translateY(0)' })}>
                      <div style={accent({ left: 0, bottom: 0, width: '100%', height: Math.max(1.5, 2 * scale) })} />
                    </div>
                    <div style={panel({ left: 0, bottom: 0, width: '100%', height: '50%',
                      transform: open ? 'translateY(100%)' : 'translateY(0)' })}>
                      <div style={accent({ left: 0, top: 0, width: '100%', height: Math.max(1.5, 2 * scale) })} />
                    </div>
                  </>
                ) : (
                  <>
                    <div style={panel({ top: 0, left: 0, height: '100%', width: '50%',
                      transform: open ? 'translateX(-100%)' : 'translateX(0)' })}>
                      <div style={accent({ top: 0, right: 0, height: '100%', width: Math.max(1.5, 2 * scale) })} />
                    </div>
                    <div style={panel({ top: 0, right: 0, height: '100%', width: '50%',
                      transform: open ? 'translateX(100%)' : 'translateX(0)' })}>
                      <div style={accent({ top: 0, left: 0, height: '100%', width: Math.max(1.5, 2 * scale) })} />
                    </div>
                  </>
                )}
              </div>
            );
          })}

          {/* Assembly Hall — the round table & CALL ASSEMBLY button are part of the image.
              When a player comes near the table (from ANY side), we add a soft red glow
              aura over the existing button so it lights up. Subtle, not a solid blob. */}
          {(() => {
            // Button center matches the image button position: tile (76, 12.8)
            const bcx = 76.0 * TILE, bcy = 12.8 * TILE;
            const pcx = pos.x + PLAYER_SIZE / 2, pcy = pos.y + PLAYER_SIZE / 2;
            const near = Math.hypot(bcx - pcx, bcy - pcy) < TILE * 4.6; // same as ASSEMBLY_RANGE
            if (!near) return null;
            const glow = 1.1 * TILE * scale;
            return (
              <div style={{
                position: 'absolute',
                left: bcx * scale - glow / 2, top: bcy * scale - glow / 2,
                width: glow, height: glow, borderRadius: '50%',
                background: 'radial-gradient(circle, rgba(255,70,70,0.30) 0%, transparent 65%)',
                boxShadow: `0 0 ${16 * scale}px rgba(255,50,50,0.85), 0 0 ${30 * scale}px rgba(255,50,50,0.45)`,
                zIndex: 6, pointerEvents: 'none',
              }} />
            );
          })()}

          {/* Verification Center — pure light-spread glow (no visible shape) when a
              player is close enough to actually touch the pod. */}
          {(() => {
            const vcx = (VERIFY_POD.x + 0.5) * TILE, vcy = (VERIFY_POD.y + 0.5) * TILE;
            const pcx = pos.x + PLAYER_SIZE / 2, pcy = pos.y + PLAYER_SIZE / 2;
            const near = Math.hypot(vcx - pcx, vcy - pcy) < VERIFY_RANGE;
            if (!near) return null;
            return (
              <div style={{
                position: 'absolute',
                left: vcx * scale, top: vcy * scale,
                width: 0, height: 0,
                boxShadow: `0 0 ${22 * scale}px ${10 * scale}px rgba(110,255,192,0.35)`,
                zIndex: 6, pointerEvents: 'none',
              }} />
            );
          })()}

          {/* Security Hub — pure light-spread glow (no visible shape) when a player
              is close enough to touch the hub. */}
          {(() => {
            const hcx = (SECURITY_HUB.x + 0.5) * TILE, hcy = (SECURITY_HUB.y + 0.5) * TILE;
            const pcx = pos.x + PLAYER_SIZE / 2, pcy = pos.y + PLAYER_SIZE / 2;
            const near = Math.hypot(hcx - pcx, hcy - pcy) < SECURITY_RANGE;
            if (!near) return null;
            return (
              <div style={{
                position: 'absolute',
                left: hcx * scale, top: hcy * scale,
                width: 0, height: 0,
                boxShadow: `0 0 ${22 * scale}px ${10 * scale}px rgba(110,255,192,0.35)`,
                zIndex: 6, pointerEvents: 'none',
              }} />
            );
          })()}

          {/* Confidential Vault — strong but clean light-spread glow (no visible shape)
              when a player is close enough to touch it. Brighter so the vault's text
              and NEAR logo become clearly visible/lit up. */}
          {(() => {
            const fcx = (VAULT_POD.x + 0.5) * TILE, fcy = (VAULT_POD.y + 0.5) * TILE;
            const pcx = pos.x + PLAYER_SIZE / 2, pcy = pos.y + PLAYER_SIZE / 2;
            const near = Math.hypot(fcx - pcx, fcy - pcy) < VAULT_RANGE;
            if (!near) return null;
            return (
              <div style={{
                position: 'absolute',
                left: fcx * scale, top: fcy * scale,
                width: 0, height: 0,
                boxShadow: `0 0 ${30 * scale}px ${16 * scale}px rgba(110,255,192,0.55)`,
                zIndex: 6, pointerEvents: 'none',
              }} />
            );
          })()}

          {/* Staking Vault — strong light-spread glow, same pattern as Confidential
              Vault, so the panel's stats/text light up clearly when approached. */}
          {(() => {
            const kcx = (STAKING_POD.x + 0.5) * TILE, kcy = (STAKING_POD.y + 0.5) * TILE;
            const pcx = pos.x + PLAYER_SIZE / 2, pcy = pos.y + PLAYER_SIZE / 2;
            const near = Math.hypot(kcx - pcx, kcy - pcy) < STAKING_RANGE;
            if (!near) return null;
            return (
              <div style={{
                position: 'absolute',
                left: kcx * scale, top: kcy * scale,
                width: 0, height: 0,
                boxShadow: `0 0 ${30 * scale}px ${16 * scale}px rgba(110,255,192,0.55)`,
                zIndex: 6, pointerEvents: 'none',
              }} />
            );
          })()}

          {/* Claim Vault — strong light-spread glow, same pattern as the other vaults. */}
          {(() => {
            const lcx = (CLAIM_POD.x + 0.5) * TILE, lcy = (CLAIM_POD.y + 0.5) * TILE;
            const pcx = pos.x + PLAYER_SIZE / 2, pcy = pos.y + PLAYER_SIZE / 2;
            const near = Math.hypot(lcx - pcx, lcy - pcy) < CLAIM_RANGE;
            if (!near) return null;
            return (
              <div style={{
                position: 'absolute',
                left: lcx * scale, top: lcy * scale,
                width: 0, height: 0,
                boxShadow: `0 0 ${30 * scale}px ${16 * scale}px rgba(110,255,192,0.55)`,
                zIndex: 6, pointerEvents: 'none',
              }} />
            );
          })()}

          {/* Electrical — strong light-spread glow over the breaker panel. */}
          {(() => {
            const ecx = (ELEC_POD.x + 0.5) * TILE, ecy = (ELEC_POD.y + 0.5) * TILE;
            const pcx = pos.x + PLAYER_SIZE / 2, pcy = pos.y + PLAYER_SIZE / 2;
            const near = Math.hypot(ecx - pcx, ecy - pcy) < ELEC_RANGE;
            if (!near) return null;
            return (
              <div style={{
                position: 'absolute',
                left: ecx * scale, top: ecy * scale,
                width: 0, height: 0,
                boxShadow: `0 0 ${30 * scale}px ${16 * scale}px rgba(110,255,192,0.55)`,
                zIndex: 6, pointerEvents: 'none',
              }} />
            );
          })()}

          {/* Near AI core (storage) — strong light-spread glow, slightly bigger spread
              since the object itself is larger. */}
          {(() => {
            const ncx = (NEARAI_POD.x + 0.5) * TILE, ncy = (NEARAI_POD.y + 0.5) * TILE;
            const pcx = pos.x + PLAYER_SIZE / 2, pcy = pos.y + PLAYER_SIZE / 2;
            const near = Math.hypot(ncx - pcx, ncy - pcy) < NEARAI_RANGE;
            if (!near) return null;
            return (
              <div style={{
                position: 'absolute',
                left: ncx * scale, top: ncy * scale,
                width: 0, height: 0,
                boxShadow: `0 0 ${38 * scale}px ${20 * scale}px rgba(110,255,192,0.55)`,
                zIndex: 6, pointerEvents: 'none',
              }} />
            );
          })()}

          {/* Near Merch console (comms) — strong light-spread glow. */}
          {(() => {
            const mcx = (NEARMERCH_POD.x + 0.5) * TILE, mcy = (NEARMERCH_POD.y + 0.5) * TILE;
            const pcx = pos.x + PLAYER_SIZE / 2, pcy = pos.y + PLAYER_SIZE / 2;
            const near = Math.hypot(mcx - pcx, mcy - pcy) < NEARMERCH_RANGE;
            if (!near) return null;
            return (
              <div style={{
                position: 'absolute',
                left: mcx * scale, top: mcy * scale,
                width: 0, height: 0,
                boxShadow: `0 0 ${30 * scale}px ${16 * scale}px rgba(110,255,192,0.55)`,
                zIndex: 6, pointerEvents: 'none',
              }} />
            );
          })()}

          {/* Ironclaw Hub (o2) — strong light-spread glow over the Deploy AI Agent console. */}
          {(() => {
            const icx = (IRONCLAW_POD.x + 0.5) * TILE, icy = (IRONCLAW_POD.y + 0.5) * TILE;
            const pcx = pos.x + PLAYER_SIZE / 2, pcy = pos.y + PLAYER_SIZE / 2;
            const near = Math.hypot(icx - pcx, icy - pcy) < IRONCLAW_RANGE;
            if (!near) return null;
            return (
              <div style={{
                position: 'absolute',
                left: icx * scale, top: icy * scale,
                width: 0, height: 0,
                boxShadow: `0 0 ${30 * scale}px ${16 * scale}px rgba(110,255,192,0.55)`,
                zIndex: 6, pointerEvents: 'none',
              }} />
            );
          })()}

          {/* Legion Hub (admin) — strong light-spread glow over the Admin Access terminal. */}
          {(() => {
            const gcx = (LEGION_POD.x + 0.5) * TILE, gcy = (LEGION_POD.y + 0.5) * TILE;
            const pcx = pos.x + PLAYER_SIZE / 2, pcy = pos.y + PLAYER_SIZE / 2;
            const near = Math.hypot(gcx - pcx, gcy - pcy) < LEGION_RANGE;
            if (!near) return null;
            return (
              <div style={{
                position: 'absolute',
                left: gcx * scale, top: gcy * scale,
                width: 0, height: 0,
                boxShadow: `0 0 ${30 * scale}px ${16 * scale}px rgba(110,255,192,0.55)`,
                zIndex: 6, pointerEvents: 'none',
              }} />
            );
          })()}

          {/* Exchange Hub (shields) — strong light-spread glow over the Cross-Chain Swap console. */}
          {(() => {
            const xcx = (EXCHANGE_POD.x + 0.5) * TILE, xcy = (EXCHANGE_POD.y + 0.5) * TILE;
            const pcx = pos.x + PLAYER_SIZE / 2, pcy = pos.y + PLAYER_SIZE / 2;
            const near = Math.hypot(xcx - pcx, xcy - pcy) < EXCHANGE_RANGE;
            if (!near) return null;
            return (
              <div style={{
                position: 'absolute',
                left: xcx * scale, top: xcy * scale,
                width: 0, height: 0,
                boxShadow: `0 0 ${30 * scale}px ${16 * scale}px rgba(110,255,192,0.55)`,
                zIndex: 6, pointerEvents: 'none',
              }} />
            );
          })()}

          {/* Meme Market (weapons) — strong light-spread glow over the Buy Meme Coin console. */}
          {(() => {
            const wcx = (MEME_POD.x + 0.5) * TILE, wcy = (MEME_POD.y + 0.5) * TILE;
            const pcx = pos.x + PLAYER_SIZE / 2, pcy = pos.y + PLAYER_SIZE / 2;
            const near = Math.hypot(wcx - pcx, wcy - pcy) < MEME_RANGE;
            if (!near) return null;
            return (
              <div style={{
                position: 'absolute',
                left: wcx * scale, top: wcy * scale,
                width: 0, height: 0,
                boxShadow: `0 0 ${30 * scale}px ${16 * scale}px rgba(110,255,192,0.55)`,
                zIndex: 6, pointerEvents: 'none',
              }} />
            );
          })()}

          {/* Cyber Defense Center (navigation) — strong light-spread glow over the
              Stop Hacker Attack console. */}
          {(() => {
            const ycx = (CYBER_POD.x + 0.5) * TILE, ycy = (CYBER_POD.y + 0.5) * TILE;
            const pcx = pos.x + PLAYER_SIZE / 2, pcy = pos.y + PLAYER_SIZE / 2;
            const near = Math.hypot(ycx - pcx, ycy - pcy) < CYBER_RANGE;
            if (!near) return null;
            return (
              <div style={{
                position: 'absolute',
                left: ycx * scale, top: ycy * scale,
                width: 0, height: 0,
                boxShadow: `0 0 ${30 * scale}px ${16 * scale}px rgba(110,255,192,0.55)`,
                zIndex: 6, pointerEvents: 'none',
              }} />
            );
          })()}

          {/* Task points — glowing stations players must walk up to (like Among Us consoles).
              Assembly Hall (cafeteria) is skipped here — its red CALL ASSEMBLY button is the indicator. */}
          {TASK_POINTS.filter(tp => tp.room !== 'cafeteria' && tp.room !== 'medbay' && tp.room !== 'security' && tp.room !== 'reactor' && tp.room !== 'upper_eng' && tp.room !== 'lower_eng' && tp.room !== 'electrical' && tp.room !== 'storage' && tp.room !== 'comms' && tp.room !== 'o2' && tp.room !== 'admin' && tp.room !== 'shields' && tp.room !== 'weapons' && tp.room !== 'navigation').map((tp) => {
            const active = nearTask?.room === tp.room;
            return (
              <div key={tp.room} style={{
                position: 'absolute',
                left: ((tp.x + 0.5) * TILE - 9) * scale,
                top: ((tp.y + 0.5) * TILE - 9) * scale,
                width: 18 * scale, height: 18 * scale, borderRadius: 4,
                background: active ? '#ffd24a' : 'rgba(255,210,74,0.45)',
                border: `${1.5 * scale}px solid #ffd24a`,
                boxShadow: active ? '0 0 12px rgba(255,210,74,0.9)' : '0 0 6px rgba(255,210,74,0.4)',
                zIndex: 4,
              }} />
            );
          })}

          {/* Vent grates — visible to EVERYONE (crewmates included), only
              in the 10 rooms that have one. The grate itself is just part
              of the room's scenery that anyone can see; only the "Enter
              Vent" interaction below is role-gated to the Saboteur, so
              crewmates can watch a Saboteur disappear into / emerge from
              one but never use it themselves. Always has a faint outline
              glow so it reads clearly against any floor color/texture —
              the raw grate art alone was too dark/low-contrast to spot
              reliably otherwise. */}
          {Object.entries(VENT_POSITIONS).map(([roomId, vp]) => (
            <div key={`vent-${roomId}`} style={{
              position: 'absolute',
              left: (vp.x * TILE - 13) * scale,
              top: (vp.y * TILE - 8.5) * scale,
              width: 26 * scale, height: 17 * scale,
              zIndex: 4, pointerEvents: 'none',
              border: `${1 * scale}px solid rgba(110,255,192,0.55)`,
              boxShadow: playerRole === 'saboteur' && nearVent && currentRoom?.id === roomId
                ? '0 0 12px rgba(110,255,192,0.9)'
                : '0 0 5px rgba(110,255,192,0.35)',
              borderRadius: 4, boxSizing: 'border-box',
            }}>
              <img src={VENT_ICON_IMG} alt="" style={{ width: '100%', height: '100%', objectFit: 'contain', display: 'block' }} />
            </div>
          ))}

          {/* Player position itself is now rendered by the avatar sprite
              below (outside this inner camera-scaled wrapper, since the
              avatar uses screen coordinates directly) — no marker needed
              here anymore. */}
        </div>

        {/* Fog of war — limited vision zone, same idea as Among Us: the player can
            only see a circular area around themselves; everywhere else stays dark.
            This is purely visual right now (single player, nothing to hide from yet),
            but it's built so the same overlay will work per-player once multiplayer
            is added — each client only ever renders its own vision circle.
            VISION_RADIUS_TILES is sized so the biggest room (Assembly Hall / cafeteria,
            20x16 tiles) is fully visible from anywhere inside it, including corners.
            In normal play the clear zone covers almost the whole visible
            radius (just a thin soft edge), so nearby surroundings read
            clearly. During a power sabotage (sabotageProgress -> 1) both the
            radius collapses to VISION_RADIUS_SABOTAGED AND the clear zone
            itself shrinks relative to that radius, producing the graduated
            3-ring blackout — same dark "lights are out" look as Among Us. */}
        {(() => {
          const radiusTiles = VISION_RADIUS_TILES + (VISION_RADIUS_SABOTAGED - VISION_RADIUS_TILES) * sabotageProgress;
          const lerp = (a, b) => a + (b - a) * sabotageProgress;
          // [UPDATE] Complete rework per Om7eth's exact spec - the
          // previous version compressed the fade INTO the existing
          // vision radius (shrinking the actual clear zone down to ~86%
          // of it to make room for the rings), which wasn't right - the
          // full configured vision range must stay 100% clear, exactly
          // as-is, and the fade rings now grow OUTWARD beyond it instead
          // (each one 16% further out than the last), so the total
          // affected radius is now LARGER than the raw vision range, not
          // squeezed inside it. Four rings: clear -> dim -> more dim ->
          // more dim -> fully dark, each a smooth radial-gradient step
          // (not a hard edge) so the eye reads it as one soft vignette.
          const maxAlpha = lerp(0.97, 0.995);
          const rPx = radiusTiles * TILE * scale; // the REAL vision range - stays fully clear out to exactly here
          const GROWTH_PER_RING = 0.16; // each successive ring's radius is 16% further out than the last
          const r0 = rPx;                          // 100% - fully clear boundary (the actual vision range, unchanged)
          const r1 = rPx * (1 + GROWTH_PER_RING);       // +16% - first dim ring
          const r2 = rPx * (1 + GROWTH_PER_RING * 2);   // +32% - more dim
          const r3 = rPx * (1 + GROWTH_PER_RING * 3);   // +48% - more dim still
          const r4 = rPx * (1 + GROWTH_PER_RING * 4);   // +64% - fully dark from here outward
          const gradientStops = [
            [r0, 0],
            [r1, maxAlpha * 0.28],
            [r2, maxAlpha * 0.55],
            [r3, maxAlpha * 0.80],
            [r4, maxAlpha],
          ].map(([r, a]) => `rgba(4,4,7,${a.toFixed(3)}) ${r}px`).join(', ');
          return (
            <div style={{
              position: 'absolute', inset: 0, pointerEvents: 'none', zIndex: 8,
              background: `radial-gradient(circle at ${playerScreenX}px ${playerScreenY}px,
                transparent 0px, transparent ${r0}px,
                ${gradientStops})`,
            }} />
          );
        })()}
      </div>

      {/* Player avatar — same sprite design for everyone, only the cloak
          color differs per player (set in the Lobby). Flips horizontally
          to face the direction of travel, and bounces while moving so it
          reads as a run rather than a float. Sized a bit larger than the
          actual collision box (PLAYER_SIZE) so the character reads clearly
          at this zoom level without inflating the hitbox itself.
          Hidden entirely while fully inside a vent — the Saboteur is
          "inside the walls" and shouldn't be visible on the map at all —
          except during the brief enter/exit squish animation, which plays
          right at the vent grate before/after that. */}
      {(!inVent || ventAnim) && (
      <div style={{
        position: 'absolute', left: playerScreenX, top: playerScreenY,
        // [BUG FIX] Lowered from 9 to 7 - below the fog-of-war overlay
        // (zIndex 8) instead of above it. Previously the player's own
        // avatar rendered ON TOP of the darkness, which is harmless for
        // ourselves (we're always centered in our own clear zone
        // anyway), but the same z-index was used for OTHER players too -
        // meaning a sabotage-darkened crewmate could still see another
        // player crystal-clear through the dark, completely defeating
        // the point of cutting the power. Below the fog, anyone outside
        // the visible radius is now actually hidden by it, the way it
        // should be.
        width: 26, height: 26, zIndex: 7, pointerEvents: 'none',
      }}>
        <div style={{
          width: '100%', height: '100%',
          transform: `translate(-50%, -60%) scaleX(${facing === 'left' ? -1 : 1})`,
          animation: ventAnim === 'entering' ? 'ventSquishIn 0.35s ease-in forwards'
            : ventAnim === 'exiting' ? 'ventSquishOut 0.35s ease-out forwards' : 'none',
          // [GHOST RULE] Lowered opacity gives a translucent, ghost-like
          // look once dead — same visual treatment otherPlayers' ghost
          // rendering already uses for other dead players, applied here to
          // our own avatar too.
          opacity: myAlive ? 1 : 0.4,
        }}>
          <img
            src={getAvatar(displayedAvatarId).img} alt=""
            style={{
              width: '100%', height: '100%', objectFit: 'contain', display: 'block',
              // [GHOST RULE] Ghosts get a slow vertical float instead of the
              // sharp walk-bob — no up/down "footstep" bounce, just a gentle
              // drifting motion that reads as floating rather than walking,
              // matching how they pass through walls instead of stepping
              // around them.
              animation: !myAlive ? 'ghostFloat 2.2s ease-in-out infinite'
                : isMoving ? 'avatarWalkBob 0.32s ease-in-out infinite' : 'none',
              filter: 'drop-shadow(0 2px 3px rgba(0,0,0,0.5))',
            }}
          />
        </div>
        {/* [NEW FEATURE] Our own name tag - deliberately a SEPARATE
            sibling from the avatar's own transform above (not nested
            inside it), so the facing-direction scaleX flip never mirrors
            the text. Shows our disguised name if currently disguised
            (matching the disguised avatar shown via displayedAvatarId),
            otherwise our real name - always plain white, since a
            Saboteur never needs to color their OWN name (the red
            coloring is only ever meaningful for telling apart OTHER
            players). */}
        <div style={{
          position: 'absolute', left: '50%', top: -12, transform: 'translateX(-50%)',
          whiteSpace: 'nowrap', fontSize: 8.5, fontWeight: 700, color: '#fff',
          textShadow: '0 1px 2px rgba(0,0,0,0.9), 0 0 4px rgba(0,0,0,0.6)',
          opacity: myAlive ? 1 : 0.6,
        }}>
          {disguiseActive
            ? (roomInfo?.players?.find((rp) => rp.avatarId === disguiseActive.avatarId)?.name || getAvatar(disguiseActive.avatarId).name)
            : displayPlayerName(playerName, playerAvatarId)}
        </div>
      </div>
      )}
      <style>{`
        @keyframes avatarWalkBob {
          0%, 100% { transform: translateY(0); }
          50% { transform: translateY(-3px); }
        }
        @keyframes ghostFloat {
          0%, 100% { transform: translateY(0); }
          50% { transform: translateY(-5px); }
        }
        @keyframes ventSquishIn {
          0% { transform: translate(-50%, -60%) scaleX(${facing === 'left' ? -1 : 1}) scale(1); opacity: 1; }
          100% { transform: translate(-50%, -60%) scaleX(${facing === 'left' ? -1 : 1}) scale(0.2); opacity: 0; }
        }
        @keyframes ventSquishOut {
          0% { transform: translate(-50%, -60%) scaleX(${facing === 'left' ? -1 : 1}) scale(0.2); opacity: 0; }
          100% { transform: translate(-50%, -60%) scaleX(${facing === 'left' ? -1 : 1}) scale(1); opacity: 1; }
        }
      `}</style>

      {/* [MULTIPLAYER] Real other players — replaces the old single
          wandering dummy crewmate. Rendered the same way as the player's
          own avatar (same size/shadow), just at each player's own synced
          position.
          [GHOST RULE] A dead other-player only ever has a fresh x/y here
          if WE are also dead (the server only broadcasts a ghost's
          movement to other ghosts — see playerMove's isGhost branch on
          the backend), so checking p.alive === false here is exactly the
          right signal to render them as a floating ghost rather than
          hiding them; alive players simply never receive this data for a
          dead player in the first place. Bodies (for dead players whose
          position is now stale, pre-ghost-movement) are drawn separately
          below and don't overlap with this. */}
      {Object.entries(otherPlayers).map(([id, p]) => {
        if (typeof p.x !== 'number' || typeof p.y !== 'number') return null;
        const isGhost = p.alive === false;
        // [GHOST RULE] A dead other-player only renders here if WE are
        // also currently dead — alive players never see a ghost moving
        // around at all (they only ever see where the body fell, drawn
        // separately below). This mirrors the server only ever
        // broadcasting a ghost's movement to other ghosts.
        if (isGhost && myAlive) return null;
        // [BUG FIX] While another player is inside a vent (between an
        // 'enter' and a matching 'exit' event), they're completely
        // hidden — same as a Saboteur's own avatar vanishing on their
        // own screen. The brief squish-in/out is shown via opacity/scale
        // during the ventAnimPhase window instead of an instant pop, so
        // nearby players see the same transition the Saboteur sees.
        if (p.inVent && !p.ventAnimPhase) return null;
        return (
          <div key={id} style={{
            position: 'absolute', left: worldToScreenX(p.x), top: worldToScreenY(p.y),
            // [BUG FIX] Lowered from 9 to 7 - same fix as our own avatar
            // above. This is what actually makes the fog-of-war hide
            // distant players during a power sabotage, instead of them
            // staying fully visible right through the darkness.
            width: 26, height: 26, zIndex: 7, pointerEvents: 'none',
            transform: 'translate(-50%, -60%)',
            opacity: p.ventAnimPhase ? 0 : (isGhost ? 0.4 : 1),
            transition: p.ventAnimPhase ? 'opacity 0.35s ease, transform 0.35s ease' : 'none',
            // [FLICKER FIX] No CSS transition on left/top here — the
            // screen position (worldToScreenX/Y) depends on BOTH this
            // player's own world position AND our own camera position
            // (which follows OUR character at a full 60fps). Putting a
            // transition on left/top meant that every time WE moved, the
            // camera shift alone made other players' on-screen position
            // change too, and the browser tried to "transition" that
            // camera-driven jump on an 80ms timer fighting against a
            // 16ms render loop — that mismatch is exactly what looked
            // like shaking/flickering whenever our own joystick moved.
            // Smoothing belongs on the camera-independent world position
            // instead (handled via the throttled emit + receiving more
            // frequent updates), not on the final screen pixel. The
            // opacity/transform transition above is unrelated (only
            // triggers during the brief vent squish window) and doesn't
            // have this problem since it's not tied to camera-driven
            // left/top changes.
          }}>
            {/* [BUG FIX] Use the disguised avatar (if any) instead of
                always rendering p.avatarId - this is what makes a
                Saboteur's disguise actually show up on every OTHER
                player's screen too, the same way it already did on the
                Saboteur's own. */}
            <img src={getAvatar(p.disguiseAvatarId || p.avatarId).img} alt="" style={{
              width: '100%', height: '100%', objectFit: 'contain', display: 'block',
              filter: 'drop-shadow(0 2px 3px rgba(0,0,0,0.5))',
              // [GHOST RULE] Same floating animation as our own ghost
              // avatar — no walk-bob, just a slow vertical drift.
              animation: isGhost ? 'ghostFloat 2.2s ease-in-out infinite' : 'none',
              transform: p.ventAnimPhase === 'entering' ? 'scale(0.3)' : p.ventAnimPhase === 'exiting' ? 'scale(0.3)' : 'scale(1)',
            }} />
            {/* [NEW FEATURE] Name tag above the avatar, same idea as
                Among Us. Shows the DISGUISED name if this player is
                currently disguised (matching the disguised avatar
                already shown above) - a Saboteur's disguise is supposed
                to actually confuse onlookers, so showing their REAL name
                while wearing someone else's avatar would defeat half the
                point. [NEW FEATURE] Colored red ONLY if WE ourselves are
                a Saboteur AND this specific player is one of our fellow
                Saboteurs (fellowSaboteurs is only ever populated for
                Saboteur clients in the first place - crewmates always
                see every name in plain white, with no way to tell who's
                who). */}
            {(() => {
              const isFellowSaboteur = playerRole === 'saboteur' && fellowSaboteurs.some(
                (s) => s.name === p.name && s.avatarId === p.avatarId
              );
              const displayedName = p.disguiseAvatarId
                ? (roomInfo?.players?.find((rp) => rp.avatarId === p.disguiseAvatarId)?.name || getAvatar(p.disguiseAvatarId).name)
                : displayPlayerName(p.name, p.avatarId);
              return (
                <div style={{
                  position: 'absolute', left: '50%', top: -12, transform: 'translateX(-50%)',
                  whiteSpace: 'nowrap', fontSize: 8.5, fontWeight: 700,
                  color: isFellowSaboteur ? '#ff5c5c' : '#fff',
                  textShadow: '0 1px 2px rgba(0,0,0,0.9), 0 0 4px rgba(0,0,0,0.6)',
                  opacity: isGhost ? 0.6 : 1,
                }}>{displayedName}</div>
              );
            })()}
          </div>
        );
      })}

      {/* Dead bodies + blood pools — stay exactly where each player died,
          permanently (until reset). The body sprite itself is the same
          avatar art rotated on its side, with a realistic irregular blood
          splatter underneath (soaked dark halo + jagged pool + wet
          highlight + scattered droplets — not a clean oval).
          [MULTIPLAYER] Multiple bodies can exist at once now — replaces
          the old single dummyBody with a map keyed by player id. */}
      {Object.entries(deadBodies).map(([id, b]) => (
        <div key={id} style={{
          position: 'absolute',
          left: worldToScreenX(b.x),
          top: worldToScreenY(b.y),
          zIndex: 4, pointerEvents: 'none', transform: 'translate(-50%, -50%)',
        }}>
          <svg width="64" height="46" viewBox="0 0 140 100" style={{
            position: 'absolute', left: '50%', top: '50%', transform: 'translate(-50%, -50%)', zIndex: 0,
          }}>
            <path d="M70 12 C86 8 102 18 108 32 C116 42 114 58 100 66 C92 76 76 80 60 78 C44 80 28 74 20 60 C12 50 16 34 28 24 C38 12 54 14 70 12 Z"
              fill="#3a0808" opacity="0.35" />
            <path d="M70 18 C84 14 98 22 102 34 C108 42 106 56 94 62 C88 70 74 74 60 72 C46 74 32 68 26 56 C20 46 24 32 34 24 C42 16 56 18 70 18 Z"
              fill="#6e0d0d" />
            <path d="M68 26 C76 24 86 28 90 36 C94 42 92 50 84 54 C78 58 68 58 60 54 C52 50 50 42 54 34 C58 28 62 28 68 26 Z"
              fill="#9c1818" opacity="0.65" />
            <ellipse cx="116" cy="20" rx="3" ry="4.5" fill="#6e0d0d" transform="rotate(40 116 20)" />
            <ellipse cx="14" cy="62" rx="4" ry="5.5" fill="#6e0d0d" transform="rotate(-20 14 62)" />
            <ellipse cx="98" cy="10" rx="2.2" ry="3" fill="#6e0d0d" transform="rotate(15 98 10)" />
            <ellipse cx="30" cy="84" rx="3.5" ry="2.5" fill="#6e0d0d" transform="rotate(60 30 84)" />
            <ellipse cx="110" cy="70" rx="2.5" ry="3.2" fill="#6e0d0d" transform="rotate(-30 110 70)" />
            <circle cx="6" cy="42" r="1.8" fill="#6e0d0d" />
            <circle cx="120" cy="48" r="1.5" fill="#6e0d0d" />
          </svg>
          <img src={getAvatar(b.avatarId).img} alt="" style={{
            position: 'relative', width: 24, height: 24, objectFit: 'contain', display: 'block',
            transform: 'rotate(90deg)', filter: 'drop-shadow(0 1px 2px rgba(0,0,0,0.6))', zIndex: 1,
          }} />
        </div>
      ))}

      {/* Kill cutscene — Among-Us-style: a full-screen close-up showing
          BOTH the killer (this player) and the victim (the dummy)
          together. Two distinct animations, picked randomly per kill
          (see killCutscene.type in handleKillDummy): a knife stab, or a
          neck twist — both read as the killer's own hands doing the act,
          not just two characters standing near each other. Steps through
          lunge -> strike -> fall over 2.5s at normal speed (no slow-mo),
          then gameplay resumes and the body/blood are left in-world.
          Everything below is positioned with fixed pixel coordinates
          inside one 280x220 "stage" div — earlier versions nested the
          knife/hand inside flex children with their own transforms, which
          made them render in the wrong place (or get clipped/invisible)
          depending on the parent's actual layout box. Fixed coordinates
          inside a single known-size stage avoids that entirely. */}
      {killCutscene && (
        <div style={{
          position: 'absolute', inset: 0, zIndex: 60, background: '#000',
          display: 'flex', alignItems: 'center', justifyContent: 'center', overflow: 'hidden',
        }}>
          <div style={{
            position: 'absolute', inset: 0,
            background: 'radial-gradient(circle at 50% 50%, transparent 30%, rgba(0,0,0,0.7) 100%)',
          }} />
          {killCutscene.stage === 'strike' && (
            <div style={{
              position: 'absolute', inset: 0, background: 'rgba(180,0,0,0.25)',
              animation: 'cutsceneFlash 0.18s ease-out',
            }} />
          )}

          {/* The stage: a fixed 280x220 box, everything inside positioned
              with absolute pixel coordinates relative to it. */}
          <div style={{ position: 'relative', width: 280, height: 220 }}>
            {/* Killer — starts left, lunges toward center on strike.
                [MULTIPLAYER] Looks up the killer's avatar by id: if I'm
                the killer, use my own displayedAvatarId (disguise-aware);
                otherwise look up the killer's avatar from otherPlayers
                since any nearby player should see the cutscene with the
                correct killer shown, not always "me". */}
            <div style={{
              position: 'absolute', top: 60, zIndex: 2,
              left: killCutscene.stage === 'lunge' ? 40 : 78,
              transition: 'left 0.5s cubic-bezier(0.3, 0, 0.4, 1)',
            }}>
              <img src={getAvatar(
                killCutscene.killerId === socketRef.current?.id
                  ? displayedAvatarId
                  : (otherPlayers[killCutscene.killerId]?.avatarId || playerAvatarId)
              ).img} alt="" style={{
                width: 84, height: 'auto', display: 'block', transform: 'scaleX(-1)',
                filter: 'drop-shadow(0 6px 16px rgba(0,0,0,0.6))',
              }} />
            </div>

            {/* Victim — starts right, recoils/falls in place.
                [MULTIPLAYER] Same id-based lookup as the killer above,
                from the victim's side. */}
            <div style={{
              position: 'absolute', top: 60, left: 156, zIndex: 1,
              transform:
                killCutscene.stage === 'fall' ? 'rotate(80deg) translateY(24px) translateX(-6px)' :
                killCutscene.stage === 'strike' && killCutscene.type === 'knife' ? 'translateX(6px) rotate(6deg)' :
                killCutscene.stage === 'strike' && killCutscene.type === 'twist' ? 'rotate(95deg)' :
                'translateX(0) rotate(0deg)',
              opacity: killCutscene.stage === 'fall' ? 0.85 : 1,
              // Normal-speed transitions throughout — no slow-motion easing.
              transition: killCutscene.stage === 'fall' ? 'transform 0.3s ease-in, opacity 0.3s' : 'transform 0.2s ease-out',
            }}>
              <img src={getAvatar(
                killCutscene.targetId === socketRef.current?.id
                  ? displayedAvatarId
                  : (otherPlayers[killCutscene.targetId]?.avatarId || playerAvatarId)
              ).img} alt="" style={{
                width: 84, height: 'auto', display: 'block',
                filter: 'drop-shadow(0 6px 16px rgba(0,0,0,0.6))',
              }} />
            </div>

            {/* Knife — only for the 'knife' kill type. A proper knife
                shape (dark wooden handle, metal guard, wide blade with an
                edge highlight) instead of a thin line — verified visible
                and recognizable at this size. Sits at the gap between
                killer and victim, thrusts further right on strike. Drawn
                on top of both (zIndex 4) so it's never hidden. */}
            {killCutscene.type === 'knife' && killCutscene.stage !== 'fall' && (
              <svg width="56" height="56" viewBox="0 0 60 60" fill="none" style={{
                position: 'absolute', top: 76, zIndex: 4,
                left: killCutscene.stage === 'lunge' ? 100 : 124,
                transform: `rotate(${killCutscene.stage === 'lunge' ? -15 : 12}deg)`,
                transition: 'left 0.2s ease-out, transform 0.2s ease-out',
              }}>
                <rect x="4" y="38" width="20" height="9" rx="2.5" fill="#3a2a1a" stroke="#1a0f08" strokeWidth="0.8" transform="rotate(-35 4 38)" />
                <rect x="22" y="32" width="6" height="14" rx="1.5" fill="#9a9a9a" transform="rotate(-35 22 32)" />
                <path d="M27 33 L52 8 L57 11 L58 16 L33 41 Z" fill="#e0e0e0" stroke="#888" strokeWidth="1.2" strokeLinejoin="round" />
                <path d="M29 33 L51 11" stroke="#fff" strokeWidth="1.5" strokeLinecap="round" opacity="0.8" />
              </svg>
            )}

            {/* Killer's grabbing hand — only for the 'twist' kill type. A
                proper hand shape (sleeve, palm, four curled fingers,
                thumb) gripping the victim's head, instead of a plain
                blob. Drawn on top of both sprites so it's always visible. */}
            {killCutscene.type === 'twist' && killCutscene.stage !== 'fall' && (
              <svg width="50" height="50" viewBox="0 0 60 60" fill="none" style={{
                position: 'absolute', top: 56, zIndex: 4,
                left: killCutscene.stage === 'lunge' ? 118 : 134,
                transform: `rotate(${killCutscene.stage === 'strike' ? 95 : 0}deg)`,
                transformOrigin: '32px 28px',
                transition: 'left 0.2s ease-out, transform 0.2s ease-out',
              }}>
                <rect x="2" y="24" width="22" height="13" rx="5" fill="#2a2a2a" transform="rotate(-10 2 24)" />
                <ellipse cx="32" cy="28" rx="11" ry="9" fill="#d8a878" />
                <path d="M38 20 Q44 18 45 24 Q45 28 40 28 Q37 27 38 20Z" fill="#d8a878" />
                <path d="M40 16 Q46 15 46 21 Q45 25 41 24 Q39 22 40 16Z" fill="#d8a878" />
                <path d="M41 13 Q47 13 46 19 Q45 22 42 21 Q40 19 41 13Z" fill="#d8a878" />
                <path d="M40 10 Q45 11 44 16 Q42 19 40 17 Q39 14 40 10Z" fill="#d8a878" />
                <path d="M24 32 Q22 38 28 39 Q32 38 30 33 Q27 30 24 32Z" fill="#c89868" />
              </svg>
            )}

            {/* Blood burst at the moment of the strike */}
            {(killCutscene.stage === 'strike' || killCutscene.stage === 'fall') && (
              <div style={{ position: 'absolute', top: 96, left: 150, zIndex: 3, pointerEvents: 'none' }}>
                {[...Array(10)].map((_, i) => (
                  <div key={i} style={{
                    position: 'absolute', left: 0, top: 0, width: 5, height: 5, borderRadius: '50%',
                    background: '#c81414',
                    transform: `rotate(${i * 36}deg) translateY(-2px)`,
                    animation: 'cutsceneBloodSpray 0.55s ease-out forwards',
                    animationDelay: `${i * 0.015}s`,
                  }} />
                ))}
              </div>
            )}
          </div>

          <p style={{
            position: 'absolute', bottom: 70, left: 0, right: 0, textAlign: 'center',
            fontSize: 13, fontWeight: 800, color: '#ff5c5c', letterSpacing: 1, textTransform: 'uppercase',
            opacity: killCutscene.stage === 'fall' ? 1 : 0, transition: 'opacity 0.3s',
          }}>Eliminated</p>

          <style>{`
            @keyframes cutsceneFlash { 0% { opacity: 0; } 30% { opacity: 1; } 100% { opacity: 0; } }
            @keyframes cutsceneBloodSpray {
              0% { opacity: 1; transform: rotate(var(--ang, 0deg)) translateY(-2px) scale(1); }
              100% { opacity: 0; transform: rotate(var(--ang, 0deg)) translateY(-34px) scale(0.4); }
            }
          `}</style>
        </div>
      )}

      {/* Directional arrow to the Electrical room — only shown while the
          power is sabotaged, so the player (or whoever's fixing it) always
          knows which way to go even with vision collapsed. Angle is
          recalculated from the live player position toward ELEC_POD every
          render, so it stays accurate as they move. */}
      {powerSabotaged && (() => {
        const ecx = (ELEC_POD.x + 0.5) * TILE, ecy = (ELEC_POD.y + 0.5) * TILE;
        const playerCx = pos.x + PLAYER_SIZE / 2, playerCy = pos.y + PLAYER_SIZE / 2;
        // atan2 gives 0° = pointing right, increasing clockwise toward down.
        // Our SVG arrow's tip points up (0°) by default, so to make it face
        // the target we rotate it by the target's angle plus 90° — turning
        // "up" into "right" (0°), "right" into "down" (90°), and so on.
        const angleDeg = Math.atan2(ecy - playerCy, ecx - playerCx) * 180 / Math.PI + 90;
        return (
          <div style={{
            position: 'absolute', top: 64, left: '50%', transform: 'translateX(-50%)',
            zIndex: 21, pointerEvents: 'none', display: 'flex', flexDirection: 'column',
            alignItems: 'center', gap: 2,
          }}>
            <div style={{
              width: 40, height: 40, borderRadius: '50%', background: 'rgba(8,8,13,0.82)',
              border: '1px solid rgba(255,209,102,0.4)', boxShadow: '0 2px 10px rgba(0,0,0,0.4)',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
            }}>
              <svg
                width="20" height="22" viewBox="0 0 22 26"
                style={{ transform: `rotate(${angleDeg}deg)`, transition: 'transform 0.15s linear' }}
              >
                <path d="M11 0 L21 20 L11 15 L1 20 Z" fill="#ffd166" stroke="#0a0a0a" strokeWidth="1" />
              </svg>
            </div>
            <span style={{
              fontSize: 9, fontWeight: 700, color: '#ffd166', letterSpacing: 0.3,
              background: 'rgba(8,8,13,0.82)', padding: '2px 7px', borderRadius: 6,
            }}>⚡ ELECTRICAL</span>
          </div>
        );
      })()}

      {/* Red alarm overlay — full-screen pulsing red wash while a hacker
          attack is active, same idea as the Among Us reactor-meltdown
          alarm. Pure CSS animation (no JS interval), so it's essentially
          free performance-wise. */}
      {hackerAttack && (
        <>
          <div style={{
            position: 'absolute', inset: 0, zIndex: 12, pointerEvents: 'none',
            background: 'rgba(180,20,20,0.28)',
            animation: 'cyberAlarmPulse 1s ease-in-out infinite',
          }} />
          <style>{`@keyframes cyberAlarmPulse { 0%, 100% { opacity: 0.35; } 50% { opacity: 0.9; } }`}</style>
        </>
      )}

      {/* Directional arrow to the Cyber Defense Center — only shown during
          a hacker attack. Same live-angle approach as the Electrical
          arrow, with its own icon (a stylized "no-signal" glyph) rather
          than an emoji. */}
      {hackerAttack && (() => {
        const ccx = (CYBER_POD.x + 0.5) * TILE, ccy = (CYBER_POD.y + 0.5) * TILE;
        const playerCx = pos.x + PLAYER_SIZE / 2, playerCy = pos.y + PLAYER_SIZE / 2;
        const angleDeg = Math.atan2(ccy - playerCy, ccx - playerCx) * 180 / Math.PI + 90;
        return (
          <div style={{
            position: 'absolute', top: 64, left: '50%', transform: 'translateX(-50%)',
            zIndex: 21, pointerEvents: 'none', display: 'flex', flexDirection: 'column',
            alignItems: 'center', gap: 2,
          }}>
            <div style={{
              width: 40, height: 40, borderRadius: '50%', background: 'rgba(8,8,13,0.82)',
              border: '1px solid rgba(255,85,85,0.5)', boxShadow: '0 2px 10px rgba(0,0,0,0.4)',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
            }}>
              <svg
                width="20" height="22" viewBox="0 0 22 26"
                style={{ transform: `rotate(${angleDeg}deg)`, transition: 'transform 0.15s linear' }}
              >
                <path d="M11 0 L21 20 L11 15 L1 20 Z" fill="#ff5555" stroke="#0a0a0a" strokeWidth="1" />
              </svg>
            </div>
            <span style={{
              display: 'flex', alignItems: 'center', gap: 4, fontSize: 9, fontWeight: 700,
              color: '#ff8a8a', letterSpacing: 0.3, background: 'rgba(8,8,13,0.82)',
              padding: '2px 8px', borderRadius: 6,
            }}>
              <svg width="9" height="9" viewBox="0 0 24 24" fill="none">
                <path d="M12 2L4 7v6c0 5 3.5 8 8 9 4.5-1 8-4 8-9V7l-8-5z" stroke="#ff8a8a" strokeWidth="2" strokeLinejoin="round" />
                <path d="M9 9l6 6M15 9l-6 6" stroke="#ff8a8a" strokeWidth="2" strokeLinecap="round" />
              </svg>
              CYBER DEFENSE
            </span>
          </div>
        );
      })()}

      {/* HUD — single slim pill, top-left only. Kept deliberately small so it never
          eats into the play area; one tap target (settings) holds everything else. */}
      <div style={{
        position: 'absolute', top: 8, left: 8, zIndex: 20,
        display: 'flex', alignItems: 'center', gap: 6,
        background: 'rgba(8,8,13,0.82)', borderRadius: 9, padding: '5px 10px',
        border: '1px solid rgba(110,255,192,0.22)', backdropFilter: 'blur(3px)',
        maxWidth: 'calc(100vw - 70px)', boxShadow: '0 2px 10px rgba(0,0,0,0.4)',
      }}>
        <span style={{ fontSize: 11, fontWeight: 700, color: '#6effc0', letterSpacing: 0.2, whiteSpace: 'nowrap' }}>
          NEAR Saboteur
        </span>
        <span style={{ color: 'rgba(255,255,255,0.25)', fontSize: 11 }}>·</span>
        <span style={{
          fontSize: 11, fontWeight: 500, color: '#cfd2da', whiteSpace: 'nowrap',
          overflow: 'hidden', textOverflow: 'ellipsis',
        }}>
          {currentRoom ? (ROOM_NAME_OVERRIDE[currentRoom.id] || currentRoom.name) : 'Corridor'}
        </span>
      </div>

      {/* Top-right controls: map + settings only. Sound now lives inside Settings,
          not duplicated out here. */}
      <div style={{ position: 'absolute', top: 8, right: 8, zIndex: 20, display: 'flex', alignItems: 'center', gap: 6 }}>
        {gateLock.group && (
          <div style={{
            display: 'flex', alignItems: 'center', gap: 4, padding: '5px 9px', borderRadius: 8,
            background: 'rgba(40,12,12,0.85)', border: '1px solid rgba(255,85,85,0.4)',
            boxShadow: '0 2px 10px rgba(0,0,0,0.4)',
          }}>
            <span style={{ fontSize: 12 }}>🔒</span>
            <span style={{ fontSize: 11, fontWeight: 800, color: '#ff8a8a', letterSpacing: 0.2 }}>
              {gateLock.group === 'A' ? 'Left' : 'Right'} · {lockSecondsLeft}s
            </span>
          </div>
        )}
        <button onClick={() => setShowMap(true)} aria-label="Map" style={{
          width: 34, height: 34, borderRadius: 9, border: '1px solid rgba(110,255,192,0.22)',
          background: 'rgba(8,8,13,0.82)', color: '#6effc0', fontSize: 15,
          display: 'flex', alignItems: 'center', justifyContent: 'center', boxShadow: '0 2px 10px rgba(0,0,0,0.4)',
        }}>
          <span style={{ position: 'relative', width: 18, height: 14, flexShrink: 0 }}>
            <span style={{
              position: 'absolute', inset: 0, border: '1.6px solid #6effc0', borderRadius: 2, boxSizing: 'border-box',
            }} />
            <span style={{
              position: 'absolute', top: 0, left: '33%', width: 0, height: '100%',
              borderLeft: '1.2px dashed #6effc0', opacity: 0.7,
            }} />
            <span style={{
              position: 'absolute', top: 0, left: '67%', width: 0, height: '100%',
              borderLeft: '1.2px dashed #6effc0', opacity: 0.7,
            }} />
            <span style={{
              position: 'absolute', top: 3, left: '50%', width: 4.5, height: 4.5, borderRadius: '50%',
              background: '#6effc0', transform: 'translateX(-50%)',
            }} />
          </span>
        </button>
        <button onClick={() => setShowSettings(true)} aria-label="Settings" style={{
          width: 34, height: 34, borderRadius: 9, border: '1px solid rgba(110,255,192,0.22)',
          background: 'rgba(8,8,13,0.82)', color: '#6effc0', fontSize: 15,
          display: 'flex', alignItems: 'center', justifyContent: 'center', boxShadow: '0 2px 10px rgba(0,0,0,0.4)',
        }}>⚙️</button>
      </div>

      {/* Settings panel — sound toggle + exit, styled to match the game's dark
          sci-fi / NEAR-green look instead of a generic light dialog. */}
      {showSettings && (
        <div onClick={() => setShowSettings(false)} style={{
          position: 'fixed', inset: 0, zIndex: 50, background: 'rgba(0,0,0,0.7)',
          display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 24,
        }}>
          <div onClick={e => e.stopPropagation()} style={{
            background: 'linear-gradient(160deg, #11141a, #0a0a0f)', borderRadius: 16,
            padding: '18px 18px 16px', width: '100%', maxWidth: 300,
            border: '1px solid rgba(110,255,192,0.25)', boxShadow: '0 0 30px rgba(110,255,192,0.08)',
          }}>
            <h2 style={{
              fontSize: 14, fontWeight: 700, margin: '0 0 14px', color: '#6effc0',
              letterSpacing: 0.4, textTransform: 'uppercase',
            }}>Settings</h2>

            <div style={{
              display: 'flex', alignItems: 'center', justifyContent: 'space-between',
              padding: '12px 2px',
            }}>
              <span style={{ fontSize: 13, color: '#e8e8f0' }}>Sound</span>
              <button onClick={() => setSoundOn(s => !s)} style={{
                width: 46, height: 26, borderRadius: 13, border: 'none', position: 'relative',
                background: soundOn ? '#6effc0' : '#2a2a33', transition: 'background 0.15s',
              }}>
                <div style={{
                  position: 'absolute', top: 3, left: soundOn ? 23 : 3, width: 20, height: 20,
                  borderRadius: '50%', background: '#0a0a0f', transition: 'left 0.15s',
                }} />
              </button>
            </div>

            <div style={{ height: 1, background: 'rgba(255,255,255,0.08)', margin: '4px 0 14px' }} />

            <button onClick={() => setShowSettings(false)} style={{
              width: '100%', padding: '10px 0', borderRadius: 10, border: '1px solid rgba(110,255,192,0.3)',
              background: 'transparent', color: '#6effc0', fontWeight: 600, fontSize: 13, marginBottom: 8,
            }}>Resume</button>

            <button onClick={() => setShowExitConfirm(true)} style={{
              width: '100%', padding: '10px 0', borderRadius: 10, border: 'none',
              background: 'rgba(255,85,85,0.15)', color: '#ff7a7a', fontWeight: 600, fontSize: 13,
            }}>🚪 Exit Game</button>

            <p style={{
              textAlign: 'center', fontSize: 10, color: '#454c48', margin: '14px 0 0', letterSpacing: 0.2,
            }}>Game creator — Om7eth</p>
          </div>
        </div>
      )}

      {/* Exit confirmation — separate step so a stray tap can't quit the game by accident. */}
      {showExitConfirm && (
        <div onClick={() => setShowExitConfirm(false)} style={{
          position: 'fixed', inset: 0, zIndex: 60, background: 'rgba(0,0,0,0.75)',
          display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 24,
        }}>
          <div onClick={e => e.stopPropagation()} style={{
            background: '#11141a', borderRadius: 16, padding: 18, width: '100%', maxWidth: 280,
            border: '1px solid rgba(255,85,85,0.3)', textAlign: 'center',
          }}>
            <p style={{ fontSize: 13, color: '#e8e8f0', margin: '0 0 6px', fontWeight: 700 }}>Exit this game?</p>
            <p style={{ fontSize: 11, color: '#9aa0ad', margin: '0 0 16px', lineHeight: 1.5 }}>
              You won't be able to rejoin this session — you'll return to the lobby and can only join a new game.
            </p>
            <div style={{ display: 'flex', gap: 8 }}>
              <button onClick={() => setShowExitConfirm(false)} style={{
                flex: 1, padding: '10px 0', borderRadius: 10, border: '1px solid rgba(255,255,255,0.15)',
                background: 'transparent', color: '#cfd2da', fontWeight: 600, fontSize: 13,
              }}>Cancel</button>
              <button onClick={resetGame} style={{
                flex: 1, padding: '10px 0', borderRadius: 10, border: 'none',
                background: '#ff5555', color: '#fff', fontWeight: 700, fontSize: 13,
              }}>Exit</button>
            </div>
          </div>
        </div>
      )}

      {/* Map overlay — full station layout with corridors drawn in (not just rooms),
          so it actually reads as a map instead of floating boxes. */}
      {showMap && (
        <div onClick={() => setShowMap(false)} style={{
          position: 'fixed', inset: 0, zIndex: 50, background: 'rgba(0,0,0,0.78)',
          display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 18,
        }}>
          <div onClick={e => e.stopPropagation()} style={{
            background: 'linear-gradient(160deg, #11141a, #0a0a0f)', borderRadius: 16, padding: 14,
            width: '100%', maxWidth: 420, border: '1px solid rgba(110,255,192,0.25)',
            boxShadow: '0 0 30px rgba(110,255,192,0.08)',
          }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
              <h2 style={{
                fontSize: 13, fontWeight: 700, margin: 0, color: '#6effc0',
                letterSpacing: 0.4, textTransform: 'uppercase',
              }}>Station Map</h2>
              <button onClick={() => setShowMap(false)} style={{
                width: 28, height: 28, borderRadius: 8, border: '1px solid rgba(255,255,255,0.15)',
                background: 'transparent', color: '#cfd2da', fontSize: 14,
              }}>✕</button>
            </div>
            <div style={{
              position: 'relative', width: '100%', paddingTop: `${(GRID_H / GRID_W) * 100}%`,
              background: '#06060a', borderRadius: 10, overflow: 'hidden',
              border: '1px solid rgba(255,255,255,0.07)',
            }}>
              {/* Corridors/doors — the actual paths connecting rooms */}
              {MINIMAP_CORRIDOR_RUNS.map((run, i) => (
                <div key={i} style={{
                  position: 'absolute',
                  left: `${(run.x / GRID_W) * 100}%`, top: `${(run.y / GRID_H) * 100}%`,
                  width: `${(run.w / GRID_W) * 100}%`, height: `${(1 / GRID_H) * 100}%`,
                  background: 'rgba(110,255,192,0.28)',
                }} />
              ))}
              {/* Rooms on top of the path layer — numbered markers instead of squeezing
                  full names into tiny boxes (which clipped names like "Verification
                  Center" or "Confidential Vault"). Full names are listed in the legend
                  below where there's room to show them completely. */}
              {ROOMS.map((rm, idx) => {
                const left = (rm.x / GRID_W) * 100;
                const top = (rm.y / GRID_H) * 100;
                const w = (rm.w / GRID_W) * 100;
                const h = (rm.h / GRID_H) * 100;
                const isHere = currentRoom?.id === rm.id;
                const isLockedVault = rm.id === 'reactor' && !vaultUnlocked;
                return (
                  <div key={rm.id} style={{
                    position: 'absolute', left: `${left}%`, top: `${top}%`, width: `${w}%`, height: `${h}%`,
                    background: isLockedVault ? 'rgba(255,180,60,0.22)' : isHere ? 'rgba(110,255,192,0.45)' : 'rgba(40,42,54,0.92)',
                    border: isLockedVault ? '1.5px solid rgba(255,180,60,0.7)' : isHere ? '1.5px solid #6effc0' : '1px solid rgba(255,255,255,0.18)',
                    borderRadius: 3, display: 'flex', alignItems: 'center', justifyContent: 'center',
                    boxSizing: 'border-box', zIndex: 2,
                  }}>
                    <span style={{
                      fontSize: 9, fontWeight: 700, color: isLockedVault ? '#ffb43c' : isHere ? '#0a0a0f' : '#9aa0ad',
                      lineHeight: 1,
                    }}>{isLockedVault ? '🔒' : idx + 1}</span>
                  </div>
                );
              })}
              {/* Player's current position */}
              <div style={{
                position: 'absolute',
                left: `${((pos.x / TILE) / GRID_W) * 100}%`,
                top: `${((pos.y / TILE) / GRID_H) * 100}%`,
                width: 5, height: 5, borderRadius: '50%', background: '#fff',
                boxShadow: '0 0 5px 2px rgba(255,255,255,0.8)', transform: 'translate(-50%,-50%)', zIndex: 3,
              }} />
            </div>

            <p style={{ fontSize: 9.5, color: '#7a7a86', margin: '8px 0 6px', textAlign: 'center' }}>
              Green lines = corridors · dot = you
            </p>

            {/* Legend — full room names, since the boxes on the map are too small to
                fit names like "Verification Center" or "Confidential Vault" without
                clipping them. Numbers here match the numbered markers on the map. */}
            <div style={{
              display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '4px 10px',
              maxHeight: 140, overflowY: 'auto', padding: '8px 4px 2px',
              borderTop: '1px solid rgba(255,255,255,0.08)',
            }}>
              {ROOMS.map((rm, idx) => {
                const isHere = currentRoom?.id === rm.id;
                const label = ROOM_NAME_OVERRIDE[rm.id] || rm.name;
                const isLockedVault = rm.id === 'reactor' && !vaultUnlocked;
                return (
                  <div key={rm.id} style={{
                    display: 'flex', alignItems: 'center', gap: 6,
                    color: isLockedVault ? '#ffb43c' : isHere ? '#6effc0' : '#cfd2da',
                    fontWeight: isHere ? 700 : 500,
                  }}>
                    <span style={{
                      width: 16, height: 16, borderRadius: 4, flexShrink: 0,
                      background: isHere ? '#6effc0' : 'rgba(255,255,255,0.12)',
                      color: isHere ? '#0a0a0f' : '#9aa0ad',
                      display: 'flex', alignItems: 'center', justifyContent: 'center',
                      fontSize: 9, fontWeight: 700,
                    }}>{idx + 1}</span>
                    <span style={{ fontSize: 11, lineHeight: 1.2 }}>
                      {label}{rm.id === 'reactor' ? (vaultUnlocked ? ' 🔓' : ' 🔒') : ''}
                    </span>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      )}

      {nearTask && !showMission && (
        <button
          onClick={() => {
            if (nearTask.room === 'cafeteria') { callMeeting('self'); return; }
            if (nearTask.room === 'reactor' && !vaultUnlocked) return;
            setShowMission(true);
          }}
          style={{
            position: 'absolute', bottom: 200, left: '50%', transform: 'translateX(-50%)',
            display: 'flex', alignItems: 'center', gap: 7,
            background: nearTask.room === 'reactor' && !vaultUnlocked ? 'rgba(40,28,8,0.85)'
              : nearTask.room === 'cafeteria' ? 'rgba(40,10,10,0.82)' : 'rgba(8,8,13,0.82)',
            color: nearTask.room === 'reactor' && !vaultUnlocked ? '#ffb43c'
              : nearTask.room === 'cafeteria' ? '#ff8a8a' : '#6effc0',
            border: `1px solid ${nearTask.room === 'reactor' && !vaultUnlocked ? 'rgba(255,180,60,0.45)'
              : nearTask.room === 'cafeteria' ? 'rgba(255,85,85,0.4)' : 'rgba(110,255,192,0.35)'}`,
            borderRadius: 20, backdropFilter: 'blur(4px)',
            padding: '8px 16px', fontSize: 12.5, fontWeight: 700, letterSpacing: 0.2, zIndex: 15,
            boxShadow: nearTask.room === 'cafeteria' ? '0 2px 14px rgba(255,85,85,0.25)' : '0 2px 14px rgba(110,255,192,0.18)',
            whiteSpace: 'nowrap', maxWidth: '88vw', textAlign: 'center',
          }}
        >{nearTask.room === 'reactor' && !vaultUnlocked
          ? `🔒 Vault Locked — needs ${MISSIONS_REQUIRED_FOR_VAULT} missions done (crew: ${crewProgress.minDone}/${MISSIONS_REQUIRED_FOR_VAULT})`
          : nearTask.room === 'cafeteria' ? '🚨 Call Assembly' : nearTask.room === 'medbay' ? '🔐 Verify Wallet' : nearTask.room === 'security' ? '🛡️ Access Security Hub' : nearTask.room === 'reactor' ? '🔒 Enable Confidential Mode' : nearTask.room === 'upper_eng' ? '📈 Stake NEAR' : nearTask.room === 'lower_eng' ? '🎁 Claim Rewards' : nearTask.room === 'electrical' ? '⚡ Repair Power Grid' : nearTask.room === 'storage' ? '🤖 Ask NEAR AI 4 Questions' : nearTask.room === 'comms' ? '🛒 Buy Merch' : nearTask.room === 'o2' ? '🚀 Deploy AI Agent' : nearTask.room === 'admin' ? '🏛️ NEAR Legion' : nearTask.room === 'shields' ? '🔁 Cross-Chain Swap' : nearTask.room === 'weapons' ? '🪙 Buy Meme Coin' : nearTask.room === 'navigation' ? '🛡️ Stop Hacker Attack' : 'Start Mission'}</button>
      )}

      {showMission && nearTask && nearTask.room === 'medbay' && (
        <div style={{
          position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.78)',
          display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 30, padding: 16,
        }}>
          <WalletVerificationMission
            confidentialMode={confidentialMode}
            onClose={() => setShowMission(false)}
            onComplete={() => { completeMission('medbay'); setShowMission(false); }}
          />
        </div>
      )}

      {showMission && nearTask && nearTask.room === 'security' && (
        <div style={{
          position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.78)',
          display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 30, padding: 16,
        }}>
          <SecurityCameraMission
            onClose={() => { completeMission('security'); setShowMission(false); }}
            players={[
              // [UPDATE] name added (via displayPlayerName, same fallback
              // used everywhere else in the game) - CameraFeed now shows
              // who's who directly on the feed, not just an avatar.
              { id: socketRef.current?.id || 'me', x: pos.x, y: pos.y, avatarId: displayedAvatarId, isMe: true, name: displayPlayerName(playerName, displayedAvatarId) },
              // [BUG FIX] Every other real player is now included too -
              // previously CCTV only ever showed our own dot, which made
              // the security cameras pointless for actually spotting
              // anyone else's movement (ghosts are excluded here since
              // they can't be filmed - same idea as them passing through
              // walls; a ghost simply isn't physically "there" for a
              // camera to pick up).
              ...Object.entries(otherPlayers)
                .filter(([, p]) => p.alive !== false && !p.inVent && typeof p.x === 'number' && typeof p.y === 'number')
                .map(([id, p]) => ({
                  id, x: p.x, y: p.y, avatarId: p.disguiseAvatarId || p.avatarId, isMe: false,
                  // [BUG FIX] Was showing the player's REAL name here even
                  // while disguised (only the avatar image itself
                  // respected disguiseAvatarId) - defeating the entire
                  // point of a disguise the moment someone checked the
                  // camera. Now matches the exact same disguise-aware
                  // name logic already used for the on-map name tag.
                  name: p.disguiseAvatarId
                    ? (roomInfo?.players?.find((rp) => rp.avatarId === p.disguiseAvatarId)?.name || getAvatar(p.disguiseAvatarId).name)
                    : displayPlayerName(p.name, p.avatarId),
                })),
            ]}
            // [NEW FEATURE] Dead bodies, live - this is what lets a kill
            // actually be "seen on camera": no special kill broadcast to
            // watch for, just the same deadBodies state every other part
            // of the game already uses, projected onto whichever
            // camera's view it happens to fall within.
            bodies={Object.entries(deadBodies).map(([id, b]) => ({ id, x: b.x, y: b.y, avatarId: b.avatarId }))}
          />
        </div>
      )}

      {showMission && nearTask && nearTask.room === 'shields' && (
        <div style={{
          position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.78)',
          display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 30, padding: 16,
        }}>
          <ExchangeSwapMission
            wallet={wallet}
            stakePosition={stakePosition}
            confidentialMode={confidentialMode}
            onSwap={handleSwapComplete}
            onClose={() => setShowMission(false)}
          />
        </div>
      )}

      {showMission && nearTask && nearTask.room === 'reactor' && (
        <div style={{
          position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.78)',
          display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 30, padding: 16,
        }}>
          <ConfidentialVaultMission
            confidentialMode={confidentialMode}
            onActivate={handleActivateConfidential}
            onClose={() => setShowMission(false)}
          />
        </div>
      )}

      {showMission && nearTask && nearTask.room === 'upper_eng' && (
        <div style={{
          position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.78)',
          display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 30, padding: 16,
        }}>
          <StakeVaultMission
            wallet={wallet}
            stakePosition={stakePosition}
            confidentialMode={confidentialMode}
            onStake={handleStake}
            onUnstake={handleUnstake}
            onClose={() => setShowMission(false)}
          />
        </div>
      )}

      {showMission && nearTask && nearTask.room === 'lower_eng' && (
        <div style={{
          position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.78)',
          display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 30, padding: 16,
        }}>
          <ClaimVaultMission
            wallet={wallet}
            stakePosition={stakePosition}
            onClaim={handleClaim}
            onClose={() => setShowMission(false)}
          />
        </div>
      )}

      {showMission && nearTask && nearTask.room === 'comms' && (
        <div style={{
          position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.78)',
          display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 30, padding: 16,
        }}>
          <MerchStoreMission
            wallet={wallet}
            onPurchase={(totalNear) => {
              setWallet(w => ({ ...w, NEAR: w.NEAR - totalNear }));
              completeMission('comms');
            }}
            onClose={() => setShowMission(false)}
          />
        </div>
      )}

      {showMission && nearTask && nearTask.room === 'electrical' && (
        <div style={{
          position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.78)',
          display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 30, padding: 16,
        }}>
          <ElectricalRepairMission
            onRepaired={() => {
              setPowerSabotaged(false);
              completeMission('electrical');
              setShowMission(false);
              // [BUG FIX] Tell the server this got fixed, so the SERVER
              // broadcasts it to every other player too — previously
              // this only ever updated our own local state, leaving
              // everyone else stuck in the dark until they each
              // personally repaired their own local copy of it too.
              socketRef.current?.emit('repairSabotage', { type: 'electricity' });
            }}
            onClose={() => setShowMission(false)}
          />
        </div>
      )}

      {showMission && nearTask && nearTask.room === 'storage' && (
        <div style={{
          position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.78)',
          display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 30, padding: 16,
        }}>
          <NearAIChatMission
            confidentialMode={confidentialMode}
            onComplete={() => { completeMission('storage'); setLegionDone(d => d.nearAi ? d : { ...d, nearAi: true }); }}
            onClose={() => setShowMission(false)}
          />
        </div>
      )}

      {showMission && nearTask && nearTask.room === 'admin' && (
        <div style={{
          position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.78)',
          display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 30, padding: 16,
        }}>
          <LegionHubMission
            sbtMinted={sbtMinted}
            onMinted={() => {
              setSbtMinted(true);
              setWallet(w => ({ ...w, NEAR: w.NEAR - SBT_MINT_FEE_NEAR }));
            }}
            wallet={wallet}
            legionDone={legionDone}
            legionClaimed={legionClaimed}
            onClaim={handleLegionClaim}
            onClose={() => setShowMission(false)}
          />
        </div>
      )}

      {showMission && nearTask && nearTask.room === 'navigation' && (
        <div style={{
          position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.78)',
          display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 30, padding: 16,
        }}>
          <CyberDefenseMission
            onResolved={() => {
              setHackerAttack(false);
              completeMission('navigation');
              setShowMission(false);
              // [BUG FIX] Same fix as the electrical repair above - tell
              // the server so it broadcasts to everyone else too.
              socketRef.current?.emit('repairSabotage', { type: 'hacker' });
            }}
            onClose={() => setShowMission(false)}
          />
        </div>
      )}

      {showMission && nearTask && nearTask.room === 'o2' && (
        <div style={{
          position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.78)',
          display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 30, padding: 16,
        }}>
          <IronClawMission
            wallet={wallet}
            onPlanSelected={(priceNear) => setWallet(w => ({ ...w, NEAR: w.NEAR - priceNear }))}
            onComplete={() => { completeMission('o2'); setShowMission(false); }}
            onClose={() => setShowMission(false)}
          />
        </div>
      )}

      {showMission && nearTask && nearTask.room === 'weapons' && (
        <div style={{
          position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.78)',
          display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 30, padding: 16,
        }}>
          <MemeMarketMission
            wallet={wallet}
            memeWallet={memeWallet}
            missionTarget={memeMission}
            onBuy={handleMemeBuy}
            onSwapBack={handleMemeSwapBack}
            onClose={() => setShowMission(false)}
          />
        </div>
      )}

      {showMission && nearTask && nearTask.room !== 'medbay' && nearTask.room !== 'security' && nearTask.room !== 'shields' && nearTask.room !== 'reactor' && nearTask.room !== 'upper_eng' && nearTask.room !== 'lower_eng' && nearTask.room !== 'comms' && nearTask.room !== 'electrical' && nearTask.room !== 'storage' && nearTask.room !== 'admin' && nearTask.room !== 'navigation' && nearTask.room !== 'o2' && nearTask.room !== 'weapons' && (
        <div style={{
          position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.78)',
          display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 30, padding: 16,
        }}>
          <div style={{
            padding: '18px 18px 16px', background: 'linear-gradient(160deg, #11141a, #0a0a0f)',
            border: '1px solid rgba(110,255,192,0.25)', borderRadius: 16, maxWidth: 320, width: '100%',
            textAlign: 'center', boxShadow: '0 0 30px rgba(110,255,192,0.08)',
          }}>
            <p style={{ marginBottom: 16, fontSize: 13.5, color: '#dfe2ea', lineHeight: 1.5 }}>
              {nearTask.room === 'cafeteria'
                ? '🚨 Emergency Meeting — call all Agents to discuss & vote (Phase 5)'
                : <>🔧 <strong>{ROOM_NAME_OVERRIDE[nearTask.room] || currentRoom?.name}</strong> mission (Phase 2)</>}
            </p>
            <button onClick={() => {
              if (nearTask.room !== 'cafeteria') completeMission(nearTask.room);
              setShowMission(false);
            }} style={{
              background: 'transparent', color: '#6effc0', border: '1px solid rgba(110,255,192,0.3)',
              borderRadius: 10, padding: '9px 22px', fontSize: 13, fontWeight: 600,
            }}>Close</button>
          </div>
        </div>
      )}

      {/* [MULTIPLAYER] Ghost indicator — shows once this player has died
          (killed or voted out), as a small persistent badge so it's
          always clear why kill/sabotage/report/chat/vote controls have
          disappeared. Movement itself keeps working as a ghost; only
          other ghosts can see us move (server-side rule), and chat/vote
          are read-only (enforced both client and server side). */}
      {!myAlive && (
        <div style={{
          position: 'absolute', top: 14, left: '50%', transform: 'translateX(-50%)', zIndex: 25,
          background: 'rgba(20,20,30,0.85)', border: '1px solid rgba(255,255,255,0.2)',
          borderRadius: 999, padding: '5px 14px', fontSize: 11, fontWeight: 700,
          color: '#cfd2da', pointerEvents: 'none',
        }}>👻 You are a ghost</div>
      )}

      {/* [NEW FEATURE] Shared crew mission-progress meter - visible to
          EVERY player regardless of role (crewmate, Saboteur, ghost),
          driven live by the server's crewProgressUpdated broadcast.
          [BUG FIX] Was previously a full-width strip that overlapped the
          centered "Enter Vent" prompt (and anything else near top-
          center) - now a small, compact tracker-style widget tucked in
          the top-left under the main HUD pill, well under half the
          screen's width, with a lower z-index than the Enter Vent button
          so it can never visually win an overlap even in edge cases on
          very narrow screens. */}
      {crewProgress.total > 0 && (
        <div style={{
          position: 'absolute', top: 44, left: 8, zIndex: 13, width: 108,
          background: 'rgba(8,8,13,0.85)', border: '1px solid rgba(110,255,192,0.22)',
          borderRadius: 9, padding: '6px 8px', backdropFilter: 'blur(3px)',
          boxShadow: '0 2px 10px rgba(0,0,0,0.4)', pointerEvents: 'none',
        }}>
          <div style={{
            display: 'flex', alignItems: 'center', gap: 4, marginBottom: 5,
          }}>
            <svg width="10" height="10" viewBox="0 0 24 24" fill="none" style={{ flexShrink: 0 }}>
              <rect x="5" y="3" width="14" height="18" rx="2" stroke="#6effc0" strokeWidth="2" />
              <path d="M9 11l2.2 2.2L15.5 9" stroke="#6effc0" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
              <path d="M9 17h6" stroke="#6effc0" strokeWidth="1.6" strokeLinecap="round" />
            </svg>
            <span style={{
              fontSize: 7.5, fontWeight: 800, color: '#9aa0ad', letterSpacing: 0.4,
              whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis',
            }}>CREW TASKS</span>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
            <div style={{
              flex: 1, height: 5, borderRadius: 3, background: 'rgba(255,255,255,0.1)', overflow: 'hidden',
            }}>
              <div style={{
                width: `${crewProgress.percent}%`, height: '100%', borderRadius: 3,
                background: 'linear-gradient(90deg, #6effc0, #2bb88a)',
                transition: 'width 0.4s ease',
              }} />
            </div>
            <span style={{ fontSize: 10, fontWeight: 800, color: '#6effc0', flexShrink: 0 }}>
              {crewProgress.percent}%
            </span>
          </div>
        </div>
      )}

      {/* [DISCUSSION COOLDOWN] Brief toast shown when a meeting can't be
          called yet — fades on its own after 2.5s (see the setTimeout in
          the meetingError handler). */}

      {meetingCooldownNotice !== null && (
        <div style={{
          position: 'absolute', top: 80, left: '50%', transform: 'translateX(-50%)', zIndex: 25,
          background: 'rgba(255,92,92,0.18)', border: '1px solid rgba(255,92,92,0.5)',
          borderRadius: 999, padding: '5px 14px', fontSize: 11, fontWeight: 700,
          color: '#ff8a8a', pointerEvents: 'none',
        }}>⏳ Discussion on cooldown — {meetingCooldownNotice}s</div>
      )}

      {/* [NEW FEATURE] Task-reminder popup - slides down from the very
          top, only on the inactive player's own screen, every 3 minutes
          they've gone without finishing a mission (see the taskReminder
          socket handler). Deliberately bold/high-contrast and animated
          in rather than a quiet toast - meant to be genuinely hard to
          miss, per Om7eth's explicit request that players were ignoring
          softer notices. Auto-dismisses after 5s on its own. */}
      {showTaskReminder && !meeting && (
        <div key={taskReminderKey} style={{
          position: 'absolute', top: 0, left: 0, right: 0, zIndex: 90,
          display: 'flex', justifyContent: 'center', pointerEvents: 'none',
          animation: 'taskReminderSlideDown 0.4s ease-out',
        }}>
          <div style={{
            marginTop: 14, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 3,
            background: 'linear-gradient(135deg,#ffc14c,#ff9f3c)', color: '#1a0f00',
            borderRadius: 14, padding: '10px 18px', boxShadow: '0 6px 20px rgba(0,0,0,0.4)',
            maxWidth: '86%',
          }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8, fontWeight: 800, fontSize: 12.5 }}>
              <span style={{ fontSize: 18 }}>⚠️</span>
              Don't forget to finish your missions!
            </div>
            {/* [UPDATE] Spells out exactly where they stand - which
                warning this is, how many they get, what happens if they
                run out (removed from the game, NOT killed - an explicit
                distinction Om7eth wanted made clear), and how often this
                check happens. */}
            <p style={{ fontSize: 10.5, fontWeight: 700, margin: 0, textAlign: 'center', opacity: 0.85 }}>
              Warning {taskReminderInfo.strikeNumber} of {taskReminderInfo.maxStrikes} - miss all {taskReminderInfo.maxStrikes} and you'll be removed from the game (not killed). Checked every {Math.round(taskReminderInfo.intervalMs / 60000)} min.
            </p>
          </div>
        </div>
      )}

      {/* [NEW FEATURE] Saboteur kill-timer alert - only this Saboteur's
          own screen ever receives the underlying socket event (see
          saboteurKillAlarm above), same slide-down pattern as the
          crewmate task-reminder but in red to read as a genuine threat
          rather than a gentle nudge. Auto-dismisses after 5s. */}
      {showSaboteurAlarm && !meeting && (
        <div key={saboteurAlarmKey} style={{
          position: 'absolute', top: 0, left: 0, right: 0, zIndex: 90,
          display: 'flex', justifyContent: 'center', pointerEvents: 'none',
          animation: 'taskReminderSlideDown 0.4s ease-out',
        }}>
          <div style={{
            marginTop: 14, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 3,
            background: 'linear-gradient(135deg,#ff5c5c,#c92f2f)', color: '#fff',
            borderRadius: 14, padding: '10px 18px', boxShadow: '0 6px 20px rgba(0,0,0,0.4)',
            maxWidth: '86%',
          }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8, fontWeight: 800, fontSize: 12.5 }}>
              <span style={{ fontSize: 18 }}>🔪</span>
              Kill someone soon, or you'll be eliminated!
            </div>
            {/* [UPDATE] Spells out exactly how much time is left until
                the 7-minute deadline. */}
            {typeof saboteurAlarmInfo.remainingMs === 'number' && (
              <p style={{ fontSize: 10.5, fontWeight: 700, margin: 0, textAlign: 'center', opacity: 0.9 }}>
                You must kill within 7 minutes of the game starting, or you'll be eliminated. Time left: {Math.floor(saboteurAlarmInfo.remainingMs / 60000)}:{String(Math.floor((saboteurAlarmInfo.remainingMs % 60000) / 1000)).padStart(2, '0')}
              </p>
            )}
          </div>
        </div>
      )}

      {/* [NEW FEATURE] Final-minute countdown - persistent (not auto-
          dismissing like the alert above) for as long as
          saboteurCountdownMs is non-null, ticking down locally once per
          second (see the effect that owns this state). Pulses to keep
          reading as urgent the whole time it's up, not just when it
          first appears. */}
      {saboteurCountdownMs !== null && !meeting && (
        <div style={{
          position: 'absolute', top: 14, left: '50%', transform: 'translateX(-50%)', zIndex: 91,
          display: 'flex', alignItems: 'center', gap: 8,
          background: 'rgba(201,47,47,0.92)', color: '#fff', borderRadius: 999,
          padding: '7px 16px', boxShadow: '0 6px 20px rgba(0,0,0,0.5)',
          fontWeight: 800, fontSize: 13, animation: 'saboteurCountdownPulse 1s ease-in-out infinite',
        }}>
          <span style={{ fontSize: 16 }}>⏱️</span>
          Kill or be eliminated: {Math.floor(saboteurCountdownMs / 60000)}:{String(Math.floor((saboteurCountdownMs % 60000) / 1000)).padStart(2, '0')}
        </div>
      )}
      <style>{`
        @keyframes taskReminderSlideDown {
          0% { transform: translateY(-100%); opacity: 0; }
          100% { transform: translateY(0); opacity: 1; }
        }
        @keyframes saboteurCountdownPulse {
          0%, 100% { transform: translateX(-50%) scale(1); }
          50% { transform: translateX(-50%) scale(1.04); }
        }
      `}</style>

      {/* Bottom-right: Saboteur panel (top, role-gated) + Mission Tracker +
          Wallet, stacked vertically. Kept as small icon buttons so they
          don't eat into the play area. */}
      <div style={{
        position: 'absolute', bottom: 36, right: 12, zIndex: 20,
        display: 'flex', flexDirection: 'column', gap: 8,
      }}>
        {/* Saboteur-only action panel — invisible to crewmates entirely.
            [MULTIPLAYER] Also hidden once dead (a ghost Saboteur can't
            sabotage anymore — see triggerSabotageAction's myAlive guard). */}
        {playerRole === 'saboteur' && myAlive && (
          <button onClick={() => setShowSaboteurPanel(true)} aria-label="Saboteur actions" style={{
            width: 44, height: 44, borderRadius: 12, border: '1px solid rgba(255,85,85,0.45)',
            background: 'rgba(30,8,8,0.88)', color: '#ff5c5c', fontSize: 18,
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            boxShadow: '0 2px 10px rgba(255,85,85,0.25)', position: 'relative',
          }}>
            <SaboteurIcon size={20} color="#ff5c5c" />
            {sabotageCooldownSecLeft > 0 && (
              <span style={{
                position: 'absolute', top: -3, right: -3, minWidth: 16, height: 16, borderRadius: 8,
                background: 'rgba(0,0,0,0.85)', color: '#ff5c5c', fontSize: 8.5, fontWeight: 700,
                display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '0 3px',
                border: '1px solid rgba(255,85,85,0.5)',
              }}>{sabotageCooldownSecLeft}</span>
            )}
            {disguiseActive && (
              <span style={{
                position: 'absolute', bottom: -3, right: -3, minWidth: 16, height: 16, borderRadius: 8,
                background: '#6effc0', color: '#06140d', fontSize: 8.5, fontWeight: 700,
                display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '0 3px',
                border: '1px solid rgba(0,0,0,0.4)',
              }}>{disguiseSecLeft}</span>
            )}
          </button>
        )}
        {playerRole === 'crewmate' && (
        <button onClick={() => setShowMissionTracker(true)} aria-label="Missions" style={{
          width: 44, height: 44, borderRadius: 12, border: '1px solid rgba(110,255,192,0.3)',
          background: 'rgba(8,8,13,0.85)', color: '#6effc0', fontSize: 18,
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          boxShadow: '0 2px 10px rgba(0,0,0,0.4)', position: 'relative',
        }}>
          📋
          {myMissions.some(m => !m.done) && (
            <span style={{
              position: 'absolute', top: -3, right: -3, minWidth: 16, height: 16, borderRadius: 8,
              background: '#ff6b6b', color: '#fff', fontSize: 9, fontWeight: 700,
              display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '0 3px',
            }}>{myMissions.filter(m => !m.done).length}</span>
          )}
        </button>
        )}
        <button onClick={() => setShowWallet(true)} aria-label="Wallet" style={{
          width: 44, height: 44, borderRadius: 12, border: '1px solid rgba(110,255,192,0.3)',
          background: 'rgba(8,8,13,0.85)', color: '#6effc0', fontSize: 18,
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          boxShadow: '0 2px 10px rgba(0,0,0,0.4)',
        }}>
          <span style={{
            position: 'relative', width: 22, height: 16, borderRadius: 4,
            border: '1.6px solid #6effc0', boxSizing: 'border-box',
          }}>
            <span style={{
              position: 'absolute', top: 4.5, left: 0, right: 0, height: 1.6, background: '#6effc0',
            }} />
            <span style={{
              position: 'absolute', right: 2, bottom: 2, width: 5, height: 3.5, borderRadius: 1,
              background: '#6effc0',
            }} />
          </span>
        </button>
      </div>

      {/* Saboteur action panel popup — 5 actions total: the original 4
          sabotage actions (sharing one 20s cooldown, each with its own
          lifetime usage cap), plus Disguise (its own independent 30s
          cooldown, 3 lifetime uses). For 20s after any kill, the 4
          sabotage actions are entirely locked out — only Disguise stays
          usable during that window. */}
      {showSaboteurPanel && (
        <div style={{
          position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.78)',
          display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 50, padding: 16,
        }} onClick={() => setShowSaboteurPanel(false)}>
          <div onClick={e => e.stopPropagation()} style={{
            padding: '16px 16px 14px', background: 'linear-gradient(160deg, #1c0808, #0a0404)',
            border: '1px solid rgba(255,85,85,0.35)', borderRadius: 16, maxWidth: 300, width: '100%',
            boxShadow: '0 0 30px rgba(255,85,85,0.12)',
          }}>
            <h2 style={{
              fontSize: 13, fontWeight: 800, color: '#ff5c5c', margin: '0 0 2px',
              display: 'flex', alignItems: 'center', gap: 6,
            }}><SaboteurIcon size={16} color="#ff5c5c" /> Saboteur Actions</h2>
            <p style={{ fontSize: 10, color: '#a07a7a', margin: '0 0 4px' }}>
              Using any sabotage action locks all 4 for 20s — choose carefully.
            </p>
            {postKillLockSecLeft > 0 && (
              <p style={{ fontSize: 11, color: '#ff8a3c', fontWeight: 700, margin: '0 0 4px' }}>
                🔒 Post-kill lockdown: {postKillLockSecLeft}s (sabotage actions disabled)
              </p>
            )}
            {sabotageCooldownSecLeft > 0 && (
              <p style={{ fontSize: 11, color: '#ff5c5c', fontWeight: 700, margin: '0 0 12px' }}>
                ⏱ Cooldown: {sabotageCooldownSecLeft}s
              </p>
            )}
            {sabotageCooldownSecLeft <= 0 && postKillLockSecLeft <= 0 && <div style={{ marginBottom: 12 }} />}

            {[
              { key: 'power', icon: '⚡', label: 'Cut Electricity', active: powerSabotaged },
              { key: 'hacker', icon: '🛡', label: 'Trigger Hacker Attack', active: hackerAttack },
              { key: 'gateLeft', icon: '🔒', label: 'Lock Gates — Left', active: gateLock.group === 'A' },
              { key: 'gateRight', icon: '🔒', label: 'Lock Gates — Right', active: gateLock.group === 'B' },
            ].map(action => {
              const usesLeft = sabotageUsesLeft[action.key];
              const onCooldown = sabotageCooldownSecLeft > 0;
              const lockedOut = postKillLockSecLeft > 0;
              const noUses = usesLeft <= 0;
              const gateConflict = (action.key === 'gateLeft' || action.key === 'gateRight') && gateLock.group && !action.active;
              const disabled = action.active || onCooldown || lockedOut || noUses || gateConflict;
              return (
                <button
                  key={action.key}
                  onClick={() => { if (!disabled) triggerSabotageAction(action.key); }}
                  disabled={disabled}
                  style={{
                    width: '100%', padding: '10px 0', borderRadius: 10, border: 'none', marginBottom: 8,
                    background: disabled ? 'rgba(255,255,255,0.06)' : 'rgba(255,85,85,0.18)',
                    color: disabled ? '#5a5a5a' : '#ff7a7a', fontWeight: 700, fontSize: 13,
                    display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 7,
                  }}
                >
                  <span>{action.icon} {action.active ? `${action.label} (active)` : action.label}</span>
                  <span style={{
                    fontSize: 9.5, fontWeight: 700, padding: '2px 6px', borderRadius: 999,
                    background: 'rgba(0,0,0,0.3)', color: disabled ? '#5a5a5a' : '#ffb4b4',
                  }}>{usesLeft} left</span>
                </button>
              );
            })}

            <div style={{ borderTop: '1px solid rgba(255,255,255,0.1)', margin: '6px 0 10px' }} />

            {/* Disguise — deliberately separate from the 4 actions above:
                its own 30s cooldown, exempt from the post-kill lockdown,
                and doesn't get blocked by sabotageCooldownSecLeft either.
                Clicking opens an avatar-choice screen instead of picking
                randomly; the button itself shows a live countdown once
                a disguise is active. */}
            {(() => {
              const disguiseOnCooldown = disguiseCooldownSecLeft > 0;
              const disguiseNoUses = disguiseUsesLeft <= 0;
              const disguiseDisabled = !!disguiseActive || disguiseOnCooldown || disguiseNoUses;
              return (
                <button
                  onClick={() => { if (!disguiseDisabled) setShowDisguisePicker(true); }}
                  disabled={disguiseDisabled}
                  style={{
                    width: '100%', padding: '10px 0', borderRadius: 10, border: 'none', marginBottom: 8,
                    background: disguiseActive ? 'rgba(110,255,192,0.28)' : disguiseDisabled ? 'rgba(255,255,255,0.06)' : 'rgba(110,255,192,0.16)',
                    color: disguiseDisabled && !disguiseActive ? '#5a5a5a' : '#6effc0', fontWeight: 700, fontSize: 13,
                    display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 7,
                  }}
                >
                  <span>
                    🎭 {disguiseActive ? `Disguised — ${disguiseSecLeft}s left` : disguiseOnCooldown ? `Disguise — ${disguiseCooldownSecLeft}s` : 'Disguise (15s)'}
                  </span>
                  <span style={{
                    fontSize: 9.5, fontWeight: 700, padding: '2px 6px', borderRadius: 999,
                    background: 'rgba(0,0,0,0.3)', color: disguiseDisabled && !disguiseActive ? '#5a5a5a' : '#a8ffda',
                  }}>{disguiseUsesLeft} left</span>
                </button>
              );
            })()}

            <button onClick={() => setShowSaboteurPanel(false)} style={{
              width: '100%', padding: '9px 0', borderRadius: 10,
              background: 'transparent', color: '#9aa0ad', border: '1px solid rgba(255,255,255,0.15)',
              fontSize: 12.5, fontWeight: 600, marginTop: 2,
            }}>Close</button>
          </div>
        </div>
      )}

      {/* Disguise avatar picker — opens when the Saboteur taps Disguise in
          the panel above. Shows every avatar except their own real one;
          tapping a choice immediately starts the 15s disguise as that
          avatar and closes both this picker and the Saboteur panel. */}
      {showDisguisePicker && (
        <div style={{
          position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.82)',
          display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 55, padding: 16,
        }} onClick={() => setShowDisguisePicker(false)}>
          <div onClick={e => e.stopPropagation()} style={{
            padding: '16px 16px 14px', background: 'linear-gradient(160deg, #0d1a14, #05100b)',
            border: '1px solid rgba(110,255,192,0.3)', borderRadius: 16, maxWidth: 300, width: '100%',
            boxShadow: '0 0 30px rgba(110,255,192,0.12)',
          }}>
            <h2 style={{
              fontSize: 13, fontWeight: 800, color: '#6effc0', margin: '0 0 4px',
              display: 'flex', alignItems: 'center', gap: 6,
            }}>🎭 Choose a Disguise</h2>
            <p style={{ fontSize: 10, color: '#7a9a8a', margin: '0 0 12px' }}>
              You'll appear as this avatar to everyone for 15 seconds.
            </p>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', gap: 8, marginBottom: 14 }}>
              {AVATARS.filter(a => a.id !== playerAvatarId).map(a => (
                <button
                  key={a.id}
                  onClick={() => {
                    triggerDisguise(a.id);
                    setShowDisguisePicker(false);
                    setShowSaboteurPanel(false);
                  }}
                  style={{
                    display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 3,
                    padding: '6px 2px', borderRadius: 9,
                    background: 'rgba(110,255,192,0.08)', border: '1px solid rgba(110,255,192,0.18)',
                  }}
                >
                  <img src={a.img} alt="" style={{ width: 28, height: 'auto', display: 'block' }} />
                  <span style={{ fontSize: 8, color: '#9aa0ad' }}>{a.name}</span>
                </button>
              ))}
            </div>
            <button onClick={() => setShowDisguisePicker(false)} style={{
              width: '100%', padding: '9px 0', borderRadius: 10,
              background: 'transparent', color: '#9aa0ad', border: '1px solid rgba(255,255,255,0.15)',
              fontSize: 12.5, fontWeight: 600,
            }}>Cancel</button>
          </div>
        </div>
      )}

      {/* ═══════════════════════════════════════════════════════════════
          EMERGENCY MEETING — alarm -> chat -> voting -> results.
          [MULTIPLAYER: SHARED] See the `meeting` state declaration above
          for the full multiplayer-readiness note. Everything here renders
          for this one real player; a real backend would broadcast the
          same stages/timing to everyone in the room simultaneously.
          ═══════════════════════════════════════════════════════════════ */}

      {/* Stage 1: Alarm — full-screen red flash + siren-style pulsing,
          3 seconds, before everyone gets pulled into the chat. */}
      {meeting && meeting.stage === 'alarm' && (
        <div style={{
          position: 'absolute', inset: 0, zIndex: 65, background: '#1a0303',
          display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
          animation: 'meetingAlarmFlash 0.5s ease-in-out infinite',
        }}>
          {/* [UPDATE] Complete redesign for the report case, per exact
              spec - the dead player's own avatar IS the centerpiece now
              (replacing the generic siren emoji), moderately sized (not
              huge), with who reported them folded into the message line
              right below it instead of being a separate row. A self-
              called meeting (no specific body) keeps the original siren
              look, since there's no one specific player to center on. */}
          {meeting.calledByReason === 'report' && meeting.reportedBody ? (
            <>
              <img
                src={getAvatar(meeting.reportedBody.avatarId).img} alt=""
                style={{ width: 76, height: 'auto', filter: 'drop-shadow(0 4px 14px rgba(255,80,80,0.5))', marginBottom: 10 }}
              />
              <h2 style={{ fontSize: 16, fontWeight: 800, color: '#ff5c5c', margin: '0 0 6px', letterSpacing: 0.5, textAlign: 'center' }}>
                {displayPlayerName(meeting.reportedBody.name, meeting.reportedBody.avatarId)} was found dead
              </h2>
              <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                <img src={getAvatar(meeting.callerAvatarId).img} alt="" style={{ width: 20, height: 'auto' }} />
                <p style={{ fontSize: 12, color: '#ffb4b4', margin: 0, fontWeight: 600 }}>
                  Reported by <span style={{ fontWeight: 800, color: '#fff' }}>{displayPlayerName(meeting.callerName, meeting.callerAvatarId)}</span>
                </p>
              </div>
            </>
          ) : (
            <>
              <div style={{ fontSize: 46, marginBottom: 10 }}>🚨</div>
              <h2 style={{ fontSize: 18, fontWeight: 800, color: '#ff5c5c', margin: '0 0 6px', letterSpacing: 1 }}>
                EMERGENCY MEETING
              </h2>
              <p style={{ fontSize: 12.5, color: '#ffb4b4', margin: 0, fontWeight: 600 }}>Meeting called</p>
            </>
          )}
        </div>
      )}
      <style>{`
        @keyframes meetingAlarmFlash {
          0%, 100% { background: #1a0303; }
          50% { background: #3a0808; }
        }
      `}</style>

      {/* Stage 2: Chat — message list + input + countdown. Other
          players' messages can't appear without a backend actually
          relaying them, so solo-test only ever shows this one player's
          own sent messages; a small note says so rather than pretending
          otherwise. */}
      {meeting && meeting.stage === 'chat' && (
        <div style={{
          position: 'absolute', inset: 0, zIndex: 65, background: '#0a0a0f',
          display: 'flex', flexDirection: 'column',
        }}>
          <div style={{
            padding: '14px 16px 10px', borderBottom: '1px solid rgba(255,255,255,0.08)',
            display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexShrink: 0,
          }}>
            <div>
              <h2 style={{ fontSize: 14, fontWeight: 800, color: '#fff', margin: '0 0 2px' }}>💬 Discussion</h2>
              <p style={{ fontSize: 10, color: '#7a8a86', margin: 0 }}>
                {meeting.calledByReason === 'report' ? 'A body was reported' : 'Emergency meeting called'}
              </p>
            </div>
            <MeetingCountdown startedAt={meeting.startedAt} durationMs={MEETING_CHAT_DURATION_MS} />
          </div>

          {/* [NEW FEATURE] Player status badges - every alive AND dead
              player shown at a glance right under the header, reusing
              the SAME card visuals as the voting screen (cross overlay
              on dead avatars, megaphone icon on whoever called this
              meeting) but here it's read-only - no tapping/voting
              during chat. Whichever player was JUST found dead by this
              specific report (not anyone who was already dead before
              this meeting) plays a brief cross-draws-in + fade
              animation the moment chat opens, so it's obvious who's
              new versus who was already known. */}
          {(() => {
            const myId = socketRef.current?.id;
            const badgeCards = [
              { id: myId, name: displayPlayerName(playerName, playerAvatarId), avatarId: playerAvatarId, isDead: !myAlive },
              ...Object.entries(otherPlayers).map(([id, p]) => ({
                // [BUG FIX] Same disguise-leak fix as the CCTV/voting
                // screens - was showing the real name even while
                // disguised.
                id, name: p.disguiseAvatarId
                  ? (roomInfo?.players?.find((rp) => rp.avatarId === p.disguiseAvatarId)?.name || getAvatar(p.disguiseAvatarId).name)
                  : displayPlayerName(p.name, p.avatarId),
                avatarId: p.disguiseAvatarId || p.avatarId,
                isDead: p.alive === false,
              })),
            ];
            return (
              <div style={{ display: 'flex', gap: 10, overflowX: 'auto', padding: '10px 14px 2px', flexShrink: 0 }}>
                {badgeCards.map((card) => {
                  const isNewlyDead = card.isDead && meeting.calledByReason === 'report'
                    && meeting.reportedBody && card.id === meeting.reportedBody.id;
                  return (
                    <div key={card.id} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', width: 40, flexShrink: 0, gap: 2 }}>
                      <div style={{ position: 'relative', width: 28, height: 28 }}>
                        <img src={getAvatar(card.avatarId).img} alt="" style={{
                          width: '100%', height: '100%', objectFit: 'contain',
                          opacity: card.isDead ? 0.5 : 1,
                          animation: isNewlyDead ? 'chatBadgeDeathFade 0.6s ease-out' : undefined,
                        }} />
                        {card.isDead && (
                          <svg viewBox="0 0 24 24" style={{
                            position: 'absolute', inset: 0,
                            animation: isNewlyDead ? 'chatBadgeCrossIn 0.5s ease-out' : undefined,
                          }}>
                            <line x1="3" y1="3" x2="21" y2="21" stroke="#ff5c5c" strokeWidth="2.5" />
                            <line x1="21" y1="3" x2="3" y2="21" stroke="#ff5c5c" strokeWidth="2.5" />
                          </svg>
                        )}
                        {card.id === meeting.calledByPlayerId && (
                          <div style={{
                            position: 'absolute', top: -3, right: -6, width: 13, height: 10,
                            background: '#ffc14c',
                            clipPath: 'polygon(0% 30%, 40% 30%, 100% 0%, 100% 100%, 40% 70%, 0% 70%)',
                          }} title="Called this meeting" />
                        )}
                      </div>
                      <span style={{
                        fontSize: 8, fontWeight: 700, color: card.isDead ? '#8a9490' : '#e8eaf0',
                        overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', maxWidth: '100%',
                      }}>{card.name}</span>
                    </div>
                  );
                })}
                <style>{`
                  @keyframes chatBadgeCrossIn { 0% { opacity: 0; } 100% { opacity: 1; } }
                  @keyframes chatBadgeDeathFade { 0% { opacity: 1; } 100% { opacity: 0.5; } }
                `}</style>
              </div>
            );
          })()}

          {/* [DEATH ANNOUNCEMENT] Lists every player known to be dead so
              far, right under the header — same as Among Us announcing
              every death (not just whichever specific body triggered
              this meeting) the moment a meeting starts. */}
          {meeting.deadPlayerNames && meeting.deadPlayerNames.length > 0 && (
            <div style={{
              margin: '8px 14px 0', padding: '8px 12px', borderRadius: 10,
              background: 'rgba(255,92,92,0.1)', border: '1px solid rgba(255,92,92,0.3)',
              fontSize: 11.5, color: '#ff8a8a', flexShrink: 0,
            }}>
              💀 {meeting.deadPlayerNames.length === 1
                ? `${meeting.deadPlayerNames[0]}'s body was found.`
                : `Bodies found: ${meeting.deadPlayerNames.join(', ')}.`}
            </div>
          )}

          {/* [UPDATE] Redesigned - now that the player-badge row sits
              right above this, the old plain text button blended in and
              was easy to miss/ignore (Om7eth's explicit feedback). Now
              a clearly pill-shaped, icon-led button with its own row,
              and the copy spells out exactly what it does and the
              current progress toward the (now 60%, was 50% then 80%) threshold -
              see voteSkipDiscussion on the backend. */}
          {myAlive && (
            <div style={{ padding: '6px 14px 0', flexShrink: 0 }}>
              <button
                onClick={() => {
                  socketRef.current?.emit('voteSkipDiscussion');
                  setMeeting((m) => m && { ...m, iVotedSkip: true });
                }}
                disabled={meeting.iVotedSkip}
                style={{
                  width: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8,
                  padding: '10px 0', borderRadius: 999, border: '1.5px solid rgba(255,193,76,0.55)',
                  background: meeting.iVotedSkip ? 'rgba(255,193,76,0.1)' : 'rgba(255,193,76,0.2)',
                  color: '#ffc14c', fontSize: 12, fontWeight: 800,
                }}
              >
                <span style={{ fontSize: 15 }}>⏭️</span>
                {meeting.iVotedSkip
                  ? `Waiting for others to skip… (${meeting.skipVoteCount || 0}/${meeting.skipVoteTotal || '?'})`
                  : 'Skip Discussion, Go to Voting (needs 60%)'}
              </button>
            </div>
          )}

          <div ref={chatScrollRef} style={{ flex: 1, overflowY: 'auto', padding: '12px 14px', display: 'flex', flexDirection: 'column', gap: 10 }}>
            {meeting.messages.length === 0 && (
              <p style={{ fontSize: 11, color: '#5f6b67', textAlign: 'center', marginTop: 30 }}>
                No messages yet. Say something to start the discussion.
              </p>
            )}
            {meeting.messages.map(msg => {
              // [NEW FEATURE] ALL-CAPS messages get a distinct highlighted
              // treatment (gold border/glow, bold text) so they visually
              // stand out in the chat, same idea as "shouting" in most
              // chat apps.
              const shouting = isAllCapsMessage(msg.text);
              return (
              <div key={msg.id} style={{
                display: 'flex', gap: 8, alignItems: 'flex-end',
                flexDirection: msg.isSelf ? 'row-reverse' : 'row',
              }}>
                <img src={getAvatar(msg.authorAvatarId).img} alt="" style={{ width: 26, height: 26, objectFit: 'contain', flexShrink: 0 }} />
                <div style={{ maxWidth: '72%' }}>
                  <div style={{
                    fontSize: 9.5, color: '#7a8a86', marginBottom: 2,
                    textAlign: msg.isSelf ? 'right' : 'left',
                  }}>{msg.authorName}</div>
                  {/* [NEW FEATURE] Tap any message to reply to it - shows a
                      small quoted preview above the input box, same idea as
                      WhatsApp/Telegram's reply feature. */}
                  <div
                    onClick={() => myAlive && setReplyingTo({ senderName: msg.authorName, text: msg.text })}
                    style={{
                      padding: '8px 12px', borderRadius: 14, fontSize: 12.5, lineHeight: 1.35,
                      background: shouting
                        ? 'linear-gradient(135deg,#ffd75e,#e8a831)'
                        : (msg.isSelf ? 'linear-gradient(135deg,#2bb88a,#1f8a68)' : 'rgba(255,255,255,0.08)'),
                      color: shouting ? '#241a00' : (msg.isSelf ? '#06140d' : '#e8eaf0'),
                      fontWeight: shouting ? 800 : 400,
                      border: shouting ? '1px solid rgba(255,255,255,0.4)' : 'none',
                      boxShadow: shouting ? '0 0 10px rgba(255,215,94,0.5)' : 'none',
                      borderBottomRightRadius: msg.isSelf ? 4 : 14,
                      borderBottomLeftRadius: msg.isSelf ? 14 : 4,
                      cursor: myAlive ? 'pointer' : 'default',
                    }}>
                    {msg.replyTo && (
                      <div style={{
                        borderLeft: `2px solid ${msg.isSelf ? 'rgba(6,20,13,0.4)' : 'rgba(110,255,192,0.5)'}`,
                        paddingLeft: 7, marginBottom: 5, opacity: 0.8,
                      }}>
                        <div style={{ fontSize: 9.5, fontWeight: 700 }}>{msg.replyTo.senderName}</div>
                        <div style={{ fontSize: 10.5, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{msg.replyTo.text}</div>
                      </div>
                    )}
                    {msg.text}
                  </div>
                </div>
              </div>
              );
            })}
          </div>

          {/* [NEW FEATURE] Reply preview bar - shown above the input only
              while replying to a specific message, with a way to cancel it. */}
          {replyingTo && (
            <div style={{
              display: 'flex', alignItems: 'center', gap: 8, padding: '7px 14px',
              borderTop: '1px solid rgba(255,255,255,0.08)', background: 'rgba(110,255,192,0.06)',
            }}>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 9.5, color: '#6effc0', fontWeight: 700 }}>Replying to {replyingTo.senderName}</div>
                <div style={{ fontSize: 10.5, color: '#9aa0ad', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{replyingTo.text}</div>
              </div>
              <button onClick={() => setReplyingTo(null)} style={{
                background: 'none', border: 'none', color: '#9aa0ad', fontSize: 16, flexShrink: 0,
              }}>✕</button>
            </div>
          )}

          {/* Chat input — alive players use main chat, ghosts get their
              own ghost-channel input right here in the meeting screen
              (same ghost-only server channel as the standalone ghost
              chat panel, just embedded here so ghosts aren't completely
              shut out during the most important part of the game) */}
          {myAlive ? (
          <div style={{
            display: 'flex', gap: 8, padding: '10px 14px', borderTop: '1px solid rgba(255,255,255,0.08)', flexShrink: 0,
          }}>
            <input
              value={chatDraft}
              onChange={e => setChatDraft(e.target.value.slice(0, 200))}
              onKeyDown={e => { if (e.key === 'Enter') sendChatMessage(); }}
              placeholder="Type a message..."
              style={{
                flex: 1, padding: '10px 14px', borderRadius: 999, border: '1px solid rgba(255,255,255,0.15)',
                background: 'rgba(255,255,255,0.06)', color: '#fff', fontSize: 13, outline: 'none',
              }}
            />
            <button onClick={sendChatMessage} disabled={!chatDraft.trim()} style={{
              width: 42, height: 42, borderRadius: '50%', border: 'none', flexShrink: 0,
              background: chatDraft.trim() ? 'linear-gradient(135deg,#6effc0,#2bb88a)' : 'rgba(255,255,255,0.08)',
              color: chatDraft.trim() ? '#06140d' : '#5a5a5a', fontSize: 16, fontWeight: 800,
            }}>↑</button>
          </div>
          ) : (
          /* Ghost chat section — same dim/translucent styling as the
             standalone ghost panel to make it visually distinct.
             Uses the same sendGhostChatMessage function and ghost
             channel so messages only ever reach other dead players. */
          <div style={{
            borderTop: '1px solid rgba(180,180,200,0.15)', flexShrink: 0,
            background: 'rgba(10,10,14,0.7)', filter: 'grayscale(0.2)',
          }}>
            <div style={{
              padding: '5px 14px 4px',
              fontSize: 10, color: 'rgba(200,200,210,0.7)', fontWeight: 700, letterSpacing: 0.3,
            }}>👻 Ghost Chat — only other ghosts can see this</div>
            {/* Ghost messages received during this meeting */}
            {ghostChatMessages.length > 0 && (
              <div style={{ maxHeight: 90, overflowY: 'auto', padding: '0 14px 4px', display: 'flex', flexDirection: 'column', gap: 6 }}>
                {ghostChatMessages.slice(-5).map(msg => (
                  <div key={msg.id} style={{
                    display: 'flex', gap: 6, alignItems: 'flex-end',
                    flexDirection: msg.isSelf ? 'row-reverse' : 'row', opacity: 0.85,
                  }}>
                    <img src={getAvatar(msg.authorAvatarId).img} alt="" style={{ width: 18, height: 18, objectFit: 'contain', flexShrink: 0, opacity: 0.7 }} />
                    <div style={{
                      padding: '5px 10px', borderRadius: 12, fontSize: 11, lineHeight: 1.35,
                      background: msg.isSelf ? 'rgba(160,160,180,0.22)' : 'rgba(255,255,255,0.06)',
                      color: 'rgba(220,220,228,0.9)',
                      borderBottomRightRadius: msg.isSelf ? 3 : 12, borderBottomLeftRadius: msg.isSelf ? 12 : 3,
                      maxWidth: '75%',
                    }}>{msg.text}</div>
                  </div>
                ))}
              </div>
            )}
            {ghostReplyingTo && (
              <div style={{ display: 'flex', alignItems: 'center', gap: 6, padding: '4px 14px', background: 'rgba(160,160,180,0.08)' }}>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: 9, color: 'rgba(200,200,210,0.9)', fontWeight: 700 }}>↩ {ghostReplyingTo.senderName}</div>
                  <div style={{ fontSize: 10, color: 'rgba(160,160,170,0.8)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{ghostReplyingTo.text}</div>
                </div>
                <button onClick={() => setGhostReplyingTo(null)} style={{ background: 'none', border: 'none', color: 'rgba(160,160,170,0.8)', fontSize: 13 }}>✕</button>
              </div>
            )}
            <div style={{ display: 'flex', gap: 7, padding: '6px 14px 10px' }}>
              <input
                value={ghostChatDraft}
                onChange={e => setGhostChatDraft(e.target.value.slice(0, 200))}
                onKeyDown={e => { if (e.key === 'Enter') sendGhostChatMessage(); }}
                placeholder="Talk to other ghosts..."
                style={{
                  flex: 1, padding: '8px 12px', borderRadius: 999,
                  border: '1px solid rgba(180,180,200,0.2)',
                  background: 'rgba(255,255,255,0.04)', color: 'rgba(225,225,232,0.9)',
                  fontSize: 12.5, outline: 'none',
                }}
              />
              <button onClick={sendGhostChatMessage} disabled={!ghostChatDraft.trim()} style={{
                width: 36, height: 36, borderRadius: '50%', border: 'none', flexShrink: 0,
                background: ghostChatDraft.trim() ? 'rgba(180,180,200,0.3)' : 'rgba(255,255,255,0.05)',
                color: 'rgba(220,220,228,0.9)', fontSize: 15, fontWeight: 800,
              }}>↑</button>
            </div>
          </div>
          )}
        </div>
      )}

      {/* [NEW FEATURE] "Discussion skipped" transition overlay - covers
          the chat screen for 1.5s once the 50% skip-threshold is
          reached, before the server actually moves the meeting to
          voting. Higher z-index than both the chat and voting screens
          (65) so it sits cleanly on top of whichever one happens to be
          rendering underneath during this brief window. */}
      {showSkipTransition && (
        <div style={{
          position: 'absolute', inset: 0, zIndex: 70, background: 'rgba(5,5,8,0.95)',
          display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 14,
        }}>
          <div style={{
            width: 36, height: 36, borderRadius: '50%',
            border: '3px solid rgba(110,255,192,0.25)', borderTopColor: '#6effc0',
            animation: 'skipSpin 0.8s linear infinite',
          }} />
          <p style={{ fontSize: 14, fontWeight: 700, color: '#cfd2da', margin: 0 }}>Discussion skipped…</p>
          <style>{`@keyframes skipSpin { to { transform: rotate(360deg); } }`}</style>
        </div>
      )}

      {/* Stage 3: Voting — every "live" player gets a tappable card
          (just this one real player for now; dead players would show
          dark/unvotable, but there are none yet in solo-test since the
          dummy never joins meetings per the current scope), plus a Skip
          Vote option. */}
      {meeting && meeting.stage === 'voting' && (
        <div style={{
          position: 'absolute', inset: 0, zIndex: 65, background: '#1a2230',
          display: 'flex', flexDirection: 'column',
        }}>
          <div style={{
            padding: '14px 16px 10px',
            display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0,
          }}>
            <h2 style={{ fontSize: 17, fontWeight: 800, color: '#fff', margin: 0 }}>Who Is The Saboteur?</h2>
          </div>

          {/* [NEW FEATURE] Grid layout (2 columns) instead of the old
              vertical list - matches the requested Among-Us-style
              voting screen layout. Every alive AND dead player (plus
              ourselves) gets a card; dead ones show dimmed with a cross
              mark, alive ones are tappable. */}
          <div style={{
            flex: 1, overflowY: 'auto', padding: 14,
            display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10, alignContent: 'start',
          }}>
            {(() => {
              const myId = socketRef.current?.id;
              // Build a unified list: ourselves + every other player,
              // each with a stable "voteKey" (their own id, used both
              // for casting votes and for matching liveVotes entries).
              const allCards = [
                { id: myId, name: displayPlayerName(playerName, playerAvatarId), avatarId: playerAvatarId, isDead: !myAlive, isMe: true },
                ...Object.entries(otherPlayers).map(([id, p]) => ({
                  // [BUG FIX] Pre-existing disguise-leak - the voting
                  // screen was showing a disguised player's REAL name
                  // right next to their disguised avatar, meaning anyone
                  // could unmask a disguise just by opening the vote
                  // screen. Now matches the same disguise-aware name
                  // logic used for the on-map name tag.
                  id, name: p.disguiseAvatarId
                    ? (roomInfo?.players?.find((rp) => rp.avatarId === p.disguiseAvatarId)?.name || getAvatar(p.disguiseAvatarId).name)
                    : displayPlayerName(p.name, p.avatarId),
                  avatarId: p.disguiseAvatarId || p.avatarId,
                  isDead: p.alive === false, isMe: false,
                })),
              ];
              return allCards.map((card) => {
                // [BUG FIX] "Has THIS player (the card itself) cast
                // their vote yet" - not "is this card MY vote target".
                // The badge means "this person has voted" (visible to
                // everyone, on their OWN card), not "this is who I
                // voted for" - those are different pieces of
                // information and the original implementation
                // conflated them.
                const hasVoted = Object.prototype.hasOwnProperty.call(meeting.liveVotes || {}, card.id);
                const isPending = pendingVoteTarget === card.id;
                // Every voter (id) whose liveVotes entry points at this
                // card - rendered as small avatars next to the card,
                // live, the moment each vote is cast. Confirmed-intended
                // behavior: once a player confirms their vote, who they
                // voted for is meant to be visible live to everyone.
                const votersForThisCard = Object.entries(meeting.liveVotes || {})
                  .filter(([, choice]) => choice === card.id)
                  .map(([voterId]) => voterId);
                return (
                  <div key={card.id} style={{ position: 'relative' }}>
                    <button
                      onClick={() => {
                        if (card.isDead || !!meeting.myVote || !myAlive) return;
                        setPendingVoteTarget(card.id);
                      }}
                      disabled={card.isDead || !!meeting.myVote || !myAlive}
                      style={{
                        width: '100%', display: 'flex', alignItems: 'center', gap: 8, padding: '9px 10px',
                        borderRadius: 10, border: 'none', background: '#283447',
                        opacity: card.isDead ? 0.5 : 1, position: 'relative',
                      }}
                    >
                      <div style={{ position: 'relative', width: 30, height: 30, flexShrink: 0 }}>
                        <img src={getAvatar(card.avatarId).img} alt="" style={{ width: '100%', height: '100%', objectFit: 'contain' }} />
                        {/* [NEW FEATURE] Dead players show a cross over
                            their dimmed avatar - matches the reference
                            screenshot's eliminated-player styling. */}
                        {card.isDead && (
                          <svg viewBox="0 0 24 24" style={{ position: 'absolute', inset: 0 }}>
                            <line x1="3" y1="3" x2="21" y2="21" stroke="#ff5c5c" strokeWidth="2.5" />
                            <line x1="21" y1="3" x2="3" y2="21" stroke="#ff5c5c" strokeWidth="2.5" />
                          </svg>
                        )}
                      </div>
                      <span style={{ fontSize: 12.5, fontWeight: 700, color: '#fff', textAlign: 'left', flex: 1, overflow: 'hidden', textOverflow: 'ellipsis' }}>
                        {card.name}{card.isMe ? ' (you)' : ''}
                      </span>
                      {/* [NEW FEATURE] "Skip"-style speaker-call badge
                          for whoever called this meeting - placeholder
                          CSS icon (a small triangle/megaphone shape)
                          until a custom sticker is provided. */}
                      {card.id === meeting.calledByPlayerId && (
                        <div style={{
                          width: 16, height: 12, flexShrink: 0,
                          background: '#ffc14c',
                          clipPath: 'polygon(0% 30%, 40% 30%, 100% 0%, 100% 100%, 40% 70%, 0% 70%)',
                        }} title="Called this meeting" />
                      )}
                      {/* [BUG FIX] "I voted" badge - now correctly shown
                          on the CARD OF WHOEVER HAS VOTED (visible to
                          everyone, on that player's own card), not on
                          whichever card they happened to vote FOR. This
                          tells everyone "this person has voted" without
                          revealing who they voted for - exactly the
                          distinction that was requested. Still styled
                          the same green-checkmark badge as before. */}
                      {hasVoted && (
                        <div style={{
                          position: 'absolute', top: -4, right: -4, width: 18, height: 18, borderRadius: '50%',
                          background: '#6effc0', display: 'flex', alignItems: 'center', justifyContent: 'center',
                        }} title="Voted">
                          <svg width="10" height="10" viewBox="0 0 24 24"><path d="M4 12l6 6L20 6" stroke="#06140d" strokeWidth="3.5" fill="none" strokeLinecap="round" strokeLinejoin="round" /></svg>
                        </div>
                      )}
                    </button>
                    {/* [NEW FEATURE] Small voter avatars under the card -
                        every player whose live vote currently points at
                        this target, shown in real time as votes come
                        in. */}
                    {votersForThisCard.length > 0 && (
                      <div style={{ display: 'flex', gap: 2, marginTop: 3, paddingLeft: 4, flexWrap: 'wrap' }}>
                        {votersForThisCard.map((vid) => {
                          const voterInfo = vid === myId
                            ? { avatarId: playerAvatarId }
                            : otherPlayers[vid];
                          if (!voterInfo) return null;
                          return <img key={vid} src={getAvatar(voterInfo.avatarId).img} alt="" style={{ width: 16, height: 16, objectFit: 'contain' }} />;
                        })}
                      </div>
                    )}

                    {/* [NEW FEATURE] Tap-to-confirm overlay - tick/cross
                        shown directly on the card the player just
                        tapped, before the vote is actually sent.
                        Placeholder CSS-drawn tick/cross until custom
                        stickers are provided. */}
                    {isPending && (
                      <div style={{
                        position: 'absolute', inset: 0, borderRadius: 10, background: 'rgba(10,14,20,0.92)',
                        display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 14, zIndex: 2,
                      }}>
                        <button
                          onClick={() => { castVote(card.id); setPendingVoteTarget(null); }}
                          style={{
                            width: 34, height: 34, borderRadius: '50%', border: 'none', background: '#3ddc84',
                            display: 'flex', alignItems: 'center', justifyContent: 'center',
                          }}
                        >
                          <svg width="16" height="16" viewBox="0 0 24 24"><path d="M4 12l6 6L20 6" stroke="#06140d" strokeWidth="3.5" fill="none" strokeLinecap="round" strokeLinejoin="round" /></svg>
                        </button>
                        <button
                          onClick={() => setPendingVoteTarget(null)}
                          style={{
                            width: 34, height: 34, borderRadius: '50%', border: 'none', background: '#ff5c5c',
                            display: 'flex', alignItems: 'center', justifyContent: 'center',
                          }}
                        >
                          <svg width="16" height="16" viewBox="0 0 24 24"><path d="M6 6l12 12M18 6L6 18" stroke="#fff" strokeWidth="3.5" strokeLinecap="round" /></svg>
                        </button>
                      </div>
                    )}
                  </div>
                );
              });
            })()}
          </div>

          <div style={{ padding: '8px 14px', display: 'flex', flexDirection: 'column', gap: 4, flexShrink: 0 }}>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
              <button
                onClick={() => { if (!meeting.myVote && myAlive) setPendingVoteTarget('skip'); }}
                disabled={!!meeting.myVote || !myAlive}
                style={{
                  padding: '9px 22px', borderRadius: 10,
                  border: `1px solid ${meeting.myVote === 'skip' ? '#6effc0' : 'rgba(255,255,255,0.25)'}`,
                  background: meeting.myVote === 'skip' ? 'rgba(110,255,192,0.12)' : '#283447',
                  color: meeting.myVote === 'skip' ? '#6effc0' : '#cfd2da', fontWeight: 700, fontSize: 13,
                  position: 'relative',
                }}
              >
                Skip Vote
                {pendingVoteTarget === 'skip' && (
                  <div style={{
                    position: 'absolute', inset: -2, borderRadius: 10, background: 'rgba(10,14,20,0.95)',
                    display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 10,
                  }}>
                    <span
                      onClick={(e) => { e.stopPropagation(); castVote('skip'); setPendingVoteTarget(null); }}
                      style={{ width: 26, height: 26, borderRadius: '50%', background: '#3ddc84', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
                    >
                      <svg width="13" height="13" viewBox="0 0 24 24"><path d="M4 12l6 6L20 6" stroke="#06140d" strokeWidth="4" fill="none" strokeLinecap="round" strokeLinejoin="round" /></svg>
                    </span>
                    <span
                      onClick={(e) => { e.stopPropagation(); setPendingVoteTarget(null); }}
                      style={{ width: 26, height: 26, borderRadius: '50%', background: '#ff5c5c', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
                    >
                      <svg width="13" height="13" viewBox="0 0 24 24"><path d="M6 6l12 12M18 6L6 18" stroke="#fff" strokeWidth="4" strokeLinecap="round" /></svg>
                    </span>
                  </div>
                )}
              </button>
              <MeetingCountdown startedAt={meeting.startedAt} durationMs={30000} />
            </div>
            {/* [BUG FIX] Skip Vote was missing the same "small voter
                avatars" row every other player-card already has - so a
                player who voted to skip just silently disappeared from
                the live vote display instead of showing up here. Same
                liveVotes lookup, just filtered for choice === 'skip'
                instead of a player id. */}
            {(() => {
              const skipVoters = Object.entries(meeting.liveVotes || {})
                .filter(([, choice]) => choice === 'skip')
                .map(([voterId]) => voterId);
              if (skipVoters.length === 0) return null;
              const myId = socketRef.current?.id;
              return (
                <div style={{ display: 'flex', gap: 2, paddingLeft: 4, flexWrap: 'wrap' }}>
                  {skipVoters.map((vid) => {
                    const avatarId = vid === myId ? playerAvatarId : otherPlayers[vid]?.avatarId;
                    if (!avatarId) return null;
                    return <img key={vid} src={getAvatar(avatarId).img} alt="" style={{ width: 16, height: 16, objectFit: 'contain' }} />;
                  })}
                </div>
              );
            })()}
          </div>
        </div>
      )}

      {/* [NEW FEATURE] Elimination role-reveal — Among-Us style, exactly
          3.5 seconds, shown on top of the results screen right after a
          successful vote-out (never for a tie/skip, since nobody was
          actually eliminated then). This is the ONLY place a player's
          true role is ever revealed, and only after they're voted out —
          never proactively, never for anyone still alive. */}
      {eliminationRoleReveal && (
        <div style={{
          position: 'absolute', inset: 0, zIndex: 70,
          background: eliminationRoleReveal.role === 'saboteur' ? 'radial-gradient(circle at 50% 42%, #3a0d0d, #050202)' : 'radial-gradient(circle at 50% 42%, #0f221a, #05070a)',
          display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 16, padding: 24,
        }}>
          {eliminationRoleReveal.avatarId && (
            <img src={getAvatar(eliminationRoleReveal.avatarId).img} alt="" style={{
              width: 96, height: 'auto',
              filter: eliminationRoleReveal.role === 'saboteur' ? 'drop-shadow(0 0 28px rgba(255,60,60,0.7))' : 'drop-shadow(0 0 22px rgba(110,255,192,0.5))',
              animation: 'roleRevealPop 0.4s ease-out',
            }} />
          )}
          <p style={{ margin: 0, fontSize: 16, fontWeight: 700, color: '#cfd2da', letterSpacing: 0.4, textAlign: 'center' }}>
            {displayPlayerName(eliminationRoleReveal.name, eliminationRoleReveal.avatarId)} was
          </p>
          <p style={{
            margin: 0, fontSize: 30, fontWeight: 900, letterSpacing: 1.4, textTransform: 'uppercase',
            fontFamily: '"Arial Black", "Helvetica Neue", sans-serif', textAlign: 'center', lineHeight: 1.15,
            color: eliminationRoleReveal.role === 'saboteur' ? '#ff3b3b' : '#ffffff',
            textShadow: eliminationRoleReveal.role === 'saboteur' ? '0 0 24px rgba(255,59,59,0.75), 0 2px 4px rgba(0,0,0,0.6)' : '0 2px 4px rgba(0,0,0,0.7)',
          }}>
            {eliminationRoleReveal.role === 'saboteur' ? 'The Saboteur' : 'A Crewmate'}
          </p>
        </div>
      )}

      {/* Stage 4: Results — shows the outcome for a few seconds, then the
          meeting closes itself and gameplay resumes. */}
      {meeting && meeting.stage === 'results' && (
        <div style={{
          position: 'absolute', inset: 0, zIndex: 65, background: 'rgba(0,0,0,0.92)',
          display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', padding: 24,
        }}>
          {meeting.result?.eliminatedName ? (
            <>
              <div style={{ fontSize: 40, marginBottom: 10 }}>⚖️</div>
              <h2 style={{ fontSize: 17, fontWeight: 800, color: '#ff5c5c', margin: '0 0 6px', textAlign: 'center' }}>
                {displayPlayerName(meeting.result.eliminatedName, meeting.result.eliminatedAvatarId)} was eliminated
              </h2>
              <p style={{ fontSize: 11.5, color: '#9aa0ad', margin: '0 0 16px', textAlign: 'center' }}>
                The group has voted them out.
              </p>
            </>
          ) : (
            <>
              <div style={{ fontSize: 40, marginBottom: 10 }}>🤷</div>
              <h2 style={{ fontSize: 17, fontWeight: 800, color: '#6effc0', margin: '0 0 6px', textAlign: 'center' }}>
                No one was eliminated
              </h2>
              <p style={{ fontSize: 11.5, color: '#9aa0ad', margin: '0 0 16px', textAlign: 'center' }}>
                The vote was skipped or didn't reach a majority.
              </p>
            </>
          )}

          {/* [NEW FEATURE] Vote breakdown — revealed only now, on the
              results screen, never during voting itself. Groups every
              cast vote by its target (including "skip" as its own
              group) and shows a small avatar for each voter under that
              target's name. */}
          {meeting.result?.votes && Object.keys(meeting.result.votes).length > 0 && (
            <div style={{ width: '100%', maxWidth: 300, maxHeight: '40vh', overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: 8 }}>
              {(() => {
                const allPlayersById = { [socketRef.current?.id]: { name: playerName, avatarId: playerAvatarId }, ...otherPlayers };
                const groups = {}; // targetId|'skip' -> [voterId, ...]
                Object.entries(meeting.result.votes).forEach(([voterId, targetId]) => {
                  if (!groups[targetId]) groups[targetId] = [];
                  groups[targetId].push(voterId);
                });
                return Object.entries(groups).map(([targetId, voterIds]) => {
                  const targetInfo = targetId === 'skip' ? null : allPlayersById[targetId];
                  return (
                    <div key={targetId} style={{
                      display: 'flex', alignItems: 'center', gap: 8, padding: '6px 10px',
                      background: 'rgba(255,255,255,0.04)', borderRadius: 10,
                    }}>
                      <span style={{ fontSize: 11, color: '#cfd2da', minWidth: 70 }}>
                        {targetId === 'skip' ? '🤷 Skip' : (targetInfo ? displayPlayerName(targetInfo.name, targetInfo.avatarId) : 'Unknown')}
                      </span>
                      <span style={{ fontSize: 12, color: '#5f6b67' }}>←</span>
                      <div style={{ display: 'flex', gap: 3, flexWrap: 'wrap' }}>
                        {voterIds.map((voterId) => {
                          const voterInfo = allPlayersById[voterId];
                          if (!voterInfo) return null;
                          return (
                            <img key={voterId} src={getAvatar(voterInfo.avatarId).img} alt="" title={voterInfo.name}
                              style={{ width: 18, height: 18, objectFit: 'contain' }} />
                          );
                        })}
                      </div>
                    </div>
                  );
                });
              })()}
            </div>
          )}
        </div>
      )}

      {/* [WIN CONDITION] Final game-over announcement — the highest
          z-index in the game, since it needs to cover even an
          in-progress meeting/voting screen if the win condition gets
          triggered while one happens to be open (e.g. a vote-out that
          ejects the last Saboteur). Shows which side won and why, plus
          a button back to the Lobby. */}
      {gameResult && (
        <div style={{
          position: 'absolute', inset: 0, zIndex: 90, background: '#05050a',
          display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'flex-end', padding: 0,
          overflow: 'hidden',
        }}>
          {/* [NEW FEATURE] Win-screen background image - the same group
              photo for every outcome, with bold text overlaid on top
              naming the winning side (rendered in code below, not baked
              into the image itself, so it works for either outcome).
              [BUG FIX] object-fit: contain (not cover) - shows the WHOLE
              image with every avatar visible, never cropped/zoomed in,
              exactly as requested. */}
          <img src={WIN_SCREEN_IMG} alt="" style={{
            position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'contain',
          }} />
          <div style={{
            position: 'absolute', inset: 0,
            background: 'linear-gradient(to bottom, rgba(5,5,10,0.15) 0%, rgba(5,5,10,0.55) 55%, rgba(5,5,10,0.92) 100%)',
          }} />
          <div style={{
            position: 'relative', zIndex: 1, display: 'flex', flexDirection: 'column',
            alignItems: 'center', width: '100%', padding: '0 24px 30px',
          }}>
            <h1 style={{
              fontSize: 30, fontWeight: 900, margin: '0 0 10px', textAlign: 'center',
              fontFamily: '"Arial Black", "Helvetica Neue", sans-serif', letterSpacing: 0.8,
              textShadow: '0 3px 10px rgba(0,0,0,0.8)', lineHeight: 1.15,
            }}>
              {/* [DEV-BRANCH ONLY TEST FEATURE] devEnded is the neutral
                  result from the host's Force End Round button - not a
                  real win, so it gets its own message instead of falling
                  into the Crewmates-Won branch. */}
              {gameResult.winner === 'saboteur' ? (
                <span style={{ color: '#fff' }}>The <span style={{ color: '#ff3b3b' }}>Saboteur</span> Won</span>
              ) : gameResult.winner === 'devEnded' ? (
                <span style={{ color: '#ff9f5a' }}>🛠 Dev Round Ended</span>
              ) : (
                <span style={{ color: '#fff' }}>The Crewmates Won</span>
              )}
            </h1>
            <p style={{ fontSize: 13, color: '#cfd2da', margin: '0 0 28px', textAlign: 'center', maxWidth: 300 }}>
              {gameResult.reason === 'elimination' && 'Too few crewmates remain — the Saboteur has taken control of the ship.'}
              {gameResult.reason === 'saboteurEjected' && 'The Saboteur was voted out and ejected.'}
              {gameResult.reason === 'missionsComplete' && 'Every crewmate finished their missions.'}
              {gameResult.reason === 'devForceEnd' && 'Ended manually via Dev Mode — no winner was decided.'}
            </p>
          {/* [NEW FEATURE] Every player gets this button now, not just
              the host - pressing it sends THIS player's own screen back
              to the Lobby and resets the room's shared game-state on the
              server (the first press does the actual reset; later
              presses from other players are harmless no-ops against an
              already-reset room). Crucially, this never forces anyone
              ELSE's screen to change - other players stay on their own
              win-screen until they personally press this too. The
              server tracks who's actually back in the Lobby
              (inLobbyView) so the room-list panel shows who's ready,
              and migrates host status after 1 minute if the original
              host specifically doesn't come back. */}
          <button
            onClick={() => {
              socketRef.current?.emit('returnToLobby');
              // [BUG FIX] This button never called the local resetGame()
              // before - only the host's "Play Again" path did (via the
              // roomResetForNewGame listener). So a player who pressed
              // "Return to Lobby" kept every bit of their local
              // game-state (ghost/alive status, wallet, sabotage/
              // disguise uses, missions, otherPlayers, etc.) exactly as
              // it was when the game ended. When the host then started a
              // NEW game, roleAssigned only ever sent role/spawnIndex/
              // speedLevel - never `alive` - so a player who'd died as a
              // ghost stayed a ghost forever, missions stayed "done",
              // and so on. Calling the same resetGame() used by the
              // "Play Again" flow here too fixes this for good.
              resetGameRef.current?.();
              setGameResult(null);
              setScreen('lobby');
            }}
            style={{
              padding: '13px 32px', borderRadius: 999, border: 'none',
              background: 'linear-gradient(135deg,#6effc0,#2bb88a)', color: '#06140d',
              fontWeight: 800, fontSize: 14,
            }}
          >Return to Lobby</button>
          </div>
        </div>
      )}

      {/* Mission-complete congrats toast — auto-dismisses after ~3s. */}
      {congratsNote && (
        <div style={{
          position: 'absolute', top: 56, left: '50%', transform: 'translateX(-50%)', zIndex: 40,
          background: 'linear-gradient(135deg, rgba(110,255,192,0.95), rgba(95,217,200,0.95))',
          color: '#0a0a0f', borderRadius: 12, padding: '10px 16px', textAlign: 'center',
          boxShadow: '0 4px 20px rgba(110,255,192,0.35)', maxWidth: 280,
        }}>
          <div style={{ fontSize: 13, fontWeight: 800 }}>🎉 Mission Complete!</div>
          <div style={{ fontSize: 11, fontWeight: 600, marginTop: 2 }}>{congratsNote.label} · +{NEAR_REWARD_PER_MISSION} NEAR earned</div>
        </div>
      )}

      {/* All-missions-complete celebration — fires once, bigger and more
          ceremonial than the per-mission toast. In real multiplayer this
          would also be the trigger for "crewmates win" once every living
          crewmate hits this state; solo-test just celebrates this one
          player's own completion. */}
      {showAllDoneModal && (
        <div style={{
          position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.82)', zIndex: 45,
          display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20,
        }}>
          <div style={{
            textAlign: 'center', maxWidth: 300, padding: '28px 22px',
            background: 'linear-gradient(160deg, rgba(110,255,192,0.12), rgba(8,8,13,0.95))',
            border: '1px solid rgba(110,255,192,0.4)', borderRadius: 20,
            boxShadow: '0 0 50px rgba(110,255,192,0.25)',
          }}>
            <div style={{ fontSize: 44, marginBottom: 10, animation: 'allDoneBounce 0.6s ease' }}>🏆</div>
            <h2 style={{ fontSize: 17, fontWeight: 800, color: '#6effc0', margin: '0 0 8px' }}>
              All Missions Complete!
            </h2>
            <p style={{ fontSize: 12, color: '#cfd2da', margin: '0 0 18px', lineHeight: 1.5 }}>
              You've finished every task assigned to you. Stay alert — the round isn't over until the Saboteur is found or all tasks are done station-wide.
            </p>
            <button onClick={() => setShowAllDoneModal(false)} style={{
              width: '100%', padding: '12px 0', borderRadius: 10, border: 'none',
              background: 'linear-gradient(135deg,#6effc0,#2bb88a)', color: '#06140d',
              fontWeight: 800, fontSize: 13.5,
            }}>Continue</button>
          </div>
          <style>{`
            @keyframes allDoneBounce {
              0% { transform: scale(0.5); opacity: 0; }
              60% { transform: scale(1.15); opacity: 1; }
              100% { transform: scale(1); }
            }
          `}</style>
        </div>
      )}

      {/* Mission Tracker panel — redesigned for clarity: a progress ring +
          summary up top (so "how am I doing" reads at a glance), then a
          height-capped scrollable list of compact mission rows below
          (room icon, name, status) so it never grows past ~70% of the
          screen no matter how many missions are assigned. */}
      {showMissionTracker && (
        <div style={{
          position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.78)',
          display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 50, padding: 16,
        }} onClick={() => setShowMissionTracker(false)}>
          <div onClick={e => e.stopPropagation()} style={{
            padding: '18px 16px 14px', background: 'linear-gradient(160deg, #11141a, #0a0a0f)',
            border: '1px solid rgba(110,255,192,0.25)', borderRadius: 16, maxWidth: 320, width: '100%',
            maxHeight: '78vh', display: 'flex', flexDirection: 'column',
            boxShadow: '0 0 30px rgba(110,255,192,0.08)',
          }}>
            {/* Progress summary — a ring showing fraction complete, plus
                the count as a big, unambiguous number. */}
            {(() => {
              const total = myMissions.length;
              const done = myMissions.filter(m => m.done).length;
              const pct = total > 0 ? done / total : 0;
              const R = 26, C = 2 * Math.PI * R;
              return (
                <div style={{
                  display: 'flex', alignItems: 'center', gap: 14, marginBottom: 14,
                  paddingBottom: 14, borderBottom: '1px solid rgba(255,255,255,0.08)', flexShrink: 0,
                }}>
                  <svg width="64" height="64" viewBox="0 0 64 64" style={{ flexShrink: 0 }}>
                    <circle cx="32" cy="32" r={R} fill="none" stroke="rgba(255,255,255,0.1)" strokeWidth="6" />
                    <circle
                      cx="32" cy="32" r={R} fill="none" stroke="#6effc0" strokeWidth="6"
                      strokeDasharray={`${C * pct} ${C}`} strokeLinecap="round"
                      transform="rotate(-90 32 32)"
                    />
                    <text x="32" y="37" textAnchor="middle" fontSize="15" fontWeight="800" fill="#fff">
                      {done}/{total}
                    </text>
                  </svg>
                  <div>
                    <h2 style={{ fontSize: 14, fontWeight: 800, color: '#fff', margin: '0 0 3px' }}>My Missions</h2>
                    <p style={{ fontSize: 11, color: '#7a8a86', margin: 0 }}>
                      {done === total ? 'All done — nice work!' : `${total - done} task${total - done === 1 ? '' : 's'} remaining`}
                    </p>
                  </div>
                </div>
              );
            })()}

            {/* Scrollable mission list — capped height so the panel
                itself never exceeds its maxHeight regardless of how many
                missions are in the list. [UI IMPROVEMENT] Incomplete
                missions are sorted to the top (done ones sink to the
                bottom) so a player immediately sees what's left to do,
                instead of having to scan past finished ones every time
                they open the tracker. Each row's location now also gets
                a small pin icon — easier to spot at a glance than plain
                text next to a checkbox-icon. */}
            <div style={{ overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: 6, paddingRight: 2 }}>
              {[...myMissions].sort((a, b) => (a.done === b.done) ? 0 : a.done ? 1 : -1).map(m => {
                const isWeapons = m.room === 'weapons' && !m.done;
                const isWallet = m.room === 'wallet_balance' && !m.done;
                let subtitle = m.room === 'wallet_balance' ? 'Anywhere' : (roomDisplayName(m.room));
                return (
                  <div key={m.room} style={{
                    display: 'flex', alignItems: 'center', gap: 10, padding: '9px 10px', borderRadius: 10,
                    background: m.done ? 'rgba(110,255,192,0.07)' : 'rgba(255,255,255,0.035)',
                    border: `1px solid ${m.done ? 'rgba(110,255,192,0.22)' : 'rgba(255,255,255,0.14)'}`,
                  }}>
                    <div style={{
                      width: 26, height: 26, borderRadius: 8, flexShrink: 0,
                      background: m.done ? 'rgba(110,255,192,0.18)' : 'rgba(255,255,255,0.06)',
                      display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 14,
                    }}>
                      {m.done ? '✓' : (m.label || '').split(' ')[0]}
                    </div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{
                        fontSize: 12, fontWeight: 700, color: m.done ? '#7fd9b8' : '#e8eaf0',
                        textDecoration: m.done ? 'line-through' : 'none',
                        whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis',
                      }}>{(m.label || '').replace(/^\S+\s/, '')}</div>
                      <div style={{
                        fontSize: 9.5, color: m.done ? '#5f6b67' : '#6effc0', marginTop: 2,
                        fontWeight: m.done ? 400 : 600,
                        display: 'flex', alignItems: 'center', gap: 3,
                      }}>
                        {!m.done && <span style={{ fontSize: 9 }}>📍</span>}
                        {subtitle}
                      </div>
                    </div>
                    {!m.done && (isWeapons || isWallet) && (
                      <div style={{
                        fontSize: 9.5, fontWeight: 700, color: '#9aa0ad', textAlign: 'right', flexShrink: 0,
                        lineHeight: 1.3,
                      }}>
                        {isWeapons && <>{memeHoldingsNear.toFixed(0)}/{m.memeTargetNear}<br />NEAR</>}
                        {isWallet && <>{(wallet.NEAR || 0).toFixed(0)}/200<br />NEAR</>}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>

            <button onClick={() => setShowMissionTracker(false)} style={{
              width: '100%', marginTop: 12, padding: '9px 0', borderRadius: 10, flexShrink: 0,
              background: 'transparent', color: '#6effc0', border: '1px solid rgba(110,255,192,0.3)',
              fontSize: 13, fontWeight: 600,
            }}>Close</button>
          </div>
        </div>
      )}

      {/* Wallet panel — total USD balance as the hero number, full asset list
          (NEAR first) below in a compact, height-capped scroll area so it
          never eats the whole screen on mobile. */}
      {showWallet && (
        <div style={{
          position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.78)',
          display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 50, padding: 16,
        }} onClick={() => setShowWallet(false)}>
          <div onClick={e => e.stopPropagation()} style={{
            padding: '14px 14px 12px', background: 'linear-gradient(160deg, #11141a, #0a0a0f)',
            border: '1px solid rgba(110,255,192,0.25)', borderRadius: 16, maxWidth: 300, width: '100%',
            maxHeight: '70vh', display: 'flex', flexDirection: 'column',
            boxShadow: '0 0 30px rgba(110,255,192,0.08)',
          }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 7, marginBottom: 10, flexShrink: 0 }}>
              <span style={{
                position: 'relative', width: 20, height: 15, borderRadius: 4,
                border: '1.6px solid #6effc0', boxSizing: 'border-box', flexShrink: 0,
              }}>
                <span style={{ position: 'absolute', top: 4.2, left: 0, right: 0, height: 1.6, background: '#6effc0' }} />
                <span style={{ position: 'absolute', right: 2, bottom: 2, width: 4.5, height: 3.2, borderRadius: 1, background: '#6effc0' }} />
              </span>
              <h2 style={{ fontSize: 13, fontWeight: 800, margin: 0, color: '#fff', letterSpacing: 0.2 }}>My Wallet</h2>
            </div>

            <div style={{
              padding: '10px 12px', borderRadius: 10, marginBottom: 10, textAlign: 'center', flexShrink: 0,
              background: 'linear-gradient(135deg, rgba(110,255,192,0.14), rgba(110,255,192,0.04))',
              border: '1px solid rgba(110,255,192,0.2)',
            }}>
              <p style={{ fontSize: 9, color: '#7fd9b8', margin: '0 0 2px', letterSpacing: 0.4 }}>TOTAL BALANCE</p>
              <p style={{ fontSize: 22, fontWeight: 800, color: '#6effc0', margin: 0 }}>
                ${(SWAP_ASSETS.reduce((sum, a) => sum + (wallet[a.id] || 0) * a.usd, 0)
                  + memeHoldingsValueNear(memeWallet) * (SWAP_ASSETS.find(a => a.id === 'NEAR')?.usd || 0)
                ).toFixed(2)}
              </p>
            </div>

            <div style={{ overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: 5, marginBottom: 10 }}>
              {[...SWAP_ASSETS]
                .sort((a, b) => (wallet[b.id] || 0) * b.usd - (wallet[a.id] || 0) * a.usd)
                .map(a => {
                const bal = wallet[a.id] || 0;
                return (
                  <div key={a.id} style={{
                    display: 'flex', alignItems: 'center', gap: 8, padding: '6px 9px', borderRadius: 8,
                    background: 'rgba(255,255,255,0.04)', border: '1px solid rgba(255,255,255,0.07)',
                  }}>
                    <CoinLogo slug={a.logo} symbol={a.id} size={18} />
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontSize: 11.5, fontWeight: 700, color: '#dfe2ea' }}>{a.id}</div>
                    </div>
                    <div style={{ textAlign: 'right' }}>
                      <div style={{ fontSize: 11.5, fontWeight: 700, color: bal > 0 ? '#7fd9b8' : '#5a655f' }}>
                        {bal.toFixed(bal > 0 && bal < 1 ? 6 : 2)}
                      </div>
                      <div style={{ fontSize: 9, color: '#5a655f' }}>${(bal * a.usd).toFixed(2)}</div>
                    </div>
                  </div>
                );
              })}
              {/* Meme coin holdings — same row layout as every other asset, but
                  CoinLogo always falls back to its plain letter badge here
                  (no slug passed) since meme coins don't have a "real" logo
                  in this wallet, by design. */}
              {[...MEME_COINS]
                .sort((a, b) => (memeWallet[b.id] || 0) - (memeWallet[a.id] || 0))
                .filter(c => (memeWallet[c.id] || 0) > 0)
                .map(c => {
                const bal = memeWallet[c.id] || 0;
                const nearVal = memeTokensToNear(c.id, bal);
                return (
                  <div key={c.id} style={{
                    display: 'flex', alignItems: 'center', gap: 8, padding: '6px 9px', borderRadius: 8,
                    background: 'rgba(255,255,255,0.04)', border: '1px solid rgba(255,255,255,0.07)',
                  }}>
                    <CoinLogo symbol={c.id} size={18} />
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontSize: 11.5, fontWeight: 700, color: '#dfe2ea' }}>{c.id}</div>
                    </div>
                    <div style={{ textAlign: 'right' }}>
                      <div style={{ fontSize: 11.5, fontWeight: 700, color: '#7fd9b8' }}>
                        {bal.toLocaleString(undefined, { maximumFractionDigits: 2 })}
                      </div>
                      <div style={{ fontSize: 9, color: '#5a655f' }}>≈ {nearVal.toFixed(4)} NEAR</div>
                    </div>
                  </div>
                );
              })}
            </div>

            <button onClick={() => setShowWallet(false)} style={{
              width: '100%', padding: '8px 0', borderRadius: 9, flexShrink: 0,
              background: 'transparent', color: '#6effc0', border: '1px solid rgba(110,255,192,0.3)',
              fontSize: 12.5, fontWeight: 600,
            }}>Close</button>
          </div>
        </div>
      )}

      {/* Kill button — Among-Us-style: large, circular, aggressively red,
          only appears for a Saboteur standing close enough to a living
          crewmate (the dummy, in solo-test). Shows the cooldown as a
          countdown instead of the icon while it's recharging. */}
      {canKillDummy && (
        <button
          onClick={handleKillDummy}
          disabled={killCooldownSecLeft > 0}
          aria-label="Kill"
          style={{
            position: 'absolute', bottom: 150, left: 16, zIndex: 16,
            width: 72, height: 72, borderRadius: '50%', border: '3px solid #fff',
            background: killCooldownSecLeft > 0
              ? 'radial-gradient(circle at 35% 30%, #5a1414, #2a0808)'
              : 'radial-gradient(circle at 35% 30%, #ff4040, #8a0000)',
            boxShadow: killCooldownSecLeft > 0
              ? '0 4px 14px rgba(0,0,0,0.5)'
              : '0 0 0 6px rgba(255,40,40,0.18), 0 4px 20px rgba(255,20,20,0.55)',
            display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
            animation: killCooldownSecLeft > 0 ? 'none' : 'killButtonPulse 1.1s ease-in-out infinite',
          }}
        >
          {killCooldownSecLeft > 0 ? (
            <span style={{ fontSize: 20, fontWeight: 800, color: '#a05050' }}>{killCooldownSecLeft}</span>
          ) : (
            <span style={{ fontSize: 26, lineHeight: 1, filter: 'drop-shadow(0 1px 2px rgba(0,0,0,0.5))' }}>🔪</span>
          )}
          <span style={{
            fontSize: 8.5, fontWeight: 800, letterSpacing: 0.5, marginTop: 2,
            color: killCooldownSecLeft > 0 ? '#7a4a4a' : '#fff',
          }}>KILL</span>
        </button>
      )}
      <style>{`
        @keyframes killButtonPulse {
          0%, 100% { box-shadow: 0 0 0 6px rgba(255,40,40,0.18), 0 4px 20px rgba(255,20,20,0.55); }
          50% { box-shadow: 0 0 0 10px rgba(255,40,40,0.28), 0 4px 26px rgba(255,20,20,0.75); }
        }
      `}</style>

      {/* Report Body — crewmate-only, appears when standing near a dead
          body. Reporting immediately calls an emergency meeting, same as
          pressing the Assembly Hall button. */}
      {canReportBody && !meeting && (
        <button
          onClick={() => callMeeting('report', nearestReportableBody?.id)}
          style={{
            position: 'absolute', bottom: 200, left: '50%', transform: 'translateX(-50%)',
            display: 'flex', alignItems: 'center', gap: 7, zIndex: 16,
            background: 'rgba(40,10,10,0.85)', color: '#ff8a8a',
            border: '1px solid rgba(255,85,85,0.45)', borderRadius: 20,
            padding: '9px 18px', fontSize: 13, fontWeight: 800, letterSpacing: 0.2,
            boxShadow: '0 2px 16px rgba(255,40,40,0.3)', whiteSpace: 'nowrap',
            animation: 'reportPulse 1s ease-in-out infinite',
          }}
        >🚩 Report Body</button>
      )}
      <style>{`
        @keyframes reportPulse {
          0%, 100% { box-shadow: 0 2px 16px rgba(255,40,40,0.3); }
          50% { box-shadow: 0 2px 22px rgba(255,40,40,0.55); }
        }
      `}</style>

      {/* [NEW FEATURE] Ghost Chat — only ever visible to a ghost (myAlive
          === false). Deliberately styled dim/translucent/grayscale
          throughout so it's immediately visually obvious this is a
          "ghost-only" surface, distinct from the normal meeting chat.
          Works anytime during the game, not just during meetings. */}
      {/* [DEV-BRANCH ONLY TEST FEATURE] Force End Round - only visible to
          the host, only while Dev Mode is on, only during an active game.
          Needed because checkWinCondition auto-skips ending the round
          while devMode is on (see backend) - without this button, a Dev
          Mode test round could otherwise never end. Tries the real win
          conditions first server-side; falls back to a neutral result if
          nothing qualifies yet. [BUG FIX] isHost/socket don't exist in
          this component's scope (they're local to the Lobby component) -
          computed locally here instead, same as everywhere else in
          MovementDemo identifies "self" (via roomInfo + socketRef).
          THIS BLOCK MUST NEVER BE MERGED TO THE LIVE/MAIN BRANCH. */}
      {screen === 'game' && roomInfo?.devMode && !!roomInfo?.players?.find(p => p.id === socketRef.current?.id)?.isHost && (
        <button
          onClick={() => socketRef.current?.emit('devForceEndGame')}
          style={{
            position: 'absolute', top: 64, left: 14, zIndex: 15,
            display: 'flex', alignItems: 'center', gap: 6,
            background: 'rgba(224,118,43,0.55)', color: '#fff',
            border: '1px solid rgba(255,159,90,0.6)', borderRadius: 20,
            padding: '8px 14px', fontSize: 12, fontWeight: 700, letterSpacing: 0.2,
          }}
        >🛠 Force End Round</button>
      )}

      {!myAlive && screen === 'game' && !showGhostChat && (
        <button
          onClick={() => setShowGhostChat(true)}
          style={{
            position: 'absolute', top: 64, right: 14, zIndex: 15,
            display: 'flex', alignItems: 'center', gap: 6,
            background: 'rgba(40,40,50,0.55)', color: 'rgba(220,220,230,0.85)',
            border: '1px solid rgba(180,180,200,0.3)', borderRadius: 20,
            padding: '8px 14px', fontSize: 12, fontWeight: 700, letterSpacing: 0.2,
            filter: 'grayscale(0.3)',
          }}
        >👻 Ghost Chat</button>
      )}

      {!myAlive && showGhostChat && (
        <div style={{
          position: 'absolute', inset: 0, zIndex: 60, display: 'flex', flexDirection: 'column',
          background: 'rgba(10,10,14,0.96)', filter: 'grayscale(0.25)',
        }}>
          <div style={{
            display: 'flex', alignItems: 'center', justifyContent: 'space-between',
            padding: '14px 16px', borderBottom: '1px solid rgba(180,180,200,0.15)', flexShrink: 0,
          }}>
            <span style={{ fontSize: 14, fontWeight: 800, color: 'rgba(220,220,230,0.9)' }}>👻 Ghost Chat — only ghosts can see this</span>
            <button onClick={() => setShowGhostChat(false)} style={{
              background: 'none', border: 'none', color: 'rgba(220,220,230,0.8)', fontSize: 18,
            }}>✕</button>
          </div>

          <div ref={ghostChatScrollRef} style={{ flex: 1, overflowY: 'auto', padding: '12px 14px', display: 'flex', flexDirection: 'column', gap: 10 }}>
            {ghostChatMessages.length === 0 && (
              <p style={{ fontSize: 11, color: 'rgba(150,150,160,0.7)', textAlign: 'center', marginTop: 30 }}>
                No spirits have spoken yet. Say something only the dead can hear.
              </p>
            )}
            {ghostChatMessages.map(msg => {
              const shouting = isAllCapsMessage(msg.text);
              return (
              <div key={msg.id} style={{
                display: 'flex', gap: 8, alignItems: 'flex-end',
                flexDirection: msg.isSelf ? 'row-reverse' : 'row',
              }}>
                <img src={getAvatar(msg.authorAvatarId).img} alt="" style={{ width: 26, height: 26, objectFit: 'contain', flexShrink: 0, opacity: 0.7 }} />
                <div style={{ maxWidth: '72%' }}>
                  <div style={{
                    fontSize: 9.5, color: 'rgba(160,160,170,0.8)', marginBottom: 2,
                    textAlign: msg.isSelf ? 'right' : 'left',
                  }}>{msg.authorName}</div>
                  <div
                    onClick={() => setGhostReplyingTo({ senderName: msg.authorName, text: msg.text })}
                    style={{
                      padding: '8px 12px', borderRadius: 14, fontSize: 12.5, lineHeight: 1.35,
                      background: shouting ? 'linear-gradient(135deg,#ffd75e,#e8a831)' : (msg.isSelf ? 'rgba(160,160,180,0.25)' : 'rgba(255,255,255,0.06)'),
                      color: shouting ? '#241a00' : 'rgba(225,225,232,0.9)',
                      fontWeight: shouting ? 800 : 400,
                      boxShadow: shouting ? '0 0 10px rgba(255,215,94,0.4)' : 'none',
                      borderBottomRightRadius: msg.isSelf ? 4 : 14,
                      borderBottomLeftRadius: msg.isSelf ? 14 : 4,
                      cursor: 'pointer',
                    }}>
                    {msg.replyTo && (
                      <div style={{
                        borderLeft: '2px solid rgba(180,180,200,0.4)',
                        paddingLeft: 7, marginBottom: 5, opacity: 0.75,
                      }}>
                        <div style={{ fontSize: 9.5, fontWeight: 700 }}>{msg.replyTo.senderName}</div>
                        <div style={{ fontSize: 10.5, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{msg.replyTo.text}</div>
                      </div>
                    )}
                    {msg.text}
                  </div>
                </div>
              </div>
              );
            })}
          </div>

          {ghostReplyingTo && (
            <div style={{
              display: 'flex', alignItems: 'center', gap: 8, padding: '7px 14px',
              borderTop: '1px solid rgba(180,180,200,0.15)', background: 'rgba(160,160,180,0.08)',
            }}>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 9.5, color: 'rgba(200,200,210,0.9)', fontWeight: 700 }}>Replying to {ghostReplyingTo.senderName}</div>
                <div style={{ fontSize: 10.5, color: 'rgba(160,160,170,0.8)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{ghostReplyingTo.text}</div>
              </div>
              <button onClick={() => setGhostReplyingTo(null)} style={{
                background: 'none', border: 'none', color: 'rgba(160,160,170,0.8)', fontSize: 16, flexShrink: 0,
              }}>✕</button>
            </div>
          )}

          <div style={{
            display: 'flex', gap: 8, padding: '10px 14px', borderTop: '1px solid rgba(180,180,200,0.15)', flexShrink: 0,
          }}>
            <input
              value={ghostChatDraft}
              onChange={e => setGhostChatDraft(e.target.value.slice(0, 200))}
              onKeyDown={e => { if (e.key === 'Enter') sendGhostChatMessage(); }}
              placeholder="Talk to other ghosts..."
              style={{
                flex: 1, padding: '10px 14px', borderRadius: 999, border: '1px solid rgba(180,180,200,0.25)',
                background: 'rgba(255,255,255,0.05)', color: 'rgba(225,225,232,0.9)', fontSize: 13, outline: 'none',
              }}
            />
            <button onClick={sendGhostChatMessage} disabled={!ghostChatDraft.trim()} style={{
              width: 42, height: 42, borderRadius: '50%', border: 'none', flexShrink: 0,
              background: ghostChatDraft.trim() ? 'rgba(180,180,200,0.35)' : 'rgba(255,255,255,0.06)',
              color: 'rgba(225,225,232,0.9)', fontSize: 16, fontWeight: 800,
            }}>↑</button>
          </div>
        </div>
      )}

      {/* Enter Vent — Saboteur-only, appears when standing near a vent
          grate in a room that has one. Placed top-center, clear of the
          joystick/kill button/bottom action stack. */}
      {nearVent && !showMission && (
        <button
          onClick={enterVent}
          style={{
            position: 'absolute', top: 64, left: '50%', transform: 'translateX(-50%)',
            display: 'flex', alignItems: 'center', gap: 7, zIndex: 15,
            background: 'rgba(8,8,13,0.85)', color: '#6effc0',
            border: '1px solid rgba(110,255,192,0.4)', borderRadius: 20,
            padding: '8px 16px', fontSize: 12.5, fontWeight: 700, letterSpacing: 0.2,
            boxShadow: '0 2px 14px rgba(110,255,192,0.2)', whiteSpace: 'nowrap',
          }}
        >
          <img src={VENT_ICON_IMG} alt="" style={{ width: 18, height: 11, objectFit: 'contain' }} />
          Enter Vent
        </button>
      )}

      {/* Vent travel controls — Saboteur is "inside the walls" but the map
          stays exactly as-is underneath (same room/camera, full gameplay
          visible) — no separate screen, per the actual Among Us feel.
          Just a small arrow button per connected room (only direct
          neighbors, per VENT_ADJACENCY) plus a separate Exit button, both
          floating over the normal view. */}
      {inVent && (
        <>
          <div style={{
            position: 'absolute', bottom: 110, left: 0, right: 0, zIndex: 17,
            display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 8, padding: '0 16px',
          }}>
            <div style={{
              display: 'flex', alignItems: 'center', gap: 6, marginBottom: 4,
              background: 'rgba(8,8,13,0.8)', borderRadius: 999, padding: '4px 12px',
            }}>
              <img src={VENT_ICON_IMG} alt="" style={{ width: 16, height: 10, objectFit: 'contain' }} />
              <span style={{ fontSize: 10, color: '#6effc0', fontWeight: 700 }}>In the vents</span>
            </div>
            <div style={{
              display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: 8,
              width: '100%', maxWidth: 280,
            }}>
              {(VENT_ADJACENCY[inVent] || []).map(destId => (
                <button
                  key={destId}
                  onClick={() => travelToVentRoom(destId)}
                  style={{
                    display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6,
                    padding: '7px 10px', borderRadius: 999, border: '1px solid rgba(110,255,192,0.4)',
                    background: 'rgba(8,8,13,0.85)', color: '#cfe8dc', fontSize: 11.5, fontWeight: 700,
                    boxShadow: '0 2px 10px rgba(110,255,192,0.15)', whiteSpace: 'nowrap', overflow: 'hidden',
                    textOverflow: 'ellipsis',
                  }}
                >
                  <span style={{ fontSize: 14, color: '#6effc0', flexShrink: 0 }}>↗</span>
                  {roomDisplayName(destId)}
                </button>
              ))}
            </div>
          </div>

          <button onClick={exitVent} style={{
            position: 'absolute', bottom: 36, left: 16, zIndex: 17,
            padding: '10px 22px', borderRadius: 999, border: 'none',
            background: 'linear-gradient(135deg,#6effc0,#2bb88a)', color: '#06140d',
            fontWeight: 800, fontSize: 12.5,
          }}>Exit Vent</button>
        </>
      )}

      {/* Joystick */}
      <div ref={joyBaseRef}
        onMouseDown={joyStart} onMouseMove={joyMove} onMouseUp={joyEnd} onMouseLeave={joyEnd}
        onTouchEnd={joyEnd}
        style={{
          // [BUG FIX] Raised from bottom:36 to bottom:65 - in the Telegram
          // Mini App WebView, a touch near the very bottom edge of the
          // joystick (which happens often when pushing it straight down)
          // could land close enough to Telegram's own swipe-down-to-close
          // gesture zone and accidentally minimize the whole app mid-game.
          position: 'absolute', bottom: 65, left: '50%', transform: 'translateX(-50%)',
          width: 110, height: 110, borderRadius: '50%',
          background: 'rgba(255,255,255,0.06)', border: '2px solid rgba(255,255,255,0.25)',
          touchAction: 'none', zIndex: 10, display: 'flex', alignItems: 'center', justifyContent: 'center',
        }}>
        <div style={{
          width: 46, height: 46, borderRadius: '50%',
          background: joyRef.current.active ? 'rgba(110,255,192,0.85)' : 'rgba(255,255,255,0.35)',
          border: '2px solid rgba(255,255,255,0.5)',
          transform: `translate(${knob.x}px,${knob.y}px)`, pointerEvents: 'none',
        }} />
      </div>
      </div>
    </div>
  );
}

// [DEV-BRANCH ONLY TEST FEATURE] On-screen crash catcher, ONLY for this
// test build. Without it, any uncaught error inside MovementDemo silently
// unmounts the whole app to a blank white page (React's default behavior)
// - impossible to debug on a mobile browser with no console access. This
// shows the actual error message + component stack directly on screen
// instead, plus a "Reload" button. THIS BLOCK MUST NEVER BE MERGED TO THE
// LIVE/MAIN BRANCH - the live game should never show a raw error screen
// to real players.
class DevErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { error: null, info: null };
  }
  static getDerivedStateFromError(error) {
    return { error };
  }
  componentDidCatch(error, info) {
    this.setState({ error, info });
    console.error('[DEV MODE CRASH CAUGHT]', error, info);
  }
  render() {
    if (this.state.error) {
      return (
        <div style={{
          position: 'fixed', inset: 0, background: '#1a0505', color: '#ffdada',
          padding: 20, overflow: 'auto', fontFamily: 'monospace', zIndex: 9999,
        }}>
          <h2 style={{ color: '#ff6b6b', fontSize: 16, margin: '0 0 12px' }}>🛠 Dev Mode caught a crash</h2>
          <p style={{ fontSize: 13, whiteSpace: 'pre-wrap', margin: '0 0 12px' }}>
            {String(this.state.error?.message || this.state.error)}
          </p>
          <p style={{ fontSize: 10, whiteSpace: 'pre-wrap', color: '#d8a0a0', opacity: 0.8 }}>
            {this.state.error?.stack}
          </p>
          <button
            onClick={() => window.location.reload()}
            style={{
              marginTop: 16, padding: '10px 18px', background: '#ff6b6b', color: '#1a0505',
              border: 'none', borderRadius: 8, fontWeight: 800, fontSize: 13,
            }}
          >Reload</button>
        </div>
      );
    }
    return this.props.children;
  }
}

export default function App() {
  return (
    <DevErrorBoundary>
      <MovementDemo />
    </DevErrorBoundary>
  );
}
